                    </div>

                    {/* DESKTOP FLEX LAYOUT (>= md) */}
                    <div className="hidden md:flex h-40 overflow-x-auto overflow-y-hidden">

                        {/* ZONE 1: COMMAND TOOLS */}
                        <div className="w-36 border-r border-slate-800 p-3 flex flex-col gap-2 shrink-0">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">地圖工具</div>
                            <div className="grid grid-cols-2 gap-2 flex-1">
                                {/* Removed Select Button */}
                                <button onClick={() => toggleTool(ToolType.OBSTACLE)} className={`tactical-btn flex-col col-span-2 ${tool === ToolType.OBSTACLE ? 'active' : ''}`}>
                                    <span className="flex items-center gap-2">
                                        <span className="text-lg">🧱</span>
                                        <span className="text-[9px]">地形</span>
                                    </span>
                                </button>
                                <button onClick={() => toggleTool(ToolType.DELETE)} className={`tactical-btn flex-col col-span-2 text-red-400 border-red-900/50 hover:border-red-500 ${tool === ToolType.DELETE ? 'active border-red-500 bg-red-950/30' : ''}`}>
                                    <span className="text-lg">❌</span>
                                    <span className="text-[9px]">移除</span>
                                </button>
                            </div>
                            {tool === ToolType.OBSTACLE && (
                                <select className="bg-slate-900 border border-slate-700 text-xs p-1 rounded text-slate-400 outline-none" value={selectedObstacle} onChange={e => setSelectedObstacle(e.target.value)}>
                                    {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                                </select>
                            )}
                        </div>

                        {/* ZONE 2: DEPLOYMENT (Flexible Width) */}
                        <div className="flex-1 p-3 flex flex-col gap-2 relative min-w-[300px]">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1 flex justify-between">
                                <span>單位部署</span>
                                <span className="text-slate-700 font-mono">單位數: {unitCount}</span>
                            </div>

                            <div className="flex gap-4 h-full">
                                {/* Team Selectors (Sets Tool) */}
                                <div className="flex flex-col gap-2 w-28 shrink-0">
                                    <button onClick={() => toggleTool(ToolType.ADD_BLUE)} className={`flex-1 tactical-btn btn-blue flex items-center justify-between px-3 ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="font-bold text-xs">藍隊</span>
                                        <span className="text-lg">🔵</span>
                                    </button>
                                    <button onClick={() => toggleTool(ToolType.ADD_RED)} className={`flex-1 tactical-btn btn-red flex items-center justify-between px-3 ${tool === ToolType.ADD_RED ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="font-bold text-xs">紅隊</span>
                                        <span className="text-lg">🔴</span>
                                    </button>
                                </div>

                                {/* Mode & Draft Config */}
                                <div className="flex-1 bg-slate-900 border border-slate-800 rounded p-2 flex flex-col gap-2 min-w-[200px]">
                                    <div className="flex bg-slate-950 rounded p-1 gap-1 shrink-0">
                                        <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'RANDOM' ? 'bg-slate-700 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                            🎲 隨機
                                        </button>
                                        <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'DRAFT' ? 'bg-slate-700 text-amber-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                            📝 自選
                                        </button>
                                    </div>

                                    <div className="flex-1 flex items-center justify-center relative overflow-hidden">
                                        {spawnMode === 'RANDOM' ? (
                                            <div className="text-slate-600 font-mono text-xs flex flex-col items-center animate-pulse">
                                                <span className="text-2xl mb-1">🎲</span>
                                                <span>隨機職階</span>
                                            </div>
                                        ) : (
                                            <div className="flex gap-1.5 w-full justify-center">
                                                {Object.values(Role).map(role => (
                                                    <button 
                                                        key={role}
                                                        onClick={() => setDraftRole(role)}
                                                        className={`w-10 h-10 rounded border flex flex-col items-center justify-center transition-all ${draftRole === role ? 'bg-amber-900/40 border-amber-500 text-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.3)] scale-110' : 'bg-slate-800 border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'}`}
                                                        title={role}
                                                    >
                                                        <span className="text-lg -mt-1 filter drop-shadow-md">{roleIcons[role]}</span>
                                                    </button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* HP Pool */}
                                <div className="flex flex-col justify-center gap-1 w-16 shrink-0">
                                    <label className="text-[9px] text-slate-500 font-bold uppercase text-center">生命值</label>
                                    <input 
                                        type="number" 
                                        value={hpInput} 
                                        onChange={e => setHpInput(parseInt(e.target.value))} 
                                        className="tactical-input text-center text-lg h-10 border-slate-700 focus:border-cyan-500 px-0"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* ZONE 3: MAP OPS */}
                        <div className="w-36 border-l border-slate-800 p-3 flex flex-col gap-2 shrink-0 bg-slate-950/50">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">地圖操作</div>
                            <div className="grid grid-cols-2 gap-2">
                                <div className="flex flex-col">
                                    <label className="text-[8px] text-slate-500">寬度</label>
                                    <input type="number" className="tactical-input p-1 text-center" value={mapW} onChange={e=>setMapW(Number(e.target.value))}/>
                                </div>
                                <div className="flex flex-col">
                                    <label className="text-[8px] text-slate-500">高度</label>
                                    <input type="number" className="tactical-input p-1 text-center" value={mapH} onChange={e=>setMapH(Number(e.target.value))}/>
                                </div>
                            </div>
                            <div className="flex gap-2 mt-auto">
                                <button onClick={updateMap} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center border-slate-600 hover:bg-slate-800">重建</button>
                                <button onClick={handleClear} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center text-red-400 border-red-900 hover:bg-red-950">清空單位</button>
                            </div>
                        </div>
                    </div>
                </div>
          </div>

          {/* RIGHT COLUMN: Inspector (Z-40) */}
          {/* Resizer - Hidden on small screens or when showcase */}
          {isLargeScreen && !isShowcaseMode && (
            <div 
                className="hidden lg:flex w-1 bg-slate-950 hover:bg-cyan-600 cursor-col-resize items-center justify-center shrink-0 transition-colors z-40 border-l border-slate-800"
                onMouseDown={startResizing}
                onTouchStart={startResizing}
            >
                <div className="w-[1px] h-8 bg-slate-600"></div>
            </div>
          )}

          {/* Panel - Desktop Sidebar OR Mobile Overlay Drawer */}
          {/* LOGIC SPLIT: Mobile is a Modal (Fixed), Desktop is a Flex Col (Relative) */}
          {isLargeScreen ? (
              // DESKTOP LAYOUT
              <div 
                className={`
                    flex flex-col z-40 shadow-2xl bg-slate-900 border-l border-slate-700 transition-all duration-300 relative h-full
                    ${isShowcaseMode ? 'w-0 border-l-0 overflow-hidden' : ''}
                `}
                style={{ width: !isShowcaseMode ? sidebarWidth : 0 }}
              >
                <InspectorPanel 
                    agent={selectedAgent} 
                    engine={engineRef.current}
                    logs={[]} 
                    db={engineRef.current.skillDB}
                    onHoverSkill={setHoveredSkill}
                />
              </div>
          ) : (
              // MOBILE DRAWER LAYOUT
              <div 
                className={`fixed inset-0 z-50 transition-opacity duration-300 ${showMobileInspector ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
                onClick={() => setShowMobileInspector(false)}
              >
                  {/* Backdrop */}
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-sm"></div>

                  {/* Slide-in Panel */}
                  <div 
                    className={`absolute right-0 top-0 bottom-0 w-full sm:w-[400px] bg-slate-900 shadow-2xl border-l border-slate-700 transform transition-transform duration-300 flex flex-col ${showMobileInspector ? 'translate-x-0' : 'translate-x-full'}`}
                    onClick={(e) => e.stopPropagation()}
                  >
                      {/* Mobile Header */}
                      <div className="p-4 border-b border-slate-700 bg-slate-950 flex justify-between items-center shrink-0 pt-safe-top">
                           <h3 className="font-bold text-slate-200 text-lg">單位監控面板</h3>
                           <button onClick={() => setShowMobileInspector(false)} className="w-10 h-10 flex items-center justify-center bg-slate-800 rounded-full text-slate-400 active:scale-95">✕</button>
                      </div>

                      <div className="flex-1 overflow-hidden">
                        <InspectorPanel 
                            agent={selectedAgent} 
                            engine={engineRef.current}
                            logs={[]} 
                            db={engineRef.current.skillDB}
                            onHoverSkill={setHoveredSkill}
                        />
                      </div>
                  </div>
              </div>
          )}
      </div>
    </div>
  );
}

export default App;

import React, { useRef, useEffect } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { HexUtils } from '../engine/utils';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Hex, Skill, GameEvent, Role } from '../types';
import { BLOCK_HEIGHT } from '../constants'; 

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = ({ engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, isShowcaseMode, spawnMode, draftRole, onSelect, onWin, winner, rematch, transitionPhase }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 }); 
    const fpsRef = useRef(60);

    // Instantiate Renderer
    const rendererRef = useRef(new GameRenderer());
    const transitionStartTime = useRef(0);

    // Bridge for Synchronous Redraw (Fixes black flash on resize)
    const drawCurrentFrameRef = useRef<() => void>(() => {});

    // Handle Transition Phase Timing
    useEffect(() => {
        transitionStartTime.current = performance.now();
    }, [transitionPhase]);

    // --- INTERACTION STATE ---
    // Agent Dragging
    const pressedAgentRef = useRef<Agent | null>(null);
    const isDraggingUnit = useRef(false);

    // Obstacle Dragging
    const draggedObstacleRef = useRef<{ 
        type: string; 
        originQ: number; 
        originR: number; 
        px: number; 
        py: number; 
    } | null>(null);

    // General Input State
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const isPanning = useRef(false);
    const isPainting = useRef(false); 
    const lastPaintHex = useRef<string>(""); 

    // Touch specific state
    const lastPinchDist = useRef<number>(0);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);

    // Track hovered hex for visual feedback
    const hoveredHexRef = useRef<Hex | null>(null);

    // Track selected agent for the render loop
    const selectedAgentRef = useRef<Agent | null>(selectedAgent);
    useEffect(() => {
        selectedAgentRef.current = selectedAgent;
    }, [selectedAgent]);

    // --- Camera Control Logic ---
    const centerCamera = () => {
        if (!canvasRef.current || !wrapperRef.current) return;

        // Ensure dims are fresh
        canvasRef.current.width = wrapperRef.current.clientWidth;
        canvasRef.current.height = wrapperRef.current.clientHeight;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        // Calculate grid visual center
        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);

        // Visual adjustments
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        // Center Point Formula: WorldPos - (ScreenSize / Zoom) / 2
        camera.current.x = p.x - (canvasRef.current.width / camera.current.zoom) / 2;
        camera.current.y = p.y + verticalOffset - (canvasRef.current.height / camera.current.zoom) / 2;
    };

    // Auto-Center Triggers
    useEffect(() => {
        if (isShowcaseMode || transitionPhase === 'IN') {
            const t = setTimeout(centerCamera, 350);
            return () => clearTimeout(t);
        } else if (!isShowcaseMode && transitionPhase === 'IDLE') {
             const t = setTimeout(centerCamera, 350);
             return () => clearTimeout(t);
        }
    }, [isShowcaseMode, transitionPhase, engine.mapConfig.w, engine.mapConfig.h]);

    // Resize Observer for Fluid Layout
    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;

        const resizeObserver = new ResizeObserver(() => {
            if (wrapperRef.current && canvasRef.current) {
                canvasRef.current.width = wrapperRef.current.clientWidth;
                canvasRef.current.height = wrapperRef.current.clientHeight;

                if (engine.agents.length === 0) {
                    centerCamera();
                }
                drawCurrentFrameRef.current();
            }
        });

        resizeObserver.observe(wrapperRef.current);
        centerCamera();

        return () => resizeObserver.disconnect();
    }, [engine]);

    // Render Loop
    useEffect(() => {
        let frameId: number;
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const drawFrame = () => {
            const ctx = canvasRef.current?.getContext('2d');
            if (ctx && canvasRef.current) {
                // Highlight logic: Selected OR currently being dragged/pressed
                const highlight = pressedAgentRef.current || selectedAgentRef.current || null;
                rendererRef.current.draw(ctx, engine, camera.current, highlight, fpsRef.current, hoveredHexRef.current, hoveredSkill); 

                // --- MANUAL OVERLAY: Dragged Obstacle ---
                if (draggedObstacleRef.current) {
                    const { type, px, py } = draggedObstacleRef.current;
                    const { x, y, zoom } = camera.current;
                    const { width, height } = canvasRef.current;

                    ctx.save();
                    // Apply Camera Transform
                    ctx.translate(width / 2, height / 2);
                    ctx.scale(zoom, zoom);
                    ctx.translate(-x - width / 2 / zoom, -y - height / 2 / zoom);

                    // Draw Sprite (Lifted)
                    const sprite = SpriteManager.getObstacleSprite(type);
                    const liftOffset = 20;
                    ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.shadowBlur = 20;
                    ctx.shadowOffsetY = 20;
                    // Standard offset for obstacle sprites to align with bottom-center
                    ctx.drawImage(sprite, px - 32, py - 86 - liftOffset);

                    ctx.restore();
                }
            }
        };

        drawCurrentFrameRef.current = drawFrame;

        const loop = (t: number) => {
            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200;

                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }

                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            rendererRef.current.update(dt / 1000, engine);

            if (transitionPhase !== 'IDLE') {
                const elapsed = (performance.now() - transitionStartTime.current) / 1000;
                const progress = Math.min(1.0, elapsed / 1.2);
                rendererRef.current.setTransition(progress, transitionPhase);
            } else {
                rendererRef.current.setTransition(0, 'IDLE');
            }

            drawFrame();
            frameId = requestAnimationFrame(loop);
        };

        engine.onWin = (team) => {
            onWin(team);
        };

        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, [engine, onWin, hoveredSkill, transitionPhase]);

    // Input Handling
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getScreenCoords = (x: number, y: number) => {
            const rect = cvs.getBoundingClientRect();
            return {
                x: x - rect.left,
                y: y - rect.top
            };
        };

        const getHexFromCoords = (sx: number, sy: number) => {
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            if (hex) return hex;

            return HexUtils.fromPx(
                sx / camera.current.zoom + camera.current.x,
                sy / camera.current.zoom + camera.current.y,
                engine.mapConfig
            );
        };

        const getHitAgentFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const wy = sy / camera.current.zoom + camera.current.y;
            const sorted = [...engine.agents].sort((a, b) => b.py - a.py);

            for (const agent of sorted) {
                if (agent.hp <= 0 && agent.fullyDead) continue;
                const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);
                const baseX = agent.px;
                const baseY = agent.py - h;
                // Hitbox: Broaden slightly for ease of touch
                const dx = Math.abs(wx - baseX);
                const dy = wy - (baseY - 40); 
                if (dx < 35 && Math.abs(dy) < 60) return agent;
            }
            return null;
        };

        const getWorldPosFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            let h = BLOCK_HEIGHT + 6;
            if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
            const wy = sy / camera.current.zoom + camera.current.y + h;
            return { x: wx, y: wy };
        };

        // --- UNIFIED ACTION HANDLER ---
        // Executes Tool Action (Spawn, Delete, Paint) on a specific Hex
        const executeToolAction = (h: Hex) => {
            if (engine.isRunning || winner !== null) return;
            const k = HexUtils.key(h);
            if (lastPaintHex.current === k) return; 

            lastPaintHex.current = k;

            const existingAgent = engine.getAgentAt(h.q, h.r);
            let agent: Agent | null = null;

            // Delete Tool Overrides everything
            if (tool === ToolType.DELETE) {
                if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
                if (existingAgent) {
                    engine.removeAgent(h.q, h.r);
                    onSelect(null);
                }
                return;
            }

            // Obstacle Painting
            if (tool === ToolType.OBSTACLE) {
                if (existingAgent) engine.removeAgent(h.q, h.r);
                engine.setObstacle(h.q, h.r, selectedObstacle);
                return;
            }

            // Unit Spawning (Only if empty)
            if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
                if (tool === ToolType.ADD_BLUE) {
                    agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
                } else if (tool === ToolType.ADD_RED) {
                    agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);
                }
            }

            // DRAFT MODE LOGIC
            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;

                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];
                agent.saveState();
                agent.reset(engine.mapConfig);
            }
        };

        // --- INPUT HANDLERS ---

        const handleDown = (sx: number, sy: number, button: number = 0) => {
            pressStartPos.current = { x: sx, y: sy };
            lastPaintHex.current = "";

            // Right Click = Pan
            if (button === 2) {
                isPanning.current = true;
                return;
            }

            if (engine.isRunning) return; // No interaction during playback (except pan/select)

            // 1. PRIORITY: HIT AGENT (Select/Drag)
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (hitAgent) {
                if (tool === ToolType.DELETE) {
                    pressedAgentRef.current = hitAgent;
                } else {
                    pressedAgentRef.current = hitAgent;
                    dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
                    onSelect(hitAgent); 
                }
                return;
            }

            // 2. SECONDARY: OBSTACLE HIT (Drag)
            const h = getHexFromCoords(sx, sy);
            if (engine.hasObstacle(h.q, h.r)) {
                // If DELETE tool, we might want to just click to delete, handled in handleUp.
                // But dragging obstacles is now a feature.
                if (tool !== ToolType.DELETE) {
                    const obsType = engine.obstacles.get(HexUtils.key(h));
                    if (obsType) {
                        const wPos = getWorldPosFromCoords(sx, sy);
                        draggedObstacleRef.current = {
                            type: obsType,
                            originQ: h.q,
                            originR: h.r,
                            px: wPos.x,
                            py: wPos.y
                        };
                        engine.removeObstacle(h.q, h.r);
                        // Visual selection feedback?
                        onSelect(null);
                        return;
                    }
                }
            }

            // 3. TERTIARY: EMPTY TILE (Tool Action / Select)
            const gridAgent = engine.getAgentAt(h.q, h.r);
            if (gridAgent) {
                pressedAgentRef.current = gridAgent;
                dragStartHex.current = { q: gridAgent.q, r: gridAgent.r };
                onSelect(gridAgent);
                return;
            }

            // Paint Mode Start
            isPainting.current = true;
            if (tool === ToolType.OBSTACLE || tool === ToolType.DELETE) {
                if (engine.isValid(h.q, h.r)) executeToolAction(h);
            }
        };

        const handleMove = (sx: number, sy: number, dx: number, dy: number) => {
            const h = getHexFromCoords(sx, sy);
            hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

            // Cursor Logic
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (cvs) {
                if (isDraggingUnit.current || draggedObstacleRef.current) cvs.style.cursor = 'grabbing';
                else if (hitAgent) cvs.style.cursor = 'pointer'; 
                else if (engine.hasObstacle(h.q, h.r)) cvs.style.cursor = 'grab';
                else if (tool === ToolType.SELECT) cvs.style.cursor = 'default';
                else cvs.style.cursor = 'crosshair'; 
            }

            if (isPanning.current) {
                camera.current.x -= dx / camera.current.zoom;
                camera.current.y -= dy / camera.current.zoom;
                return;
            }

            // DRAG LOGIC: UNIT
            if (pressedAgentRef.current && !engine.isRunning && tool !== ToolType.DELETE) {
                if (isDraggingUnit.current) {
                    const wPos = getWorldPosFromCoords(sx, sy);
                    pressedAgentRef.current.px = wPos.x;
                    pressedAgentRef.current.py = wPos.y;
                    pressedAgentRef.current.physics.z = 20; 
                    return;
                }
                if (pressStartPos.current) {
                    const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);
                    if (dist > 10) { 
                        isDraggingUnit.current = true;
                        const wPos = getWorldPosFromCoords(sx, sy);
                        pressedAgentRef.current.px = wPos.x;
                        pressedAgentRef.current.py = wPos.y;
                    }
                }
            }

            // DRAG LOGIC: OBSTACLE
            if (draggedObstacleRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                draggedObstacleRef.current.px = wPos.x;
                draggedObstacleRef.current.py = wPos.y;
                return; // Consume event
            }

            // CHECK DRAG THRESHOLD FOR OBSTACLE START
            // (Handled implicitly since we set draggedObstacleRef immediately on Down for instant feedback, 
            // but effectively we might want threshold. But for obstacles, picking up immediately feels fine.)

            // PAINT LOGIC
            if (isPainting.current && !isDraggingUnit.current && !draggedObstacleRef.current && (tool === ToolType.OBSTACLE || tool === ToolType.DELETE)) {
                if (engine.isValid(h.q, h.r)) {
                    executeToolAction(h);
                }
            }

            // Pan on Drag Background
            if (!isPainting.current && !pressedAgentRef.current && !draggedObstacleRef.current && pressStartPos.current) {
                const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);
                if (dist > 5) {
                    isPanning.current = true;
                    camera.current.x -= dx / camera.current.zoom;
                    camera.current.y -= dy / camera.current.zoom;
                }
            }
        };

        const handleUp = (sx: number, sy: number) => {
            const h = getHexFromCoords(sx, sy);

            if (isPanning.current) {
                isPanning.current = false;
                pressStartPos.current = null;
                return;
            }

            // 1. END UNIT DRAG
            if (isDraggingUnit.current && pressedAgentRef.current) {
                const agent = pressedAgentRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const isObstacle = engine.obstacles.has(HexUtils.key(h));
                const occupant = engine.getAgentAt(h.q, h.r);
                const isOccupiedByOther = occupant && occupant !== agent;

                agent.physics.z = 0;

                if (isValidHex && !isObstacle && !isOccupiedByOther) {
                    engine.updateAgentPosition(agent, h.q, h.r);
                    const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                    agent.px = p.x; agent.py = p.y;
                } else {
                    if (dragStartHex.current) {
                        agent.q = dragStartHex.current.q;
                        agent.r = dragStartHex.current.r;
                        const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                        agent.px = p.x; agent.py = p.y;
                        engine.updateAgentPosition(agent, agent.q, agent.r);
                    }
                }
                isDraggingUnit.current = false;
                dragStartHex.current = null;
                onSelect(agent);
            } 
            // 2. END OBSTACLE DRAG
            else if (draggedObstacleRef.current) {
                const { type, originQ, originR } = draggedObstacleRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const occupant = engine.getAgentAt(h.q, h.r);
                const hasExistingObstacle = engine.hasObstacle(h.q, h.r); // Might be another one

                if (isValidHex && !occupant && !hasExistingObstacle) {
                    // Success Place
                    engine.setObstacle(h.q, h.r, type);
                } else {
                    // Revert
                    engine.setObstacle(originQ, originR, type);
                }
                draggedObstacleRef.current = null;
            }
            // 3. CLICK (Tap)
            else if (pressStartPos.current) {
                const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);

                if (dist < 10) {
                    if (pressedAgentRef.current) {
                        if (tool === ToolType.DELETE) {
                            const a = pressedAgentRef.current;
                            engine.removeAgent(a.q, a.r);
                            onSelect(null);
                        } else {
                            onSelect(pressedAgentRef.current);
                        }
                    } 
                    else if (tool !== ToolType.SELECT && tool !== ToolType.DELETE) {
                        // Place Unit / Toggle Obstacle (Single Tap)
                        if (engine.isValid(h.q, h.r)) executeToolAction(h);
                    }
                    else if (tool === ToolType.DELETE) {
                        // Click to delete obstacle
                        if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
                    }
                    else {
                        onSelect(null);
                    }
                }
            }

            // Cleanup
            pressedAgentRef.current = null;
            isPainting.current = false;
            pressStartPos.current = null;
            lastPaintHex.current = "";
            if (cvs) cvs.style.cursor = 'default';
        };

        // Mouse Listeners
        const handleMouseDown = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleDown(pos.x, pos.y, e.button);
        };
        const handleMouseMove = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleMove(pos.x, pos.y, e.movementX, e.movementY);
        };
        const handleMouseUp = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleUp(pos.x, pos.y);
        };

        // Touch Listeners
        const onTouchStart = (e: TouchEvent) => {
            if (e.touches.length === 1) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                lastTouchPos.current = pos;
                handleDown(pos.x, pos.y, 0);
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                isDraggingUnit.current = false;
                pressedAgentRef.current = null;
                draggedObstacleRef.current = null; // Cancel drag
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            e.preventDefault(); 
            if (e.touches.length === 1 && lastTouchPos.current) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const dx = pos.x - lastTouchPos.current.x;
                const dy = pos.y - lastTouchPos.current.y;
                handleMove(pos.x, pos.y, dx, dy);
                lastTouchPos.current = pos;
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                const currentDist = Math.hypot(t1.x - t2.x, t1.y - t2.y);

                if (lastPinchDist.current > 0) {
                    const delta = currentDist - lastPinchDist.current;
                    const zoomSensitivity = 0.005;
                    camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta * zoomSensitivity));
                }
                lastPinchDist.current = currentDist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            e.preventDefault();
            if (e.changedTouches.length > 0 && lastTouchPos.current) {
                const pos = getScreenCoords(e.changedTouches[0].clientX, e.changedTouches[0].clientY);
                handleUp(pos.x, pos.y);
            }
            lastTouchPos.current = null;
            lastPinchDist.current = 0;
        };

        const handleWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        };

        const handleContextMenu = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        cvs.addEventListener('wheel', handleWheel, { passive: false });
        cvs.addEventListener('contextmenu', handleContextMenu);

        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            cvs.removeEventListener('wheel', handleWheel);
            cvs.removeEventListener('contextmenu', handleContextMenu);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
        };
    }, [engine, tool, selectedObstacle, hpInput, onSelect, winner, spawnMode, draftRole]);

    return (
        <div ref={wrapperRef} className="flex-1 overflow-hidden relative bg-slate-950 border-r border-slate-700">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner`}
                style={{ backgroundColor: engine.currentScene.background }} 
            />

            {/* STANDARD MODE VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import React, { useRef, useEffect } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { HexUtils } from '../engine/utils';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Hex, Skill, GameEvent, Role } from '../types';
import { BLOCK_HEIGHT } from '../constants'; 

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = ({ engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, isShowcaseMode, spawnMode, draftRole, onSelect, onWin, winner, rematch, transitionPhase }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 }); 
    const fpsRef = useRef(60);

    // Instantiate Renderer
    const rendererRef = useRef(new GameRenderer());
    const transitionStartTime = useRef(0);

    // Bridge for Synchronous Redraw
    const drawCurrentFrameRef = useRef<() => void>(() => {});

    // Handle Transition Phase Timing
    useEffect(() => {
        transitionStartTime.current = performance.now();
    }, [transitionPhase]);

    // --- INTERACTION STATE ---
    // Interaction Mode State Machine
    type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';
    const interactionMode = useRef<InteractionMode>('IDLE');

    // Unit Dragging
    const pressedAgentRef = useRef<Agent | null>(null);

    // Obstacle Dragging
    const draggedObstacleRef = useRef<{ 
        type: string; 
        originQ: number; 
        originR: number; 
        px: number; 
        py: number; 
    } | null>(null);

    // General Input State
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const lastPaintHex = useRef<string>(""); 

    // Touch specific state
    const lastPinchDist = useRef<number>(0);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);

    // Track hovered hex for visual feedback
    const hoveredHexRef = useRef<Hex | null>(null);

    // Track selected agent for the render loop
    const selectedAgentRef = useRef<Agent | null>(selectedAgent);
    useEffect(() => {
        selectedAgentRef.current = selectedAgent;
    }, [selectedAgent]);

    // --- Camera Control Logic ---
    const centerCamera = () => {
        if (!canvasRef.current || !wrapperRef.current) return;

        canvasRef.current.width = wrapperRef.current.clientWidth;
        canvasRef.current.height = wrapperRef.current.clientHeight;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        camera.current.x = p.x - (canvasRef.current.width / camera.current.zoom) / 2;
        camera.current.y = p.y + verticalOffset - (canvasRef.current.height / camera.current.zoom) / 2;
    };

    useEffect(() => {
        if (isShowcaseMode || transitionPhase === 'IN') {
            const t = setTimeout(centerCamera, 350);
            return () => clearTimeout(t);
        } else if (!isShowcaseMode && transitionPhase === 'IDLE') {
             const t = setTimeout(centerCamera, 350);
             return () => clearTimeout(t);
        }
    }, [isShowcaseMode, transitionPhase, engine.mapConfig.w, engine.mapConfig.h]);

    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;
        const resizeObserver = new ResizeObserver(() => {
            if (wrapperRef.current && canvasRef.current) {
                canvasRef.current.width = wrapperRef.current.clientWidth;
                canvasRef.current.height = wrapperRef.current.clientHeight;
                if (engine.agents.length === 0) centerCamera();
                drawCurrentFrameRef.current();
            }
        });
        resizeObserver.observe(wrapperRef.current);
        centerCamera();
        return () => resizeObserver.disconnect();
    }, [engine]);

    // Render Loop
    useEffect(() => {
        let frameId: number;
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const drawFrame = () => {
            const ctx = canvasRef.current?.getContext('2d');
            if (ctx && canvasRef.current) {
                const highlight = pressedAgentRef.current || selectedAgentRef.current || null;
                rendererRef.current.draw(ctx, engine, camera.current, highlight, fpsRef.current, hoveredHexRef.current, hoveredSkill); 

                // Draw Dragged Obstacle Ghost
                if (draggedObstacleRef.current) {
                    const { type, px, py } = draggedObstacleRef.current;
                    const { x, y, zoom } = camera.current;
                    const { width, height } = canvasRef.current;

                    ctx.save();
                    ctx.translate(width / 2, height / 2);
                    ctx.scale(zoom, zoom);
                    ctx.translate(-x - width / 2 / zoom, -y - height / 2 / zoom);

                    const sprite = SpriteManager.getObstacleSprite(type);
                    const liftOffset = 40; // Higher lift for visibility
                    ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.shadowBlur = 30;
                    ctx.shadowOffsetY = 30;
                    ctx.globalAlpha = 0.9;
                    ctx.drawImage(sprite, px - 32, py - 86 - liftOffset);
                    ctx.restore();
                }
            }
        };

        drawCurrentFrameRef.current = drawFrame;

        const loop = (t: number) => {
            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200;
                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }
                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            rendererRef.current.update(dt / 1000, engine);

            if (transitionPhase !== 'IDLE') {
                const elapsed = (performance.now() - transitionStartTime.current) / 1000;
                const progress = Math.min(1.0, elapsed / 1.2);
                rendererRef.current.setTransition(progress, transitionPhase);
            } else {
                rendererRef.current.setTransition(0, 'IDLE');
            }

            drawFrame();
            frameId = requestAnimationFrame(loop);
        };

        engine.onWin = (team) => { onWin(team); };
        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, [engine, onWin, hoveredSkill, transitionPhase]);

    // Input Handling
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getScreenCoords = (x: number, y: number) => {
            const rect = cvs.getBoundingClientRect();
            return { x: x - rect.left, y: y - rect.top };
        };

        const getHexFromCoords = (sx: number, sy: number) => {
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            if (hex) return hex;
            return HexUtils.fromPx(
                sx / camera.current.zoom + camera.current.x,
                sy / camera.current.zoom + camera.current.y,
                engine.mapConfig
            );
        };

        const getHitAgentFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const wy = sy / camera.current.zoom + camera.current.y;
            const sorted = [...engine.agents].sort((a, b) => b.py - a.py);

            for (const agent of sorted) {
                if (agent.hp <= 0 && agent.fullyDead) continue;
                const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);
                const baseX = agent.px;
                const baseY = agent.py - h;
                const dx = Math.abs(wx - baseX);
                const dy = wy - (baseY - 40); 
                if (dx < 35 && Math.abs(dy) < 60) return agent;
            }
            return null;
        };

        const getWorldPosFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            let h = BLOCK_HEIGHT + 6;
            if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
            const wy = sy / camera.current.zoom + camera.current.y + h;
            return { x: wx, y: wy };
        };

        const executeToolAction = (h: Hex) => {
            if (engine.isRunning || winner !== null) return;
            const k = HexUtils.key(h);
            if (lastPaintHex.current === k) return; 

            lastPaintHex.current = k;
            const existingAgent = engine.getAgentAt(h.q, h.r);
            let agent: Agent | null = null;

            if (tool === ToolType.DELETE) {
                if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
                if (existingAgent) {
                    engine.removeAgent(h.q, h.r);
                    onSelect(null);
                }
                return;
            }

            if (tool === ToolType.OBSTACLE) {
                if (existingAgent) engine.removeAgent(h.q, h.r);
                engine.setObstacle(h.q, h.r, selectedObstacle);
                return;
            }

            if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
                if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
                else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);
            }

            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];
                agent.saveState();
                agent.reset(engine.mapConfig);
            }
        };

        // --- UNIFIED INPUT HANDLER ---

        const handleDown = (sx: number, sy: number, button: number = 0) => {
            pressStartPos.current = { x: sx, y: sy };
            lastPaintHex.current = "";
            interactionMode.current = 'DOWN';

            // Right Click always Pans
            if (button === 2) {
                interactionMode.current = 'PAN';
                return;
            }

            if (engine.isRunning) {
                interactionMode.current = 'PAN';
                return;
            }

            // Identify potential targets for drag start
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (hitAgent) {
                pressedAgentRef.current = hitAgent;
                if (tool !== ToolType.DELETE) {
                    dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
                }
                // Don't set mode to DRAG_UNIT yet, wait for move threshold
                return;
            }

            // Check Obstacle
            const h = getHexFromCoords(sx, sy);
            const validGrid = engine.isValid(h.q, h.r);

            if (validGrid && engine.hasObstacle(h.q, h.r)) {
                if (tool !== ToolType.DELETE) {
                    // Pre-load obstacle drag data but don't activate
                    const obsType = engine.obstacles.get(HexUtils.key(h));
                    if (obsType) {
                        draggedObstacleRef.current = {
                            type: obsType,
                            originQ: h.q, originR: h.r,
                            px: 0, py: 0
                        };
                    }
                }
            }
        };

        const handleMove = (sx: number, sy: number, dx: number, dy: number) => {
            const h = getHexFromCoords(sx, sy);
            hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

            // Cursor Logic
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (cvs) {
                if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
                else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
                else if (hitAgent) cvs.style.cursor = 'pointer'; 
                else if (engine.hasObstacle(h.q, h.r)) cvs.style.cursor = 'grab';
                else if (tool === ToolType.SELECT) cvs.style.cursor = 'default';
                else cvs.style.cursor = 'crosshair'; 
            }

            // 1. If IDLE, just update cursor (already done above)
            if (interactionMode.current === 'IDLE') return;

            // 2. If PANNING, apply movement
            if (interactionMode.current === 'PAN') {
                camera.current.x -= dx / camera.current.zoom;
                camera.current.y -= dy / camera.current.zoom;
                return;
            }

            // 3. If PAINTING, execute paint
            if (interactionMode.current === 'PAINT') {
                if (engine.isValid(h.q, h.r)) {
                    executeToolAction(h);
                }
                return;
            }

            // 4. If DRAGGING UNIT
            if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                pressedAgentRef.current.px = wPos.x;
                pressedAgentRef.current.py = wPos.y;
                return;
            }

            // 5. If DRAGGING OBS
            if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                draggedObstacleRef.current.px = wPos.x;
                draggedObstacleRef.current.py = wPos.y;
                return;
            }

            // 6. ARBITRATION (Transition from DOWN to specific mode)
            if (interactionMode.current === 'DOWN' && pressStartPos.current) {
                const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);

                // Threshold exceeded: Decide intent
                if (dist > 10) {
                    // A. Prioritize Unit Drag
                    if (pressedAgentRef.current && tool !== ToolType.DELETE) {
                        interactionMode.current = 'DRAG_UNIT';
                        pressedAgentRef.current.physics.z = 20; // Lift visual
                        onSelect(pressedAgentRef.current);
                        return;
                    }

                    // B. Secondary Obstacle Drag
                    if (draggedObstacleRef.current && tool !== ToolType.DELETE) {
                        interactionMode.current = 'DRAG_OBS';
                        // Lift logical obstacle from map
                        const { originQ, originR } = draggedObstacleRef.current;
                        engine.removeObstacle(originQ, originR);
                        onSelect(null);

                        // Set initial visual pos
                        const wPos = getWorldPosFromCoords(sx, sy);
                        draggedObstacleRef.current.px = wPos.x;
                        draggedObstacleRef.current.py = wPos.y;
                        return;
                    }

                    // C. Paint vs Pan
                    // If hitting a valid tile AND using a paint-friendly tool (Obstacle/Delete)
                    if (engine.isValid(h.q, h.r) && (tool === ToolType.OBSTACLE || tool === ToolType.DELETE)) {
                        interactionMode.current = 'PAINT';
                        executeToolAction(h);
                    } else {
                        // Default to Pan for Unit Spawning tools or Select tool on empty space
                        interactionMode.current = 'PAN';
                        // Catch up camera movement for the initial drag distance
                        camera.current.x -= dx / camera.current.zoom;
                        camera.current.y -= dy / camera.current.zoom;
                    }
                }
            }
        };

        const handleUp = (sx: number, sy: number) => {
            const h = getHexFromCoords(sx, sy);

            // 1. CLICK Logic (If we never left DOWN state)
            if (interactionMode.current === 'DOWN') {
                if (pressedAgentRef.current) {
                    if (tool === ToolType.DELETE) {
                        const a = pressedAgentRef.current;
                        engine.removeAgent(a.q, a.r);
                        onSelect(null);
                    } else {
                        onSelect(pressedAgentRef.current);
                    }
                } else if (engine.hasObstacle(h.q, h.r)) {
                    if (tool === ToolType.DELETE) {
                        engine.removeObstacle(h.q, h.r);
                    }
                    // Else: Select obstacle? Not implemented, maybe highlight.
                } else if (tool !== ToolType.SELECT && tool !== ToolType.DELETE) {
                    // Place Unit logic
                    if (engine.isValid(h.q, h.r)) executeToolAction(h);
                } else {
                    // Click on empty/void with Select tool
                    onSelect(null);
                }
            }

            // 2. Drop Unit
            if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
                const agent = pressedAgentRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const isObstacle = engine.obstacles.has(HexUtils.key(h));
                const occupant = engine.getAgentAt(h.q, h.r);
                const isOccupiedByOther = occupant && occupant !== agent;

                agent.physics.z = 0; // Drop visual

                if (isValidHex && !isObstacle && !isOccupiedByOther) {
                    engine.updateAgentPosition(agent, h.q, h.r);
                    const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                    agent.px = p.x; agent.py = p.y;
                } else {
                    // Revert
                    if (dragStartHex.current) {
                        agent.q = dragStartHex.current.q;
                        agent.r = dragStartHex.current.r;
                        const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                        agent.px = p.x; agent.py = p.y;
                        engine.updateAgentPosition(agent, agent.q, agent.r);
                    }
                }
                onSelect(agent);
            }

            // 3. Drop Obstacle
            if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
                const { type, originQ, originR } = draggedObstacleRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const occupant = engine.getAgentAt(h.q, h.r);
                const hasExistingObstacle = engine.hasObstacle(h.q, h.r);

                if (isValidHex && !occupant && !hasExistingObstacle) {
                    engine.setObstacle(h.q, h.r, type);
                } else {
                    engine.setObstacle(originQ, originR, type); // Revert
                }
            }

            // Reset
            interactionMode.current = 'IDLE';
            pressedAgentRef.current = null;
            draggedObstacleRef.current = null;
            pressStartPos.current = null;
            lastPaintHex.current = "";
            if (cvs) cvs.style.cursor = 'default';
        };

        // Event Listeners
        const handleMouseDown = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleDown(pos.x, pos.y, e.button);
        };
        const handleMouseMove = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleMove(pos.x, pos.y, e.movementX, e.movementY);
        };
        const handleMouseUp = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleUp(pos.x, pos.y);
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.touches.length === 1) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                lastTouchPos.current = pos;
                handleDown(pos.x, pos.y, 0);
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                // Reset interaction if pinch starts
                interactionMode.current = 'IDLE';
                pressedAgentRef.current = null;
                draggedObstacleRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault(); 
            if (e.touches.length === 1 && lastTouchPos.current) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const dx = pos.x - lastTouchPos.current.x;
                const dy = pos.y - lastTouchPos.current.y;
                handleMove(pos.x, pos.y, dx, dy);
                lastTouchPos.current = pos;
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                const currentDist = Math.hypot(t1.x - t2.x, t1.y - t2.y);

                if (lastPinchDist.current > 0) {
                    const delta = currentDist - lastPinchDist.current;
                    const zoomSensitivity = 0.005;
                    camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta * zoomSensitivity));
                }
                lastPinchDist.current = currentDist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.changedTouches.length > 0 && lastTouchPos.current) {
                const pos = getScreenCoords(e.changedTouches[0].clientX, e.changedTouches[0].clientY);
                handleUp(pos.x, pos.y);
            }
            lastTouchPos.current = null;
            lastPinchDist.current = 0;
        };

        const handleWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        };

        const handleContextMenu = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        cvs.addEventListener('wheel', handleWheel, { passive: false });
        cvs.addEventListener('contextmenu', handleContextMenu);

        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            cvs.removeEventListener('wheel', handleWheel);
            cvs.removeEventListener('contextmenu', handleContextMenu);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
        };
    }, [engine, tool, selectedObstacle, hpInput, onSelect, winner, spawnMode, draftRole]);

    return (
        <div ref={wrapperRef} className="flex-1 overflow-hidden relative bg-slate-950 border-r border-slate-700">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner`}
                style={{ backgroundColor: engine.currentScene.background }} 
            />

            {/* STANDARD MODE VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50 pointer-events-auto">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

