export default App;

import React, { useRef, useEffect } from 'react';
import { Agent, GameEngine } from '../engine/game';
import { GameRenderer } from '../engine/renderer';
import { HexUtils } from '../engine/utils';
import { SpriteManager } from '../engine/sprites';
import { Team, ToolType, Hex, Skill, GameEvent, Role } from '../types';
import { BLOCK_HEIGHT } from '../constants'; 

interface GameCanvasProps {
    engine: GameEngine;
    tool: ToolType;
    selectedObstacle: string; 
    hpInput: number;
    selectedAgent: Agent | null; 
    hoveredSkill: Skill | null;
    isShowcaseMode: boolean; 
    spawnMode: 'RANDOM' | 'DRAFT';
    draftRole: Role; 
    onSelect: (a: Agent | null) => void;
    onWin: (team: Team) => void;
    winner: Team | null;
    rematch: () => void;
    transitionPhase: 'IDLE' | 'IN' | 'OUT';
}

const GameCanvas: React.FC<GameCanvasProps> = ({ engine, tool, selectedObstacle, hpInput, selectedAgent, hoveredSkill, isShowcaseMode, spawnMode, draftRole, onSelect, onWin, winner, rematch, transitionPhase }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const wrapperRef = useRef<HTMLDivElement>(null);
    const camera = useRef({ x: 0, y: 0, zoom: 1.0 }); 
    const fpsRef = useRef(60);

    // Instantiate Renderer
    const rendererRef = useRef(new GameRenderer());
    const transitionStartTime = useRef(0);

    // Bridge for Synchronous Redraw
    const drawCurrentFrameRef = useRef<() => void>(() => {});

    // Handle Transition Phase Timing
    useEffect(() => {
        transitionStartTime.current = performance.now();
    }, [transitionPhase]);

    // --- INTERACTION STATE ---
    // Interaction Mode State Machine
    type InteractionMode = 'IDLE' | 'DOWN' | 'DRAG_UNIT' | 'DRAG_OBS' | 'PAN' | 'PAINT';
    const interactionMode = useRef<InteractionMode>('IDLE');

    // Unit Dragging
    const pressedAgentRef = useRef<Agent | null>(null);

    // Obstacle Dragging
    const draggedObstacleRef = useRef<{ 
        type: string; 
        originQ: number; 
        originR: number; 
        px: number; 
        py: number; 
    } | null>(null);

    // General Input State
    const pressStartPos = useRef<{x: number, y: number} | null>(null);
    const dragStartHex = useRef<{q: number, r: number} | null>(null);
    const lastPaintHex = useRef<string>(""); 

    // Touch specific state
    const lastPinchDist = useRef<number>(0);
    const lastTouchPos = useRef<{x: number, y: number} | null>(null);

    // Track hovered hex for visual feedback
    const hoveredHexRef = useRef<Hex | null>(null);

    // Track selected agent for the render loop
    const selectedAgentRef = useRef<Agent | null>(selectedAgent);
    useEffect(() => {
        selectedAgentRef.current = selectedAgent;
    }, [selectedAgent]);

    // --- Camera Control Logic ---
    const centerCamera = () => {
        if (!canvasRef.current || !wrapperRef.current) return;

        canvasRef.current.width = wrapperRef.current.clientWidth;
        canvasRef.current.height = wrapperRef.current.clientHeight;

        const cw = engine.mapConfig.w;
        const ch = engine.mapConfig.h;

        const centerHex = { q: Math.floor(cw / 2), r: Math.floor(ch / 2) };
        const p = HexUtils.toPx(centerHex.q, centerHex.r, engine.mapConfig);
        const verticalOffset = -BLOCK_HEIGHT * 2; 

        camera.current.x = p.x - (canvasRef.current.width / camera.current.zoom) / 2;
        camera.current.y = p.y + verticalOffset - (canvasRef.current.height / camera.current.zoom) / 2;
    };

    useEffect(() => {
        if (isShowcaseMode || transitionPhase === 'IN') {
            const t = setTimeout(centerCamera, 350);
            return () => clearTimeout(t);
        } else if (!isShowcaseMode && transitionPhase === 'IDLE') {
             const t = setTimeout(centerCamera, 350);
             return () => clearTimeout(t);
        }
    }, [isShowcaseMode, transitionPhase, engine.mapConfig.w, engine.mapConfig.h]);

    useEffect(() => {
        if (!wrapperRef.current || !canvasRef.current) return;
        const resizeObserver = new ResizeObserver(() => {
            if (wrapperRef.current && canvasRef.current) {
                canvasRef.current.width = wrapperRef.current.clientWidth;
                canvasRef.current.height = wrapperRef.current.clientHeight;
                if (engine.agents.length === 0) centerCamera();
                drawCurrentFrameRef.current();
            }
        });
        resizeObserver.observe(wrapperRef.current);
        centerCamera();
        return () => resizeObserver.disconnect();
    }, [engine]);

    // Render Loop
    useEffect(() => {
        let frameId: number;
        let lastTime = 0;
        let acc = 0;
        const targetFPS = 60;
        const step = 1000 / targetFPS;
        let frameCount = 0;
        let lastFpsTime = 0;

        const drawFrame = () => {
            const ctx = canvasRef.current?.getContext('2d');
            if (ctx && canvasRef.current) {
                const highlight = pressedAgentRef.current || selectedAgentRef.current || null;
                rendererRef.current.draw(ctx, engine, camera.current, highlight, fpsRef.current, hoveredHexRef.current, hoveredSkill); 

                // Draw Dragged Obstacle Ghost
                if (draggedObstacleRef.current) {
                    const { type, px, py } = draggedObstacleRef.current;
                    const { x, y, zoom } = camera.current;
                    const { width, height } = canvasRef.current;

                    ctx.save();
                    ctx.translate(width / 2, height / 2);
                    ctx.scale(zoom, zoom);
                    ctx.translate(-x - width / 2 / zoom, -y - height / 2 / zoom);

                    const sprite = SpriteManager.getObstacleSprite(type);
                    const liftOffset = 40; // Higher lift for visibility
                    ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.shadowBlur = 30;
                    ctx.shadowOffsetY = 30;
                    ctx.globalAlpha = 0.9;
                    // Adjusted offset from 86 to 80 to match engine renderer
                    ctx.drawImage(sprite, px - 32, py - 80 - liftOffset);
                    ctx.restore();
                }
            }
        };

        drawCurrentFrameRef.current = drawFrame;

        const loop = (t: number) => {
            if (!lastTime) lastTime = t;
            const dt = t - lastTime;
            lastTime = t;

            frameCount++;
            if (t - lastFpsTime >= 1000) {
                fpsRef.current = frameCount;
                frameCount = 0;
                lastFpsTime = t;
            }

            if (engine.isRunning) {
                acc += dt;
                if (acc > 200) acc = 200;
                const frameEvents: GameEvent[] = [];
                while (acc >= step) {
                    const sdt = (step / 1000) * engine.timeScale;
                    engine.tick(sdt);
                    engine.battleTime += sdt;
                    acc -= step;
                    frameEvents.push(...engine.events);
                }
                if (frameEvents.length > 0) {
                    rendererRef.current.processEventsWithEngine(frameEvents, engine);
                }
            }

            rendererRef.current.update(dt / 1000, engine);

            if (transitionPhase !== 'IDLE') {
                const elapsed = (performance.now() - transitionStartTime.current) / 1000;
                const progress = Math.min(1.0, elapsed / 1.2);
                rendererRef.current.setTransition(progress, transitionPhase);
            } else {
                rendererRef.current.setTransition(0, 'IDLE');
            }

            drawFrame();
            frameId = requestAnimationFrame(loop);
        };

        engine.onWin = (team) => { onWin(team); };
        frameId = requestAnimationFrame(loop);
        return () => cancelAnimationFrame(frameId);
    }, [engine, onWin, hoveredSkill, transitionPhase]);

    // Input Handling
    useEffect(() => {
        const cvs = canvasRef.current;
        if (!cvs) return;

        const getScreenCoords = (x: number, y: number) => {
            const rect = cvs.getBoundingClientRect();
            return { x: x - rect.left, y: y - rect.top };
        };

        const getHexFromCoords = (sx: number, sy: number) => {
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            if (hex) return hex;
            return HexUtils.fromPx(
                sx / camera.current.zoom + camera.current.x,
                sy / camera.current.zoom + camera.current.y,
                engine.mapConfig
            );
        };

        const getHitAgentFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const wy = sy / camera.current.zoom + camera.current.y;
            const sorted = [...engine.agents].sort((a, b) => b.py - a.py);

            for (const agent of sorted) {
                if (agent.hp <= 0 && agent.fullyDead) continue;
                const h = rendererRef.current.getTerrainHeight(agent.q, agent.r, engine);
                const baseX = agent.px;
                const baseY = agent.py - h;
                const dx = Math.abs(wx - baseX);
                const dy = wy - (baseY - 40); 
                if (dx < 35 && Math.abs(dy) < 60) return agent;
            }
            return null;
        };

        const getWorldPosFromCoords = (sx: number, sy: number) => {
            const wx = sx / camera.current.zoom + camera.current.x;
            const hex = rendererRef.current.getHexAtScreenPoint(sx, sy, camera.current, engine);
            let h = BLOCK_HEIGHT + 6;
            if (hex) h = rendererRef.current.getTerrainHeight(hex.q, hex.r, engine);
            const wy = sy / camera.current.zoom + camera.current.y + h;
            return { x: wx, y: wy };
        };

        const executeToolAction = (h: Hex) => {
            if (engine.isRunning || winner !== null) return;
            const k = HexUtils.key(h);
            if (lastPaintHex.current === k) return; 

            lastPaintHex.current = k;
            const existingAgent = engine.getAgentAt(h.q, h.r);
            let agent: Agent | null = null;

            if (tool === ToolType.DELETE) {
                if (engine.hasObstacle(h.q, h.r)) engine.removeObstacle(h.q, h.r);
                if (existingAgent) {
                    engine.removeAgent(h.q, h.r);
                    onSelect(null);
                }
                return;
            }

            if (tool === ToolType.OBSTACLE) {
                if (existingAgent) engine.removeAgent(h.q, h.r);
                engine.setObstacle(h.q, h.r, selectedObstacle);
                return;
            }

            if (!existingAgent && !engine.hasObstacle(h.q, h.r)) {
                if (tool === ToolType.ADD_BLUE) agent = engine.addAgent(Team.BLUE, h.q, h.r, hpInput);
                else if (tool === ToolType.ADD_RED) agent = engine.addAgent(Team.RED, h.q, h.r, hpInput);
            }

            if (agent && spawnMode === 'DRAFT') {
                agent.role = draftRole;
                const validSkills = engine.skillDB.filter(s => s.role === agent!.role && (s.team === undefined || s.team === agent!.team));
                const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;
                agent.skillIds = [
                    rnd(validSkills.filter(s => s.tag === 'ULT')),
                    rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
                    rnd(validSkills.filter(s => s.tag === 'BASIC'))
                ];
                agent.saveState();
                agent.reset(engine.mapConfig);
            }
        };

        // --- UNIFIED INPUT HANDLER ---

        const handleDown = (sx: number, sy: number, button: number = 0) => {
            pressStartPos.current = { x: sx, y: sy };
            lastPaintHex.current = "";
            interactionMode.current = 'DOWN';

            // Right Click always Pans
            if (button === 2) {
                interactionMode.current = 'PAN';
                return;
            }

            if (engine.isRunning) {
                interactionMode.current = 'PAN';
                return;
            }

            // Identify potential targets for drag start
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (hitAgent) {
                pressedAgentRef.current = hitAgent;
                if (tool !== ToolType.DELETE) {
                    dragStartHex.current = { q: hitAgent.q, r: hitAgent.r };
                }
                // Don't set mode to DRAG_UNIT yet, wait for move threshold
                return;
            }

            // Check Obstacle
            const h = getHexFromCoords(sx, sy);
            const validGrid = engine.isValid(h.q, h.r);

            if (validGrid && engine.hasObstacle(h.q, h.r)) {
                if (tool !== ToolType.DELETE) {
                    // Pre-load obstacle drag data but don't activate
                    const obsType = engine.obstacles.get(HexUtils.key(h));
                    if (obsType) {
                        draggedObstacleRef.current = {
                            type: obsType,
                            originQ: h.q, originR: h.r,
                            px: 0, py: 0
                        };
                    }
                }
            }
        };

        const handleMove = (sx: number, sy: number, dx: number, dy: number) => {
            const h = getHexFromCoords(sx, sy);
            hoveredHexRef.current = engine.isValid(h.q, h.r) ? h : null;

            // Cursor Logic
            const hitAgent = getHitAgentFromCoords(sx, sy);
            if (cvs) {
                if (interactionMode.current === 'DRAG_UNIT' || interactionMode.current === 'DRAG_OBS') cvs.style.cursor = 'grabbing';
                else if (interactionMode.current === 'PAN') cvs.style.cursor = 'move';
                else if (hitAgent) cvs.style.cursor = 'pointer'; 
                else if (engine.hasObstacle(h.q, h.r)) cvs.style.cursor = 'grab';
                else if (tool === ToolType.SELECT) cvs.style.cursor = 'default';
                else cvs.style.cursor = 'crosshair'; 
            }

            // 1. If IDLE, just update cursor (already done above)
            if (interactionMode.current === 'IDLE') return;

            // 2. If PANNING, apply movement
            if (interactionMode.current === 'PAN') {
                camera.current.x -= dx / camera.current.zoom;
                camera.current.y -= dy / camera.current.zoom;
                return;
            }

            // 3. If PAINTING, execute paint
            if (interactionMode.current === 'PAINT') {
                if (engine.isValid(h.q, h.r)) {
                    executeToolAction(h);
                }
                return;
            }

            // 4. If DRAGGING UNIT
            if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                pressedAgentRef.current.px = wPos.x;
                pressedAgentRef.current.py = wPos.y;
                return;
            }

            // 5. If DRAGGING OBS
            if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
                const wPos = getWorldPosFromCoords(sx, sy);
                draggedObstacleRef.current.px = wPos.x;
                draggedObstacleRef.current.py = wPos.y;
                return;
            }

            // 6. ARBITRATION (Transition from DOWN to specific mode)
            if (interactionMode.current === 'DOWN' && pressStartPos.current) {
                const dist = Math.sqrt((sx - pressStartPos.current.x)**2 + (sy - pressStartPos.current.y)**2);

                // Threshold exceeded: Decide intent
                if (dist > 10) {
                    // A. Prioritize Unit Drag
                    if (pressedAgentRef.current && tool !== ToolType.DELETE) {
                        interactionMode.current = 'DRAG_UNIT';
                        pressedAgentRef.current.physics.z = 20; // Lift visual
                        onSelect(pressedAgentRef.current);
                        return;
                    }

                    // B. Secondary Obstacle Drag
                    if (draggedObstacleRef.current && tool !== ToolType.DELETE) {
                        interactionMode.current = 'DRAG_OBS';
                        // Lift logical obstacle from map
                        const { originQ, originR } = draggedObstacleRef.current;
                        engine.removeObstacle(originQ, originR);
                        onSelect(null);

                        // Set initial visual pos
                        const wPos = getWorldPosFromCoords(sx, sy);
                        draggedObstacleRef.current.px = wPos.x;
                        draggedObstacleRef.current.py = wPos.y;
                        return;
                    }

                    // C. Paint vs Pan
                    // If hitting a valid tile AND using a paint-friendly tool (Obstacle/Delete)
                    if (engine.isValid(h.q, h.r) && (tool === ToolType.OBSTACLE || tool === ToolType.DELETE)) {
                        interactionMode.current = 'PAINT';
                        executeToolAction(h);
                    } else {
                        // Default to Pan for Unit Spawning tools or Select tool on empty space
                        interactionMode.current = 'PAN';
                        // Catch up camera movement for the initial drag distance
                        camera.current.x -= dx / camera.current.zoom;
                        camera.current.y -= dy / camera.current.zoom;
                    }
                }
            }
        };

        const handleUp = (sx: number, sy: number) => {
            const h = getHexFromCoords(sx, sy);

            // 1. CLICK Logic (If we never left DOWN state)
            if (interactionMode.current === 'DOWN') {
                if (pressedAgentRef.current) {
                    if (tool === ToolType.DELETE) {
                        const a = pressedAgentRef.current;
                        engine.removeAgent(a.q, a.r);
                        onSelect(null);
                    } else {
                        onSelect(pressedAgentRef.current);
                    }
                } else if (engine.hasObstacle(h.q, h.r)) {
                    if (tool === ToolType.DELETE) {
                        engine.removeObstacle(h.q, h.r);
                    }
                    // Else: Select obstacle? Not implemented, maybe highlight.
                } else if (tool !== ToolType.SELECT && tool !== ToolType.DELETE) {
                    // Place Unit logic
                    if (engine.isValid(h.q, h.r)) executeToolAction(h);
                } else {
                    // Click on empty/void with Select tool
                    onSelect(null);
                }
            }

            // 2. Drop Unit
            if (interactionMode.current === 'DRAG_UNIT' && pressedAgentRef.current) {
                const agent = pressedAgentRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const isObstacle = engine.obstacles.has(HexUtils.key(h));
                const occupant = engine.getAgentAt(h.q, h.r);
                const isOccupiedByOther = occupant && occupant !== agent;

                agent.physics.z = 0; // Drop visual

                if (isValidHex && !isObstacle && !isOccupiedByOther) {
                    engine.updateAgentPosition(agent, h.q, h.r);
                    const p = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                    agent.px = p.x; agent.py = p.y;
                } else {
                    // Revert
                    if (dragStartHex.current) {
                        agent.q = dragStartHex.current.q;
                        agent.r = dragStartHex.current.r;
                        const p = HexUtils.toPx(agent.q, agent.r, engine.mapConfig);
                        agent.px = p.x; agent.py = p.y;
                        engine.updateAgentPosition(agent, agent.q, agent.r);
                    }
                }
                onSelect(agent);
            }

            // 3. Drop Obstacle
            if (interactionMode.current === 'DRAG_OBS' && draggedObstacleRef.current) {
                const { type, originQ, originR } = draggedObstacleRef.current;
                const isValidHex = engine.isValid(h.q, h.r);
                const occupant = engine.getAgentAt(h.q, h.r);
                const hasExistingObstacle = engine.hasObstacle(h.q, h.r);

                if (isValidHex && !occupant && !hasExistingObstacle) {
                    engine.setObstacle(h.q, h.r, type);
                } else {
                    engine.setObstacle(originQ, originR, type); // Revert
                }
            }

            // Reset
            interactionMode.current = 'IDLE';
            pressedAgentRef.current = null;
            draggedObstacleRef.current = null;
            pressStartPos.current = null;
            lastPaintHex.current = "";
            if (cvs) cvs.style.cursor = 'default';
        };

        // Event Listeners
        const handleMouseDown = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleDown(pos.x, pos.y, e.button);
        };
        const handleMouseMove = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleMove(pos.x, pos.y, e.movementX, e.movementY);
        };
        const handleMouseUp = (e: MouseEvent) => {
            const pos = getScreenCoords(e.clientX, e.clientY);
            handleUp(pos.x, pos.y);
        };

        const onTouchStart = (e: TouchEvent) => {
            if (e.touches.length === 1) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                lastTouchPos.current = pos;
                handleDown(pos.x, pos.y, 0);
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                lastPinchDist.current = Math.hypot(t1.x - t2.x, t1.y - t2.y);
                // Reset interaction if pinch starts
                interactionMode.current = 'IDLE';
                pressedAgentRef.current = null;
                draggedObstacleRef.current = null;
            }
        };

        const onTouchMove = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault(); 
            if (e.touches.length === 1 && lastTouchPos.current) {
                const pos = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const dx = pos.x - lastTouchPos.current.x;
                const dy = pos.y - lastTouchPos.current.y;
                handleMove(pos.x, pos.y, dx, dy);
                lastTouchPos.current = pos;
            } else if (e.touches.length === 2) {
                const t1 = getScreenCoords(e.touches[0].clientX, e.touches[0].clientY);
                const t2 = getScreenCoords(e.touches[1].clientX, e.touches[1].clientY);
                const currentDist = Math.hypot(t1.x - t2.x, t1.y - t2.y);

                if (lastPinchDist.current > 0) {
                    const delta = currentDist - lastPinchDist.current;
                    const zoomSensitivity = 0.005;
                    camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta * zoomSensitivity));
                }
                lastPinchDist.current = currentDist;
            }
        };

        const onTouchEnd = (e: TouchEvent) => {
            if (e.cancelable) e.preventDefault();
            if (e.changedTouches.length > 0 && lastTouchPos.current) {
                const pos = getScreenCoords(e.changedTouches[0].clientX, e.changedTouches[0].clientY);
                handleUp(pos.x, pos.y);
            }
            lastTouchPos.current = null;
            lastPinchDist.current = 0;
        };

        const handleWheel = (e: WheelEvent) => {
            e.preventDefault();
            const delta = e.deltaY > 0 ? -0.1 : 0.1;
            camera.current.zoom = Math.max(0.5, Math.min(3.0, camera.current.zoom + delta));
        };

        const handleContextMenu = (e: MouseEvent) => e.preventDefault();

        cvs.addEventListener('mousedown', handleMouseDown);
        window.addEventListener('mousemove', handleMouseMove);
        window.addEventListener('mouseup', handleMouseUp);
        cvs.addEventListener('wheel', handleWheel, { passive: false });
        cvs.addEventListener('contextmenu', handleContextMenu);

        cvs.addEventListener('touchstart', onTouchStart, { passive: false });
        cvs.addEventListener('touchmove', onTouchMove, { passive: false });
        cvs.addEventListener('touchend', onTouchEnd, { passive: false });

        return () => {
            cvs.removeEventListener('mousedown', handleMouseDown);
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
            cvs.removeEventListener('wheel', handleWheel);
            cvs.removeEventListener('contextmenu', handleContextMenu);
            cvs.removeEventListener('touchstart', onTouchStart);
            cvs.removeEventListener('touchmove', onTouchMove);
            cvs.removeEventListener('touchend', onTouchEnd);
        };
    }, [engine, tool, selectedObstacle, hpInput, onSelect, winner, spawnMode, draftRole]);

    return (
        <div ref={wrapperRef} className="flex-1 overflow-hidden relative bg-slate-950 border-r border-slate-700">
            <canvas 
                ref={canvasRef} 
                className={`block shadow-inner`}
                style={{ backgroundColor: engine.currentScene.background }} 
            />

            {/* STANDARD MODE VICTORY SCREEN */}
            {winner !== null && !isShowcaseMode && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/70 z-50 pointer-events-auto">
                    <div className="text-center p-8 bg-slate-900 rounded-lg border border-slate-700 shadow-2xl animate-bounce-in">
                        <h2 className={`text-4xl font-bold mb-4 font-serif tracking-widest ${winner === Team.BLUE ? 'text-blue-400' : 'text-red-400'}`}>
                            {winner === Team.BLUE ? 'VICTORY' : 'DEFEAT'}
                        </h2>
                        <button onClick={rematch} className="bg-slate-700 hover:bg-slate-600 text-white font-bold py-2 px-6 rounded border border-slate-500">REMATCH</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default GameCanvas;

import { Agent, GameEngine } from "./game";
import { HexUtils } from "./utils";
import { SpriteManager } from "./sprites";
import { Hex, GameEvent, Skill, Team } from "../types";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING } from "../constants";

// Sub-systems
import { GridSystem, RenderableItem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import * as VFXSpawners from "./systems/vfx/spawners"; 
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";

// NEW Renderers
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";

// Constants
const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20; 
const OBSTACLE_Z_INDEX = 10;
// CHANGED: From 86 to 80 to match Sprite Generation Anchor (cy=80)
const OBSTACLE_OFFSET_Y = 80; 

export interface Camera {
    x: number;
    y: number;
    zoom: number;
}

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public hud: HUDSystem;

    // New Composition Renderers
    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;

    // Camera Shake Effects
    private shakeTimer = 0; 
    private shakeIntensity = 0;

    // Transition State
    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.hud = new HUDSystem();

        // Initialize sub-renderers
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, camera: Camera, engine: GameEngine): Hex | null {
        return this.grid.getHexAtScreenPoint(mouseX, mouseY, camera, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        if (this.shakeTimer > 0) {
            this.shakeTimer -= dt;
        }

        // Delegate updates
        this.tacticalRenderer.update(dt, engine);
        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = this.grid.getTerrainHeight(hex.q, hex.r, engine);
            const visualY = event.pos.y - terrainHeight;

            // 1. HUD Events (Floating Text)
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualY - HUD_TEXT_OFFSET; 

                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     color = val > 100 ? '#ef4444' : '#fff'; 
                     size = val > 100 ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) {
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);
                 }

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     this.hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         VFXSpawners.spawnDomainExpansion(this.vfx, event.pos.x, event.pos.y, event.skill.color, 4.0);
                         this.triggerCameraShake(0.5, 8); 
                     }
                 }
            }

            // 2. VFX Handling
            switch (event.type) {
                case 'DAMAGE': 
                    const isHeavy = Math.abs(event.value || 0) > 50;
                    VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY - 20, 0, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');

                    if (isHeavy) {
                        this.triggerCameraShake(0.2, 5); 
                        VFXSpawners.spawnDebris(this.vfx, event.pos.x, visualY - 20, event.color || '#fff', 3);
                    }
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = this.grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const sx = source.px;
                            const sy = source.py - sH - 40; 

                            const tx = event.pos.x;
                            const ty = visualY - 20; 

                            VFXSpawners.spawnBeam(this.vfx, sx, sy, tx, ty, event.color || '#fff');
                            VFXSpawners.spawnExplosion(this.vfx, tx, ty, 0, 8, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualY); 
                    break;

                case 'DEATH':
                    const team = event.team !== undefined ? event.team : Team.BLUE; 
                    VFXSpawners.spawnUnitShatter(this.vfx, event.pos.x, visualY, team);
                    this.triggerCameraShake(0.3, 10);
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(this.vfx, event.pos.x, visualY, event.color || '#fff');
                    break;
            }
        });
    }

    private handleHitVisuals(event: GameEvent, engine: GameEngine, visualY: number): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';

        if (isUlt) {
            this.triggerCameraShake(0.6, 15); 
            VFXSpawners.spawnDivinePillar(this.vfx, event.pos.x, visualY, color, 1.5);
            VFXSpawners.spawnShockwave(this.vfx, event.pos.x, visualY, color, 2.0);

            if (event.skill?.type === 'AOE') {
                const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = this.grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        const distToCenter = Math.abs(h.q - centerHex.q) + Math.abs(h.r - centerHex.r);
                        if (distToCenter > 0) {
                            const delay = distToCenter * 0.05;
                            VFXSpawners.spawnDivinePillar(this.vfx, tilePos.x, tileVisualY, color, 0.7, delay);
                            VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        } else {
                            VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        }
                    }
                });
            } else {
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 3.0);
                VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY, 0, 50, color, 2.0, 1.0, 'SPARK');
            }
        } else {
            if (event.skill?.type === 'AOE') {
                const center = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
                const radius = event.skill.aoeRadius || 1;
                HexUtils.range(center, radius).forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        VFXSpawners.addGridFlash(this.vfx, h.q, h.r, color);
                        if (h.q === center.q && h.r === center.r) {
                            VFXSpawners.addDecal(this.vfx, event.pos.x, visualY, color);
                        }
                    }
                });
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 1.2);
            } else {
                VFXSpawners.addImpact(this.vfx, event.pos.x, visualY, color, 'RING', 0.8);
                VFXSpawners.spawnExplosion(this.vfx, event.pos.x, visualY, 0, 8, color, 1.2, 0.6, 'SPARK');
            }
        }
    }

    private triggerCameraShake(duration: number, intensity: number) {
        this.shakeTimer = duration;
        this.shakeIntensity = intensity;
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const { width: canvasWidth, height: canvasHeight } = ctx.canvas;
        const scene = engine.currentScene;
        const defaultStyle = scene.obstacleStyle || 'WALL'; 

        // 1. Complex Background (Delegated)
        ctx.clearRect(0, 0, canvasWidth, canvasHeight);
        this.backgroundRenderer.draw(ctx, canvasWidth, canvasHeight, scene, engine.mapConfig, this.globalTime);

        // 2. Camera Transform application
        ctx.save();

        let shakeOffsetX = 0;
        let shakeOffsetY = 0;
        if (this.shakeTimer > 0) {
            shakeOffsetX = (Math.random() - 0.5) * this.shakeIntensity;
            shakeOffsetY = (Math.random() - 0.5) * this.shakeIntensity;
        }

        ctx.translate(canvasWidth / 2 + shakeOffsetX, canvasHeight / 2 + shakeOffsetY);
        ctx.scale(camera.zoom, camera.zoom);
        ctx.translate(-camera.x - canvasWidth / 2 / camera.zoom, -camera.y - canvasHeight / 2 / camera.zoom);

        // 3. MAIN PASS: Collect and Sort Renderables
        let renderList: RenderableItem[] = [];

        renderList.push(...this.grid.collectRenderables(
            engine, hoveredHex, hoveredSkill, highlight, 
            this.vfx.state.gridFlashes, engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        ));

        renderList.push(...this.vfxRenderer.collectRenderables(
            engine,
            this.vfx,
            (q, r) => this.grid.getTerrainHeight(q, r, engine),
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        ));

        renderList.push(...this.unit.collectRenderables(
            engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), this.globalTime, highlight, engine.mapConfig
        ));

        // Iterate over Obstacles
        engine.obstacles.forEach((type, key) => {
             const [q, r] = key.split(',').map(Number);
             const pos = HexUtils.toPx(q, r, engine.mapConfig);

             let visualY = pos.y;
             if (this.transitionPhase !== 'IDLE') {
                 const centerQ = Math.floor(engine.mapConfig.w / 2);
                 const centerR = Math.floor(engine.mapConfig.h / 2);
                 const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                 const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;
                 const d = dist / maxDist;

                 if (this.transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (this.transitionT > trigger) {
                        const fallT = Math.min(1, (this.transitionT - trigger) * 2.5);
                        visualY += fallT * fallT * fallT * 1000;
                    }
                 } else if (this.transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (this.transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                 }
             }

             if (visualY < pos.y + 800) {
                 const terrainH = this.grid.getTerrainHeight(q, r, engine);
                 renderList.push({
                     y: visualY, z: OBSTACLE_Z_INDEX,
                     draw: (c) => {
                         const sprite = SpriteManager.getObstacleSprite(type || defaultStyle);
                         // REMOVED +20 OFFSET to align visual Y=80 anchor to tile center
                         c.drawImage(sprite, pos.x - 32, visualY - terrainH - OBSTACLE_OFFSET_Y);
                     }
                 });
             }
        });

        renderList.sort((a, b) => {
            if (Math.abs(a.y - b.y) < 2) return a.z - b.z;
            if (a.z > 50 && b.z <= 50) return 1; 
            if (b.z > 50 && a.z <= 50) return -1;
            return a.y - b.y;
        });

        renderList.forEach(item => item.draw(ctx));

        // 4. Occlusion Pass
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    (q, r) => this.grid.getTerrainHeight(q, r, engine), 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 5. Tactical Overlay Lines (World Space) - Delegated
        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        // 6. Top VFX (Delegated to VFX Renderer)
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        // 7. HUD
        this.hud.draw(ctx, engine.agents, (q, r) => this.grid.getTerrainHeight(q, r, engine), engine.mapConfig);

        // 8. Holographic Director HUD (Delegated)
        if (engine.directorTargetId) {
            ctx.restore(); 
            this.tacticalRenderer.drawHUD(ctx, engine, canvasWidth, canvasHeight, camera, this.globalTime);
            ctx.save();
        } else {
            ctx.restore();
            ctx.save();
        }

        ctx.restore(); // Final restore

        // 9. Debug Overlay (Delegated)
        this.tacticalRenderer.drawDebug(ctx, fps);
    }
}

import { GameEngine } from "../../game";
import { HexUtils, Vector, MapConfig } from "../../utils";
import { AssetManager } from "../../assets";
import { RenderableItem } from "../grid";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { Particle } from "../vfx/state"; // Changed import to state

const UNIT_CHEST_HEIGHT = 40;

export class VFXRenderer {

    // --- Helper to calculate vertical offset during map transition ---
    private getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const centerQ = Math.floor(mapConfig.w / 2);
        const centerR = Math.floor(mapConfig.h / 2);
        const hex = HexUtils.fromPx(x, y, mapConfig);
        const maxDist = Math.max(mapConfig.w, mapConfig.h) / 2;
        const dist = Math.sqrt((hex.q - centerQ)**2 + (hex.r - centerR)**2);
        const d = dist / maxDist;

        if (phase === 'OUT') {
            const trigger = d * 0.3;
            if (t > trigger) {
                const fallT = Math.min(1, (t - trigger) * 2.5);
                return fallT * fallT * fallT * 1000;
            }
        } else if (phase === 'IN') {
            const trigger = d * 0.3;
            const riseT = Math.max(0, Math.min(1, (t - trigger) * 2.5));
            const easedRise = 1 - Math.pow(1 - riseT, 3);
            return (1 - easedRise) * 1000;
        }
        return 0;
    }

    // --- Rendering Collections ---

    public collectRenderables(
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        // 1. Decals (Ground Level) - Access via state
        vfx.state.decals.forEach(d => {
            const offsetY = this.getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            list.push({
                y: drawY, z: 0,
                draw: (ctx) => {
                    const img = AssetManager.getBlastZone(d.color);
                    ctx.save();
                    ctx.translate(d.x, drawY);
                    ctx.scale(d.scale, d.scale);
                    ctx.globalAlpha = Math.min(1, d.life);
                    ctx.drawImage(img, -64, -32, 128, 64);
                    ctx.restore();
                }
            });
        });

        // 2. Projectiles (Projectiles are stored in Engine, not VFX state, so this remains same)
        engine.projectiles.forEach(p => {
             const offsetP = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             const getVisualPos = (lx: number, ly: number) => {
                 const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: lx, y: ly});
                 const t = Math.min(1, Math.max(0, currentDist / totalDist));
                 const currentTerrainHeight = hStart + (hEnd - hStart) * t;

                 let arcOffset = 0;
                 // Apply Arc to ARROW, FIREBALL, and BOMB
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'FIREBALL' || p.skill.visual === 'BOMB') {
                     const apex = Math.min(150, totalDist * 0.3);
                     arcOffset = Math.sin(t * Math.PI) * apex; 
                 }

                 const off = this.getTransitionOffset(lx, ly, mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - currentTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     shadowY: ly - currentTerrainHeight + off
                 };
             };

             const headVis = getVisualPos(p.x, p.y);

             // Calculate Pitch Rotation (Visual Angle)
             // Use current direction to target to allow for homing curves
             const lookAheadDist = 5;
             const currentDir = Vector.sub(p.targetPos, {x: p.x, y: p.y});
             const distRemaining = Vector.mag(currentDir);

             // SAFE FALLBACK: If extremely close, keep moving towards target (or use last known good dir)
             // to prevent NaN when normalization fails on 0-length vector
             let dir;
             if (distRemaining > 0.1) {
                 dir = Vector.normalize(currentDir);
             } else {
                 // Fallback to overall trajectory logic to prevent snap
                 const totalTrajectory = Vector.sub(p.targetPos, {x: p.startX, y: p.startY});
                 const totalMag = Vector.mag(totalTrajectory);
                 dir = totalMag > 0.1 ? Vector.normalize(totalTrajectory) : {x: 1, y: 0};
             }

             const nextLx = p.x + dir.x * lookAheadDist;
             const nextLy = p.y + dir.y * lookAheadDist;
             const nextVis = getVisualPos(nextLx, nextLy);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);

             // Extra rotation for bombs (spin)
             const spin = p.skill.visual === 'BOMB' ? (Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y}) * 0.1) : 0;

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail (Before Head) ---
                    if (p.trail.length > 1) {
                        const trailVis = p.trail.map(t => getVisualPos(t.x, t.y));
                        // Add current head position to close the gap
                        trailVis.push(headVis);

                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            // ARROW: Thin, faint motion blur line
                            ctx.beginPath();
                            ctx.moveTo(trailVis[0].x, trailVis[0].y);
                            for (let i = 1; i < trailVis.length; i++) {
                                ctx.lineTo(trailVis[i].x, trailVis[i].y);
                            }
                            ctx.strokeStyle = `rgba(255, 255, 255, 0.2)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            // MAGIC / BOLT / FIREBALL: Tapered glowing ribbon
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            // Iterate segments to vary width/opacity
                            for (let i = 0; i < trailVis.length - 1; i++) {
                                const pt = trailVis[i];
                                const next = trailVis[i+1];

                                // Ratio 0 (tail) -> 1 (head)
                                const ratio = i / (trailVis.length - 1); 

                                ctx.beginPath();
                                ctx.moveTo(pt.x, pt.y);
                                ctx.lineTo(next.x, next.y);

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio;

                                // Color handling
                                ctx.strokeStyle = p.skill.color;
                                ctx.globalAlpha = ratio * 0.5; // Fade out tail

                                ctx.stroke();
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.shadowY);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.ellipse(0, 0, 10, 5, 0, 0, Math.PI*2); ctx.fill();
                    ctx.restore();

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') {
                        ctx.rotate(spin);
                    } else {
                        ctx.rotate(angle);
                    }

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);

                    // Visual Fallback for Missing Assets
                    if (img && img.width > 0) {
                        ctx.drawImage(img, -48, -32, 96, 64);
                    } else {
                        ctx.fillStyle = '#ff00ff';
                        ctx.fillRect(-5, -5, 10, 10);
                    }

                    ctx.restore();
                 }
             });
        });

        return list;
    }

    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        // Iterate over vfx.state.particles
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            const offset = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            // Z acts as Y-offset in 2D draw call (up is negative)
            const drawY = p.y + offset - p.z;

            if (p.type === 'PILLAR' || p.type === 'SHOCKWAVE' || p.type === 'DOMAIN') {
                ctx.save();
                ctx.translate(p.x, drawY - 20); // Ground effects
                if (p.type === 'PILLAR') this.drawPillar(ctx, p, progress);
                else if (p.type === 'SHOCKWAVE') this.drawShockwave(ctx, p, progress);
                else if (p.type === 'DOMAIN') this.drawDomain(ctx, p, progress);
                ctx.restore();
                return;
            }

            ctx.save();
            ctx.translate(p.x, drawY);

            if (p.type === 'BEAM') {
                if (p.targetX !== undefined && p.targetY !== undefined) {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 5;
                    ctx.lineCap = 'round';
                    ctx.globalCompositeOperation = 'lighter';
                    ctx.beginPath();
                    ctx.moveTo(0, 0);
                    ctx.lineTo(p.targetX - p.x, p.targetY - p.y); 
                    ctx.stroke();
                }
            } else if (p.type === 'RING') {
                ctx.scale(1, 0.55); 
                const r = progress * 40;
                ctx.strokeStyle = p.color;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 1 - progress;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
            } else if (p.type === 'SPARK') {
                const r = p.size;
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#fff'); 
                grad.addColorStop(0.3, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.globalAlpha = 1 - Math.pow(progress, 3); 
                ctx.globalCompositeOperation = 'lighter'; 
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();
            } else if (p.type === 'DEBRIS' || p.type === 'SHARD') {
                // Drawing Shards as jagged polygons
                ctx.fillStyle = p.color;
                ctx.rotate(p.rotation);

                // Draw a rough triangle/quad shape
                ctx.beginPath();
                const s = p.size;
                if (p.type === 'SHARD') {
                    // Jagged Shard
                    ctx.moveTo(-s, -s/2);
                    ctx.lineTo(0, -s);
                    ctx.lineTo(s, -s/2);
                    ctx.lineTo(0, s);
                } else {
                    // Box debris
                    ctx.rect(-s/2, -s/2, s, s);
                }
                ctx.fill();

                // Add highlight edge
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        });
    }

    private drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.globalCompositeOperation = 'lighter';

        const lifeRatio = p.life / p.maxLife;
        const pulse = 1 + Math.sin(progress * 15) * 0.1;
        const baseWidth = 50 * (lifeRatio < 0.2 ? lifeRatio * 5 : 1) * pulse;
        const height = 1000;
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 

        ctx.save();
        ctx.scale(1, 0.55); 
        const ringSize = baseWidth * 1.5;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.5, 0, 0, ringSize);
        ringGrad.addColorStop(0, 'rgba(255,255,255,0)');
        ringGrad.addColorStop(0.5, p.color);
        ringGrad.addColorStop(1, 'rgba(255,255,255,0)');
        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha * 0.6;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
        coreGrad.addColorStop(0, '#fff');
        coreGrad.addColorStop(0.3, 'rgba(255,255,255,0.2)');
        coreGrad.addColorStop(1, 'transparent');

        ctx.fillStyle = coreGrad;
        ctx.globalAlpha = alpha;
        ctx.fillRect(-baseWidth * 0.2, -height, baseWidth * 0.4, height);

        const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
        glowGrad.addColorStop(0, p.color);
        glowGrad.addColorStop(0.5, 'transparent');

        ctx.fillStyle = glowGrad;
        ctx.globalAlpha = alpha * 0.6;
        ctx.fillRect(-baseWidth * 0.8, -height, baseWidth * 1.6, height);
    }

    private drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.scale(1, 0.55); 
        const r = progress * 250; 
        const width = 30 * (1 - progress);
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress) * 0.8;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
    }

    private drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         ctx.scale(1, 0.55); 
         ctx.fillStyle = p.color;
         ctx.globalAlpha = 0.3 * (1 - progress);
         ctx.globalCompositeOperation = 'screen';
         ctx.beginPath(); ctx.arc(0, 0, 250, 0, Math.PI * 2); ctx.fill();
         ctx.strokeStyle = p.color;
         ctx.lineWidth = 2;
         ctx.beginPath(); ctx.arc(0, 0, 250, 0, Math.PI*2); ctx.stroke();
    }
}

const cache: Map<string, HTMLCanvasElement> = new Map();

// Dimensions
const ICON_SIZE = 32;
const VFX_SIZE = 64;
const MAGIC_CIRCLE_SIZE = 128;
const PROJ_WIDTH = 96;
const PROJ_HEIGHT = 64;
const BLAST_WIDTH = 128;
const BLAST_HEIGHT = 64;
const STATUS_SIZE = 48;
const FOG_SIZE = 256; // New large sprite for fog

function createCanvas(w: number, h: number) {
    const canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d')!; 
    ctx.imageSmoothingEnabled = true; 
    return { canvas, ctx };
}

// --- Generators ---

const generateGlowOrb = (color: string, size: number = VFX_SIZE): HTMLCanvasElement => {
     const { canvas, ctx } = createCanvas(size, size);
     const cx = size / 2;
     const cy = size / 2;
     const r = size / 2;

     // Core Glow
     const grad = ctx.createRadialGradient(cx, cy, r * 0.1, cx, cy, r);
     grad.addColorStop(0, '#fff');        // Core White
     grad.addColorStop(0.2, color);       // Mid Color
     grad.addColorStop(1, 'transparent'); // Edge

     ctx.fillStyle = grad;
     ctx.beginPath(); 
     ctx.arc(cx, cy, r, 0, Math.PI * 2); 
     ctx.fill();

     return canvas;
};

// New: Pre-blurred fog cloud to avoid ctx.filter='blur()'
const generateFogCloud = (color: string): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(FOG_SIZE, FOG_SIZE);
    const cx = FOG_SIZE / 2;
    const cy = FOG_SIZE / 2;

    // Create a soft cloud shape
    const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, FOG_SIZE / 2);
    grad.addColorStop(0, color);
    grad.addColorStop(0.6, color);
    grad.addColorStop(1, 'transparent');

    ctx.fillStyle = grad;
    // Draw multiple overlapping circles to form a cloud
    ctx.globalAlpha = 0.5;
    ctx.beginPath(); ctx.arc(cx, cy, FOG_SIZE * 0.4, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(cx - 30, cy + 20, FOG_SIZE * 0.25, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(cx + 30, cy - 20, FOG_SIZE * 0.3, 0, Math.PI*2); ctx.fill();

    return canvas;
};

const generateMagicCircle = (color: string, isUlt: boolean): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(MAGIC_CIRCLE_SIZE, MAGIC_CIRCLE_SIZE);
    const cx = MAGIC_CIRCLE_SIZE / 2;
    const cy = MAGIC_CIRCLE_SIZE / 2;
    const radius = 50;

    ctx.shadowColor = color;
    ctx.shadowBlur = 10;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;

    // Outer Ring
    ctx.beginPath(); 
    ctx.arc(cx, cy, radius, 0, Math.PI * 2); 
    ctx.stroke();

    // Inner Runes/Shapes
    ctx.lineWidth = 1;
    if (isUlt) {
        // Hexagram for Ultimates
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            const angle = (i * Math.PI * 2) / 6;
            const x = cx + Math.cos(angle) * radius;
            const y = cy + Math.sin(angle) * radius;
            const x2 = cx + Math.cos(angle + 2 * Math.PI / 3) * radius;
            const y2 = cy + Math.sin(angle + 2 * Math.PI / 3) * radius;
            ctx.moveTo(x, y); 
            ctx.lineTo(x2, y2);
        }
        ctx.stroke();

        // Solid Inner Glow
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.2;
        ctx.beginPath(); 
        ctx.arc(cx, cy, 20, 0, Math.PI * 2); 
        ctx.fill();
    } else {
        // Simple Triangle for Basic/Active
        ctx.beginPath();
        ctx.moveTo(cx, cy - radius);
        ctx.lineTo(cx + 43, cy + 25);
        ctx.lineTo(cx - 43, cy + 25);
        ctx.closePath();
        ctx.stroke();
    }

    return canvas;
};

const generateWarningRune = (): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(128, 64);
    const cx = 64;
    const cy = 32;

    const color = '#ef4444'; // Red
    ctx.shadowColor = color;
    ctx.shadowBlur = 15;
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;

    // Perspective Squash
    ctx.scale(1, 0.5); 

    // Outer Circle
    ctx.beginPath(); 
    ctx.arc(cx, cy * 2, 40, 0, Math.PI * 2); 
    ctx.stroke();

    // X Mark
    ctx.beginPath();
    ctx.moveTo(cx - 20, cy * 2 - 20); 
    ctx.lineTo(cx + 20, cy * 2 + 20);
    ctx.moveTo(cx + 20, cy * 2 - 20); 
    ctx.lineTo(cx - 20, cy * 2 + 20);
    ctx.stroke();

    // Fill
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.3;
    ctx.beginPath(); 
    ctx.arc(cx, cy * 2, 35, 0, Math.PI * 2); 
    ctx.fill();

    return canvas;
};

const generateProjectileSprite = (visual: string, color: string): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(PROJ_WIDTH, PROJ_HEIGHT);
    const cx = PROJ_WIDTH / 2;
    const cy = PROJ_HEIGHT / 2;

    ctx.shadowColor = color;
    ctx.shadowBlur = 15;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    switch (visual) {
        case 'ARROW':
            // Shaft
            ctx.strokeStyle = '#e2e8f0'; 
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(10, cy);
            ctx.lineTo(80, cy);
            ctx.stroke();

            // Head
            ctx.fillStyle = '#f8fafc';
            ctx.beginPath();
            ctx.moveTo(80, cy);
            ctx.lineTo(65, cy - 8);
            ctx.lineTo(70, cy); 
            ctx.lineTo(65, cy + 8);
            ctx.closePath();
            ctx.fill();

            // Fletching (Energy Color)
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(15, cy); ctx.lineTo(5, cy - 8);
            ctx.moveTo(25, cy); ctx.lineTo(15, cy - 8);
            ctx.moveTo(15, cy); ctx.lineTo(5, cy + 8);
            ctx.moveTo(25, cy); ctx.lineTo(15, cy + 8);
            ctx.stroke();
            break;

        case 'FIREBALL':
            // Trail Gradient
            const grad = ctx.createLinearGradient(cx + 20, cy, 0, cy);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.ellipse(cx - 10, cy, 40, 15, 0, 0, Math.PI * 2);
            ctx.fill();

            // Core
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 20;
            ctx.beginPath();
            ctx.arc(cx + 25, cy, 10, 0, Math.PI * 2);
            ctx.fill();
            break;

        case 'BOMB':
            // Round bomb body
            ctx.fillStyle = '#1c1917'; // Dark Iron
            ctx.shadowColor = '#000';
            ctx.shadowBlur = 5;
            ctx.beginPath(); ctx.arc(cx, cy, 12, 0, Math.PI*2); ctx.fill();

            // Highlight
            ctx.fillStyle = '#57534e';
            ctx.beginPath(); ctx.arc(cx - 4, cy - 4, 4, 0, Math.PI*2); ctx.fill();

            // Fuse
            ctx.strokeStyle = '#d6d3d1';
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(cx, cy - 12); ctx.quadraticCurveTo(cx + 5, cy - 18, cx + 10, cy - 15); ctx.stroke();

            // Spark
            ctx.fillStyle = color; // Glow Color
            ctx.shadowColor = color; ctx.shadowBlur = 10;
            ctx.beginPath(); ctx.arc(cx + 10, cy - 15, 3, 0, Math.PI*2); ctx.fill();
            break;

        case 'BOLT':
        default:
            // Outer Glow - SHARPENED
            const boltGrad = ctx.createRadialGradient(cx, cy, 5, cx, cy, 22); // Reduced from 30
            boltGrad.addColorStop(0, '#fff');
            boltGrad.addColorStop(0.3, color);
            boltGrad.addColorStop(1, 'transparent');
            ctx.fillStyle = boltGrad;
            ctx.beginPath(); 
            ctx.arc(cx, cy, 22, 0, Math.PI * 2); // Reduced from 30
            ctx.fill();

            // Diamond Core
            ctx.fillStyle = '#fff';
            ctx.shadowColor = '#fff';
            ctx.shadowBlur = 10;
            ctx.beginPath();
            ctx.moveTo(cx + 20, cy);
            ctx.lineTo(cx, cy - 10);
            ctx.lineTo(cx - 20, cy);
            ctx.lineTo(cx, cy + 10);
            ctx.closePath();
            ctx.fill();

            // Electric Arcs
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(cx - 25, cy); ctx.lineTo(cx - 35, cy - 5);
            ctx.moveTo(cx + 25, cy); ctx.lineTo(cx + 35, cy + 5);
            ctx.stroke();
            break;
    }

    return canvas;
};

const generateBlastZone = (color: string): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(BLAST_WIDTH, BLAST_HEIGHT); 
    const cx = BLAST_WIDTH / 2;
    const cy = BLAST_HEIGHT / 2;

    // Perspective
    ctx.scale(1, 0.5); 

    // Scorch Mark Gradient
    const grad = ctx.createRadialGradient(cx, cy * 2, 0, cx, cy * 2, 50);
    grad.addColorStop(0, '#1c1917'); // Black center
    grad.addColorStop(0.6, '#1c1917');
    grad.addColorStop(1, 'transparent');

    ctx.fillStyle = grad;
    ctx.globalAlpha = 0.8;
    ctx.beginPath();
    ctx.arc(cx, cy * 2, 50, 0, Math.PI * 2);
    ctx.fill();

    // Cracked Edges
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.globalAlpha = 1.0;

    for (let i = 0; i < 8; i++) {
        const angle = i * (Math.PI / 4) + (Math.random() - 0.5);
        const dist = 10 + Math.random() * 20;

        ctx.beginPath();
        ctx.moveTo(cx + Math.cos(angle) * 10, cy * 2 + Math.sin(angle) * 10);
        ctx.lineTo(cx + Math.cos(angle) * (dist + 20), cy * 2 + Math.sin(angle) * (dist + 20));

        // Branching crack
        if (Math.random() > 0.5) {
             ctx.lineTo(cx + Math.cos(angle + 0.3) * (dist + 35), cy * 2 + Math.sin(angle + 0.3) * (dist + 35));
        }

        ctx.stroke();
    }

    // Center Glow
    ctx.fillStyle = color;
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 0.4;
    ctx.beginPath();
    ctx.arc(cx, cy * 2, 20, 0, Math.PI * 2);
    ctx.fill();

    return canvas;
};

const generateSkillIcon = (visual: string, color: string): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);

    // Background Frame
    ctx.fillStyle = '#1e293b'; 
    ctx.fillRect(0, 0, ICON_SIZE, ICON_SIZE);

    ctx.strokeStyle = '#334155'; 
    ctx.strokeRect(0, 0, ICON_SIZE, ICON_SIZE);

    // Symbol
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = '20px Arial';
    ctx.fillStyle = color;
    ctx.shadowColor = color; 
    ctx.shadowBlur = 5;

    let symbol = '●';
    switch (visual) {
        case 'SLASH': symbol = '⚔️'; break;
        case 'ARROW': symbol = '🏹'; break;
        case 'FIREBALL': symbol = '🔥'; break;
        case 'BOLT': symbol = '⚡'; break;
        case 'BEAM': symbol = '✨'; break;
        case 'SMASH': symbol = '🔨'; break;
        case 'BOMB': symbol = '💣'; break;
    }

    ctx.fillText(symbol, ICON_SIZE / 2, ICON_SIZE / 2 + 2); // +2 for visual centering
    return canvas;
};

const generateStatusIcon = (type: string): HTMLCanvasElement => {
    const { canvas, ctx } = createCanvas(STATUS_SIZE, STATUS_SIZE);
    const cx = STATUS_SIZE / 2;
    const cy = STATUS_SIZE / 2;

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = 'bold 28px sans-serif';
    ctx.shadowBlur = 5;

    switch (type) {
        case 'STUN':
            ctx.shadowColor = '#facc15';
            ctx.fillStyle = '#facc15';
            ctx.fillText('💫', cx, cy);
            break;
        case 'SILENCE':
            ctx.shadowColor = '#94a3b8';
            ctx.fillStyle = '#e2e8f0';
            // Speech bubble
            ctx.font = 'bold 24px sans-serif';
            ctx.fillText('💬', cx, cy);
            ctx.font = 'bold 12px sans-serif';
            ctx.fillStyle = '#0f172a';
            ctx.fillText('...', cx, cy - 2);
            break;
        case 'POISON': // DoT
            ctx.shadowColor = '#22c55e';
            ctx.fillStyle = '#4ade80';
            ctx.fillText('☠️', cx, cy);
            break;
        case 'BURN': // DoT
            ctx.shadowColor = '#ef4444';
            ctx.fillStyle = '#f87171';
            ctx.fillText('🔥', cx, cy);
            break;
        case 'REGEN': // HoT
            ctx.shadowColor = '#4ade80';
            ctx.fillStyle = '#86efac';
            ctx.fillText('➕', cx, cy);
            break;
        case 'BANISH':
            ctx.shadowColor = '#c084fc';
            ctx.fillStyle = '#d8b4fe';
            ctx.fillText('👻', cx, cy);
            break;
    }

    return canvas;
};

export const AssetManager = {
    // VFX: Generic Glow Particles
    getVFX(visual: string, color: string): HTMLCanvasElement {
         const key = `VFX_ORB_${color}`;
         if (!cache.has(key)) cache.set(key, generateGlowOrb(color));
         return cache.get(key)!;
    },

    // New: Optimized Glow Sprite (Small) for replacement of shadowBlur
    getGlowSprite(color: string): HTMLCanvasElement {
        const key = `GLOW_SPRITE_${color}`;
        if (!cache.has(key)) cache.set(key, generateGlowOrb(color, 64));
        return cache.get(key)!;
    },

    // New: Pre-rendered Fog
    getFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_${color}`;
        if (!cache.has(key)) cache.set(key, generateFogCloud(color));
        return cache.get(key)!;
    },

    // VFX: Projectiles
    getProjectile(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (!cache.has(key)) {
            // Fallback to BOLT if unknown
            const v = ['ARROW', 'FIREBALL', 'BOLT', 'BOMB'].includes(visual) ? visual : 'BOLT';
            cache.set(key, generateProjectileSprite(v, color));
        }
        return cache.get(key)!;
    },

    // UI: Skill Icons
    getSkillIcon(visual: string, color: string): HTMLCanvasElement {
        const key = `SK_ICON_${visual}_${color}`;
        if (!cache.has(key)) cache.set(key, generateSkillIcon(visual, color));
        return cache.get(key)!;
    },

    // UI: Status Icons
    getStatusIcon(type: string): HTMLCanvasElement {
        const key = `STATUS_${type}`;
        if (!cache.has(key)) cache.set(key, generateStatusIcon(type));
        return cache.get(key)!;
    },

    // VFX: Ground Decals
    getBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_${color}_V2`; // V2 for updated style
        if (!cache.has(key)) cache.set(key, generateBlastZone(color));
        return cache.get(key)!;
    },

    // VFX: Casting Circles
    getMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const key = `MAGIC_CIRCLE_${color}_${isUlt}`;
        if (!cache.has(key)) cache.set(key, generateMagicCircle(color, isUlt));
        return cache.get(key)!;
    },

    // VFX: Danger Indicators
    getWarningRune(): HTMLCanvasElement {
        const key = 'WARNING_RUNE';
        if (!cache.has(key)) cache.set(key, generateWarningRune());
        return cache.get(key)!;
    }
};

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --bg-dark: #020617;
    --text-main: #e2e8f0;
    --accent-cyan: #06b6d4;
    --accent-amber: #f59e0b;
  }

  html {
    font-size: 16px;
    height: 100%;
  }

  body {
    @apply bg-slate-950 text-slate-200 overflow-hidden select-none;
    font-family: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    height: 100%;
    margin: 0;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  /* Tactical Data Typography */
  code, pre, .font-mono {
    font-family: 'JetBrains Mono', 'Consolas', 'Courier New', monospace;
  }
}

@layer components {
  /* Panels */
  .glass-panel {
    @apply bg-slate-900/90 backdrop-blur-md border border-slate-700/60 shadow-xl rounded-sm;
  }

  /* Tactical Buttons */
  .tactical-btn {
    @apply relative overflow-hidden px-3 py-1.5 font-bold tracking-widest text-xs uppercase transition-all duration-200
           bg-slate-900 border border-slate-700 text-slate-400 rounded-sm
           hover:bg-slate-800 hover:border-cyan-500 hover:text-cyan-400 hover:shadow-[0_0_10px_rgba(6,182,212,0.15)]
           active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed disabled:hover:border-slate-700 disabled:hover:text-slate-400 disabled:hover:shadow-none
           flex items-center justify-center gap-2;
  }

  .tactical-btn::before {
    content: '';
    @apply absolute top-0 left-0 w-[2px] h-full bg-cyan-500 opacity-0 transition-opacity duration-200;
  }

  .tactical-btn:hover::before {
    @apply opacity-100;
  }

  .tactical-btn.active {
    @apply bg-cyan-950/40 border-cyan-500 text-cyan-400 shadow-[0_0_10px_rgba(6,182,212,0.25)];
  }

  .tactical-btn.active::before {
    @apply opacity-100 bg-cyan-400;
  }

  /* Team Specific Variants */
  .tactical-btn.btn-blue.active {
    @apply bg-blue-950/40 border-blue-500 text-blue-400 shadow-[0_0_10px_rgba(59,130,246,0.25)];
  }
  .tactical-btn.btn-blue::before { @apply bg-blue-500; }
  .tactical-btn.btn-blue:hover { @apply border-blue-500 text-blue-400; }

  .tactical-btn.btn-red.active {
    @apply bg-red-950/40 border-red-500 text-red-400 shadow-[0_0_10px_rgba(239,68,68,0.25)];
  }
  .tactical-btn.btn-red::before { @apply bg-red-500; }
  .tactical-btn.btn-red:hover { @apply border-red-500 text-red-400; }

  /* Inputs */
  .tactical-input {
    @apply bg-slate-950 border border-slate-700 rounded-sm px-2 py-1 text-slate-200 font-mono text-sm
           focus:border-cyan-500 focus:ring-1 focus:ring-cyan-500/50 outline-none transition-all placeholder-slate-600;
  }

  /* Layout Helpers */
  .full-stretch {
    @apply w-full h-full flex flex-col;
  }
}

@layer utilities {
  .no-scrollbar::-webkit-scrollbar {
    display: none;
  }
  .no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
  }
}

/* Custom Scrollbar - High Visibility Industrial Look */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}

::-webkit-scrollbar-track {
  background: #020617;
  border-left: 1px solid #1e293b;
}

::-webkit-scrollbar-thumb {
  background: #334155;
  border: 1px solid #475569;
  border-radius: 1px;
}

::-webkit-scrollbar-thumb:hover {
  background: #475569;
  border-color: #94a3b8;
}

/* Keyframe Animations */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideUp {
  from { transform: translateY(20px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

@keyframes pulseGlow {
  0%, 100% { box-shadow: 0 0 5px rgba(6, 182, 212, 0.2); border-color: rgba(6, 182, 212, 0.5); }
  50% { box-shadow: 0 0 15px rgba(6, 182, 212, 0.5); border-color: rgba(6, 182, 212, 1); }
}

@keyframes bounceIn {
  0% { opacity: 0; transform: scale(0.3); }
  50% { opacity: 1; transform: scale(1.05); }
  70% { transform: scale(0.9); }
  100% { transform: scale(1); }
}

@keyframes gradientFlow {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.animate-fade-in { animation: fadeIn 0.5s ease-out forwards; }
.animate-slide-up { animation: slideUp 0.4s ease-out forwards; }
.animate-pulse-glow { animation: pulseGlow 2s infinite; }
.animate-bounce-in { animation: bounceIn 0.5s cubic-bezier(0.215, 0.610, 0.355, 1.000) both; }
.animate-gradient-flow {
  background-size: 200% 200%;
  animation: gradientFlow 8s ease infinite;
}

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import InspectorPanel from './components/InspectorPanel';
import { ToolType, Team, Skill, Role } from './types';
import { OBSTACLE_DB } from './data/obstacles';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0);
  const [showMobileInspector, setShowMobileInspector] = useState(false);
  const [showMapSettings, setShowMapSettings] = useState(false);

  // Layout State (Responsive)
  const [isLargeScreen, setIsLargeScreen] = useState(() => window.innerWidth >= 1024);

  // Tooling
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

  // Settings
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [winner, setWinner] = useState<Team | null>(null);

  // Spawn Logic
  const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
  const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

  // Layout & UI
  const [sidebarWidth, setSidebarWidth] = useState(420);
  const isResizing = useRef(false);
  const [showFactionWarning, setShowFactionWarning] = useState(false);
  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

  // --- Responsive Listener ---
  useEffect(() => {
      const handleResize = () => setIsLargeScreen(window.innerWidth >= 1024);
      window.addEventListener('resize', handleResize);
      return () => window.removeEventListener('resize', handleResize);
  }, []);

  // --- Logic ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.clear(false); 
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  // --- Hybrid Input Resizing (Mouse & Touch) ---
  const startResizing = useCallback((e: React.MouseEvent | React.TouchEvent) => {
      isResizing.current = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
      // Prevent scrolling on touch
      if ('touches' in e) e.stopPropagation();
  }, []);

  const stopResizing = useCallback(() => {
      isResizing.current = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
  }, []);

  const performResize = useCallback((clientX: number) => {
      if (isResizing.current) {
          const newWidth = window.innerWidth - clientX;
          // Constraints for Tablet/Desktop
          const maxWidth = window.innerWidth * 0.8;
          if (newWidth > 300 && newWidth < maxWidth) {
              setSidebarWidth(newWidth);
          }
      }
  }, []);

  const handleMouseMove = useCallback((e: MouseEvent) => performResize(e.clientX), [performResize]);
  const handleTouchMove = useCallback((e: TouchEvent) => performResize(e.touches[0].clientX), [performResize]);

  useEffect(() => {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', stopResizing);
      window.addEventListener('touchmove', handleTouchMove);
      window.addEventListener('touchend', stopResizing);
      return () => {
          window.removeEventListener('mousemove', handleMouseMove);
          window.removeEventListener('mouseup', stopResizing);
          window.removeEventListener('touchmove', handleTouchMove);
          window.removeEventListener('touchend', stopResizing);
      };
  }, [handleMouseMove, handleTouchMove, stopResizing]);

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const handleRestart = useCallback(() => {
    if (winner !== null) return;
    engineRef.current.restart();
    setIsPlaying(true);
    setTool(ToolType.SELECT);
  }, [winner]);

  const handleClear = useCallback(() => {
    engineRef.current.clear(); 
    setIsPlaying(false);
    setSelectedAgent(null);
    setWinner(null);
    setHoveredSkill(null);
  }, []);

  const updateMap = useCallback(() => {
      engineRef.current.mapConfig.w = mapW;
      engineRef.current.mapConfig.h = mapH;
      engineRef.current.clear(true);
      setSelectedAgent(null);
      setWinner(null);
  }, [mapW, mapH]);

  const handleSelectAgent = useCallback((agent: Agent | null) => {
    setSelectedAgent(agent);
  }, []);

  const onWin = (team: Team) => {
    setWinner(team);
    if (isShowcaseMode) {
        setTimeout(() => {
            setTransitionPhase('OUT');
            engineRef.current.agents = [];
            engineRef.current.combat.projectiles = [];
            setTimeout(() => {
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 
                setTimeout(() => {
                    setTransitionPhase('IDLE');
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

  const roleIcons: Record<Role, string> = {
      [Role.TANK]: '🛡️',
      [Role.WARRIOR]: '⚔️',
      [Role.RANGER]: '🏹',
      [Role.MAGE]: '🔮',
      [Role.SUPPORT]: '⚕️'
  };

  // Helper to toggle tools (clicking active tool turns it off)
  const toggleTool = (t: ToolType) => {
      if (tool === t) setTool(ToolType.SELECT);
      else setTool(t);
  };

  return (
    <div className="h-[100dvh] w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none touch-none">

      {/* FLOATING HUD (Top Center) - Z-Index 30 */}
      <div className={`absolute top-4 left-1/2 -translate-x-1/2 z-30 transition-all duration-500 w-auto max-w-[95%] pointer-events-none ${isShowcaseMode ? '-translate-y-32 opacity-0' : 'translate-y-0 opacity-100'}`}>
          <div className="glass-panel px-3 py-2 rounded-xl md:rounded-full flex flex-wrap md:flex-nowrap items-center justify-center gap-3 shadow-[0_0_20px_rgba(0,0,0,0.5)] border-slate-600/50 backdrop-blur-lg pointer-events-auto">

                {/* Control Group */}
                <div className="flex items-center gap-3">
                    <button 
                        onClick={togglePlay} 
                        disabled={winner !== null}
                        className={`flex items-center justify-center w-10 h-10 rounded-full border transition-all shadow-lg ${isPlaying ? 'bg-amber-900/50 border-amber-500 text-amber-400' : 'bg-emerald-900/50 border-emerald-500 text-emerald-400 hover:shadow-[0_0_15px_rgba(16,185,129,0.4)]'}`}
                    >
                        {isPlaying ? '⏸' : '▶'}
                    </button>

                    <button 
                        onClick={handleRestart} 
                        disabled={!isPlaying && winner === null}
                        className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-800 border border-slate-600 text-slate-400 hover:text-white hover:border-white transition-colors"
                        title="重置回合"
                    >
                        ↺
                    </button>
                </div>

                <div className="hidden xl:block w-px h-8 bg-slate-700"></div>

                {/* Speed Control - Hidden on small screens */}
                <div className="hidden xl:flex flex-1 flex-col items-center min-w-[120px]">
                    <div className="flex items-center justify-between w-full mb-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">模擬速度</span>
                        <div className="text-[10px] font-mono text-cyan-400">{timeScale.toFixed(1)}x</div>
                    </div>
                    <input 
                        type="range" min="0.1" max="3.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                    />
                </div>

                {/* Mode Switch (Desktop Only) */}
                <button 
                    onClick={() => { setIsShowcaseMode(true); startShowcaseMatch(); }}
                    className="hidden lg:flex px-3 py-1.5 rounded bg-slate-800/50 hover:bg-purple-900/30 border border-transparent hover:border-purple-500/50 text-xs font-bold text-slate-400 hover:text-purple-300 transition-all items-center gap-2"
                >
                    <span>📺</span>
                    <span>展示模式</span>
                </button>
          </div>
      </div>

      {/* WARNING NOTIFICATION */}
      {showFactionWarning && (
            <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                <div className="bg-red-950/90 text-red-200 px-6 py-3 rounded border border-red-500 flex items-center gap-3 shadow-xl">
                    <span className="text-xl">⚠️</span>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                        <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                    </div>
                </div>
            </div>
      )}

      {/* MAP SETTINGS MODAL (Mobile Only) */}
      {showMapSettings && (
        <div className="fixed inset-0 z-50 flex items-end justify-center sm:items-center bg-black/50 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setShowMapSettings(false)}>
            <div className="bg-slate-900 border border-slate-700 p-4 rounded-xl shadow-2xl w-full max-w-sm space-y-4 mb-32 sm:mb-0 pointer-events-auto" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center border-b border-slate-800 pb-2">
                    <h3 className="font-bold text-slate-300">地圖設定</h3>
                    <button onClick={() => setShowMapSettings(false)} className="text-slate-500 hover:text-slate-300 w-8 h-8 flex items-center justify-center">✕</button>
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                        <label className="text-xs text-slate-500 font-bold uppercase">寬度</label>
                        <input type="number" className="tactical-input w-full text-center h-10 text-lg" value={mapW} onChange={e=>setMapW(Number(e.target.value))} />
                    </div>
                    <div className="space-y-1">
                        <label className="text-xs text-slate-500 font-bold uppercase">高度</label>
                        <input type="number" className="tactical-input w-full text-center h-10 text-lg" value={mapH} onChange={e=>setMapH(Number(e.target.value))} />
                    </div>
                </div>
                <div className="flex gap-3 pt-2">
                    <button onClick={() => { updateMap(); setShowMapSettings(false); }} className="flex-1 tactical-btn py-3 border-slate-600 hover:bg-slate-800">重建地圖</button>
                    <button onClick={() => { handleClear(); setShowMapSettings(false); }} className="flex-1 tactical-btn py-3 text-red-400 border-red-900 hover:bg-red-950">清空單位</button>
                </div>
            </div>
        </div>
      )}

      {/* SHOWCASE OVERLAY */}
      {isShowcaseMode && (
            <div className="absolute inset-0 z-50 flex items-end justify-center pb-32 pointer-events-none overflow-hidden">
                {/* 1. Animated Gradient Background Layer */}
                <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-900/10 to-transparent"></div>

                {/* 2. Flowing Mesh Gradient at the bottom */}
                <div className="absolute bottom-0 left-0 w-full h-[60vh] opacity-70">
                     <div className="absolute inset-0 bg-gradient-to-r from-blue-900/30 via-purple-900/30 to-cyan-900/30 animate-gradient-flow"></div>
                     <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-transparent"></div>
                </div>

                <div className="text-center pointer-events-auto animate-fade-in px-4 relative z-10">
                    <h1 className="text-5xl md:text-7xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 via-cyan-100 to-red-500 mb-4 drop-shadow-[0_0_20px_rgba(6,182,212,0.5)] font-mono tracking-tighter">
                        TACTICAL<span className="text-slate-100">.</span>OS
                    </h1>
                    <div className="text-cyan-500 text-xs md:text-sm tracking-[0.5em] mb-10 uppercase font-bold text-shadow">戰場模擬引擎 v4.0</div>
                    <button 
                        onClick={enterManualMode}
                        className="group relative px-10 py-4 bg-slate-900/80 border border-cyan-500/50 text-cyan-400 font-bold tracking-[0.2em] text-sm uppercase overflow-hidden hover:scale-105 transition-all duration-300 shadow-[0_0_30px_rgba(6,182,212,0.2)] hover:shadow-[0_0_50px_rgba(6,182,212,0.4)] hover:border-cyan-400 hover:bg-slate-800 backdrop-blur-sm"
                    >
                        <span className="relative z-10 flex items-center gap-4">
                            <span>初始化指揮系統</span>
                            <span className="text-lg">➜</span>
                        </span>
                    </button>
                </div>
                {/* Discrete Time Control for Showcase */}
                <div className="absolute bottom-8 right-8 z-50 pointer-events-auto flex items-center gap-4 glass-panel px-5 py-3 rounded-full group animate-fade-in border-slate-600/50">
                    <span className="text-[10px] text-cyan-500 font-bold uppercase tracking-wider">模擬速率</span>
                    <input 
                        type="range" min="0.1" max="4.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-24 md:w-32 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                    <span className="text-[10px] w-8 text-right font-mono text-cyan-300 font-bold">{timeScale.toFixed(1)}x</span>
                </div>
            </div>
      )}

      {/* MAIN CONTENT ROW */}
      <div className="flex-1 flex overflow-hidden relative z-0">

          {/* LEFT COLUMN: Canvas + Dock */}
          <div className="flex-1 flex flex-col relative min-w-0 min-h-0 z-0 basis-0 bg-slate-900">
                <GameCanvas 
                    engine={engineRef.current} 
                    tool={tool}
                    selectedObstacle={selectedObstacle}
                    hpInput={hpInput}
                    selectedAgent={selectedAgent}
                    hoveredSkill={hoveredSkill}
                    isShowcaseMode={isShowcaseMode}
                    spawnMode={spawnMode}
                    draftRole={draftRole}
                    onSelect={handleSelectAgent} 
                    onWin={onWin}
                    winner={winner}
                    rematch={() => { setWinner(null); engineRef.current.restart(); setIsPlaying(true); }}
                    transitionPhase={transitionPhase}
                />

                {/* BOTTOM DOCK */}
                {/* Safe area padding added for modern phones */}
                <div className={`bg-slate-950 border-t border-slate-800 shrink-0 z-30 transition-all duration-500 w-full pb-[env(safe-area-inset-bottom)] ${isShowcaseMode ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100'}`}>

                    {/* MOBILE GRID LAYOUT (< md) - 4x2 GRID */}
                    <div className="md:hidden grid grid-cols-4 gap-2 p-2 h-auto">

                        {/* ROW 1: PRIMARY ACTIONS */}
                        <button onClick={() => toggleTool(ToolType.ADD_BLUE)} className={`h-12 tactical-btn btn-blue ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-70'}`}>
                            <span className="text-2xl">🔵</span>
                        </button>

                        <button onClick={() => toggleTool(ToolType.ADD_RED)} className={`h-12 tactical-btn btn-red ${tool === ToolType.ADD_RED ? 'active' : 'opacity-70'}`}>
                            <span className="text-2xl">🔴</span>
                        </button>

                        <div className={`relative h-12 tactical-btn p-0 ${tool === ToolType.OBSTACLE ? 'active border-cyan-500' : ''}`}>
                            <button onClick={() => toggleTool(ToolType.OBSTACLE)} className="w-full h-full flex items-center justify-center">
                                <span className="text-2xl">🧱</span>
                                <span className="text-[8px] absolute bottom-0.5 right-1 opacity-50">▼</span>
                            </button>
                            <select 
                                className="absolute inset-0 opacity-0 w-full h-full cursor-pointer"
                                value={selectedObstacle} 
                                onChange={e => { setSelectedObstacle(e.target.value); setTool(ToolType.OBSTACLE); }}
                            >
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        </div>

                        <button onClick={() => toggleTool(ToolType.DELETE)} className={`h-12 tactical-btn text-red-400 border-red-900/50 ${tool === ToolType.DELETE ? 'active bg-red-950/50 border-red-500' : ''}`}>
                            <span className="text-2xl">❌</span>
                        </button>

                        {/* ROW 2: CONFIG & INSPECT */}
                        <div className="h-12 flex items-center justify-center bg-slate-900 border border-slate-700 rounded-sm relative">
                            <span className="text-[8px] text-slate-500 absolute -top-1.5 left-1 bg-slate-900 px-0.5">HP</span>
                            <input 
                                type="number" 
                                value={hpInput} 
                                onChange={e => setHpInput(parseInt(e.target.value))} 
                                className="w-full h-full bg-transparent text-center text-sm font-mono text-slate-200 outline-none"
                            />
                        </div>

                        <button 
                            onClick={() => setShowMapSettings(!showMapSettings)}
                            className={`h-12 tactical-btn ${showMapSettings ? 'border-cyan-500 text-cyan-400' : ''}`}
                        >
                            <span className="text-xl">🗺️</span>
                        </button>

                        <button 
                            onClick={() => selectedAgent && setShowMobileInspector(!showMobileInspector)}
                            disabled={!selectedAgent}
                            className={`col-span-2 h-12 tactical-btn ${showMobileInspector ? 'active' : ''} ${selectedAgent ? 'border-blue-500/50 text-blue-300 animate-pulse-glow' : 'opacity-30'}`}
                        >
                            <span className="text-lg mr-2">👁️</span>
                            <span className="text-xs">單位資訊</span>
                        </button>
                    </div>

                    {/* DESKTOP FLEX LAYOUT (>= md) */}
                    <div className="hidden md:flex h-40 overflow-x-auto overflow-y-hidden">

                        {/* ZONE 1: COMMAND TOOLS (Expanded to fill space) */}
                        <div className="w-48 border-r border-slate-800 p-3 flex flex-col gap-2 shrink-0">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">地圖編輯</div>
                            <div className="flex gap-2 flex-1">
                                <div className={`flex-1 relative flex flex-col tactical-btn p-0 ${tool === ToolType.OBSTACLE ? 'active' : ''}`}>
                                    <button onClick={() => toggleTool(ToolType.OBSTACLE)} className="w-full flex-1 flex flex-col items-center justify-center gap-1">
                                        <span className="text-2xl">🧱</span>
                                        <span className="text-[10px]">地形</span>
                                    </button>
                                    <div className="h-6 w-full border-t border-slate-700 relative bg-black/20">
                                        <select 
                                            className="w-full h-full bg-transparent text-[10px] text-center appearance-none cursor-pointer text-slate-400 outline-none"
                                            value={selectedObstacle} 
                                            onChange={e => { setSelectedObstacle(e.target.value); setTool(ToolType.OBSTACLE); }}
                                        >
                                            {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                                        </select>
                                        <span className="absolute right-1 top-1.5 text-[8px] opacity-50 pointer-events-none">▼</span>
                                    </div>
                                </div>

                                <button onClick={() => toggleTool(ToolType.DELETE)} className={`flex-1 tactical-btn flex-col text-red-400 border-red-900/50 hover:border-red-500 ${tool === ToolType.DELETE ? 'active border-red-500 bg-red-950/30' : ''}`}>
                                    <span className="text-2xl">❌</span>
                                    <span className="text-[10px]">移除</span>
                                </button>
                            </div>
                        </div>

                        {/* ZONE 2: DEPLOYMENT (Flexible Width) */}
                        <div className="flex-1 p-3 flex flex-col gap-2 relative min-w-[300px]">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1 flex justify-between">
                                <span>單位部署</span>
                                <span className="text-slate-700 font-mono">單位數: {unitCount}</span>
                            </div>

                            <div className="flex gap-4 h-full">
                                {/* Team Selectors (Sets Tool) */}
                                <div className="flex flex-col gap-2 w-28 shrink-0">
                                    <button onClick={() => toggleTool(ToolType.ADD_BLUE)} className={`flex-1 tactical-btn btn-blue flex items-center justify-between px-3 ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="font-bold text-xs">藍隊</span>
                                        <span className="text-lg">🔵</span>
                                    </button>
                                    <button onClick={() => toggleTool(ToolType.ADD_RED)} className={`flex-1 tactical-btn btn-red flex items-center justify-between px-3 ${tool === ToolType.ADD_RED ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="font-bold text-xs">紅隊</span>
                                        <span className="text-lg">🔴</span>
                                    </button>
                                </div>

                                {/* Mode & Draft Config */}
                                <div className="flex-1 bg-slate-900 border border-slate-800 rounded p-2 flex flex-col gap-2 min-w-[200px]">
                                    <div className="flex bg-slate-950 rounded p-1 gap-1 shrink-0">
                                        <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'RANDOM' ? 'bg-slate-700 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                            🎲 隨機
                                        </button>
                                        <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'DRAFT' ? 'bg-slate-700 text-amber-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                            📝 自選
                                        </button>
                                    </div>

                                    <div className="flex-1 flex items-center justify-center relative overflow-hidden">
                                        {spawnMode === 'RANDOM' ? (
                                            <div className="text-slate-600 font-mono text-xs flex flex-col items-center animate-pulse">
                                                <span className="text-2xl mb-1">🎲</span>
                                                <span>隨機職階</span>
                                            </div>
                                        ) : (
                                            <div className="flex gap-1.5 w-full justify-center">
                                                {Object.values(Role).map(role => (
                                                    <button 
                                                        key={role}
                                                        onClick={() => setDraftRole(role)}
                                                        className={`w-10 h-10 rounded border flex flex-col items-center justify-center transition-all ${draftRole === role ? 'bg-amber-900/40 border-amber-500 text-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.3)] scale-110' : 'bg-slate-800 border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'}`}
                                                        title={role}
                                                    >
                                                        <span className="text-lg -mt-1 filter drop-shadow-md">{roleIcons[role]}</span>
                                                    </button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* HP Pool */}
                                <div className="flex flex-col justify-center gap-1 w-16 shrink-0">
                                    <label className="text-[9px] text-slate-500 font-bold uppercase text-center">生命值</label>
                                    <input 
                                        type="number" 
                                        value={hpInput} 
                                        onChange={e => setHpInput(parseInt(e.target.value))} 
                                        className="tactical-input text-center text-lg h-10 border-slate-700 focus:border-cyan-500 px-0"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* ZONE 3: MAP OPS */}
                        <div className="w-36 border-l border-slate-800 p-3 flex flex-col gap-2 shrink-0 bg-slate-950/50">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">地圖操作</div>
                            <div className="grid grid-cols-2 gap-2">
                                <div className="flex flex-col">
                                    <label className="text-[8px] text-slate-500">寬度</label>
                                    <input type="number" className="tactical-input p-1 text-center" value={mapW} onChange={e=>setMapW(Number(e.target.value))}/>
                                </div>
                                <div className="flex flex-col">
                                    <label className="text-[8px] text-slate-500">高度</label>
                                    <input type="number" className="tactical-input p-1 text-center" value={mapH} onChange={e=>setMapH(Number(e.target.value))}/>
                                </div>
                            </div>
                            <div className="flex gap-2 mt-auto">
                                <button onClick={updateMap} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center border-slate-600 hover:bg-slate-800">重建</button>
                                <button onClick={handleClear} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center text-red-400 border-red-900 hover:bg-red-950">清空單位</button>
                            </div>
                        </div>
                    </div>
                </div>
          </div>

          {/* RIGHT COLUMN: Inspector (Z-40) */}
          {/* Resizer - Hidden on small screens or when showcase */}
          {isLargeScreen && !isShowcaseMode && (
            <div 
                className="hidden lg:flex w-1 bg-slate-950 hover:bg-cyan-600 cursor-col-resize items-center justify-center shrink-0 transition-colors z-40 border-l border-slate-800"
                onMouseDown={startResizing}
                onTouchStart={startResizing}
            >
                <div className="w-[1px] h-8 bg-slate-600"></div>
            </div>
          )}

          {/* Panel - Desktop Sidebar OR Mobile Overlay Drawer */}
          {/* LOGIC SPLIT: Mobile is a Modal (Fixed), Desktop is a Flex Col (Relative) */}
          {isLargeScreen ? (
              // DESKTOP LAYOUT
              <div 
                className={`
                    flex flex-col z-40 shadow-2xl bg-slate-900 border-l border-slate-700 transition-all duration-300 relative h-full
                    ${isShowcaseMode ? 'w-0 border-l-0 overflow-hidden' : ''}
                `}
                style={{ width: !isShowcaseMode ? sidebarWidth : 0 }}
              >
                <InspectorPanel 
                    agent={selectedAgent} 
                    engine={engineRef.current}
                    logs={[]} 
                    db={engineRef.current.skillDB}
                    onHoverSkill={setHoveredSkill}
                />
              </div>
          ) : (
              // MOBILE DRAWER LAYOUT
              <div 
                className={`fixed inset-0 z-50 transition-opacity duration-300 ${showMobileInspector ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
                onClick={() => setShowMobileInspector(false)}
              >
                  {/* Backdrop */}
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-sm"></div>

                  {/* Slide-in Panel */}
                  <div 
                    className={`absolute right-0 top-0 bottom-0 w-full sm:w-[400px] bg-slate-900 shadow-2xl border-l border-slate-700 transform transition-transform duration-300 flex flex-col ${showMobileInspector ? 'translate-x-0' : 'translate-x-full'}`}
                    onClick={(e) => e.stopPropagation()}
                  >
                      {/* Mobile Header */}
                      <div className="p-4 border-b border-slate-700 bg-slate-950 flex justify-between items-center shrink-0 pt-safe-top">
                           <h3 className="font-bold text-slate-200 text-lg">單位監控面板</h3>
                           <button onClick={() => setShowMobileInspector(false)} className="w-10 h-10 flex items-center justify-center bg-slate-800 rounded-full text-slate-400 active:scale-95">✕</button>
                      </div>

                      <div className="flex-1 overflow-hidden">
                        <InspectorPanel 
                            agent={selectedAgent} 
                            engine={engineRef.current}
                            logs={[]} 
                            db={engineRef.current.skillDB}
                            onHoverSkill={setHoveredSkill}
                        />
                      </div>
                  </div>
              </div>
          )}
      </div>
    </div>
  );
}

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import InspectorPanel from './components/InspectorPanel';
import { ToolType, Team, Skill, Role } from './types';
import { OBSTACLE_DB } from './data/obstacles';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0);
  const [showMobileInspector, setShowMobileInspector] = useState(false);
  const [showMapSettings, setShowMapSettings] = useState(false);

  // Layout State (Responsive)
  const [isLargeScreen, setIsLargeScreen] = useState(() => window.innerWidth >= 1024);

  // Tooling
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

  // Settings
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [winner, setWinner] = useState<Team | null>(null);

  // Spawn Logic
  const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
  const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

  // Layout & UI
  const [sidebarWidth, setSidebarWidth] = useState(420);
  const isResizing = useRef(false);
  const [showFactionWarning, setShowFactionWarning] = useState(false);
  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

  // --- Responsive Listener ---
  useEffect(() => {
      const handleResize = () => setIsLargeScreen(window.innerWidth >= 1024);
      window.addEventListener('resize', handleResize);
      return () => window.removeEventListener('resize', handleResize);
  }, []);

  // --- Logic ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.clear(false); 
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  // --- Hybrid Input Resizing (Mouse & Touch) ---
  const startResizing = useCallback((e: React.MouseEvent | React.TouchEvent) => {
      isResizing.current = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
      // Prevent scrolling on touch
      if ('touches' in e) e.stopPropagation();
  }, []);

  const stopResizing = useCallback(() => {
      isResizing.current = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
  }, []);

  const performResize = useCallback((clientX: number) => {
      if (isResizing.current) {
          const newWidth = window.innerWidth - clientX;
          // Constraints for Tablet/Desktop
          const maxWidth = window.innerWidth * 0.8;
          if (newWidth > 300 && newWidth < maxWidth) {
              setSidebarWidth(newWidth);
          }
      }
  }, []);

  const handleMouseMove = useCallback((e: MouseEvent) => performResize(e.clientX), [performResize]);
  const handleTouchMove = useCallback((e: TouchEvent) => performResize(e.touches[0].clientX), [performResize]);

  useEffect(() => {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', stopResizing);
      window.addEventListener('touchmove', handleTouchMove);
      window.addEventListener('touchend', stopResizing);
      return () => {
          window.removeEventListener('mousemove', handleMouseMove);
          window.removeEventListener('mouseup', stopResizing);
          window.removeEventListener('touchmove', handleTouchMove);
          window.removeEventListener('touchend', stopResizing);
      };
  }, [handleMouseMove, handleTouchMove, stopResizing]);

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const handleRestart = useCallback(() => {
    if (winner !== null) return;
    engineRef.current.restart();
    setIsPlaying(true);
    setTool(ToolType.SELECT);
  }, [winner]);

  const handleClear = useCallback(() => {
    engineRef.current.clear(); 
    setIsPlaying(false);
    setSelectedAgent(null);
    setWinner(null);
    setHoveredSkill(null);
  }, []);

  const updateMap = useCallback(() => {
      engineRef.current.mapConfig.w = mapW;
      engineRef.current.mapConfig.h = mapH;
      engineRef.current.clear(true);
      setSelectedAgent(null);
      setWinner(null);
  }, [mapW, mapH]);

  const handleSelectAgent = useCallback((agent: Agent | null) => {
    setSelectedAgent(agent);
  }, []);

  const onWin = (team: Team) => {
    setWinner(team);
    if (isShowcaseMode) {
        setTimeout(() => {
            setTransitionPhase('OUT');
            engineRef.current.agents = [];
            engineRef.current.combat.projectiles = [];
            setTimeout(() => {
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 
                setTimeout(() => {
                    setTransitionPhase('IDLE');
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

  const roleIcons: Record<Role, string> = {
      [Role.TANK]: '🛡️',
      [Role.WARRIOR]: '⚔️',
      [Role.RANGER]: '🏹',
      [Role.MAGE]: '🔮',
      [Role.SUPPORT]: '⚕️'
  };

  // Helper to toggle tools (clicking active tool turns it off)
  const toggleTool = (t: ToolType) => {
      if (tool === t) setTool(ToolType.SELECT);
      else setTool(t);
  };

  return (
    <div className="h-[100dvh] w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none touch-none">

      {/* WARNING NOTIFICATION */}
      {showFactionWarning && (
            <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                <div className="bg-red-950/90 text-red-200 px-6 py-3 rounded border border-red-500 flex items-center gap-3 shadow-xl">
                    <span className="text-xl">⚠️</span>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                        <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                    </div>
                </div>
            </div>
      )}

      {/* MAP SETTINGS MODAL (Mobile Only) */}
      {showMapSettings && (
        <div className="fixed inset-0 z-50 flex items-end justify-center sm:items-center bg-black/50 backdrop-blur-sm p-4 animate-fade-in" onClick={() => setShowMapSettings(false)}>
            <div className="bg-slate-900 border border-slate-700 p-4 rounded-xl shadow-2xl w-full max-w-sm space-y-4 mb-32 sm:mb-0 pointer-events-auto" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center border-b border-slate-800 pb-2">
                    <h3 className="font-bold text-slate-300">地圖設定</h3>
                    <button onClick={() => setShowMapSettings(false)} className="text-slate-500 hover:text-slate-300 w-8 h-8 flex items-center justify-center">✕</button>
                </div>
                <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1">
                        <label className="text-xs text-slate-500 font-bold uppercase">寬度</label>
                        <input type="number" className="tactical-input w-full text-center h-10 text-lg" value={mapW} onChange={e=>setMapW(Number(e.target.value))} />
                    </div>
                    <div className="space-y-1">
                        <label className="text-xs text-slate-500 font-bold uppercase">高度</label>
                        <input type="number" className="tactical-input w-full text-center h-10 text-lg" value={mapH} onChange={e=>setMapH(Number(e.target.value))} />
                    </div>
                </div>
                <div className="flex gap-3 pt-2">
                    <button onClick={() => { updateMap(); setShowMapSettings(false); }} className="flex-1 tactical-btn py-3 border-slate-600 hover:bg-slate-800">重建地圖</button>
                    <button onClick={() => { handleClear(); setShowMapSettings(false); }} className="flex-1 tactical-btn py-3 text-red-400 border-red-900 hover:bg-red-950">清空單位</button>
                </div>
            </div>
        </div>
      )}

      {/* SHOWCASE OVERLAY (Ghost Layer) */}
      {isShowcaseMode && (
            <div className="absolute inset-0 z-50 pointer-events-none overflow-hidden flex flex-col justify-end">
                {/* 1. Dynamic Bottom Background (Glassmorphism & Gradient) */}
                <div className="absolute inset-x-0 bottom-0 h-[45vh] pointer-events-none">
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950/90 via-slate-900/60 to-transparent backdrop-blur-[4px]"></div>
                    {/* Subtle Flowing Energy */}
                    <div className="absolute inset-0 opacity-30 mix-blend-screen">
                        <div className="absolute inset-0 bg-gradient-to-r from-blue-900/20 via-purple-900/20 to-cyan-900/20 animate-gradient-flow"></div>
                    </div>
                </div>

                {/* 2. Content */}
                <div className="relative z-10 w-full flex flex-col items-center pb-32">
                    <div className="text-center pointer-events-auto animate-fade-in px-4">
                        <h1 className="text-5xl md:text-7xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-500 via-cyan-100 to-red-500 mb-4 drop-shadow-[0_0_20px_rgba(6,182,212,0.5)] font-mono tracking-tighter">
                            TACTICAL<span className="text-slate-100">.</span>OS
                        </h1>
                        <div className="text-cyan-500 text-xs md:text-sm tracking-[0.5em] mb-10 uppercase font-bold text-shadow">戰場模擬引擎 v4.0</div>
                        <button 
                            onClick={enterManualMode}
                            className="group relative px-10 py-4 bg-slate-900/80 border border-cyan-500/50 text-cyan-400 font-bold tracking-[0.2em] text-sm uppercase overflow-hidden hover:scale-105 transition-all duration-300 shadow-[0_0_30px_rgba(6,182,212,0.2)] hover:shadow-[0_0_50px_rgba(6,182,212,0.4)] hover:border-cyan-400 hover:bg-slate-800 backdrop-blur-sm"
                        >
                            <span className="relative z-10 flex items-center gap-4">
                                <span>初始化指揮系統</span>
                                <span className="text-lg">➜</span>
                            </span>
                        </button>
                    </div>
                </div>

                {/* 3. Discrete Time Control for Showcase */}
                <div className="absolute bottom-8 right-8 z-50 pointer-events-auto flex items-center gap-4 glass-panel px-5 py-3 rounded-full group animate-fade-in border-slate-600/50">
                    <span className="text-[10px] text-cyan-500 font-bold uppercase tracking-wider">模擬速率</span>
                    <input 
                        type="range" min="0.1" max="4.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-24 md:w-32 h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-400"
                    />
                    <span className="text-[10px] w-8 text-right font-mono text-cyan-300 font-bold">{timeScale.toFixed(1)}x</span>
                </div>
            </div>
      )}

      {/* MAIN CONTENT ROW */}
      <div className="flex-1 flex overflow-hidden relative z-0">

          {/* LEFT COLUMN: Canvas + Dock + Floating HUD */}
          <div className="flex-1 flex flex-col relative min-w-0 min-h-0 z-0 basis-0 bg-slate-900">

                {/* FLOATING HUD (Moved inside Left Column to center on Game View and avoid Right Panel overlap) */}
                <div className={`absolute top-4 left-1/2 -translate-x-1/2 z-30 transition-all duration-500 w-auto max-w-[95%] pointer-events-none ${isShowcaseMode ? '-translate-y-32 opacity-0' : 'translate-y-0 opacity-100'}`}>
                    <div className="glass-panel px-3 py-2 rounded-xl md:rounded-full flex flex-wrap md:flex-nowrap items-center justify-center gap-3 shadow-[0_0_20px_rgba(0,0,0,0.5)] border-slate-600/50 backdrop-blur-lg pointer-events-auto">

                            {/* Control Group */}
                            <div className="flex items-center gap-3">
                                <button 
                                    onClick={togglePlay} 
                                    disabled={winner !== null}
                                    className={`flex items-center justify-center w-10 h-10 rounded-full border transition-all shadow-lg ${isPlaying ? 'bg-amber-900/50 border-amber-500 text-amber-400' : 'bg-emerald-900/50 border-emerald-500 text-emerald-400 hover:shadow-[0_0_15px_rgba(16,185,129,0.4)]'}`}
                                >
                                    {isPlaying ? '⏸' : '▶'}
                                </button>

                                <button 
                                    onClick={handleRestart} 
                                    disabled={!isPlaying && winner === null}
                                    className="flex items-center justify-center w-8 h-8 rounded-full bg-slate-800 border border-slate-600 text-slate-400 hover:text-white hover:border-white transition-colors"
                                    title="重置回合"
                                >
                                    ↺
                                </button>
                            </div>

                            <div className="hidden xl:block w-px h-8 bg-slate-700"></div>

                            {/* Speed Control - Hidden on small screens */}
                            <div className="hidden xl:flex flex-1 flex-col items-center min-w-[120px]">
                                <div className="flex items-center justify-between w-full mb-1">
                                    <span className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">模擬速度</span>
                                    <div className="text-[10px] font-mono text-cyan-400">{timeScale.toFixed(1)}x</div>
                                </div>
                                <input 
                                    type="range" min="0.1" max="3.0" step="0.1" 
                                    value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                                    className="w-full h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-cyan-500"
                                />
                            </div>

                            {/* Mode Switch (Desktop Only) */}
                            <button 
                                onClick={() => { setIsShowcaseMode(true); startShowcaseMatch(); }}
                                className="hidden lg:flex px-3 py-1.5 rounded bg-slate-800/50 hover:bg-purple-900/30 border border-transparent hover:border-purple-500/50 text-xs font-bold text-slate-400 hover:text-purple-300 transition-all items-center gap-2"
                            >
                                <span>📺</span>
                                <span>展示模式</span>
                            </button>
                    </div>
                </div>

                <GameCanvas 
                    engine={engineRef.current} 
                    tool={tool}
                    selectedObstacle={selectedObstacle}
                    hpInput={hpInput}
                    selectedAgent={selectedAgent}
                    hoveredSkill={hoveredSkill}
                    isShowcaseMode={isShowcaseMode}
                    spawnMode={spawnMode}
                    draftRole={draftRole}
                    onSelect={handleSelectAgent} 
                    onWin={onWin}
                    winner={winner}
                    rematch={() => { setWinner(null); engineRef.current.restart(); setIsPlaying(true); }}
                    transitionPhase={transitionPhase}
                />

                {/* BOTTOM DOCK */}
                {/* Safe area padding added for modern phones */}
                <div className={`bg-slate-950 border-t border-slate-800 shrink-0 z-30 transition-all duration-500 w-full pb-[env(safe-area-inset-bottom)] ${isShowcaseMode ? 'translate-y-full opacity-0' : 'translate-y-0 opacity-100'}`}>

                    {/* MOBILE GRID LAYOUT (< md) - 4x2 GRID */}
                    <div className="md:hidden grid grid-cols-4 gap-2 p-2 h-auto">

                        {/* ROW 1: PRIMARY ACTIONS */}
                        <button onClick={() => toggleTool(ToolType.ADD_BLUE)} className={`h-12 tactical-btn btn-blue ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-70'}`}>
                            <span className="text-2xl">🔵</span>
                        </button>

                        <button onClick={() => toggleTool(ToolType.ADD_RED)} className={`h-12 tactical-btn btn-red ${tool === ToolType.ADD_RED ? 'active' : 'opacity-70'}`}>
                            <span className="text-2xl">🔴</span>
                        </button>

                        <div className={`relative h-12 tactical-btn p-0 ${tool === ToolType.OBSTACLE ? 'active border-cyan-500' : ''}`}>
                            <button onClick={() => toggleTool(ToolType.OBSTACLE)} className="w-full h-full flex items-center justify-center">
                                <span className="text-2xl">🧱</span>
                                <span className="text-[8px] absolute bottom-0.5 right-1 opacity-50">▼</span>
                            </button>
                            <select 
                                className="absolute inset-0 opacity-0 w-full h-full cursor-pointer"
                                value={selectedObstacle} 
                                onChange={e => { setSelectedObstacle(e.target.value); setTool(ToolType.OBSTACLE); }}
                            >
                                {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                            </select>
                        </div>

                        <button onClick={() => toggleTool(ToolType.DELETE)} className={`h-12 tactical-btn text-red-400 border-red-900/50 ${tool === ToolType.DELETE ? 'active bg-red-950/50 border-red-500' : ''}`}>
                            <span className="text-2xl">❌</span>
                        </button>

                        {/* ROW 2: CONFIG & INSPECT */}
                        <div className="h-12 flex items-center justify-center bg-slate-900 border border-slate-700 rounded-sm relative">
                            <span className="text-[8px] text-slate-500 absolute -top-1.5 left-1 bg-slate-900 px-0.5">HP</span>
                            <input 
                                type="number" 
                                value={hpInput} 
                                onChange={e => setHpInput(parseInt(e.target.value))} 
                                className="w-full h-full bg-transparent text-center text-sm font-mono text-slate-200 outline-none"
                            />
                        </div>

                        <button 
                            onClick={() => setShowMapSettings(!showMapSettings)}
                            className={`h-12 tactical-btn ${showMapSettings ? 'border-cyan-500 text-cyan-400' : ''}`}
                        >
                            <span className="text-xl">🗺️</span>
                        </button>

                        <button 
                            onClick={() => selectedAgent && setShowMobileInspector(!showMobileInspector)}
                            disabled={!selectedAgent}
                            className={`col-span-2 h-12 tactical-btn ${showMobileInspector ? 'active' : ''} ${selectedAgent ? 'border-blue-500/50 text-blue-300 animate-pulse-glow' : 'opacity-30'}`}
                        >
                            <span className="text-lg mr-2">👁️</span>
                            <span className="text-xs">單位資訊</span>
                        </button>
                    </div>

                    {/* DESKTOP FLEX LAYOUT (>= md) */}
                    <div className="hidden md:flex h-40 overflow-x-auto overflow-y-hidden">

                        {/* ZONE 1: COMMAND TOOLS (Expanded to fill space) */}
                        <div className="w-48 border-r border-slate-800 p-3 flex flex-col gap-2 shrink-0">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">地圖編輯</div>
                            <div className="flex gap-2 flex-1">
                                <div className={`flex-1 relative flex flex-col tactical-btn p-0 ${tool === ToolType.OBSTACLE ? 'active' : ''}`}>
                                    <button onClick={() => toggleTool(ToolType.OBSTACLE)} className="w-full flex-1 flex flex-col items-center justify-center gap-1">
                                        <span className="text-2xl">🧱</span>
                                        <span className="text-[10px]">地形</span>
                                    </button>
                                    <div className="h-6 w-full border-t border-slate-700 relative bg-black/20">
                                        <select 
                                            className="w-full h-full bg-transparent text-[10px] text-center appearance-none cursor-pointer text-slate-400 outline-none"
                                            value={selectedObstacle} 
                                            onChange={e => { setSelectedObstacle(e.target.value); setTool(ToolType.OBSTACLE); }}
                                        >
                                            {Object.values(OBSTACLE_DB).map(o => <option key={o.id} value={o.id}>{o.name}</option>)}
                                        </select>
                                        <span className="absolute right-1 top-1.5 text-[8px] opacity-50 pointer-events-none">▼</span>
                                    </div>
                                </div>

                                <button onClick={() => toggleTool(ToolType.DELETE)} className={`flex-1 tactical-btn flex-col text-red-400 border-red-900/50 hover:border-red-500 ${tool === ToolType.DELETE ? 'active border-red-500 bg-red-950/30' : ''}`}>
                                    <span className="text-2xl">❌</span>
                                    <span className="text-[10px]">移除</span>
                                </button>
                            </div>
                        </div>

                        {/* ZONE 2: DEPLOYMENT (Flexible Width) */}
                        <div className="flex-1 p-3 flex flex-col gap-2 relative min-w-[300px]">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1 flex justify-between">
                                <span>單位部署</span>
                                <span className="text-slate-700 font-mono">單位數: {unitCount}</span>
                            </div>

                            <div className="flex gap-4 h-full">
                                {/* Team Selectors (Sets Tool) */}
                                <div className="flex flex-col gap-2 w-28 shrink-0">
                                    <button onClick={() => toggleTool(ToolType.ADD_BLUE)} className={`flex-1 tactical-btn btn-blue flex items-center justify-between px-3 ${tool === ToolType.ADD_BLUE ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="font-bold text-xs">藍隊</span>
                                        <span className="text-lg">🔵</span>
                                    </button>
                                    <button onClick={() => toggleTool(ToolType.ADD_RED)} className={`flex-1 tactical-btn btn-red flex items-center justify-between px-3 ${tool === ToolType.ADD_RED ? 'active' : 'opacity-60 hover:opacity-100'}`}>
                                        <span className="font-bold text-xs">紅隊</span>
                                        <span className="text-lg">🔴</span>
                                    </button>
                                </div>

                                {/* Mode & Draft Config */}
                                <div className="flex-1 bg-slate-900 border border-slate-800 rounded p-2 flex flex-col gap-2 min-w-[200px]">
                                    <div className="flex bg-slate-950 rounded p-1 gap-1 shrink-0">
                                        <button onClick={() => setSpawnMode('RANDOM')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'RANDOM' ? 'bg-slate-700 text-cyan-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                            🎲 隨機
                                        </button>
                                        <button onClick={() => setSpawnMode('DRAFT')} className={`flex-1 py-1 text-[10px] font-bold rounded transition-colors ${spawnMode === 'DRAFT' ? 'bg-slate-700 text-amber-400 shadow-sm' : 'text-slate-500 hover:text-slate-300'}`}>
                                            📝 自選
                                        </button>
                                    </div>

                                    <div className="flex-1 flex items-center justify-center relative overflow-hidden">
                                        {spawnMode === 'RANDOM' ? (
                                            <div className="text-slate-600 font-mono text-xs flex flex-col items-center animate-pulse">
                                                <span className="text-2xl mb-1">🎲</span>
                                                <span>隨機職階</span>
                                            </div>
                                        ) : (
                                            <div className="flex gap-1.5 w-full justify-center">
                                                {Object.values(Role).map(role => (
                                                    <button 
                                                        key={role}
                                                        onClick={() => setDraftRole(role)}
                                                        className={`w-10 h-10 rounded border flex flex-col items-center justify-center transition-all ${draftRole === role ? 'bg-amber-900/40 border-amber-500 text-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.3)] scale-110' : 'bg-slate-800 border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'}`}
                                                        title={role}
                                                    >
                                                        <span className="text-lg -mt-1 filter drop-shadow-md">{roleIcons[role]}</span>
                                                    </button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>

                                {/* HP Pool */}
                                <div className="flex flex-col justify-center gap-1 w-16 shrink-0">
                                    <label className="text-[9px] text-slate-500 font-bold uppercase text-center">生命值</label>
                                    <input 
                                        type="number" 
                                        value={hpInput} 
                                        onChange={e => setHpInput(parseInt(e.target.value))} 
                                        className="tactical-input text-center text-lg h-10 border-slate-700 focus:border-cyan-500 px-0"
                                    />
                                </div>
                            </div>
                        </div>

                        {/* ZONE 3: MAP OPS */}
                        <div className="w-36 border-l border-slate-800 p-3 flex flex-col gap-2 shrink-0 bg-slate-950/50">
                            <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">地圖操作</div>
                            <div className="grid grid-cols-2 gap-2">
                                <div className="flex flex-col">
                                    <label className="text-[8px] text-slate-500">寬度</label>
                                    <input type="number" className="tactical-input p-1 text-center" value={mapW} onChange={e=>setMapW(Number(e.target.value))}/>
                                </div>
                                <div className="flex flex-col">
                                    <label className="text-[8px] text-slate-500">高度</label>
                                    <input type="number" className="tactical-input p-1 text-center" value={mapH} onChange={e=>setMapH(Number(e.target.value))}/>
                                </div>
                            </div>
                            <div className="flex gap-2 mt-auto">
                                <button onClick={updateMap} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center border-slate-600 hover:bg-slate-800">重建</button>
                                <button onClick={handleClear} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center text-red-400 border-red-900 hover:bg-red-950">清空單位</button>
                            </div>
                        </div>
                    </div>
                </div>
          </div>

          {/* RIGHT COLUMN: Inspector (Z-40) */}
          {/* Resizer - Hidden on small screens or when showcase */}
          {isLargeScreen && !isShowcaseMode && (
            <div 
                className="hidden lg:flex w-1 bg-slate-950 hover:bg-cyan-600 cursor-col-resize items-center justify-center shrink-0 transition-colors z-40 border-l border-slate-800"
                onMouseDown={startResizing}
                onTouchStart={startResizing}
            >
                <div className="w-[1px] h-8 bg-slate-600"></div>
            </div>
          )}

          {/* Panel - Desktop Sidebar OR Mobile Overlay Drawer */}
          {/* LOGIC SPLIT: Mobile is a Modal (Fixed), Desktop is a Flex Col (Relative) */}
          {isLargeScreen ? (
              // DESKTOP LAYOUT
              <div 
                className={`
                    flex flex-col z-40 shadow-2xl bg-slate-900 border-l border-slate-700 transition-all duration-300 relative h-full
                    ${isShowcaseMode ? 'w-0 border-l-0 overflow-hidden' : ''}
                `}
                style={{ width: !isShowcaseMode ? sidebarWidth : 0 }}
              >
                <InspectorPanel 
                    agent={selectedAgent} 
                    engine={engineRef.current}
                    logs={[]} 
                    db={engineRef.current.skillDB}
                    onHoverSkill={setHoveredSkill}
                />
              </div>
          ) : (
              // MOBILE DRAWER LAYOUT
              <div 
                className={`fixed inset-0 z-50 transition-opacity duration-300 ${showMobileInspector ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
                onClick={() => setShowMobileInspector(false)}
              >
                  {/* Backdrop */}
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-sm"></div>

                  {/* Slide-in Panel */}
                  <div 
                    className={`absolute right-0 top-0 bottom-0 w-full sm:w-[400px] bg-slate-900 shadow-2xl border-l border-slate-700 transform transition-transform duration-300 flex flex-col ${showMobileInspector ? 'translate-x-0' : 'translate-x-full'}`}
                    onClick={(e) => e.stopPropagation()}
                  >
                      {/* Mobile Header */}
                      <div className="p-4 border-b border-slate-700 bg-slate-950 flex justify-between items-center shrink-0 pt-safe-top">
                           <h3 className="font-bold text-slate-200 text-lg">單位監控面板</h3>
                           <button onClick={() => setShowMobileInspector(false)} className="w-10 h-10 flex items-center justify-center bg-slate-800 rounded-full text-slate-400 active:scale-95">✕</button>
                      </div>

                      <div className="flex-1 overflow-hidden">
                        <InspectorPanel 
                            agent={selectedAgent} 
                            engine={engineRef.current}
                            logs={[]} 
                            db={engineRef.current.skillDB}
                            onHoverSkill={setHoveredSkill}
                        />
                      </div>
                  </div>
              </div>
          )}
      </div>
    </div>
  );
}

export default App;

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { AnimState, Role, Team, MovementType } from "../../types";
import { RenderableItem } from "./grid";
import { HEX_SIZE } from "../../constants";
import { HexUtils, MapConfig, Vector } from "../utils";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public collectRenderables(
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION LOGIC ---
            let h = 0;

            if (agent.isMoving && agent.path.length > 0) {
                // Movement Interpolation
                // Linearly interpolate between start tile height and end tile height based on move progress
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                h = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                // Static / Physics Drift
                // If the unit has drifted significantly from its logical tile center (e.g., knockback),
                // sample height at its visual position to prevent clipping through walls.
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;

                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    h = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    h = getTerrainHeight(agent.q, agent.r);
                }
            }

            // Apply Visual Offset (Y is down in Canvas, so subtract height to move "up")
            const visualY = agent.py - h;

            list.push({
                y: agent.py + 1, // Sort by base position (ground level) to maintain consistency with terrain sorting
                z: 10,
                draw: (ctx) => this.drawAssembly(
                    ctx, 
                    agent, 
                    agent.px, 
                    visualY, 
                    globalTime, 
                    highlightAgent === agent,
                    false // Normal Mode
                )
            });
        });

        return list;
    }

    // Called by Renderer for Occlusion Pass
    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        globalTime: number,
        mapConfig: MapConfig
    ) {
        // Consistent height logic for silhouettes
        let h = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            h = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
            if (distSq > 100) {
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            } else {
                h = getTerrainHeight(agent.q, agent.r);
            }
        }

        const visualY = agent.py - h;

        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =================================================================================
    // 🎨 HIERARCHICAL VECTOR ASSEMBLY RENDERER
    // =================================================================================

    private drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        // 1. Setup Constraint Space
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        // Distinct Scale Factors for Roles
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; // Bulky
            case Role.WARRIOR: roleScaleMod = 1.1; break; // Standard strong
            case Role.RANGER: roleScaleMod = 0.9; break; // Agile/Slim
            case Role.MAGE: roleScaleMod = 0.9; break; // Small/Floating
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY);
        ctx.scale(scaleFactor, scaleFactor);

        // 3. Apply Physics (Z-Jump / Blast)
        // We apply Physics Z translation to the whole container (Base + Body)
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        // --- DRAW BASE & ANCHOR (Ground Level - Before Physics Translation) ---
        // This ensures the marker stays on the "Ground" even if the unit flies up
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            const assets = SpriteManager.getUnitImages(agent.role, agent.team);

            // Standard Ground Base
            ctx.save();
            ctx.drawImage(assets.base, -64, -79); 

            // NEW: FLYING UNIT ANCHOR (Target Reticle on Grid)
            if (agent.movementType === MovementType.FLYING) {
                this.drawFlyingAnchor(ctx, agent, globalTime, physX, physY, physZ);
            }

            // Casting Floor Rune (Ground level)
            if (agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill) {
                    const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                    ctx.save(); 
                    ctx.scale(1, 0.5); 
                    ctx.rotate(globalTime * 2);
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(circle, -64, -64, 128, 128); 
                    ctx.restore();
                }
            }
            ctx.restore();
        }

        // Apply Logic/Physics Offset to Body
        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); // Apply Ragdoll Rotation

        // --- PREPARE BODY TRANSFORM ---
        // Shift up to align body feet with ground (y=0)
        const BODY_GROUNDING_OFFSET = -31; 
        let bodyFloat = BODY_GROUNDING_OFFSET; 

        // Add Breathing / Hovering
        if (agent.hp > 0) {
             if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && !agent.isMoving && agent.visualStatus === 'NONE') {
                bodyFloat -= 5 + Math.sin(globalTime * 2) * 3; // Mages float higher
            }
        } else {
            bodyFloat = -5; // Dead units sink slightly into ground
        }

        ctx.translate(0, bodyFloat);

        // --- 2. Spawn Animation (Materialize) ---
        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; // From game.ts init
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); // 0 -> 1
            const eased = 1 - Math.pow(1 - progress, 3); // Cubic Out

            spawnAlpha = eased;
            const spawnStretch = 2.0 - eased; // 2.0 -> 1.0
            whiteOverlay = 1 - eased; // 1 -> 0

            // Scale body vertically around its feet (now at 0,0 due to translate)
            ctx.scale(1, spawnStretch);
            ctx.globalAlpha *= spawnAlpha;
        }

        // Hit Flash / Death Filter
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
            ctx.filter = 'brightness(200%)'; 
        } else if (whiteOverlay > 0) {
            ctx.filter = `brightness(${100 + whiteOverlay * 200}%)`;
        }

        // --- NEW: FLIGHT VFX (Under Feet) ---
        // Drawn before flipping scale so particles don't flip with facing
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            this.drawFlightVFX(ctx, agent, globalTime);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // SILHOUETTE MODE SETUP
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        // 4. Render Body (or Special Form)
        if (agent.visualStatus === 'POLYMORPH') {
            // Draw Sheep
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Standard Unit Render
            if (agent.team === Team.BLUE) {
                this.drawImperialLegion(ctx, agent, globalTime, isSilhouette);
            } else {
                this.drawArcaneCovenant(ctx, agent, globalTime, isSilhouette);
            }

            // Casting VFX (Only if alive)
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                this.drawCastingVFX(ctx, agent, globalTime);
            }

            // Frozen Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                // Ice block needs to cover body, roughly centered
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            // Stasis Overlay
            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // 6. Selection Ring & Status (Only Normal Mode & Alive)
        if (!isSilhouette) {
            this.drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            this.drawStatusEffects(ctx, agent, globalTime);

            if (isSelected && agent.hp > 0) {
                // Draw Selection Ring around Body center (approx -20)
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2 / scaleFactor; 
                ctx.beginPath();
                ctx.ellipse(0, -20, 30, 15, 0, 0, Math.PI * 2);
                ctx.stroke();
            }
        }

        ctx.restore(); // End Assembly

        // 7. NEW: Spawn Role Indicator
        // Drawn AFTER restore so it is not affected by body stretch/fade/rotation
        if (agent.spawnTimer > 0 && !isSilhouette) {
            this.drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }

    // --- NEW: Flying Unit Visual Aids ---

    private drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
        const color = agent.team === Team.BLUE ? '#60a5fa' : '#f87171'; // Blue-400 : Red-400
        const pulse = 1 + Math.sin(t * 8) * 0.1;

        ctx.save();

        // 1. Dashed Ground Ring
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.setLineDash([4, 4]); // Dashed line
        ctx.beginPath();
        // Slightly larger than standard base shadow (rx=40, ry=20)
        ctx.ellipse(0, 0, 35 * pulse, 18 * pulse, 0, 0, Math.PI * 2);
        ctx.stroke();

        // 2. Center Crosshair (Logical Center)
        ctx.setLineDash([]);
        ctx.lineWidth = 1;
        const len = 10;
        ctx.beginPath();
        ctx.moveTo(-len, 0); ctx.lineTo(len, 0);
        ctx.moveTo(0, -len/2); ctx.lineTo(0, len/2);
        ctx.stroke();

        // 3. Vertical Connector (Depth Cue)
        // Connects Ground Center (0,0) to Body Center (physX, physY - physZ)
        // Since we are currently at Ground (0,0) relative to drawX/Y, and Body is shifted by phys,
        // we draw a line to (physX, physY - physZ).

        // Note: Body is offset by ~ -31 (BODY_GROUNDING_OFFSET). We connect to roughly the feet.
        const feetY = physY - physZ - 30; 

        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(physX, feetY);
        ctx.strokeStyle = color;
        ctx.globalAlpha = 0.4;
        ctx.setLineDash([2, 2]);
        ctx.stroke();

        ctx.restore();
    }

    private drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; // Light Blue / Light Red

        ctx.save();
        ctx.translate(0, 10); // Position slightly below feet (which are at 0,0)
        ctx.scale(1, 0.5); // Perspective squash for ground plane effect

        // Rotating Wind/Energy Swirl
        ctx.rotate(t * 3);

        // Ring 1
        ctx.beginPath();
        ctx.arc(0, 0, 20 + Math.sin(t * 10) * 2, 0, Math.PI * 1.5);
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.6;
        ctx.lineCap = 'round';
        ctx.stroke();

        // Ring 2 (Inner, faster)
        ctx.beginPath();
        ctx.arc(0, 0, 12, Math.PI, Math.PI * 3.5);
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.4;
        ctx.stroke();

        // Particles
        /* Simple particle effect without new system overhead */
        ctx.fillStyle = color;
        for(let i=0; i<3; i++) {
            const angle = t * 5 + i * (Math.PI * 2 / 3);
            const r = 15;
            const px = Math.cos(angle) * r;
            const py = Math.sin(angle) * r;
            ctx.globalAlpha = 0.8;
            ctx.beginPath(); ctx.arc(px, py, 2, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    }

    private drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
        const assets = SpriteManager.getUnitImages(agent.role, agent.team);
        const totalDuration = 0.5;
        const alpha = Math.max(0, agent.spawnTimer / totalDuration);
        const yOffset = -85 * scale; // Moved up higher because body is now higher

        ctx.save();
        ctx.translate(x, y + yOffset);
        const popScale = 1.0 + alpha * 0.2;
        ctx.scale(popScale, popScale);
        ctx.globalAlpha = alpha;

        ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
        ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

        ctx.drawImage(assets.icon, -12, -12, 24, 24);

        ctx.font = 'bold 10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillStyle = '#fff';
        ctx.strokeStyle = 'rgba(0,0,0,0.8)';
        ctx.lineWidth = 2;
        ctx.strokeText(agent.role, 0, 28);
        ctx.fillText(agent.role, 0, 28);

        ctx.restore();
    }

    private drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        if (agent.hp <= 0) return;

        ctx.save();
        // Undo facing flip so icons don't flip
        if (agent.facing < 0) ctx.scale(-1, 1);

        const HEAD_Y = -75; // Adjusted head position for icons

        // 1. STUN
        if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
            const icon = AssetManager.getStatusIcon('STUN');
            const angle = t * 5;
            ctx.drawImage(icon, -20 + Math.cos(angle)*10, HEAD_Y + Math.sin(angle)*5, 24, 24);
            ctx.drawImage(icon, -10 + Math.cos(angle + 2)*10, HEAD_Y - 10 + Math.sin(angle + 2)*5, 16, 16);
        }

        // 2. SILENCE
        if (agent.silenceTimer > 0) {
            const icon = AssetManager.getStatusIcon('SILENCE');
            ctx.drawImage(icon, 15, HEAD_Y - 5 + Math.sin(t * 3) * 3, 24, 24);
        }

        // 3. BANISH
        if (agent.banished && agent.visualStatus === 'NONE') {
            const icon = AssetManager.getStatusIcon('BANISH');
            ctx.globalAlpha = 0.7;
            ctx.drawImage(icon, -12, HEAD_Y - 20 + Math.sin(t * 2) * 5, 24, 24);
        }

        // 4. DoT
        if (agent.dotTimer > 0) {
            const pulse = 1 + Math.sin(t * 10) * 0.2;
            const iconSize = 28 * pulse; 
            const icon = AssetManager.getStatusIcon('POISON'); 
            const glow = AssetManager.getGlowSprite('#ef4444');
            ctx.globalCompositeOperation = 'lighter';
            ctx.drawImage(glow, -35 - iconSize/2, HEAD_Y - iconSize/2, iconSize*2, iconSize*2);
            ctx.globalCompositeOperation = 'source-over';
            ctx.drawImage(icon, -35, HEAD_Y, iconSize, iconSize);

            ctx.globalAlpha = 0.8;
            for(let i=0; i<5; i++) {
                const cycle = (t * 2 + i * 0.7) % 1;
                const yOff = -cycle * 60; 
                const xOff = Math.sin(t * 5 + i) * 15;
                const size = (1 - cycle) * 7;
                ctx.fillStyle = i % 2 === 0 ? '#10b981' : '#a855f7';
                if (cycle < 1) {
                    ctx.beginPath(); ctx.arc(xOff, -20 + yOff, size, 0, Math.PI*2); ctx.fill();
                }
            }
        }

        // 5. HoT
        if (agent.hotTimer > 0) {
            const icon = AssetManager.getStatusIcon('REGEN');
            ctx.drawImage(icon, 25, HEAD_Y, 24, 24);
            ctx.globalAlpha = 0.8;
            ctx.fillStyle = '#4ade80';
            ctx.font = 'bold 14px sans-serif';
            for(let i=0; i<3; i++) {
                const cycle = (t * 1.5 + i * 0.4) % 1;
                const yOff = -cycle * 40;
                const xOff = Math.cos(t * 3 + i) * 15;
                if (cycle < 1) ctx.fillText('+', xOff, -20 + yOff);
            }
        }

        ctx.restore();
    }

    // --- VFX METHODS ---

    private drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (!skill) return;

        const progress = 1 - (agent.castTimer / skill.cast);
        const color = skill.color;

        ctx.save();
        if (agent.facing < 0) ctx.scale(-1, 1);

        // 1. Rising Energy Lines
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = color;
        ctx.lineWidth = 3; 
        const lineCount = 5 + Math.floor(progress * 8); 
        for(let i=0; i<lineCount; i++) {
            const h = (t * 150 + i * 40) % 90; 
            const alpha = 1 - (h / 90);
            const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
            ctx.globalAlpha = alpha;
            ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
        }

        // 2. Converging Rings
        if (progress > 0.2) {
            const ringScale = (1 - progress) * 2.5; 
            ctx.globalAlpha = progress;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

            ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
            ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
            ctx.restore();
        }

        // 3. Hand Glow
        ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
        ctx.fillStyle = color;
        ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

        // 4. Final Flash
        if (progress > 0.9) {
            ctx.globalAlpha = (progress - 0.9) * 10;
            ctx.fillStyle = '#fff';
