    else ctx.fill();

    if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && agent.hp > 0) {
        const orbGlow = AssetManager.getGlowSprite(glowColor);
        for(let i=0; i<3; i++) {
            const angle = t * 2 + (i * Math.PI * 2 / 3);
            const ox = Math.cos(angle) * (agent.role === Role.MAGE ? 20 : 15) * (1 - energyGather * 0.8);
            const oy = Math.sin(angle) * 5;
            ctx.save(); ctx.translate(ox, oy - 20);
            if(!isSilhouette) { 
                ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.6;
                ctx.drawImage(orbGlow, -10, -15, 20, 20);
                ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1.0;
                ctx.fillStyle = glowColor;
                ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.fill();
            } else {
                ctx.strokeStyle = glowColor;
                ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.stroke();
            }
            ctx.restore();
        }
    }

    if (!isSilhouette) {
        ctx.fillStyle = secondary;
        ctx.beginPath(); ctx.ellipse(0, -10, 6, 15, 0, 0, Math.PI*2); ctx.fill();
        const coreGlow = AssetManager.getGlowSprite(glowColor);
        ctx.save(); ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = 0.5 + Math.sin(t*10)*0.2 + energyGather * 0.5;
        ctx.drawImage(coreGlow, -10, -25, 20, 20); ctx.restore();
        ctx.fillStyle = glowColor;
        ctx.beginPath(); ctx.arc(0, -15, 4, 0, Math.PI*2); ctx.fill();
    }

    ctx.save();
    const headBob = (agent.hp > 0) ? Math.sin(t*3.5)*2 : 0;
    ctx.translate(0, (agent.role === Role.TANK ? -45 : -40) + headBob); 

    if (isSilhouette) {
        ctx.fillStyle = 'transparent'; ctx.strokeStyle = silhouetteColor;
    } else {
        ctx.fillStyle = '#f5f5f4';
    }

    ctx.beginPath();
    if (agent.role === Role.TANK) {
        ctx.moveTo(-12, -10); ctx.lineTo(12, -10); ctx.lineTo(0, 12);
    } else {
        ctx.moveTo(-6, -8); ctx.lineTo(6, -8); ctx.lineTo(0, 8);
    }

    if (isSilhouette) ctx.stroke();
    else {
        ctx.fill();
        ctx.fillStyle = glowColor;
        ctx.fillRect(-3, -4, 2, 2); ctx.fillRect(1, -4, 2, 2);
    }
    ctx.restore();

    ctx.save();
    ctx.translate(15, -15);
    if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
        const bladeAngle = (agent.hp > 0) ? Math.sin(t) * 0.2 + (agent.animState === AnimState.ATTACK ? -1 : 0) : 0;
        ctx.rotate(bladeAngle);
        if(!isSilhouette) {
            const wepGlow = AssetManager.getGlowSprite(glowColor);
            ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
            ctx.drawImage(wepGlow, -10, -20, 30, 30); ctx.restore();
        } else {
            ctx.strokeStyle = silhouetteColor;
        }

        if (agent.role === Role.TANK) {
            ctx.lineWidth = 3;
            if (!isSilhouette) ctx.strokeStyle = glowColor;
            ctx.beginPath(); ctx.arc(0, 0, 20, Math.PI/2, 3*Math.PI/2); ctx.stroke();
        } else {
            ctx.beginPath();
            ctx.moveTo(0, 10); ctx.lineTo(5, -30); ctx.lineTo(-2, -25);
            if (isSilhouette) ctx.stroke(); else { ctx.fillStyle = glowColor; ctx.fill(); }
        }
    } else if (agent.role === Role.RANGER) {
        ctx.translate(5, 0);
        ctx.rotate(agent.animState === AnimState.ATTACK ? -0.5 : 0);
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.stroke();
        } else {
            ctx.fillStyle = secondary;
            ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.fill();
            const wepGlow = AssetManager.getGlowSprite(glowColor);
            ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
            ctx.drawImage(wepGlow, 0, -10, 20, 20); ctx.restore();
            ctx.fillStyle = glowColor; ctx.beginPath(); ctx.arc(10, 0, 3, 0, Math.PI*2); ctx.fill();
        }
    }
    ctx.restore();

    ctx.restore(); 
}

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171'; // Blue-400 : Red-400

    // We are at Ground Level (0,0).
    // Unit Feet are at (physX, physY - physZ).
    // We want to draw a column connecting Ground(0,0) to Feet.

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. "Divine Light" Lift Column (Gradient Fill)
    const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
    // Transparent at bottom to blend with ground, stronger at top to show lift source
    grad.addColorStop(0, isBlue ? 'rgba(96, 165, 250, 0.0)' : 'rgba(248, 113, 113, 0.0)');
    grad.addColorStop(0.3, isBlue ? 'rgba(96, 165, 250, 0.1)' : 'rgba(248, 113, 113, 0.1)');
    grad.addColorStop(1.0, isBlue ? 'rgba(96, 165, 250, 0.3)' : 'rgba(248, 113, 113, 0.3)');

    // Column Shape (Tapered Cylinder)
    const baseW = 20; // Ground width
    const topW = 15;  // Feet width

    ctx.beginPath();
    // Start Bottom Left
    ctx.moveTo(-baseW, 0);
    // Line to Top Left
    ctx.lineTo(feetX - topW, feetY);
    // Curve Top (Feet)
    ctx.ellipse(feetX, feetY, topW, topW * 0.5, 0, Math.PI, 0); // Top semi-circle
    // Line to Bottom Right
    ctx.lineTo(baseW, 0);
    // Curve Bottom (Ground)
    ctx.ellipse(0, 0, baseW, baseW * 0.5, 0, 0, Math.PI); // Bottom semi-circle

    ctx.fillStyle = grad;
    ctx.fill();

    // 2. Rising Energy Streams / Rings
    // Adds motion inside the column
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.5;

    const height = Math.abs(feetY);
    // Density of rings based on height
    const ringCount = Math.max(2, Math.floor(height / 25));

    for(let i=0; i<ringCount; i++) {
        // Scroll rings upward
        const phase = (t * 1.5 + i / ringCount) % 1; 

        // Interpolate position between ground(0,0) and feet(feetX, feetY)
        const curX = feetX * phase;
        const curY = feetY * phase;

        // Interpolate width
        const curW = baseW + (topW - baseW) * phase;

        // Fade in/out at ends
        const alpha = Math.sin(phase * Math.PI); 

        ctx.globalAlpha = alpha * 0.6;
        ctx.beginPath();
        ctx.ellipse(curX, curY, curW, curW * 0.5, 0, 0, Math.PI * 2);
        ctx.stroke();
    }

    // 3. Ground Anchor Ring (Target Reticle)
    ctx.globalAlpha = 1.0;
    const pulse = 1 + Math.sin(t * 8) * 0.1;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([4, 4]); 
    ctx.beginPath();
    ctx.ellipse(0, 0, 35 * pulse, 18 * pulse, 0, 0, Math.PI * 2);
    ctx.stroke();

    // Crosshair Center
    ctx.setLineDash([]);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(-8, 0); ctx.lineTo(8, 0);
    ctx.moveTo(0, -4); ctx.lineTo(0, 4);
    ctx.stroke();

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 10); // Slightly below body center (feet)
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 5); // Faster spin

    // Inner Turbine Ring
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.5;
    ctx.stroke();

    // Outer Thruster Arcs
    ctx.beginPath();
    ctx.arc(0, 0, 18 + Math.sin(t * 15) * 2, 0, Math.PI * 1.5);
    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.7;
    ctx.lineCap = 'round';
    ctx.stroke();

    // Particles (Exhaust)
    ctx.fillStyle = color;
    for(let i=0; i<3; i++) {
        const angle = t * 8 + i * (Math.PI * 2 / 3);
        const r = 16;
        const px = Math.cos(angle) * r;
        const py = Math.sin(angle) * r;
        ctx.globalAlpha = 0.8;
        ctx.beginPath(); ctx.arc(px, py, 2.5, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
        if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill && skill.visual) {
            const icon = AssetManager.getSkillIcon(skill.visual, skill.color);
            ctx.save();
            // Move Higher relative to Body top (approx -120 local)
            ctx.translate(0, -110);
            const pulse = 1 + Math.sin(t * 10) * 0.1;
            ctx.scale(pulse, pulse);

            const glow = AssetManager.getGlowSprite(skill.color);
            ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.6;
            ctx.drawImage(glow, -32, -32, 64, 64);
            ctx.globalCompositeOperation = 'source-over';
            ctx.globalAlpha = 1.0;

            ctx.drawImage(icon, -12, -12, 24, 24);

            // Cast Bar
            ctx.fillStyle = '#000';
            ctx.fillRect(-14, 20, 28, 5); 
            ctx.fillStyle = skill.color;
            const pct = Math.max(0, 1 - (agent.castTimer / skill.cast));
            ctx.fillRect(-14, 20, 28 * pct, 5);
            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    ctx.save();
    // Undo facing flip so icons don't flip
    if (agent.facing < 0) ctx.scale(-1, 1);

    const HEAD_Y = -75; // Adjusted head position for icons

    // 1. STUN
    if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
        const icon = AssetManager.getStatusIcon('STUN');
        const angle = t * 5;
        ctx.drawImage(icon, -20 + Math.cos(angle)*10, HEAD_Y + Math.sin(angle)*5, 24, 24);
        ctx.drawImage(icon, -10 + Math.cos(angle + 2)*10, HEAD_Y - 10 + Math.sin(angle + 2)*5, 16, 16);
    }

    // 2. SILENCE
    if (agent.silenceTimer > 0) {
        const icon = AssetManager.getStatusIcon('SILENCE');
        ctx.drawImage(icon, 15, HEAD_Y - 5 + Math.sin(t * 3) * 3, 24, 24);
    }

    // 3. BANISH
    if (agent.banished && agent.visualStatus === 'NONE') {
        const icon = AssetManager.getStatusIcon('BANISH');
        ctx.globalAlpha = 0.7;
        ctx.drawImage(icon, -12, HEAD_Y - 20 + Math.sin(t * 2) * 5, 24, 24);
    }

    // 4. DoT
    if (agent.dotTimer > 0) {
        const pulse = 1 + Math.sin(t * 10) * 0.2;
        const iconSize = 28 * pulse; 
        const icon = AssetManager.getStatusIcon('POISON'); 
        const glow = AssetManager.getGlowSprite('#ef4444');
        ctx.globalCompositeOperation = 'lighter';
        ctx.drawImage(glow, -35 - iconSize/2, HEAD_Y - iconSize/2, iconSize*2, iconSize*2);
        ctx.globalCompositeOperation = 'source-over';
        ctx.drawImage(icon, -35, HEAD_Y, iconSize, iconSize);

        ctx.globalAlpha = 0.8;
        for(let i=0; i<5; i++) {
            const cycle = (t * 2 + i * 0.7) % 1;
            const yOff = -cycle * 60; 
            const xOff = Math.sin(t * 5 + i) * 15;
            const size = (1 - cycle) * 7;
            ctx.fillStyle = i % 2 === 0 ? '#10b981' : '#a855f7';
            if (cycle < 1) {
                ctx.beginPath(); ctx.arc(xOff, -20 + yOff, size, 0, Math.PI*2); ctx.fill();
            }
        }
    }

    // 5. HoT
    if (agent.hotTimer > 0) {
        const icon = AssetManager.getStatusIcon('REGEN');
        ctx.drawImage(icon, 25, HEAD_Y, 24, 24);
        ctx.globalAlpha = 0.8;
        ctx.fillStyle = '#4ade80';
        ctx.font = 'bold 14px sans-serif';
        for(let i=0; i<3; i++) {
            const cycle = (t * 1.5 + i * 0.4) % 1;
            const yOff = -cycle * 40;
            const xOff = Math.cos(t * 3 + i) * 15;
            if (cycle < 1) ctx.fillText('+', xOff, -20 + yOff);
        }
    }

    ctx.restore();
}

export function drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
    const assets = SpriteManager.getUnitImages(agent.role, agent.team);
    const totalDuration = 0.5;
    const alpha = Math.max(0, agent.spawnTimer / totalDuration);
    const yOffset = -85 * scale; // Moved up higher because body is now higher

    ctx.save();
    ctx.translate(x, y + yOffset);
    const popScale = 1.0 + alpha * 0.2;
    ctx.scale(popScale, popScale);
    ctx.globalAlpha = alpha;

    ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
    ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

    ctx.drawImage(assets.icon, -12, -12, 24, 24);

    ctx.font = 'bold 10px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    ctx.lineWidth = 2;
    ctx.strokeText(agent.role, 0, 28);
    ctx.fillText(agent.role, 0, 28);

    ctx.restore();
}

import { Agent } from "../game";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";
import { Role, Team, MovementType } from "../../types";
import { RenderableItem } from "./grid";
import { HEX_SIZE } from "../../constants";
import { HexUtils, MapConfig } from "../utils";

// Modules
import { drawImperialLegion, drawArcaneCovenant } from "../renderers/units/UnitModels";
import { drawFlyingAnchor, drawFlightVFX, drawCastingVFX, drawStatusEffects, drawStatusIcons, drawSpawnIndicator } from "../renderers/units/UnitVisuals";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public collectRenderables(
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // --- HEIGHT CORRECTION LOGIC ---
            let h = 0;

            if (agent.isMoving && agent.path.length > 0) {
                // Movement Interpolation
                // Linearly interpolate between start tile height and end tile height based on move progress
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                h = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                // Static / Physics Drift
                // If the unit has drifted significantly from its logical tile center (e.g., knockback),
                // sample height at its visual position to prevent clipping through walls.
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;

                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    h = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    h = getTerrainHeight(agent.q, agent.r);
                }
            }

            // Apply Visual Offset (Y is down in Canvas, so subtract height to move "up")
            const visualY = agent.py - h;

            list.push({
                y: agent.py + 1, // Sort by base position (ground level) to maintain consistency with terrain sorting
                z: 10,
                draw: (ctx) => this.drawAssembly(
                    ctx, 
                    agent, 
                    agent.px, 
                    visualY, 
                    globalTime, 
                    highlightAgent === agent,
                    false // Normal Mode
                )
            });
        });

        return list;
    }

    // Called by Renderer for Occlusion Pass
    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        globalTime: number,
        mapConfig: MapConfig
    ) {
        // Consistent height logic for silhouettes
        let h = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            h = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
            if (distSq > 100) {
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                h = getTerrainHeight(visualHex.q, visualHex.r);
            } else {
                h = getTerrainHeight(agent.q, agent.r);
            }
        }

        const visualY = agent.py - h;

        this.drawAssembly(ctx, agent, agent.px, visualY, globalTime, false, true);
    }

    // =================================================================================
    // 🎨 HIERARCHICAL VECTOR ASSEMBLY RENDERER
    // =================================================================================

    private drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        // 1. Setup Constraint Space
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;

        // Distinct Scale Factors for Roles
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; // Bulky
            case Role.WARRIOR: roleScaleMod = 1.1; break; // Standard strong
            case Role.RANGER: roleScaleMod = 0.9; break; // Agile/Slim
            case Role.MAGE: roleScaleMod = 0.9; break; // Small/Floating
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }

        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY);
        ctx.scale(scaleFactor, scaleFactor);

        // 3. Apply Physics (Z-Jump / Blast)
        // We apply Physics Z translation to the whole container (Base + Body)
        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        // --- DRAW BASE & ANCHOR (Ground Level - Before Physics Translation) ---
        // This ensures the marker stays on the "Ground" even if the unit flies up
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            const assets = SpriteManager.getUnitImages(agent.role, agent.team);

            // Standard Ground Base
            ctx.save();
            ctx.drawImage(assets.base, -64, -79); 

            // FLYING UNIT ANCHOR (Target Reticle on Grid + Lift Beam)
            if (agent.movementType === MovementType.FLYING) {
                drawFlyingAnchor(ctx, agent, globalTime, physX, physY, physZ);
            }

            // Casting Floor Rune (Ground level)
            if (agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill) {
                    const circle = AssetManager.getMagicCircle(skill.color, skill.tag === 'ULT');
                    ctx.save(); 
                    ctx.scale(1, 0.5); 
                    ctx.rotate(globalTime * 2);
                    ctx.globalAlpha = 0.6;
                    ctx.drawImage(circle, -64, -64, 128, 128); 
                    ctx.restore();
                }
            }
            ctx.restore();
        }

        // Apply Logic/Physics Offset to Body
        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); // Apply Ragdoll Rotation

        // --- PREPARE BODY TRANSFORM ---
        // Shift up to align body feet with ground (y=0)
        const BODY_GROUNDING_OFFSET = -31; 
        let bodyFloat = BODY_GROUNDING_OFFSET; 

        // Add Breathing / Hovering
        if (agent.hp > 0) {
             if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && !agent.isMoving && agent.visualStatus === 'NONE') {
                bodyFloat -= 5 + Math.sin(globalTime * 2) * 3; // Mages float higher
            }
        } else {
            bodyFloat = -5; // Dead units sink slightly into ground
        }

        ctx.translate(0, bodyFloat);

        // --- 2. Spawn Animation (Materialize) ---
        let spawnAlpha = 1.0;
        let whiteOverlay = 0;

        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; // From game.ts init
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); // 0 -> 1
            const eased = 1 - Math.pow(1 - progress, 3); // Cubic Out

            spawnAlpha = eased;
            const spawnStretch = 2.0 - eased; // 2.0 -> 1.0
            whiteOverlay = 1 - eased; // 1 -> 0

            // Scale body vertically around its feet (now at 0,0 due to translate)
            ctx.scale(1, spawnStretch);
            ctx.globalAlpha *= spawnAlpha;
        }

        // Hit Flash / Death Filter
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
            ctx.filter = 'brightness(200%)'; 
        } else if (whiteOverlay > 0) {
            ctx.filter = `brightness(${100 + whiteOverlay * 200}%)`;
        }

        // --- FLIGHT VFX (Under Feet) ---
        // Drawn before flipping scale so particles don't flip with facing
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            drawFlightVFX(ctx, agent, globalTime);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // SILHOUETTE MODE SETUP
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        // 4. Render Body (or Special Form)
        if (agent.visualStatus === 'POLYMORPH') {
            // Draw Sheep
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(globalTime * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Standard Unit Render
            if (agent.team === Team.BLUE) {
                drawImperialLegion(ctx, agent, globalTime, isSilhouette);
            } else {
                drawArcaneCovenant(ctx, agent, globalTime, isSilhouette);
            }

            // Casting VFX (Only if alive)
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                drawCastingVFX(ctx, agent, globalTime);
            }

            // Frozen Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                // Ice block needs to cover body, roughly centered
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            // Stasis Overlay
            if (agent.visualStatus === 'STASIS') {
                ctx.save();
                ctx.fillStyle = '#facc15';
                ctx.globalAlpha = 0.4;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath();
                ctx.ellipse(0, -15, 25, 50, 0, 0, Math.PI*2);
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
                ctx.restore();
            }
        }

        // 6. Selection Ring & Status (Only Normal Mode & Alive)
        if (!isSilhouette) {
            drawStatusIcons(ctx, agent, globalTime, drawX, drawY, scaleFactor);
            drawStatusEffects(ctx, agent, globalTime);

            if (isSelected && agent.hp > 0) {
                // Draw Selection Ring around Body center (approx -20)
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2 / scaleFactor; 
                ctx.beginPath();
                ctx.ellipse(0, -20, 30, 15, 0, 0, Math.PI * 2);
                ctx.stroke();
            }
        }

        ctx.restore(); // End Assembly

        // 7. Spawn Role Indicator
        // Drawn AFTER restore so it is not affected by body stretch/fade/rotation
        if (agent.spawnTimer > 0 && !isSilhouette) {
            drawSpawnIndicator(ctx, agent, drawX, drawY, scaleFactor);
        }
    }
}

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";

// Optimization: Precompute Hex Polygon Offsets
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS.push({ 
        x: HEX_SIZE * Math.cos(angle), 
        y: HEX_SIZE * Math.sin(angle) * ISO_SCALE_Y 
    });
}

// Procedural Noise function
function noise(q: number, r: number) {
    return Math.sin(q * 12.9898 + r * 78.233) * 43758.5453 - Math.floor(Math.sin(q * 12.9898 + r * 78.233) * 43758.5453);
}

export const TerrainRenderer = {

    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any
    ) {
        const BASE_THICKNESS = 12; // Visual foundation thickness
        const topY = height; 

        // 1. Draw Side Faces (The Stack)
        // Rotated 45deg: Front faces are 5, 0, 1 (Right-Down, Down, Left-Down)
        const visibleIndices = [5, 0, 1];

        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const c1 = HEX_CORNERS[i];
            const c2 = HEX_CORNERS[j];

            const x1 = x + c1.x;
            const y1_top = y + c1.y - topY;
            const x2 = x + c2.x;
            const y2_top = y + c2.y - topY;

            const y1_bottom = y + c1.y + BASE_THICKNESS;
            const y2_bottom = y + c2.y + BASE_THICKNESS;

            const grad = ctx.createLinearGradient(0, y - topY, 0, y + BASE_THICKNESS);
            const baseColor = (i === 0) ? theme.sideDark : theme.sideLight;
            grad.addColorStop(0, baseColor);
            grad.addColorStop(1, '#020617'); 

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.closePath();
            ctx.fill();

            // "Layer Lines" for Block Stack Effect
            if (height > BLOCK_HEIGHT) {
                ctx.strokeStyle = 'rgba(0,0,0,0.3)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    ctx.moveTo(x1, y + c1.y - hStep);
                    ctx.lineTo(x2, y + c2.y - hStep);
                }
                ctx.stroke();
            }

            // Outline Side
            ctx.strokeStyle = 'rgba(255,255,255,0.05)'; 
            ctx.lineWidth = 1; 
            ctx.stroke();
        }

        // 2. Draw Top Face (Base)
        this.traceTopFace(ctx, x, y - topY);

        const topGrad = ctx.createRadialGradient(x, y - topY, 0, x, y - topY, size);
        topGrad.addColorStop(0, theme.top);
        topGrad.addColorStop(1, theme.detail); 
        ctx.fillStyle = topGrad;
        ctx.fill();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        ctx.save();
        ctx.fillStyle = detailColor;
        ctx.strokeStyle = detailColor;
        ctx.globalAlpha = 0.3; 

        const n = noise(q, r);
        const n2 = noise(r, q);

        if (type === 'VOID') {
            if (n > 0.6) {
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(cx - 10, cy - 5);
                ctx.lineTo(cx, cy + 5);
                ctx.lineTo(cx + 10, cy - 2);
                ctx.stroke();
            } else if (n < 0.3) {
                ctx.beginPath();
                ctx.arc(cx + n2 * 10, cy + n * 10, 2, 0, Math.PI * 2);
                ctx.fill();
            }
        } else if (type === 'FOREST') {
            const tufts = Math.floor(n * 3) + 1;
            for(let i=0; i<tufts; i++) {
                const ox = (noise(q+i, r) - 0.5) * 20;
                const oy = (noise(r, q+i) - 0.5) * 10;
                ctx.beginPath();
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox - 3, cy + oy - 5);
                ctx.moveTo(cx + ox, cy + oy);
                ctx.lineTo(cx + ox + 3, cy + oy - 5);
                ctx.stroke();
            }
        } else if (type === 'ICE') {
            ctx.globalAlpha = 0.5;
            ctx.fillStyle = '#fff';
            if (n > 0.5) {
                ctx.beginPath();
                ctx.moveTo(cx - 15, cy + 5);
                ctx.lineTo(cx + 15, cy - 5);
                ctx.lineTo(cx + 18, cy - 4);
                ctx.lineTo(cx - 12, cy + 6);
                ctx.fill();
            }
        } else if (type === 'MAGMA') {
            ctx.strokeStyle = '#000';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.4;
            ctx.beginPath();
            ctx.moveTo(cx - 10, cy);
            ctx.lineTo(cx - 5, cy + 5 * n);
            ctx.lineTo(cx + 5, cy - 5 * n2);
            ctx.lineTo(cx + 10, cy);
            ctx.stroke();
            if (n > 0.8) {
                ctx.fillStyle = '#ef4444';
                ctx.globalAlpha = 0.6;
                ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI*2); ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = '#92400e';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.2;
            ctx.beginPath();
            ctx.arc(cx - 10, cy - 10, 30, 0.5, 2.0);
            ctx.stroke();
        }

        ctx.restore();
    },

    traceTopFace(ctx: CanvasRenderingContext2D, x: number, y: number) {
        ctx.beginPath();
        const c0 = HEX_CORNERS[0];
        ctx.moveTo(x + c0.x, y + c0.y);
        for (let i = 1; i < 6; i++) {
            const c = HEX_CORNERS[i];
            ctx.lineTo(x + c.x, y + c.y);
        }
        ctx.closePath();
    }
};

import { TerrainRenderer } from "./TerrainRenderer";

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Note: y here should be the "visual top" y (y - topY)
        size: number,
        specialStatus: string | undefined,
        dangerInfo: {color: string, progress: number} | undefined,
        lightColor: string | null,
        lightIntensity: number,
        flash: any,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number
    ) {
        // Helper to trace the hex shape at current position
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        // 1. SPECIAL STATUS FLOOR EFFECT (Frozen/Polymorph)
        if (specialStatus) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // 2. AOE TELEGRAPH (Danger Zone)
        if (dangerInfo) {
            trace(); 
            ctx.save();
            // Tile Coloring
            const opacity = 0.1 + dangerInfo.progress * 0.6;
            ctx.fillStyle = dangerInfo.color;
            ctx.globalAlpha = opacity;
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.fill(); 

            // Glowing Border
            ctx.strokeStyle = dangerInfo.color;
            ctx.lineWidth = 1 + dangerInfo.progress * 2;
            ctx.globalAlpha = 0.8;
            ctx.stroke();

            // Rising Particles
            if (dangerInfo.progress > 0.2) {
                const particleCount = 3 + Math.floor(dangerInfo.progress * 5);
                ctx.fillStyle = dangerInfo.color;
                ctx.globalCompositeOperation = 'lighter'; 

                for(let i=0; i<particleCount; i++) {
                    const seed = (Math.abs(q * 100 + r * 10) + i * 123.45);
                    const speed = 20 + (seed % 20);
                    const t = (globalTime * speed * 0.05 + seed) % 1; 
                    const pAlpha = 1 - t;

                    // Simple particle offset logic relative to tile center
                    const pX = x + Math.sin(t * 10 + seed) * (size * 0.5);
                    const pY = y - (t * 40); 

                    ctx.globalAlpha = pAlpha * opacity; 
                    const pSize = 1 + (seed % 2);

                    ctx.beginPath();
                    ctx.arc(pX, pY, pSize, 0, Math.PI*2);
                    ctx.fill();
                }
            }
            ctx.restore();
        }

        // 3. Dynamic Lighting (Projectile Pass)
        if (lightColor && lightIntensity > 0) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // 4. Interactive Highlights (Hover/Range/Flash)
        if (flash || isRange || isHover || hasUnit) {
            ctx.save();
            trace(); 

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2; 
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.8; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.15)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 3; 
                ctx.stroke(); 
            }

            if (flash) {
                ctx.globalCompositeOperation = 'lighter';
                ctx.fillStyle = flash.color;
                ctx.globalAlpha = 0.6;
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            if (hasUnit && !isHover && !dangerInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.3)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils } from "../utils";
import { Hex, Skill, Projectile } from "../../types";

// Renderers
import { TerrainRenderer } from "../renderers/grid/TerrainRenderer";
import { GridOverlays } from "../renderers/grid/GridOverlays";

export interface RenderableItem {
    y: number;
    z: number;
    draw: (ctx: CanvasRenderingContext2D) => void;
}

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

export class GridSystem {
    // Optimization: Cache tiles to avoid re-parsing keys and re-calculating positions every frame
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuseable buffers to reduce GC pressure
    private _dangerZones = new Map<string, {color: string, progress: number}>();
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    // Passthrough
    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtScreenPoint(mx: number, my: number, camera: {x: number, y: number, zoom: number}, engine: GameEngine): Hex | null {
        this.ensureCache(engine);

        // Convert screen mouse to world coordinates (unzoomed)
        const wx = mx / camera.zoom + camera.x;
        const wy = my / camera.zoom + camera.y;

        const candidates: CachedTile[] = [];
        const limit = HEX_SIZE * 2; 

        for (const tile of this._tileCache) {
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - (tile.py - tile.h));
            if (dist < limit) { 
                candidates.push(tile);
            }
        }

        // Sort by visual depth (Front to Back)
        candidates.sort((a, b) => b.py - a.py);

        for (const cand of candidates) {
            const testHex = HexUtils.fromPx(wx, wy + cand.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === cand.q && rounded.r === cand.r) {
                return { q: cand.q, r: cand.r };
            }
        }

        return null;
    }

    /**
     * Identifies agents that are visually blocked by taller terrain in front of them.
     */
    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);

            // In Diamond Isometric, "Front" means Higher Y on screen.
            // Blocks with higher Y and higher Z can occlude units with lower Y.
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            let isBlocked = false;

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);

                    // Check if neighbor is physically "in front" (Screen Y is larger)
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         // If the blocking tile is strictly taller
                         if (nHeight > uHeight) {
                             isBlocked = true;
                             break;
                         }
                    }
                }
            }

            if (isBlocked) {
                occluded.push(a);
            }
        });

        return occluded;
    }

    collectRenderables(
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        flashes: any[],
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ): RenderableItem[] {
        this.ensureCache(engine);

        const list: RenderableItem[] = [];
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Clear and Reuse Buffers
        this._dangerZones.clear();
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        engine.agents.forEach(a => {
            if (a.hp > 0 && a.castingSkillIdx !== -1) {
                const s = a.skills[a.castingSkillIdx];
                if (s && s.type === 'AOE') {
                    let centerHex: Hex | null = null;
                    if (a.targetHex) centerHex = a.targetHex;
                    else if (a.target) centerHex = {q: a.target.q, r: a.target.r};
                    else centerHex = {q: a.q, r: a.r};

                    if (centerHex) {
                        const progress = 1 - (a.castTimer / s.cast);
                        // Using raw HexUtils range which creates arrays, acceptable for small radii
                        HexUtils.range(centerHex, s.aoeRadius || 1).forEach(h => {
                            this._dangerZones.set(`${h.q},${h.r}`, {
                                color: s.color, 
                                progress: progress
                            });
                        });
                    }
                }
            }

            if(a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') {
                    this._unitVisualStatus.set(key, a.visualStatus);
                }
            }
        });

        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            // --- TRANSITION LOGIC ---
            let visualY = py;

            if (transitionPhase !== 'IDLE') {
                const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                const d = dist / maxDist; 

                if (transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (transitionT > trigger) {
                        const fallT = Math.min(1, (transitionT - trigger) * 2.5);
                        const easedFall = fallT * fallT * fallT;
                        visualY += easedFall * 1000;
                    }
                } else if (transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                }
            }

            if (visualY > py + 800) continue;

            const flash = flashes.find(f => f.q === q && f.r === r);
            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                // HEIGHT AWARE RANGE CHECK
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const tileH = h;
                const bonus = Math.max(0, Math.floor((agentH - tileH) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;

                if (HexUtils.dist({q, r}, highlightAgent) <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;

            const k = `${q},${r}`;
            const dangerInfo = this._dangerZones.get(k);
            const hasUnit = this._unitPresence.has(k);
            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;
            const PROJ_LIGHT_RADIUS = 40; 
            const PROJ_LIGHT_RADIUS_SQ = PROJ_LIGHT_RADIUS * PROJ_LIGHT_RADIUS;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / PROJ_LIGHT_RADIUS);
                }
            }

            list.push({
                y: visualY, 
                z: 0,        
                draw: (ctx) => {
                    // 1. Draw Physical Block
                    TerrainRenderer.drawBlockGeometry(ctx, px, visualY, HEX_SIZE, h, theme);

                    // 2. Draw Texture Detail
                    TerrainRenderer.drawTerrainDetail(ctx, px, visualY - h, q, r, scene.textureType, theme.detail);

                    // 3. Draw Overlays (Status, Range, Danger, Lighting)
                    GridOverlays.drawOverlays(
                        ctx, px, visualY - h, HEX_SIZE,
                        specialStatus, dangerInfo,
                        lightColor, Math.min(1, lightIntensity),
                        flash, isRange, rangeColor, isHover, hasUnit,
                        q, r, globalTime
                    );
                }
            });
        }

        return list;
    }
}

import { Team } from './types';

export const HEX_SIZE = 36; // Slightly smaller to accommodate height
export const BLOCK_HEIGHT = 24; // Increased to 24 for distinct "Step" look (Tactics Ogre style)
export const MAX_TERRAIN_TIER = 6; // Max height steps
export const ISO_SCALE_Y = 0.58; // Moved here from utils.ts

// --- VISUAL STANDARDS (UNIT ANCHORS) ---
export const UNIT_VISUAL_HEIGHT = 90; // Standardized "Head" position. Ensures clearance for tallest sprites.
export const HUD_PADDING = 10;        // Safety buffer between sprite top and UI elements.
export const HUD_ANCHOR_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING;

