    UI_BG: '#0a0a0c', // LoL Client Dark Grey
    UI_BORDER: '#785a28', // Hextech Gold
    SHADOW: 'rgba(0, 0, 0, 0.6)',

    // FACTION THEMES (WoW Style)
    TEAMS: {
