            // ALLIANCE: Royal Blue, Gold, Marble
            main: '#2563eb', 
            dark: '#1e3a8a', 
            light: '#fbbf24', // Gold trim
            glow: 'rgba(59, 130, 246, 0.8)',
            accent: '#f8fafc' // Marble White
        }, 
        [Team.RED]: { 
            // HORDE: Crimson, Iron Grey, Bone
            main: '#dc2626', 
            dark: '#450a0a', 
            light: '#a1a1aa', // Iron Grey
            glow: 'rgba(220, 38, 38, 0.8)',
