import { HEX_SIZE, ISO_SCALE_Y } from "../constants";
import { Hex, Point } from "../types";

export interface MapConfig {
    w: number;
    h: number;
    offsetX: number;
    offsetY: number;
}

// FFT Style Isometric Constants
// Projection Angle: ~35 degrees
// Scale Y to simulate 3D perspective on standard hex grid
// ISO_SCALE_Y moved to constants.ts

// Rotation Constants (45 degrees)
const ANGLE = Math.PI / 4;
const SIN_A = Math.sin(ANGLE);
const COS_A = Math.cos(ANGLE);

// --- Integer Hashing Constants ---
// Hash = (q + 128) << 16 | (r + 128)
// This maps q,r to a unique 32-bit integer.
// Neighbors can be found by adding constant offsets directly to the hash.
// Directions: [1,0], [1,-1], [0,-1], [-1,0], [-1,1], [0,1]
// Q is high 16 bits (step = 65536)
// R is low 16 bits (step = 1)
const Q_STEP = 1 << 16;
const R_STEP = 1;

export const NEIGHBOR_HASH_OFFSETS = [
    Q_STEP,             // (1, 0)
    Q_STEP - R_STEP,    // (1, -1)
    -R_STEP,            // (0, -1)
    -Q_STEP,            // (-1, 0)
    -Q_STEP + R_STEP,   // (-1, 1)
    R_STEP              // (0, 1)
];

export const Easing = {
    // Smooth start and end (Quadratic)
    easeInOutQuad: (t: number) => t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t,

    // Overshoot slightly (Elastic-like)
    easeOutBack: (t: number) => {
        const c1 = 1.70158;
        const c3 = c1 + 1;
        return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
    },

    // Pull back before shooting forward
    easeInBack: (t: number) => {
        const c1 = 1.70158;
        const c3 = c1 + 1;
        return c3 * t * t * t - c1 * t * t;
    }
};

export const HexUtils = {
    /**
     * Converts Offset Coordinates to Axial.
     * Uses Odd-R offset logic.
     */
    offsetToAxial: (col: number, row: number, config: MapConfig): Hex => {
        const q = col - (row - (row & 1)) / 2;
        const r = row;
        return { q: Math.floor(q), r };
    },

    /**
     * ROTATED ISOMETRIC PROJECTION
     * 1. Convert Hex to orthogonal (Cartesian Pointy-Topped)
     * 2. Rotate 45 degrees
     * 3. Squash Y for 2.5D effect
     */
    toPx: (q: number, r: number, config: MapConfig): Point => {
        // 1. Standard Pointy-topped Hex Conversion (Cartesian)
        const cx = (Math.sqrt(3) * q + Math.sqrt(3) / 2 * r) * HEX_SIZE;
        const cy = (1.5 * r) * HEX_SIZE; // Fixed 3.0/2 -> 1.5

        // 2. Rotate 45 degrees (Rotation Matrix)
        const rx = cx * COS_A - cy * SIN_A;
        const ry = cx * SIN_A + cy * COS_A;

        // 3. Apply Offset and Y-Compression
        return { 
            x: config.offsetX + rx, 
            y: config.offsetY + ry * ISO_SCALE_Y 
        };
    },

    /**
     * Inverse Projection (Mouse Picking)
     * Reverses the Rotated Isometric Projection.
     */
    fromPx: (x: number, y: number, config: MapConfig): Hex => {
        // 1. Remove Offset
        const dx = x - config.offsetX;
        const dy = y - config.offsetY;

        // 2. Un-squash Y
        const unsquashedY = dy / ISO_SCALE_Y;

        // 3. Inverse Rotation (-45 degrees)
        // x = x'*cos + y'*sin
        // y = -x'*sin + y'*cos
        const cx = dx * COS_A + unsquashedY * SIN_A;
        const cy = -dx * SIN_A + unsquashedY * COS_A;

        // 4. Standard Hex Inverse Calculation
        const q = (Math.sqrt(3)/3 * cx - 1/3 * cy) / HEX_SIZE;
        const r = (2/3 * cy) / HEX_SIZE;

        return HexUtils.round(q, r);
    },

    /**
     * Rounds floating point axial coords to the nearest valid Hex.
     */
    round: (q: number, r: number): Hex => {
        let s = -q - r;
        let qi = Math.round(q);
        let ri = Math.round(r);
        let si = Math.round(s);
        const q_diff = Math.abs(qi - q);
        const r_diff = Math.abs(ri - r);
        const s_diff = Math.abs(si - s);

        if (q_diff > r_diff && q_diff > s_diff) qi = -ri - si;
        else if (r_diff > s_diff) ri = -qi - si;

        return { q: qi, r: ri };
    },

    /**
     * Manhattan distance on a hex grid.
     */
    dist: (a: Hex, b: Hex): number => {
        const aq = Math.round(a.q); const ar = Math.round(a.r);
        const bq = Math.round(b.q); const br = Math.round(b.r);
        return (Math.abs(aq - bq) + Math.abs(aq + ar - bq - br) + Math.abs(ar - br)) / 2;
    },

    key: (h: Hex): string => `${h.q},${h.r}`,

    /**
     * High-performance Integer Hashing for Hex Coordinates.
     * Replaces string keys in critical loops.
     * Supports range roughly -128 to 127, sufficient for game maps.
     */
    hash: (q: number, r: number): number => {
        return (q + 128) << 16 | (r + 128);
    },

    /**
     * Decodes hash back to Hex.
     */
    unhash: (h: number): Hex => {
        const r = (h & 0xFFFF) - 128;
        const q = (h >> 16) - 128;
        return { q, r };
    },

    lerp: (a: number, b: number, t: number): number => a + (b - a) * t,

    neighbors: (h: Hex): Hex[] => {
        const dirs = [[1, 0], [1, -1], [0, -1], [-1, 0], [-1, 1], [0, 1]];
        return dirs.map(d => ({ q: h.q + d[0], r: h.r + d[1] }));
    },

    range: (center: Hex, n: number): Hex[] => {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    }
};

export const Vector = {
    sub: (a: Point, b: Point): Point => ({ x: a.x - b.x, y: a.y - b.y }),
    add: (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y }),
    mult: (a: Point, s: number): Point => ({ x: a.x * s, y: a.y * s }),

    // Linear Interpolation between two vectors
    lerp: (a: Point, b: Point, t: number): Point => ({
        x: a.x + (b.x - a.x) * t,
        y: a.y + (b.y - a.y) * t
    }),

    mag: (a: Point): number => Math.sqrt(a.x * a.x + a.y * a.y),

    normalize: (a: Point): Point => {
        const m = Vector.mag(a);
        return m === 0 ? { x: 0, y: 0 } : { x: a.x / m, y: a.y / m };
    },

    dist: (a: Point, b: Point): number => Vector.mag(Vector.sub(a, b))
};

import { Agent, GameEngine } from "../game";
import { MovementType } from "../../types";
import { HexUtils } from "../utils";

// Physics Constants
const PHYSICS_STIFFNESS_ALIVE = 150;
const PHYSICS_STIFFNESS_DEAD = 0;
const PHYSICS_DAMPING_ALIVE = 25; 
const PHYSICS_DAMPING_DEAD = 1.0; 
const GRAVITY = 2000; 

export class PhysicsEngine {

    public update(a: Agent, dt: number, engine: GameEngine) {
        const isDead = a.hp <= 0;
        const stiffness = isDead ? PHYSICS_STIFFNESS_DEAD : PHYSICS_STIFFNESS_ALIVE; 

        // If airborne (z > 0), reduce drag to allow projectile motion
        const isAirborne = a.physics.z > 0;
        const damping = (isDead && isAirborne) ? 0.5 : (isDead ? PHYSICS_DAMPING_DEAD : PHYSICS_DAMPING_ALIVE);

        // 1. Spring Forces (Return to 0,0 relative local space)
        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        // 2. Acceleration (Force - Damping)
        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        // 3. Integrate Velocity
        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        // 4. Vertical Dynamics (Gravity vs Flight)
        if (a.movementType === MovementType.FLYING && !isDead) {
            // Flying Unit Logic
            if (a.stunTimer > 0 || a.visualStatus === 'FROZEN' || a.visualStatus === 'POLYMORPH') {
                // CRASH STATE: Apply Gravity immediately
                a.physics.vz -= GRAVITY * dt;
            } else {
                // HOVER STATE: Bob around a target altitude
                // Increased to 90 to visually clear walls (80px)
                const hoverHeight = 90; 
                const hoverFreq = 3;
                const targetZ = hoverHeight + Math.sin(engine.battleTime * hoverFreq) * 10;

                // Soft spring to maintain height
                const dz = targetZ - a.physics.z;
                a.physics.vz += dz * 5 * dt;
                a.physics.vz *= 0.95; // Drag to stop oscillation
            }
        } else {
            // Ground Unit Logic
            if (isDead || isAirborne) {
                a.physics.vz -= GRAVITY * dt;
            }
        }

        // 5. Integrate Position
        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // 6. Ground Collision (Bounce)
        if (a.physics.z < 0) {
            a.physics.z = 0;
            // Elastic collision with ground loss
            if (Math.abs(a.physics.vz) > 100) {
                a.physics.vz = -a.physics.vz * 0.5; // Bounce back
                a.physics.vx *= 0.6; // Ground friction
                a.physics.vy *= 0.6;
                a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        // 7. World Position Drift (Slide effect for dead units or knockback correction)
        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px;
            const dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            // Increased snap threshold to stop jitter
            if (distSq > 0.5) {
                const driftSpeed = 12.0 * dt;
                a.px += dx * driftSpeed;
                a.py += dy * driftSpeed;
                if (distSq < 2) {
                    a.px = targetPos.x;
                    a.py = targetPos.y;
                }
            } else {
                a.px = targetPos.x;
                a.py = targetPos.y;
            }
        } else if (isDead) {
            // Apply physics velocity to world position (Flying through air)
            a.px += a.physics.vx * dt * 0.1; 
            a.py += a.physics.vy * dt * 0.1;
        }
    }
}

import { Agent, GameEngine } from "../game";
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";

export class TargetingSystem {

    // =========================================================================================
    // 🏹 RANGE CALCULATION (High Ground Bonus)
    // =========================================================================================

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        const h1 = engine.map.getTerrainHeight(a.q, a.r);
        const h2 = engine.map.getTerrainHeight(targetQ, targetR);

        // Bonus: +1 Range per Block Height advantage
        // Only applies if attacker is higher. No penalty for low ground (to avoid frustration).
        const deltaH = h1 - h2;
        const heightBonus = Math.max(0, Math.floor(deltaH / BLOCK_HEIGHT));

        return baseRange + heightBonus;
    }

    // =========================================================================================
    // 🎯 TARGET ACQUISITION
    // =========================================================================================

    public updateTarget(a: Agent, engine: GameEngine) {
        if (a.target && (a.target.hp <= 0 || a.target.banished)) a.target = null;
        let minD = 999;
        let t: Agent | null = null;

        for (const o of engine.agents) {
            if (o.team !== a.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(a, o);
                if (d < minD) { minD = d; t = o; }
            }
        }
        a.target = t;
    }

    public calculateOptimalTarget(source: Agent, skill: Skill, engine: GameEngine): { targetAgent: Agent | null, targetHex: Hex | null } {
        // 1. Special Case: Silence Logic (Prioritize Casters/Ults)
        if (skill.ccType === 'SILENCE' || skill.ccType2 === 'SILENCE') {
            const enemies = engine.agents.filter(a => 
                a.team !== source.team && a.hp > 0 && !a.banished && 
                HexUtils.dist(source, a) <= this.getEffectiveRange(source, a.q, a.r, skill.range, engine)
            );

            if (enemies.length > 0) {
                enemies.sort((a, b) => {
                    const score = (u: Agent) => {
                        if (u.castingSkillIdx === -1) return 0;
                        const s = u.skills[u.castingSkillIdx];
                        if (s?.tag === 'ULT') return 3;
                        if (s?.tag === 'ACTIVE') return 2;
                        return 1;
                    };
                    const sA = score(a);
                    const sB = score(b);
                    if (sA !== sB) return sB - sA;
                    return HexUtils.dist(source, a) - HexUtils.dist(source, b);
                });
                return { targetAgent: enemies[0], targetHex: null };
            }
        }

        // 2. AOE Logic (Find Best Cluster)
        if (skill.type === 'AOE') {
            const candidateHexes = new Set<number>();
            const radius = skill.aoeRadius || 1;
            // Rough search: Range + Radius + small buffer.
            const searchDist = skill.range + 5; 

            engine.agents.forEach(enemy => {
                if (enemy.team !== source.team && enemy.hp > 0 && !enemy.banished) {
                    if (HexUtils.dist(source, enemy) <= searchDist) {
                        candidateHexes.add(HexUtils.hash(enemy.q, enemy.r));
                        HexUtils.neighbors(enemy).forEach(n => candidateHexes.add(HexUtils.hash(n.q, n.r)));
                    }
                }
            });

            let bestHex: Hex | null = null;
            let bestScore = -1;

            candidateHexes.forEach(hHash => {
                const h = HexUtils.unhash(hHash);
                if (!engine.map.isValid(h.q, h.r)) return;

                // Range Check: Can source cast to this ground position?
                const effRange = this.getEffectiveRange(source, h.q, h.r, skill.range, engine);
                if (HexUtils.dist(source, h) > effRange) return;

                let score = 0;
                let hitCount = 0;

                for (const target of engine.agents) {
                    if (target.hp <= 0 || target.banished) continue;

                    if (HexUtils.dist(h, target) <= radius) {
                        if (skill.power >= 0) {
                            if (target.team !== source.team) {
                                hitCount++;
                                score += 10;
                                if (target.castingSkillIdx !== -1) score += 5;
                            }
                        } else {
                            if (target.team === source.team) {
                                hitCount++;
                                score += 10;
                                if (target.hp < target.maxHp * 0.5) score += 5;
                            }
                        }
                    }
                }

                if (hitCount > 0 && score > bestScore) {
                    bestScore = score;
                    bestHex = h;
                }
            });

            if (bestHex) {
                return { targetAgent: null, targetHex: bestHex };
            }
        }

        // 3. Default Single Target Logic (Nearest)
        let minD = 999;
        let t: Agent | null = null;
        for (const o of engine.agents) {
            if (o.team !== source.team && o.hp > 0 && !o.banished) {
                const d = HexUtils.dist(source, o);
                // Check against Height-Aware Range
                const effRange = this.getEffectiveRange(source, o.q, o.r, skill.range, engine);
                if (d <= effRange && d < minD) { minD = d; t = o; }
            }
        }
        return { targetAgent: t, targetHex: null };
    }
}

import { Agent, GameEngine } from "../game";
import { Hex, MovementType } from "../../types";
import { HexUtils, NEIGHBOR_HASH_OFFSETS } from "../utils";
import { BLOCK_HEIGHT } from "../../constants";
import { OBSTACLE_DB } from "../../data/obstacles";
import { TargetingSystem } from "./TargetingSystem";

const PATHFINDING_MAX_ITERATIONS = 2500; 
const QUEUE_CAPACITY = 4096; 

export class Pathfinder {
    // Memory Buffers (Reused to avoid GC)
    private _pfQueue: Int32Array; 
    private _pfCameFrom: Map<number, number> = new Map();
    private _pfBlockers: Set<number> = new Set();

    constructor() {
        this._pfQueue = new Int32Array(QUEUE_CAPACITY);
    }

    public findPath(
        startAgent: Agent, 
        endQ: number, 
        endR: number, 
        range: number,
        ignoreUnits: boolean, 
        engine: GameEngine,
        targeting: TargetingSystem
    ): Hex[] {
        const startH = HexUtils.hash(startAgent.q, startAgent.r);

        // Optimization: Pre-check if start satisfies range (using Height Bonus from TargetingSystem)
        const effRange = targeting.getEffectiveRange(startAgent, endQ, endR, range, engine);
        const startDist = HexUtils.dist({q: startAgent.q, r: startAgent.r}, {q: endQ, r: endR});
        if (startDist <= effRange) return [];

        this._pfCameFrom.clear();
        this._pfBlockers.clear();

        // 1. Populate Blockers
        // If ignoreUnits is TRUE (Ghost Mode), we only block Walls/Obstacles
        if (!ignoreUnits) {
            for (const a of engine.agents) {
                if (a.hp > 0 && !a.banished && a !== startAgent) {
                    const h = HexUtils.hash(a.q, a.r);
                    this._pfBlockers.add(h);

                    if (a.isMoving && a.path.length > 0) {
                        const hp = HexUtils.hash(a.path[0].q, a.path[0].r);
                        this._pfBlockers.add(hp);
                    }
                }
            }
        }

        let head = 0; 
        let tail = 0; 
        this._pfQueue[head++] = startH; 
        this._pfCameFrom.set(startH, -1); 

        let iterations = 0;
        let foundHash = -1;
        const targetHex = { q: endQ, r: endR };

        while (tail < head) {
            iterations++;
            if (iterations > PATHFINDING_MAX_ITERATIONS) break;

            const currentH = this._pfQueue[tail++]; 
            const currentHex = HexUtils.unhash(currentH);

            // SUCCESS CONDITION: Inside Range? (Check height for this specific tile)
            const currentEffRange = targeting.getEffectiveRange(currentHex, targetHex.q, targetHex.r, range, engine);
            if (HexUtils.dist(currentHex, targetHex) <= currentEffRange) {
                foundHash = currentH;
                break;
            }

            for(let j = 0; j < 6; j++) {
                const offset = NEIGHBOR_HASH_OFFSETS[j];
                const nextH = currentH + offset;

                if (this._pfCameFrom.has(nextH)) continue;

                // Map Bounds Check
                if (!engine.map.isValidHash(nextH)) continue;

                // Static Obstacle Check
                if (engine.map.hasObstacleHash(nextH)) {
                    // Check obstacle type permissions
                    const obstacleTypeId = engine.map.obstacles.get(HexUtils.key(HexUtils.unhash(nextH)));
                    const obstacleDef = OBSTACLE_DB[obstacleTypeId || 'WALL'];

                    if (startAgent.movementType === MovementType.FLYING) {
                        if (obstacleDef?.blocksFlying) continue;
                    } else {
                        if (obstacleDef?.blocksMovement) continue;
                    }
                }

                // Dynamic Unit Check (Only if not ignoring units)
                if (!ignoreUnits && this._pfBlockers.has(nextH)) {
                    continue;
                }

                // --- TACTICS OGRE HEIGHT CHECK ---
                // Flying units IGNORE terrain height traversal costs
                if (startAgent.movementType !== MovementType.FLYING) {
                    const currentTerrainH = engine.map.getTerrainHeight(currentHex.q, currentHex.r);
                    const nextHexCoord = HexUtils.unhash(nextH);
                    const nextTerrainH = engine.map.getTerrainHeight(nextHexCoord.q, nextHexCoord.r);
                    const deltaH = Math.abs(nextTerrainH - currentTerrainH);

                    // Allow climb/drop if deltaH <= Jump Height (in pixels)
                    // Using max(1, jump) to ensure at least 1 block can be traversed by default
                    const maxClimb = Math.max(1, startAgent.jump) * BLOCK_HEIGHT;

                    if (deltaH > maxClimb) {
                        continue; // Too steep!
                    }
                }

                this._pfCameFrom.set(nextH, currentH);

                if (head < QUEUE_CAPACITY) {
                    this._pfQueue[head++] = nextH;
                }
            }
        }

        if (foundHash !== -1) {
            const path: Hex[] = [];
            let curr = foundHash;

            let sanity = 0;
            while (curr !== startH && sanity++ < 100) {
                path.push(HexUtils.unhash(curr));
                const prev = this._pfCameFrom.get(curr);
                if (prev === undefined || prev === -1) break;
                curr = prev;
            }
            return path.reverse();
        }

        return [];
    }
}

import { Agent, GameEngine } from "../game";
import { HexUtils, Vector } from "../utils";
import { AnimState, Hex, NodeState, MovementType } from "../../types";

// Modules
import { PhysicsEngine } from "../physics/PhysicsEngine";
import { Pathfinder } from "../ai/Pathfinder";
import { TargetingSystem } from "../ai/TargetingSystem";

const STACKING_RESOLUTION_FORCE = 5;

export class MovementSystem {
    // Logic Modules
    public physics: PhysicsEngine;
    public pathfinder: Pathfinder;
    public targeting: TargetingSystem;

    // Optimization: Reuse Stacking Map to reduce GC
    private _stackingMap = new Map<number, Agent[]>();

    constructor() {
        this.physics = new PhysicsEngine();
        this.pathfinder = new Pathfinder();
        this.targeting = new TargetingSystem();
    }

    // =========================================================================================
    // 🏹 PROXIES (For backward compatibility & cleaner access)
    // =========================================================================================

    public getEffectiveRange(a: Hex, targetQ: number, targetR: number, baseRange: number, engine: GameEngine): number {
        return this.targeting.getEffectiveRange(a, targetQ, targetR, baseRange, engine);
    }

    public updateTarget(a: Agent, engine: GameEngine) {
        this.targeting.updateTarget(a, engine);
    }

    public calculateOptimalTarget(source: Agent, skill: any, engine: GameEngine) {
        return this.targeting.calculateOptimalTarget(source, skill, engine);
    }

    // =========================================================================================
    // 🏃 MOVEMENT & PHYSICS ORCHESTRATION
    // =========================================================================================

    public updatePhysics(a: Agent, dt: number, engine: GameEngine) {
        this.physics.update(a, dt, engine);
    }

    public updateMovement(a: Agent, dt: number, engine: GameEngine) {
        // Use per-agent move speed WITH dynamic multiplier (Charge effect)
        a.moveProgress += a.moveSpeed * a.moveSpeedMult * dt;

        const c = HexUtils.toPx(a.q, a.r, engine.mapConfig);
        const nextHex = a.path[0];
        const n = HexUtils.toPx(nextHex.q, nextHex.r, engine.mapConfig);

        // Simple facing logic based on screen X
        if (n.x > c.x) a.facing = 1;
        else if (n.x < c.x) a.facing = -1;

        a.px = HexUtils.lerp(c.x, n.x, a.moveProgress);
        a.py = HexUtils.lerp(c.y, n.y, a.moveProgress);

        if (a.moveProgress >= 1) {
            // Commit move
            engine.updateAgentPosition(a, nextHex.q, nextHex.r);
            engine.log(a, 'MOVE', '移動', `(${nextHex.q},${nextHex.r})`, '抵達目的地');

            a.isMoving = false;
            a.moveSpeedMult = 1.0; // Reset speed after step completes

            // Small nudge to separate stacked units visually if they glitch
            a.physics.vx -= a.facing * STACKING_RESOLUTION_FORCE; 
        }
    }

    public moveAgentToHex(a: Agent, targetHex: Hex, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        if (a.isMoving) {
            a.moveSpeedMult = speedMult; // Update dynamic speed
            a.setAnim(AnimState.MOVE);
            return NodeState.RUNNING;
        }

        // Check range (With Height Bonus)
        const effRange = this.targeting.getEffectiveRange(a, targetHex.q, targetHex.r, r, engine);
        if (HexUtils.dist(a, targetHex) <= effRange) {
            a.setAnim(AnimState.COMBAT_IDLE);
            return NodeState.SUCCESS;
        }

        // 1. Try Standard Pathfinding (Respecting Allies)
        let path = this.pathfinder.findPath(a, targetHex.q, targetHex.r, r, false, engine, this.targeting);

        // 2. Fallback: Ghost Pathfinding (Ignoring Allies)
        // If normal path failed, try to find a path ignoring units to see if "direction" exists
        if (path.length === 0) {
            path = this.pathfinder.findPath(a, targetHex.q, targetHex.r, r, true, engine, this.targeting); 
        }

        if (path.length > 0) {
            const next = path[0];

            // CRITICAL CHECK: Even if we found a ghost path, is the IMMEDIATE NEXT STEP blocked?
            if (engine.isBlocked(next.q, next.r, a.id, a.movementType)) {
                // Wait queue logic
                a.setAnim(AnimState.COMBAT_IDLE);
                // Only log block once to avoid spam (throttling)
                if (Math.random() < 0.05) {
                    engine.log(a, 'MOVE', '移動', `(${next.q},${next.r})`, '路徑被阻擋，等待中');
                }
                return NodeState.RUNNING; 
            }

            engine.log(a, 'MOVE', '移動', `前往 (${next.q},${next.r})`, '開始移動');
            a.path = [next];
            a.trajectory = path; // Visual only
            a.isMoving = true;
            a.moveProgress = 0;
            a.moveSpeedMult = speedMult;
            a.setAnim(AnimState.MOVE);

            // Physics Lean (Visual flair)
            const dir = a.facing;
            a.physics.vx += dir * 2; 

            return NodeState.RUNNING;
        }

        // Truly unreachable (walled off)
        return NodeState.FAILURE;
    }

    public moveAgent(a: Agent, t: Agent, r: number, engine: GameEngine, speedMult: number = 1.0): NodeState {
        // When chasing a unit, we want to get within range R of them.
        return this.moveAgentToHex(a, {q: t.q, r: t.r}, r, engine, speedMult);
    }

    public resolveStacking(engine: GameEngine) {
        this._stackingMap.clear();
        const map = this._stackingMap;

        engine.agents.forEach(a => {
            if (a.hp <= 0 || a.banished) return;
            const h = HexUtils.hash(a.q, a.r);
            if (!map.has(h)) map.set(h, []);
            map.get(h)!.push(a);
        });

        map.forEach((list, hash) => {
            if (list.length > 1) {
                const coords = HexUtils.unhash(hash);

                const stationary = list.filter(a => !a.isMoving);
                const keep = stationary.length > 0 ? stationary[0] : list[0];
                const toDisplace = list.filter(a => a !== keep);

                toDisplace.forEach(agent => {
                    const neighbors = HexUtils.neighbors(coords);
                    for (let i = neighbors.length - 1; i > 0; i--) {
                        const j = Math.floor(Math.random() * (i + 1));
                        [neighbors[i], neighbors[j]] = [neighbors[j], neighbors[i]];
                    }

                    let target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.isBlocked(n.q, n.r, engine, agent.id, agent.movementType));

                    // Fallback: Try valid but not obstacle (ignoring units)
                    if (!target) target = neighbors.find(n => engine.map.isValid(n.q, n.r) && !engine.map.hasObstacle(n.q, n.r));

                    if (target) {
                        engine.updateAgentPosition(agent, target.q, target.r);
                        // Cancel current move to allow physics drift to slide unit visually
                        if (agent.isMoving) {
                            agent.isMoving = false;
                            agent.path = [];
                        }
                    }
                });
            }
        });
    }
}

export function createCanvas(w: number, h: number) {
    const canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d')!;
    ctx.imageSmoothingEnabled = true; 
    return { canvas, ctx };
}

import { Role, Team } from "../../types";
import { PALETTE } from "../../constants";
import { createCanvas } from "./CanvasUtils";

// Dimensions
const BASE_SIZE = 128;
const ICON_SIZE = 64;
const WEAPON_SIZE = 128;

export const UnitFactory = {

    generateTokenBase(team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BASE_SIZE, BASE_SIZE);
        const cx = BASE_SIZE / 2;
        const cy = BASE_SIZE / 2 + 15; // Offset slightly down
        const rx = 40;
        const ry = 20; 
        const height = 16; 

        // Drop Shadow
        ctx.fillStyle = 'rgba(0,0,0,0.6)';
        ctx.beginPath(); 
        ctx.ellipse(cx, cy + 5, rx + 6, ry + 6, 0, 0, Math.PI * 2); 
        ctx.fill();

        if (team === Team.RED) {
            // --- HORDE STYLE (Spiked, Iron, Crimson) ---
            ctx.fillStyle = '#1c1917'; 

            // Spikes
            for (let i = 0; i < 6; i++) {
                const angle = (i * Math.PI * 2) / 6;
                const sx = cx + Math.cos(angle) * (rx + 5);
                const sy = cy + Math.sin(angle) * (ry + 5);
                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(sx + Math.cos(angle) * 15, sy + Math.sin(angle) * 15 - 10); 
                ctx.lineTo(sx + Math.cos(angle + 0.2) * 5, sy + Math.sin(angle + 0.2) * 5);
                ctx.fill();
            }

            // Side (Thickness)
            const gradSide = ctx.createLinearGradient(0, cy - height, 0, cy + ry);
            gradSide.addColorStop(0, '#450a0a'); 
            gradSide.addColorStop(0.5, '#1c1917'); 
            gradSide.addColorStop(1, '#450a0a');
            ctx.fillStyle = gradSide;

            ctx.beginPath(); 
            ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI, false); 
            ctx.lineTo(cx + rx, cy - height); 
            ctx.ellipse(cx, cy - height, rx, ry, 0, 0, Math.PI, true); 
            ctx.lineTo(cx - rx, cy); 
            ctx.fill();

            // Top Surface
            ctx.fillStyle = '#7f1d1d'; 
            ctx.beginPath(); 
            ctx.ellipse(cx, cy - height, rx, ry, 0, 0, Math.PI * 2); 
            ctx.fill();

            // Iron Rim
            ctx.strokeStyle = '#a1a1aa'; 
            ctx.lineWidth = 4; 
            ctx.beginPath(); 
            ctx.ellipse(cx, cy - height, rx - 2, ry - 2, 0, 0, Math.PI * 2); 
            ctx.stroke();

        } else {
            // --- ALLIANCE STYLE (Smooth, Gold, Royal Blue) ---

            // Side (Thickness)
            const gradSide = ctx.createLinearGradient(0, cy - height, 0, cy + ry);
            gradSide.addColorStop(0, '#fbbf24'); 
            gradSide.addColorStop(0.5, '#b45309'); 
            gradSide.addColorStop(1, '#fbbf24');
            ctx.fillStyle = gradSide;

            ctx.beginPath(); 
            ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI, false); 
            ctx.lineTo(cx + rx, cy - height); 
            ctx.ellipse(cx, cy - height, rx, ry, 0, 0, Math.PI, true); 
            ctx.lineTo(cx - rx, cy); 
            ctx.fill();

            // Top Surface (Marble/Light)
            const gradTop = ctx.createRadialGradient(cx, cy - height, 0, cx, cy - height, rx);
            gradTop.addColorStop(0, '#f8fafc'); 
            gradTop.addColorStop(1, '#e2e8f0');
            ctx.fillStyle = gradTop; 
            ctx.beginPath(); 
            ctx.ellipse(cx, cy - height, rx - 3, ry - 3, 0, 0, Math.PI * 2); 
            ctx.fill();

            // Blue Ring
            ctx.strokeStyle = '#2563eb'; 
            ctx.lineWidth = 2; 
            ctx.beginPath(); 
            ctx.ellipse(cx, cy - height, rx * 0.7, ry * 0.7, 0, 0, Math.PI * 2); 
            ctx.stroke();
        }
        return canvas;
    },

    generateRoleIcon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);
        const cx = ICON_SIZE / 2;
        const cy = ICON_SIZE / 2;

        const isBlue = team === Team.BLUE;
        const color = isBlue ? '#2563eb' : '#dc2626'; 
        const secColor = isBlue ? '#fbbf24' : '#52525b';

        ctx.shadowColor = 'rgba(0,0,0,0.5)'; 
        ctx.shadowBlur = 4;
        ctx.lineJoin = 'round'; 
        ctx.lineCap = 'round';

        switch (role) {
            case Role.TANK:
                ctx.fillStyle = secColor; 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2;
                if (isBlue) {
                    // Shield Shape
                    ctx.beginPath(); 
                    ctx.moveTo(cx - 15, cy - 15); 
                    ctx.lineTo(cx + 15, cy - 15); 
                    ctx.lineTo(cx + 15, cy); 
                    ctx.quadraticCurveTo(cx, cy + 25, cx, cy + 25); 
                    ctx.quadraticCurveTo(cx - 15, cy, cx - 15, cy); 
                    ctx.closePath();
                } else {
                    // Tower Shield (Square with spikes)
                    ctx.beginPath();
                    ctx.rect(cx - 14, cy - 18, 28, 36);
                }
                ctx.fill(); 
                ctx.stroke();

                // Center Dot/Spike
                ctx.fillStyle = color; 
                ctx.beginPath(); 
                ctx.arc(cx, cy, isBlue ? 6 : 8, 0, Math.PI * 2); 
                ctx.fill();
                break;

            case Role.WARRIOR:
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 3; 
                ctx.beginPath();
                if (isBlue) {
                    // Sword
                    ctx.moveTo(cx, cy - 20); ctx.lineTo(cx, cy + 15); 
                    ctx.moveTo(cx - 8, cy + 15); ctx.lineTo(cx + 8, cy + 15); 
                    ctx.moveTo(cx, cy + 15); ctx.lineTo(cx, cy + 25);
                } else {
                    // Double Axe
                    ctx.moveTo(cx, cy + 20); ctx.lineTo(cx, cy - 20); // Handle
                    // Left Blade
                    ctx.moveTo(cx, cy - 15); 
                    ctx.quadraticCurveTo(cx - 15, cy - 25, cx - 20, cy - 5); 
                    ctx.quadraticCurveTo(cx - 10, cy, cx, cy - 5);
                    // Right Blade
                    ctx.moveTo(cx, cy - 15); 
                    ctx.quadraticCurveTo(cx + 15, cy - 25, cx + 20, cy - 5); 
                    ctx.quadraticCurveTo(cx + 10, cy, cx, cy - 5);
                }
                ctx.stroke();
                break;

            case Role.RANGER:
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2; 
                ctx.beginPath();
                if (isBlue) {
                    // Bow
                    ctx.arc(cx - 5, cy, 15, -Math.PI/2, Math.PI/2); 
                    ctx.moveTo(cx - 5, cy - 15); ctx.lineTo(cx - 5, cy + 15); 
                    ctx.moveTo(cx - 10, cy); ctx.lineTo(cx + 15, cy);
                } else {
                    // Crossbow
                    ctx.moveTo(cx - 5, cy + 15); ctx.lineTo(cx - 5, cy - 15); // Stock
                    ctx.moveTo(cx - 15, cy - 10); ctx.lineTo(cx + 5, cy - 10); // Limb
                }
                ctx.stroke();
                break;

            case Role.MAGE:
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2; 
                ctx.beginPath();
                // Staff diagonally
                ctx.moveTo(cx + 10, cy - 20); 
                ctx.lineTo(cx - 10, cy + 20); 
                ctx.stroke();

                // Orb / Gem
                ctx.fillStyle = color; 
                ctx.beginPath();
                if (isBlue) {
                    ctx.arc(cx + 10, cy - 20, 6, 0, Math.PI * 2);
                } else { 
                    // Crooked top
                    ctx.moveTo(cx + 10, cy - 20); ctx.lineTo(cx + 15, cy - 25);
                    ctx.moveTo(cx + 10, cy - 20); ctx.lineTo(cx + 5, cy - 28);
                    ctx.stroke();
                }
                ctx.fill();
                break;

            case Role.SUPPORT:
            default:
                if (isBlue) {
                    // Hammer / Mace
                    ctx.fillStyle = '#fff'; 
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(cx, cy + 15); ctx.lineTo(cx, cy - 10); // Handle
                    ctx.stroke();
                    ctx.fillRect(cx - 8, cy - 20, 16, 12); // Head
                } else {
                    // Claw
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(cx - 10, cy + 10); ctx.lineTo(cx + 15, cy - 10);
                    ctx.moveTo(cx - 5, cy + 10); ctx.lineTo(cx + 20, cy - 5);
                    ctx.stroke();
                }
                break;
        }
        return canvas;
    },

    generateWeapon(role: Role, team: Team): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(WEAPON_SIZE, WEAPON_SIZE);

        const isBlue = team === Team.BLUE;
        const mainColor = isBlue ? '#fbbf24' : '#ef4444'; 
        const metalColor = isBlue ? '#e2e8f0' : '#27272a';
        const darkMetal = '#18181b';

        ctx.translate(WEAPON_SIZE / 2, WEAPON_SIZE / 2);
        ctx.scale(1.5, 1.5);

        ctx.shadowColor = mainColor;
        ctx.shadowBlur = 5;
        ctx.lineJoin = 'round';

        switch (role) {
            case Role.WARRIOR:
                if (isBlue) {
                    // --- BLUE: CLAYMORE (Long, Straight) ---
                    ctx.rotate(Math.PI / 4);
                    // Handle
                    ctx.fillStyle = '#3f2c22'; ctx.fillRect(-3, -15, 6, 20); 
                    // Guard (Cross)
                    ctx.fillStyle = '#fbbf24'; 
                    ctx.beginPath(); ctx.moveTo(-15, 5); ctx.lineTo(15, 5); ctx.lineTo(0, -2); ctx.fill();
                    // Blade
                    ctx.fillStyle = '#e2e8f0'; ctx.strokeStyle = '#94a3b8';
                    ctx.beginPath(); 
                    ctx.moveTo(-6, 5); ctx.lineTo(-4, 60); ctx.lineTo(0, 75); ctx.lineTo(4, 60); ctx.lineTo(6, 5);
                    ctx.fill(); ctx.stroke();
                    // Fuller (Blood groove)
                    ctx.fillStyle = '#94a3b8'; ctx.fillRect(-1, 5, 2, 50);
                } else {
                    // --- RED: GREATAXE (Wide, Double-headed) ---
                    ctx.rotate(Math.PI / 4);
                    // Handle (Long)
                    ctx.fillStyle = '#3f2c22'; ctx.fillRect(-4, -10, 8, 70); 
                    // Axe Head
                    ctx.translate(0, 45); // Move to head position
                    ctx.fillStyle = darkMetal; ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 1;

                    // Left Blade
                    ctx.beginPath();
                    ctx.moveTo(-4, 0); 
                    ctx.quadraticCurveTo(-20, -25, -35, -20); // Top curve
                    ctx.quadraticCurveTo(-30, 0, -35, 20);    // Edge
                    ctx.quadraticCurveTo(-20, 25, -4, 10);    // Bottom curve
                    ctx.fill(); ctx.stroke();

                    // Right Blade
                    ctx.beginPath();
                    ctx.moveTo(4, 0); 
                    ctx.quadraticCurveTo(20, -25, 35, -20);
                    ctx.quadraticCurveTo(30, 0, 35, 20);
                    ctx.quadraticCurveTo(20, 25, 4, 10);
                    ctx.fill(); ctx.stroke();

                    // Spike on top
                    ctx.beginPath(); ctx.moveTo(-5, -10); ctx.lineTo(0, -25); ctx.lineTo(5, -10); ctx.fill();
                }
                break;

            case Role.TANK:
                if (isBlue) {
                    // --- BLUE: KITE SHIELD (Elegant) ---
                    ctx.fillStyle = '#1e3a8a'; ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
                    ctx.beginPath(); 
                    ctx.moveTo(-15, -20); ctx.lineTo(15, -20); 
                    ctx.lineTo(15, 5); ctx.lineTo(0, 25); ctx.lineTo(-15, 5); 
                    ctx.closePath();
                    ctx.fill(); ctx.stroke();
                    // Symbol
                    ctx.fillStyle = '#fbbf24'; ctx.beginPath(); ctx.arc(0, -5, 5, 0, Math.PI*2); ctx.fill();
                } else {
                    // --- RED: TOWER SHIELD (Thick, Spiked, Rectangular) ---
                    ctx.fillStyle = '#18181b'; // Dark Iron

                    // Main Plate
                    ctx.beginPath();
                    ctx.moveTo(-18, -25); ctx.lineTo(18, -25);
                    ctx.lineTo(16, 25); ctx.lineTo(0, 30); ctx.lineTo(-16, 25);
                    ctx.closePath();
                    ctx.fill();

                    // Metal Banding
                    ctx.strokeStyle = '#52525b'; ctx.lineWidth = 4;
                    ctx.stroke();

                    // Spikes
                    ctx.fillStyle = '#d4d4d8';
                    const spikes = [[0,0], [-10, -15], [10, -15], [0, 15]];
                    spikes.forEach(([sx, sy]) => {
                        ctx.beginPath(); ctx.arc(sx, sy, 3, 0, Math.PI*2); ctx.fill();
                        ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(sx, sy-8); ctx.stroke(); // Spike tip
                    });

                    // Glow cracks
                    ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 1;
                    ctx.beginPath(); ctx.moveTo(-10, 0); ctx.lineTo(10, 0); ctx.stroke();
                }
                break;

            case Role.RANGER:
                if (isBlue) {
                    // --- BLUE: LONGBOW (Vertical, Curved) ---
                    ctx.rotate(-Math.PI / 4);
                    // Wood
                    ctx.strokeStyle = '#fcd34d'; ctx.lineWidth = 3;
                    ctx.beginPath(); ctx.arc(10, 0, 30, -Math.PI/2, Math.PI/2); ctx.stroke();
                    // String
                    ctx.strokeStyle = '#fff'; ctx.lineWidth = 1; 
                    ctx.beginPath(); ctx.moveTo(10, -30); ctx.lineTo(8, 30); ctx.stroke();
                    // Handle
                    ctx.fillStyle = '#b45309'; ctx.fillRect(8, -5, 4, 10);
                } else {
                    // --- RED: HEAVY CROSSBOW (Horizontal structure) ---
                    ctx.rotate(-Math.PI / 4);

                    // Stock
                    ctx.fillStyle = '#3f2c22'; ctx.fillRect(-10, -2, 40, 4);

                    // Limb (Bow part) - Perpendicular
                    ctx.strokeStyle = '#52525b'; ctx.lineWidth = 4;
                    ctx.beginPath(); 
                    ctx.moveTo(20, -15); 
                    ctx.quadraticCurveTo(15, 0, 20, 15); 
                    ctx.stroke();

                    // String
                    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1;
                    ctx.beginPath(); ctx.moveTo(20, -15); ctx.lineTo(-5, 0); ctx.lineTo(20, 15); ctx.stroke();

                    // Bolt loaded
                    ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
                    ctx.beginPath(); ctx.moveTo(-5, 0); ctx.lineTo(25, 0); ctx.stroke();
                }
                break;

            case Role.MAGE:
                ctx.rotate(Math.PI / 8);
                if (isBlue) {
                    // --- BLUE: CRYSTAL STAFF ---
                    // Shaft
                    ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 3;
                    ctx.beginPath(); ctx.moveTo(0, -10); ctx.lineTo(0, 60); ctx.stroke();

                    // Head (Crescent)
                    ctx.lineWidth = 2;
                    ctx.beginPath(); ctx.arc(0, 60, 10, Math.PI, 0); ctx.stroke();

                    // Crystal
                    ctx.fillStyle = '#60a5fa'; ctx.shadowColor = '#60a5fa'; ctx.shadowBlur = 15;
                    ctx.beginPath(); ctx.moveTo(0, 55); ctx.lineTo(5, 65); ctx.lineTo(0, 75); ctx.lineTo(-5, 65); ctx.fill();
                } else {
                    // --- RED: VOODOO STAFF ---
                    // Crooked Shaft
                    ctx.strokeStyle = '#4a0404'; ctx.lineWidth = 4; 
                    ctx.beginPath(); 
                    ctx.moveTo(0, -10); ctx.lineTo(2, 20); ctx.lineTo(-2, 40); ctx.lineTo(0, 60); 
                    ctx.stroke();

                    // Head (Skull-ish shape)
                    ctx.fillStyle = '#e5e5e5'; ctx.shadowColor = '#10b981'; 
                    ctx.beginPath(); ctx.arc(0, 65, 8, 0, Math.PI*2); ctx.fill();
                    // Green Eyes
                    ctx.fillStyle = '#10b981'; 
                    ctx.beginPath(); ctx.arc(-3, 67, 2, 0, Math.PI*2); ctx.arc(3, 67, 2, 0, Math.PI*2); ctx.fill();

                    // Feathers/Charms
                    ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
                    ctx.beginPath(); ctx.moveTo(0, 55); ctx.lineTo(10, 50); ctx.stroke();
                }
                break;

            case Role.SUPPORT:
            default:
                if (isBlue) {
                    // --- BLUE: WARHAMMER / MACE ---
                    ctx.rotate(Math.PI / 4);
                    // Handle
                    ctx.fillStyle = '#3f2c22'; ctx.fillRect(-2, -10, 4, 50);
                    // Head (Blocky)
                    ctx.translate(0, 45);
                    ctx.fillStyle = '#94a3b8'; ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2;
                    ctx.fillRect(-10, -8, 20, 16); ctx.strokeRect(-10, -8, 20, 16);
                    // Runes on head
                    ctx.fillStyle = '#fbbf24'; ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
                } else {
                    // --- RED: CLAWS / FIST WEAPON ---
                    // Grip
                    ctx.fillStyle = '#27272a'; ctx.fillRect(-8, -8, 16, 16);

                    // Blades
                    ctx.fillStyle = '#d4d4d8'; ctx.shadowColor = '#ef4444'; ctx.shadowBlur = 5;
                    const blades = [-10, 0, 10];
                    blades.forEach((offset, i) => {
                        ctx.beginPath();
                        ctx.moveTo(offset, 0);
                        // Curve out
                        ctx.quadraticCurveTo(offset * 1.5, 30, offset * 0.5, 45);
                        ctx.lineTo(offset * 0.5 - 2, 40); // Inner edge
                        ctx.closePath();
                        ctx.fill();
                    });
                }
                break;
        }

        return canvas;
    },

    generateSheep(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(64, 64);
        const cx = 32, cy = 45;

        // Fluff
        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#d1d5db'; ctx.shadowBlur = 5;
        const fluffs = [
            {x: 0, y: -10, r: 15}, {x: -12, y: -5, r: 12}, {x: 12, y: -5, r: 12},
            {x: -8, y: 8, r: 12}, {x: 8, y: 8, r: 12}
        ];
        fluffs.forEach(f => {
            ctx.beginPath(); ctx.arc(cx + f.x, cy + f.y, f.r, 0, Math.PI*2); ctx.fill();
        });

        // Head
        ctx.shadowBlur = 0;
        ctx.fillStyle = '#1c1917';
        ctx.beginPath(); 
        ctx.ellipse(cx - 15, cy - 5, 8, 10, -0.2, 0, Math.PI*2); 
        ctx.fill();

        // Eye
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(cx - 17, cy - 7, 2, 0, Math.PI*2); ctx.fill();

        // Legs
        ctx.fillStyle = '#1c1917';
        ctx.fillRect(cx - 10, cy + 10, 4, 10);
        ctx.fillRect(cx + 6, cy + 10, 4, 10);

        return canvas;
    }
};

import { OBSTACLE_STYLES } from "../../constants";
import { createCanvas } from "./CanvasUtils";

export const EnvironmentFactory = {

    generateObstacle(styleKey: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(64, 96);
        const cx = 32;
        const cy = 80;

        // Default Fallback
        const style = OBSTACLE_STYLES[styleKey] || OBSTACLE_STYLES['WALL'];

        ctx.fillStyle = style.main;
        ctx.strokeStyle = style.light;
        ctx.lineWidth = 2;
        ctx.lineJoin = 'round';

        if (styleKey === 'TREE') {
            // --- ANCIENT TREE ---
            // Trunk
            ctx.fillStyle = style.dark;
            ctx.beginPath();
            ctx.moveTo(cx - 8, cy); 
            ctx.lineTo(cx + 8, cy); 
            ctx.lineTo(cx + 6, cy - 40); 
            ctx.lineTo(cx - 6, cy - 40); 
            ctx.fill();

            // Foliage Layers
            ctx.fillStyle = style.detail; 
            ctx.shadowColor = 'rgba(0,0,0,0.5)'; ctx.shadowBlur = 5;

            const leaves = (y: number, r: number) => {
                ctx.beginPath(); 
                ctx.arc(cx, y, r, 0, Math.PI * 2); 
                ctx.fill(); 
                ctx.stroke();
            };
            leaves(cy - 40, 20);
            leaves(cy - 60, 16);
            leaves(cy - 75, 12);

        } else if (styleKey === 'ICE_CRYSTAL') {
            // --- ICE SPIKES ---
            ctx.fillStyle = style.main;
            ctx.globalAlpha = 0.8;
            ctx.shadowColor = style.light; ctx.shadowBlur = 10;

            const shard = (x: number, h: number, w: number, ang: number) => {
                ctx.save();
                ctx.translate(x, cy);
                ctx.rotate(ang);
                ctx.beginPath();
                ctx.moveTo(-w, 0);
                ctx.lineTo(0, -h);
                ctx.lineTo(w, 0);
                ctx.fill(); ctx.stroke();

                // Highlight
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 1;
                ctx.beginPath(); ctx.moveTo(-w, 0); ctx.lineTo(0, -h); ctx.stroke();
                ctx.restore();
            };

            shard(cx, 60, 15, 0);
            shard(cx - 10, 40, 10, -0.2);
            shard(cx + 12, 45, 12, 0.3);

        } else if (styleKey === 'OBSIDIAN_PILLAR') {
            // --- MAGMA ROCK ---
            ctx.fillStyle = style.main;

            ctx.beginPath();
            ctx.moveTo(cx - 15, cy);
            ctx.lineTo(cx - 10, cy - 70);
            ctx.lineTo(cx + 15, cy - 80);
            ctx.lineTo(cx + 20, cy);
            ctx.closePath();
            ctx.fill(); ctx.stroke();

            // Cracks
            ctx.strokeStyle = style.detail; // Magma Red
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(cx, cy - 10); ctx.lineTo(cx + 5, cy - 30); ctx.lineTo(cx - 5, cy - 50);
            ctx.stroke();

        } else if (styleKey === 'SANDSTONE') {
            // --- ERODED ROCK ---
            ctx.fillStyle = style.main;

            ctx.beginPath();
            ctx.ellipse(cx, cy - 20, 20, 30, 0, 0, Math.PI * 2);
            ctx.fill(); ctx.stroke();

            // Layers
            ctx.strokeStyle = style.dark;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(cx - 18, cy - 10); ctx.quadraticCurveTo(cx, cy - 5, cx + 18, cy - 10);
            ctx.moveTo(cx - 18, cy - 30); ctx.quadraticCurveTo(cx, cy - 25, cx + 18, cy - 30);
            ctx.stroke();

        } else {
            // --- WALL (Default) ---
            // Main Boulder
            ctx.fillStyle = style.dark;
            ctx.beginPath(); 
            ctx.moveTo(cx, cy - 80); 
            ctx.lineTo(cx + 24, cy - 70); 
            ctx.lineTo(cx, cy - 60); 
            ctx.lineTo(cx - 24, cy - 70); 
            ctx.closePath(); 
            ctx.fill(); ctx.stroke();

            // Side Facets
            ctx.fillStyle = style.main; 
            ctx.beginPath(); 
            ctx.moveTo(cx - 24, cy - 70); 
            ctx.lineTo(cx, cy - 60); 
            ctx.lineTo(cx, cy); 
            ctx.lineTo(cx - 24, cy - 10); 
            ctx.closePath(); 
            ctx.fill(); ctx.stroke();

            ctx.fillStyle = style.light; 
            ctx.beginPath(); 
            ctx.moveTo(cx, cy - 60); 
            ctx.lineTo(cx + 24, cy - 70); 
            ctx.lineTo(cx + 24, cy - 10); 
            ctx.lineTo(cx, cy); 
            ctx.closePath(); 
            ctx.fill(); ctx.stroke();

            // Moss Detail
            if (style.detail) {
                ctx.fillStyle = style.detail; 
                ctx.beginPath(); 
                ctx.arc(cx, cy - 5, 10, 0, Math.PI, true); 
                ctx.fill();
            }
        }

        return canvas;
    },

    generateIceBlock(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(96, 128);
        const cx = 48, cy = 90;

        ctx.fillStyle = 'rgba(224, 242, 254, 0.4)'; // Sky-100 translucent
        ctx.strokeStyle = '#38bdf8'; // Sky-400
        ctx.lineWidth = 2;

        // Crystal Shape
        ctx.beginPath();
        ctx.moveTo(cx - 30, cy);
        ctx.lineTo(cx - 35, cy - 60);
        ctx.lineTo(cx, cy - 100);
        ctx.lineTo(cx + 35, cy - 70);
        ctx.lineTo(cx + 30, cy);
        ctx.closePath();

        ctx.fill();
        ctx.stroke();

        // Facets
        ctx.beginPath(); ctx.moveTo(cx, cy - 100); ctx.lineTo(cx - 10, cy - 50); ctx.lineTo(cx - 30, cy); ctx.stroke();
        ctx.beginPath(); ctx.moveTo(cx, cy - 100); ctx.lineTo(cx + 15, cy - 40); ctx.lineTo(cx + 30, cy); ctx.stroke();

        return canvas;
    }
};

import { Role, Team } from "../types";
import { PALETTE } from "../constants";
import { UnitFactory } from "./graphics/UnitFactory";
import { EnvironmentFactory } from "./graphics/EnvironmentFactory";

const cache: Map<string, any> = new Map();

export interface UnitAssets {
    base: HTMLCanvasElement; // Pre-rendered base
    weapon: HTMLCanvasElement; // Pre-rendered weapon
    icon: HTMLCanvasElement;   // Pre-rendered class icon
    color: string;           // Glow color
}

// ==========================================
// Sprite Manager (Cache & Facade)
// ==========================================
export const SpriteManager = {
    getUnitImages(role: Role, team: Team): UnitAssets {
        // Updated keys to force refresh with new designs
        const keyBase = `TOKEN_BASE_${team}_V3`; 
        let base = cache.get(keyBase);
        if (!base) {
            base = UnitFactory.generateTokenBase(team);
            cache.set(keyBase, base);
        }

        const keyWep = `WEAPON_${role}_${team}_V3`;
        let weapon = cache.get(keyWep);
        if (!weapon) {
            weapon = UnitFactory.generateWeapon(role, team);
            cache.set(keyWep, weapon);
        }

        const keyIcon = `ROLE_ICON_${role}_${team}_V3`;
        let icon = cache.get(keyIcon);
        if (!icon) {
            icon = UnitFactory.generateRoleIcon(role, team);
            cache.set(keyIcon, icon);
        }

        return {
            base: base,
            weapon: weapon,
            icon: icon,
            color: PALETTE.TEAMS[team].glow
        };
    },

    getObstacleSprite(styleKey: string = 'WALL'): HTMLCanvasElement {
        const key = `OBSTACLE_${styleKey}`;
        if (cache.has(key)) return cache.get(key)!;

        const canvas = EnvironmentFactory.generateObstacle(styleKey);
        cache.set(key, canvas);
        return canvas;
    },

    getSpecialModel(type: 'SHEEP' | 'ICE'): HTMLCanvasElement {
        const key = `MODEL_${type}`;
        if (cache.has(key)) return cache.get(key)!;

        let canvas;
        if (type === 'SHEEP') {
            canvas = UnitFactory.generateSheep();
        } else {
            canvas = EnvironmentFactory.generateIceBlock();
        }

        cache.set(key, canvas);
        return canvas;
    }
};

import { createCanvas } from "./CanvasUtils";

// Dimensions
const VFX_SIZE = 64;
const MAGIC_CIRCLE_SIZE = 128;
const PROJ_WIDTH = 96;
const PROJ_HEIGHT = 64;
const BLAST_WIDTH = 128;
const BLAST_HEIGHT = 64;
const FOG_SIZE = 256;

export const VFXFactory = {

    generateGlowOrb(color: string, size: number = VFX_SIZE): HTMLCanvasElement {
         const { canvas, ctx } = createCanvas(size, size);
         const cx = size / 2;
         const cy = size / 2;
         const r = size / 2;

         // Core Glow
         const grad = ctx.createRadialGradient(cx, cy, r * 0.1, cx, cy, r);
         grad.addColorStop(0, '#fff');        // Core White
         grad.addColorStop(0.2, color);       // Mid Color
         grad.addColorStop(1, 'transparent'); // Edge

         ctx.fillStyle = grad;
         ctx.beginPath(); 
         ctx.arc(cx, cy, r, 0, Math.PI * 2); 
         ctx.fill();

         return canvas;
    },

    generateFogCloud(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(FOG_SIZE, FOG_SIZE);
        const cx = FOG_SIZE / 2;
        const cy = FOG_SIZE / 2;

        // Create a soft cloud shape
        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, FOG_SIZE / 2);
        grad.addColorStop(0, color);
        grad.addColorStop(0.6, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        // Draw multiple overlapping circles to form a cloud
        ctx.globalAlpha = 0.5;
        ctx.beginPath(); ctx.arc(cx, cy, FOG_SIZE * 0.4, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(cx - 30, cy + 20, FOG_SIZE * 0.25, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(cx + 30, cy - 20, FOG_SIZE * 0.3, 0, Math.PI*2); ctx.fill();

        return canvas;
    },

    generateMagicCircle(color: string, isUlt: boolean): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(MAGIC_CIRCLE_SIZE, MAGIC_CIRCLE_SIZE);
        const cx = MAGIC_CIRCLE_SIZE / 2;
        const cy = MAGIC_CIRCLE_SIZE / 2;
        const radius = 50;

        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;

        // Outer Ring
        ctx.beginPath(); 
        ctx.arc(cx, cy, radius, 0, Math.PI * 2); 
        ctx.stroke();

        // Inner Runes/Shapes
        ctx.lineWidth = 1;
        if (isUlt) {
            // Hexagram for Ultimates
            ctx.beginPath();
            for (let i = 0; i < 6; i++) {
                const angle = (i * Math.PI * 2) / 6;
                const x = cx + Math.cos(angle) * radius;
                const y = cy + Math.sin(angle) * radius;
                const x2 = cx + Math.cos(angle + 2 * Math.PI / 3) * radius;
                const y2 = cy + Math.sin(angle + 2 * Math.PI / 3) * radius;
                ctx.moveTo(x, y); 
                ctx.lineTo(x2, y2);
            }
            ctx.stroke();

            // Solid Inner Glow
            ctx.fillStyle = color;
            ctx.globalAlpha = 0.2;
            ctx.beginPath(); 
            ctx.arc(cx, cy, 20, 0, Math.PI * 2); 
            ctx.fill();
        } else {
            // Simple Triangle for Basic/Active
            ctx.beginPath();
            ctx.moveTo(cx, cy - radius);
            ctx.lineTo(cx + 43, cy + 25);
            ctx.lineTo(cx - 43, cy + 25);
            ctx.closePath();
            ctx.stroke();
        }

        return canvas;
    },

    generateWarningRune(): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64;
        const cy = 32;

        const color = '#ef4444'; // Red
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;

        // Perspective Squash
        ctx.scale(1, 0.5); 

        // Outer Circle
        ctx.beginPath(); 
        ctx.arc(cx, cy * 2, 40, 0, Math.PI * 2); 
        ctx.stroke();

        // X Mark
        ctx.beginPath();
        ctx.moveTo(cx - 20, cy * 2 - 20); 
        ctx.lineTo(cx + 20, cy * 2 + 20);
        ctx.moveTo(cx + 20, cy * 2 - 20); 
        ctx.lineTo(cx - 20, cy * 2 + 20);
        ctx.stroke();

        // Fill
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.3;
        ctx.beginPath(); 
        ctx.arc(cx, cy * 2, 35, 0, Math.PI * 2); 
        ctx.fill();

        return canvas;
    },

    generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(PROJ_WIDTH, PROJ_HEIGHT);
        const cx = PROJ_WIDTH / 2;
        const cy = PROJ_HEIGHT / 2;

        ctx.shadowColor = color;
        ctx.shadowBlur = 15;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        switch (visual) {
            case 'ARROW':
                // Shaft
                ctx.strokeStyle = '#e2e8f0'; 
                ctx.lineWidth = 3;
                ctx.beginPath();
                ctx.moveTo(10, cy);
                ctx.lineTo(80, cy);
                ctx.stroke();

                // Head
                ctx.fillStyle = '#f8fafc';
                ctx.beginPath();
                ctx.moveTo(80, cy);
                ctx.lineTo(65, cy - 8);
                ctx.lineTo(70, cy); 
                ctx.lineTo(65, cy + 8);
                ctx.closePath();
                ctx.fill();

                // Fletching (Energy Color)
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(15, cy); ctx.lineTo(5, cy - 8);
                ctx.moveTo(25, cy); ctx.lineTo(15, cy - 8);
                ctx.moveTo(15, cy); ctx.lineTo(5, cy + 8);
                ctx.moveTo(25, cy); ctx.lineTo(15, cy + 8);
                ctx.stroke();
                break;

            case 'FIREBALL':
                // Trail Gradient
                const grad = ctx.createLinearGradient(cx + 20, cy, 0, cy);
                grad.addColorStop(0, color);
                grad.addColorStop(1, 'transparent');

                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.ellipse(cx - 10, cy, 40, 15, 0, 0, Math.PI * 2);
                ctx.fill();

                // Core
                ctx.fillStyle = '#fff';
                ctx.shadowBlur = 20;
                ctx.beginPath();
                ctx.arc(cx + 25, cy, 10, 0, Math.PI * 2);
                ctx.fill();
                break;

            case 'BOMB':
                // Round bomb body
                ctx.fillStyle = '#1c1917'; // Dark Iron
                ctx.shadowColor = '#000';
                ctx.shadowBlur = 5;
                ctx.beginPath(); ctx.arc(cx, cy, 12, 0, Math.PI*2); ctx.fill();

                // Highlight
                ctx.fillStyle = '#57534e';
                ctx.beginPath(); ctx.arc(cx - 4, cy - 4, 4, 0, Math.PI*2); ctx.fill();

                // Fuse
                ctx.strokeStyle = '#d6d3d1';
                ctx.lineWidth = 2;
                ctx.beginPath(); ctx.moveTo(cx, cy - 12); ctx.quadraticCurveTo(cx + 5, cy - 18, cx + 10, cy - 15); ctx.stroke();

                // Spark
                ctx.fillStyle = color; // Glow Color
                ctx.shadowColor = color; ctx.shadowBlur = 10;
                ctx.beginPath(); ctx.arc(cx + 10, cy - 15, 3, 0, Math.PI*2); ctx.fill();
                break;

            case 'BOLT':
            default:
                // Outer Glow - SHARPENED
                const boltGrad = ctx.createRadialGradient(cx, cy, 5, cx, cy, 22); 
                boltGrad.addColorStop(0, '#fff');
                boltGrad.addColorStop(0.3, color);
                boltGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = boltGrad;
                ctx.beginPath(); 
                ctx.arc(cx, cy, 22, 0, Math.PI * 2); 
                ctx.fill();

                // Diamond Core
                ctx.fillStyle = '#fff';
                ctx.shadowColor = '#fff';
                ctx.shadowBlur = 10;
                ctx.beginPath();
                ctx.moveTo(cx + 20, cy);
                ctx.lineTo(cx, cy - 10);
                ctx.lineTo(cx - 20, cy);
                ctx.lineTo(cx, cy + 10);
                ctx.closePath();
                ctx.fill();

                // Electric Arcs
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(cx - 25, cy); ctx.lineTo(cx - 35, cy - 5);
                ctx.moveTo(cx + 25, cy); ctx.lineTo(cx + 35, cy + 5);
                ctx.stroke();
                break;
        }

        return canvas;
    },

    generateBlastZone(color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(BLAST_WIDTH, BLAST_HEIGHT); 
        const cx = BLAST_WIDTH / 2;
        const cy = BLAST_HEIGHT / 2;

        // Perspective
        ctx.scale(1, 0.5); 

        // Scorch Mark Gradient
        const grad = ctx.createRadialGradient(cx, cy * 2, 0, cx, cy * 2, 50);
        grad.addColorStop(0, '#1c1917'); // Black center
        grad.addColorStop(0.6, '#1c1917');
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.globalAlpha = 0.8;
        ctx.beginPath();
        ctx.arc(cx, cy * 2, 50, 0, Math.PI * 2);
        ctx.fill();

        // Cracked Edges
        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 1.0;

        for (let i = 0; i < 8; i++) {
            const angle = i * (Math.PI / 4) + (Math.random() - 0.5);
            const dist = 10 + Math.random() * 20;

            ctx.beginPath();
            ctx.moveTo(cx + Math.cos(angle) * 10, cy * 2 + Math.sin(angle) * 10);
            ctx.lineTo(cx + Math.cos(angle) * (dist + 20), cy * 2 + Math.sin(angle) * (dist + 20));

            // Branching crack
            if (Math.random() > 0.5) {
                 ctx.lineTo(cx + Math.cos(angle + 0.3) * (dist + 35), cy * 2 + Math.sin(angle + 0.3) * (dist + 35));
            }

            ctx.stroke();
        }

        // Center Glow
        ctx.fillStyle = color;
        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = 0.4;
        ctx.beginPath();
        ctx.arc(cx, cy * 2, 20, 0, Math.PI * 2);
        ctx.fill();

        return canvas;
    }
};

import { createCanvas } from "./CanvasUtils";

const ICON_SIZE = 32;
const STATUS_SIZE = 48;

export const UIFactory = {

    generateSkillIcon(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(ICON_SIZE, ICON_SIZE);

        // Background Frame
        ctx.fillStyle = '#1e293b'; 
        ctx.fillRect(0, 0, ICON_SIZE, ICON_SIZE);

        ctx.strokeStyle = '#334155'; 
        ctx.strokeRect(0, 0, ICON_SIZE, ICON_SIZE);

        // Symbol
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = '20px Arial';
        ctx.fillStyle = color;
        ctx.shadowColor = color; 
        ctx.shadowBlur = 5;

        let symbol = '●';
        switch (visual) {
            case 'SLASH': symbol = '⚔️'; break;
            case 'ARROW': symbol = '🏹'; break;
            case 'FIREBALL': symbol = '🔥'; break;
            case 'BOLT': symbol = '⚡'; break;
            case 'BEAM': symbol = '✨'; break;
            case 'SMASH': symbol = '🔨'; break;
            case 'BOMB': symbol = '💣'; break;
        }

        ctx.fillText(symbol, ICON_SIZE / 2, ICON_SIZE / 2 + 2); // +2 for visual centering
        return canvas;
    },

    generateStatusIcon(type: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(STATUS_SIZE, STATUS_SIZE);
        const cx = STATUS_SIZE / 2;
        const cy = STATUS_SIZE / 2;

        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = 'bold 28px sans-serif';
        ctx.shadowBlur = 5;

        switch (type) {
            case 'STUN':
                ctx.shadowColor = '#facc15';
                ctx.fillStyle = '#facc15';
                ctx.fillText('💫', cx, cy);
                break;
            case 'SILENCE':
                ctx.shadowColor = '#94a3b8';
                ctx.fillStyle = '#e2e8f0';
                // Speech bubble
                ctx.font = 'bold 24px sans-serif';
                ctx.fillText('💬', cx, cy);
                ctx.font = 'bold 12px sans-serif';
                ctx.fillStyle = '#0f172a';
                ctx.fillText('...', cx, cy - 2);
                break;
            case 'POISON': // DoT
                ctx.shadowColor = '#22c55e';
                ctx.fillStyle = '#4ade80';
                ctx.fillText('☠️', cx, cy);
                break;
            case 'BURN': // DoT
                ctx.shadowColor = '#ef4444';
                ctx.fillStyle = '#f87171';
                ctx.fillText('🔥', cx, cy);
                break;
            case 'REGEN': // HoT
                ctx.shadowColor = '#4ade80';
                ctx.fillStyle = '#86efac';
                ctx.fillText('➕', cx, cy);
                break;
            case 'BANISH':
                ctx.shadowColor = '#c084fc';
                ctx.fillStyle = '#d8b4fe';
                ctx.fillText('👻', cx, cy);
                break;
        }

        return canvas;
    }
};

