                                                className={`w-10 h-10 rounded border flex flex-col items-center justify-center transition-all ${draftRole === role ? 'bg-amber-900/40 border-amber-500 text-amber-400 shadow-[0_0_10px_rgba(245,158,11,0.3)] scale-110' : 'bg-slate-800 border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'}`}
                                                title={role}
                                            >
                                                <span className="text-lg -mt-1 filter drop-shadow-md">{roleIcons[role]}</span>
                                            </button>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </div>

                        {/* HP Pool */}
                        <div className="flex flex-col justify-center gap-1 w-16 shrink-0">
                            <label className="text-[9px] text-slate-500 font-bold uppercase text-center">生命值</label>
                            <input 
                                type="number" 
                                value={hpInput} 
                                onChange={e => setHpInput(parseInt(e.target.value))} 
                                className="tactical-input text-center text-lg h-10 border-slate-700 focus:border-cyan-500 px-0"
                            />
                        </div>
                    </div>
                </div>

                {/* ZONE 3: MAP OPS */}
                <div className="w-36 border-l border-slate-800 p-3 flex flex-col gap-2 shrink-0 bg-slate-950/50">
                    <div className="text-[10px] font-bold text-slate-600 uppercase tracking-wider mb-1">地圖操作</div>
                    <div className="grid grid-cols-2 gap-2">
                        <div className="flex flex-col">
                            <label className="text-[8px] text-slate-500">寬度</label>
                            <input type="number" className="tactical-input p-1 text-center" value={mapW} onChange={e=>setMapW(Number(e.target.value))}/>
                        </div>
                        <div className="flex flex-col">
                            <label className="text-[8px] text-slate-500">高度</label>
                            <input type="number" className="tactical-input p-1 text-center" value={mapH} onChange={e=>setMapH(Number(e.target.value))}/>
                        </div>
                    </div>
                    <div className="flex gap-2 mt-auto">
                        <button onClick={onUpdateMap} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center border-slate-600 hover:bg-slate-800">重建</button>
                        <button onClick={onClearMap} className="flex-1 tactical-btn text-[9px] px-1 py-2 justify-center text-red-400 border-red-900 hover:bg-red-950">清空單位</button>
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { GameEngine, Agent } from './engine/game';
import GameCanvas from './components/GameCanvas';
import InspectorPanel from './components/InspectorPanel';
import { ToolType, Team, Skill, Role } from './types';

// UI Components
import { ShowcaseOverlay } from './components/ui/ShowcaseOverlay';
import { MapSettingsModal } from './components/ui/MapSettingsModal';
import { PlaybackHUD } from './components/ui/PlaybackHUD';
import { ControlDock } from './components/ui/ControlDock';

function App() {
  const engineRef = useRef(new GameEngine());

  // App States
  const [isShowcaseMode, setIsShowcaseMode] = useState(true);
  const [isPlaying, setIsPlaying] = useState(false);
  const [unitCount, setUnitCount] = useState(0);
  const [showMobileInspector, setShowMobileInspector] = useState(false);
  const [showMapSettings, setShowMapSettings] = useState(false);

  // Layout State (Responsive)
  const [isLargeScreen, setIsLargeScreen] = useState(() => window.innerWidth >= 1024);

  // Tooling
  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL'); 
  const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
  const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

  // Settings
  const [hpInput, setHpInput] = useState(600); 
  const [mapW, setMapW] = useState(12);
  const [mapH, setMapH] = useState(8);
  const [timeScale, setTimeScale] = useState(1.0);
  const [winner, setWinner] = useState<Team | null>(null);

  // Spawn Logic
  const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
  const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

  // Layout & UI
  const [sidebarWidth, setSidebarWidth] = useState(420);
  const isResizing = useRef(false);
  const [showFactionWarning, setShowFactionWarning] = useState(false);
  const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

  // --- Responsive Listener ---
  useEffect(() => {
      const handleResize = () => setIsLargeScreen(window.innerWidth >= 1024);
      window.addEventListener('resize', handleResize);
      return () => window.removeEventListener('resize', handleResize);
  }, []);

  // --- Logic ---

  const setupShowcaseMap = useCallback(() => {
      const engine = engineRef.current;
      engine.stop();
      setWinner(null);
      setSelectedAgent(null);
      engine.mapConfig.w = Math.floor(10 + Math.random() * 4);
      engine.mapConfig.h = Math.floor(8 + Math.random() * 4);
      engine.clear(false); 
  }, []);

  const spawnShowcaseUnits = useCallback(() => {
      const engine = engineRef.current;
      const validHexes = (Array.from(engine.mapKeys) as string[]).map(k => {
          const [q, r] = k.split(',').map(Number);
          return {q, r};
      });
      for (let i = validHexes.length - 1; i > 0; i--) {
          const j = Math.floor(Math.random() * (i + 1));
          [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
      }
      let spawnIndex = 0;
      const spawn = (team: Team) => {
          if (spawnIndex < validHexes.length) {
              const h = validHexes[spawnIndex++];
              const hp = 500 + Math.floor(Math.random() * 400); 
              engine.addAgent(team, h.q, h.r, hp);
          }
      };
      for(let i=0; i<5; i++) spawn(Team.BLUE);
      for(let i=0; i<5; i++) spawn(Team.RED);
      engine.play();
      setIsPlaying(true);
  }, []);

  const startShowcaseMatch = useCallback(() => {
      setupShowcaseMap();
      spawnShowcaseUnits();
  }, [setupShowcaseMap, spawnShowcaseUnits]);

  useEffect(() => {
      startShowcaseMatch();
  }, [startShowcaseMatch]);

  const enterManualMode = () => {
      setIsShowcaseMode(false);
      engineRef.current.stop();
      setIsPlaying(false);
      setWinner(null);
      engineRef.current.clear(true); 
      engineRef.current.agents = [];
      setUnitCount(0);
  };

  useEffect(() => {
    const interval = setInterval(() => {
        setUnitCount(engineRef.current.agents.length);
    }, 500); 
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
      engineRef.current.timeScale = timeScale;
  }, [timeScale]);

  // --- Hybrid Input Resizing (Mouse & Touch) ---
  const startResizing = useCallback((e: React.MouseEvent | React.TouchEvent) => {
      isResizing.current = true;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
      // Prevent scrolling on touch
      if ('touches' in e) e.stopPropagation();
  }, []);

  const stopResizing = useCallback(() => {
      isResizing.current = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
  }, []);

  const performResize = useCallback((clientX: number) => {
      if (isResizing.current) {
          const newWidth = window.innerWidth - clientX;
          // Constraints for Tablet/Desktop
          const maxWidth = window.innerWidth * 0.8;
          if (newWidth > 300 && newWidth < maxWidth) {
              setSidebarWidth(newWidth);
          }
      }
  }, []);

  const handleMouseMove = useCallback((e: MouseEvent) => performResize(e.clientX), [performResize]);
  const handleTouchMove = useCallback((e: TouchEvent) => performResize(e.touches[0].clientX), [performResize]);

  useEffect(() => {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', stopResizing);
      window.addEventListener('touchmove', handleTouchMove);
      window.addEventListener('touchend', stopResizing);
      return () => {
          window.removeEventListener('mousemove', handleMouseMove);
          window.removeEventListener('mouseup', stopResizing);
          window.removeEventListener('touchmove', handleTouchMove);
          window.removeEventListener('touchend', stopResizing);
      };
  }, [handleMouseMove, handleTouchMove, stopResizing]);

  const togglePlay = useCallback(() => {
    if (winner !== null) return;

    if (isPlaying) {
        engineRef.current.stop();
        setIsPlaying(false);
    } else {
        const hasBlue = engineRef.current.agents.some(a => a.team === Team.BLUE);
        const hasRed = engineRef.current.agents.some(a => a.team === Team.RED);

        if (!hasBlue || !hasRed) {
            setShowFactionWarning(true);
            setTimeout(() => setShowFactionWarning(false), 2500);
            return;
        }

        engineRef.current.play();
        setIsPlaying(true);
        setTool(ToolType.SELECT);
    }
  }, [isPlaying, winner]);

  const handleRestart = useCallback(() => {
    if (winner !== null) return;
    engineRef.current.restart();
    setIsPlaying(true);
    setTool(ToolType.SELECT);
  }, [winner]);

  const handleClear = useCallback(() => {
    engineRef.current.clear(); 
    setIsPlaying(false);
    setSelectedAgent(null);
    setWinner(null);
    setHoveredSkill(null);
  }, []);

  const updateMap = useCallback(() => {
      engineRef.current.mapConfig.w = mapW;
      engineRef.current.mapConfig.h = mapH;
      engineRef.current.clear(true);
      setSelectedAgent(null);
      setWinner(null);
  }, [mapW, mapH]);

  const handleSelectAgent = useCallback((agent: Agent | null) => {
    setSelectedAgent(agent);
  }, []);

  const onWin = (team: Team) => {
    setWinner(team);
    if (isShowcaseMode) {
        setTimeout(() => {
            setTransitionPhase('OUT');
            engineRef.current.agents = [];
            engineRef.current.combat.projectiles = [];
            setTimeout(() => {
                setupShowcaseMap(); 
                setTransitionPhase('IN'); 
                setTimeout(() => {
                    setTransitionPhase('IDLE');
                    spawnShowcaseUnits(); 
                }, 1200);
            }, 1500);
        }, 2000);
    } else {
        setIsPlaying(false);
    }
  };

  const handleShowcaseStart = () => {
      setIsShowcaseMode(true);
      startShowcaseMatch();
  };

  // Helper to toggle tools (clicking active tool turns it off)
  const toggleTool = (t: ToolType) => {
      if (tool === t) setTool(ToolType.SELECT);
      else setTool(t);
  };

  return (
    <div className="h-[100dvh] w-screen bg-slate-950 text-slate-200 overflow-hidden font-sans flex flex-col relative select-none touch-none">

      {/* WARNING NOTIFICATION */}
      {showFactionWarning && (
            <div className="absolute top-24 left-1/2 -translate-x-1/2 z-50 animate-bounce-in pointer-events-none w-[90%] max-w-md">
                <div className="bg-red-950/90 text-red-200 px-6 py-3 rounded border border-red-500 flex items-center gap-3 shadow-xl">
                    <span className="text-xl">⚠️</span>
                    <div className="flex flex-col">
                        <span className="text-xs font-bold tracking-widest text-red-400 uppercase">部署錯誤</span>
                        <span className="text-xs">請部署雙方單位以開始戰鬥。</span>
                    </div>
                </div>
            </div>
      )}

      {/* MAP SETTINGS MODAL (Mobile Only) */}
      {showMapSettings && (
        <MapSettingsModal 
            width={mapW} height={mapH} 
            onChangeW={setMapW} onChangeH={setMapH}
            onRebuild={updateMap} onClear={handleClear}
            onClose={() => setShowMapSettings(false)}
        />
      )}

      {/* SHOWCASE OVERLAY */}
      {isShowcaseMode && (
        <ShowcaseOverlay 
            onEnter={enterManualMode} 
            timeScale={timeScale} 
            setTimeScale={setTimeScale} 
        />
      )}

      {/* MAIN CONTENT ROW */}
      <div className="flex-1 flex overflow-hidden relative z-0">

          {/* LEFT COLUMN: Canvas + Dock + Floating HUD */}
          <div className="flex-1 flex flex-col relative min-w-0 min-h-0 z-0 basis-0 bg-slate-900">

                {/* FLOATING HUD */}
                <PlaybackHUD 
                    hidden={isShowcaseMode}
                    isPlaying={isPlaying}
                    winner={winner}
                    timeScale={timeScale}
                    onTogglePlay={togglePlay}
                    onRestart={handleRestart}
                    onSetTimeScale={setTimeScale}
                    onShowcase={handleShowcaseStart}
                />

                <GameCanvas 
                    engine={engineRef.current} 
                    tool={tool}
                    selectedObstacle={selectedObstacle}
                    hpInput={hpInput}
                    selectedAgent={selectedAgent}
                    hoveredSkill={hoveredSkill}
                    isShowcaseMode={isShowcaseMode}
                    spawnMode={spawnMode}
                    draftRole={draftRole}
                    onSelect={handleSelectAgent} 
                    onWin={onWin}
                    winner={winner}
                    rematch={() => { setWinner(null); engineRef.current.restart(); setIsPlaying(true); }}
                    transitionPhase={transitionPhase}
                />

                {/* BOTTOM DOCK */}
                <ControlDock 
                    hidden={isShowcaseMode}
                    tool={tool}
                    setTool={setTool}
                    spawnMode={spawnMode}
                    setSpawnMode={setSpawnMode}
                    draftRole={draftRole}
                    setDraftRole={setDraftRole}
                    selectedObstacle={selectedObstacle}
                    setSelectedObstacle={setSelectedObstacle}
                    hpInput={hpInput}
                    setHpInput={setHpInput}
                    mapW={mapW}
                    setMapW={setMapW}
                    mapH={mapH}
                    setMapH={setMapH}
                    unitCount={unitCount}
                    onUpdateMap={updateMap}
                    onClearMap={handleClear}
                    showMapSettings={showMapSettings}
                    setShowMapSettings={setShowMapSettings}
                    showMobileInspector={showMobileInspector}
                    setShowMobileInspector={setShowMobileInspector}
                    hasSelectedAgent={!!selectedAgent}
                />
          </div>

          {/* RIGHT COLUMN: Inspector (Z-40) */}
          {isLargeScreen && !isShowcaseMode && (
            <div 
                className="hidden lg:flex w-1 bg-slate-950 hover:bg-cyan-600 cursor-col-resize items-center justify-center shrink-0 transition-colors z-40 border-l border-slate-800"
                onMouseDown={startResizing}
                onTouchStart={startResizing}
            >
                <div className="w-[1px] h-8 bg-slate-600"></div>
            </div>
          )}

          {/* Panel - Desktop Sidebar OR Mobile Overlay Drawer */}
          {isLargeScreen ? (
              // DESKTOP LAYOUT
              <div 
                className={`
                    flex flex-col z-40 shadow-2xl bg-slate-900 border-l border-slate-700 transition-all duration-300 relative h-full
                    ${isShowcaseMode ? 'w-0 border-l-0 overflow-hidden' : ''}
                `}
                style={{ width: !isShowcaseMode ? sidebarWidth : 0 }}
              >
                <InspectorPanel 
                    agent={selectedAgent} 
                    engine={engineRef.current}
                    logs={[]} 
                    db={engineRef.current.skillDB}
                    onHoverSkill={setHoveredSkill}
                />
              </div>
          ) : (
              // MOBILE DRAWER LAYOUT
              <div 
                className={`fixed inset-0 z-50 transition-opacity duration-300 ${showMobileInspector ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
                onClick={() => setShowMobileInspector(false)}
              >
                  {/* Backdrop */}
                  <div className="absolute inset-0 bg-black/60 backdrop-blur-sm"></div>

                  {/* Slide-in Panel */}
                  <div 
                    className={`absolute right-0 top-0 bottom-0 w-full sm:w-[400px] bg-slate-900 shadow-2xl border-l border-slate-700 transform transition-transform duration-300 flex flex-col ${showMobileInspector ? 'translate-x-0' : 'translate-x-full'}`}
                    onClick={(e) => e.stopPropagation()}
                  >
                      {/* Mobile Header */}
                      <div className="p-4 border-b border-slate-700 bg-slate-950 flex justify-between items-center shrink-0 pt-safe-top">
                           <h3 className="font-bold text-slate-200 text-lg">單位監控面板</h3>
                           <button onClick={() => setShowMobileInspector(false)} className="w-10 h-10 flex items-center justify-center bg-slate-800 rounded-full text-slate-400 active:scale-95">✕</button>
                      </div>

                      <div className="flex-1 overflow-hidden">
                        <InspectorPanel 
                            agent={selectedAgent} 
                            engine={engineRef.current}
                            logs={[]} 
                            db={engineRef.current.skillDB}
                            onHoverSkill={setHoveredSkill}
                        />
                      </div>
                  </div>
              </div>
          )}
      </div>
    </div>
  );
}

export default App;

import React, { useEffect, useRef } from 'react';

interface ShowcaseOverlayProps {
    onEnter: () => void;
    timeScale: number;
    setTimeScale: (v: number) => void;
}

export const ShowcaseOverlay: React.FC<ShowcaseOverlayProps> = ({ onEnter, timeScale, setTimeScale }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    // --- MATRIX / DIGITAL RAIN EFFECT ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let width = window.innerWidth;
        let height = window.innerHeight;
        let animationFrameId: number;

        const resize = () => {
            width = window.innerWidth;
            height = window.innerHeight;
            canvas.width = width;
            canvas.height = height;
        };
        window.addEventListener('resize', resize);
        resize();

        // Configuration
        const fontSize = 14;
        const columns = Math.floor(width / fontSize);
        const drops: number[] = new Array(columns).fill(1);

        // Characters: Hex, Tactical symbols, Katakana mix
        const chars = "0123456789ABCDEFXYZTARGETLOCATEDSYSTEMANALYSISERRORWARNING"; 

        const draw = () => {
            // Semi-transparent black to create trail effect
            // Removing 'backdrop-blur', using canvas trail instead
            ctx.fillStyle = 'rgba(2, 6, 23, 0.1)'; // Slate-950 with low alpha
            ctx.fillRect(0, 0, width, height);

            ctx.font = `bold ${fontSize}px monospace`;

            for (let i = 0; i < drops.length; i++) {
                // Randomize color slightly between Cyan, Blue and dimmed White
                const seed = Math.random();
                if (seed > 0.95) ctx.fillStyle = '#fff'; // Sparkle
                else if (seed > 0.8) ctx.fillStyle = '#3b82f6'; // Blue-500
                else ctx.fillStyle = '#06b6d4'; // Cyan-500 (Main)

                const text = chars[Math.floor(Math.random() * chars.length)];
                const x = i * fontSize;
                const y = drops[i] * fontSize;

                ctx.fillText(text, x, y);

                // Reset drop to top randomly
                if (y > height && Math.random() > 0.975) {
                    drops[i] = 0;
                }
                drops[i]++;
            }

            animationFrameId = requestAnimationFrame(draw);
        };

        draw();

        return () => {
            window.removeEventListener('resize', resize);
            cancelAnimationFrame(animationFrameId);
        };
    }, []);

    return (
        <div className="absolute inset-0 z-50 flex flex-col justify-center items-center overflow-hidden pointer-events-none">

            {/* 1. Canvas Background (The Digital Rain) */}
            <canvas 
                ref={canvasRef} 
                className="absolute inset-0 w-full h-full opacity-60"
            />

            {/* 2. Vignette & Scanlines Overlay (Visual Polish) */}
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,#020617_90%)] opacity-80"></div>
            <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiAvPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSIxIiBmaWxsPSJyZ2JhKDI1NSwgMjU1LDI1NSwgMC4wNSkiIC8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>

            {/* 3. Main Content - Centered */}
            <div className="relative z-10 w-full max-w-4xl flex flex-col items-center pointer-events-auto p-4 animate-fade-in">

                {/* Decorative Brackets */}
                <div className="flex justify-between w-full max-w-lg mb-2 opacity-50 text-cyan-500 font-mono text-xs">
                    <span>// SYSTEM_READY</span>
                    <span>V4.0.1_BETA</span>
                </div>

                <div className="relative border-y border-cyan-500/30 bg-slate-950/40 p-12 w-full text-center backdrop-blur-[2px]">
                    {/* Animated Glitch Title */}
                    <h1 className="text-6xl md:text-8xl font-black text-transparent bg-clip-text bg-gradient-to-b from-white via-cyan-200 to-cyan-500 mb-2 font-mono tracking-tighter drop-shadow-[0_0_25px_rgba(6,182,212,0.5)]">
                        TACTICAL.OS
                    </h1>

                    <div className="flex items-center justify-center gap-4 text-cyan-400 font-mono text-sm md:text-base tracking-[0.3em] uppercase mb-8">
                        <span className="w-2 h-2 bg-cyan-500 rounded-full animate-pulse"></span>
                        <span>Neural Battle Simulation</span>
                        <span className="w-2 h-2 bg-cyan-500 rounded-full animate-pulse"></span>
                    </div>

                    <button 
                        onClick={onEnter}
                        className="group relative inline-flex items-center justify-center px-12 py-4 overflow-hidden font-bold text-white transition-all duration-300 bg-transparent border-2 border-cyan-500/50 hover:border-cyan-400 hover:shadow-[0_0_30px_rgba(6,182,212,0.4)]"
                    >
                        <span className="absolute inset-0 w-full h-full -mt-1 rounded-lg opacity-30 bg-gradient-to-b from-transparent via-transparent to-gray-700"></span>
                        <span className="relative text-lg tracking-[0.2em] flex items-center gap-3 group-hover:gap-5 transition-all">
                            INITIALIZE
                            <svg className="w-5 h-5 fill-current" viewBox="0 0 24 24"><path d="M10 6L8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z"/></svg>
                        </span>
                    </button>
                </div>

                <div className="flex justify-between w-full max-w-lg mt-2 opacity-50 text-cyan-500 font-mono text-xs">
                    <span>AWAITING INPUT...</span>
                    <span>SECURE_CONNECTION</span>
                </div>
            </div>

            {/* 4. Time Scale Control (Bottom Right) */}
            <div className="absolute bottom-8 right-8 z-50 pointer-events-auto flex items-center gap-4 px-6 py-3 border border-slate-700/50 bg-slate-950/60 backdrop-blur-sm rounded-none">
                <span className="text-[10px] text-cyan-500 font-bold uppercase tracking-wider">SIMULATION_SPEED</span>
                <div className="flex items-center gap-3">
                    <input 
                        type="range" min="0.1" max="4.0" step="0.1" 
                        value={timeScale} onChange={(e) => setTimeScale(parseFloat(e.target.value))}
                        className="w-32 h-1 bg-slate-700 rounded-none appearance-none cursor-pointer accent-cyan-400"
                    />
                    <span className="text-xs font-mono text-white w-8 text-right">{timeScale.toFixed(1)}x</span>
                </div>
            </div>
        </div>
    );
};

import React, { useEffect, useRef, useState } from 'react';

interface ShowcaseOverlayProps {
    onEnter: () => void;
    timeScale: number;
    setTimeScale: (v: number) => void;
}

type LayoutPreset = 'CENTER' | 'BOTTOM_CENTER' | 'BOTTOM_LEFT' | 'BOTTOM_RIGHT';

interface MatrixConfig {
    speed: number;
    fontSize: number;
    textColor: string;
    bgColor: string;
    bgOpacity: number; // 0.0 - 1.0 (Controls how much of the map is hidden)
    trailFade: number; // 0.05 - 0.5 (Controls how long the text trails are)
}

export const ShowcaseOverlay: React.FC<ShowcaseOverlayProps> = ({ onEnter, timeScale, setTimeScale }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [showSettings, setShowSettings] = useState(false);

    // --- Configuration State ---
    const [layout, setLayout] = useState<LayoutPreset>('BOTTOM_CENTER');
    const [config, setConfig] = useState<MatrixConfig>({
        speed: 1.0,
        fontSize: 16,
        textColor: '#06b6d4', // Cyan-500
        bgColor: '#020617',   // Slate-950
        bgOpacity: 0.85,      // Solid enough to read, but see-through
        trailFade: 0.1        // Standard trail
    });

