export interface MatrixConfig {
    // Rain Physics
    speed: number;        // Global Speed Multiplier
    density: number;      // Font Size (Smaller = More dense columns)
    trailLength: number;  // How long the tail is

    // Colors
    textColor: string;    // Main text color
    headColor: string;    // Leading character color (usually white)
    bgColor: string;      // The background overlay color

    // Opacity
    bgOpacity: number;    // 0.0 - 1.0 (Independent background dimming)
    textOpacity: number;  // 0.0 - 1.0 (Master text brightness)
}

export const DEFAULT_MATRIX_CONFIG: MatrixConfig = {
    speed: 1.0,
    density: 16,
    trailLength: 20,
    textColor: '#06b6d4', // Cyan-500
    headColor: '#ffffff',
    bgColor: '#020617',   // Slate-950
    bgOpacity: 0.5,       // Semi-transparent default
    textOpacity: 1.0
};

import { useEffect, useRef } from 'react';
import { MatrixConfig } from './types';

interface Column {
    x: number;
    y: number;        // Current head position
    speed: number;    // Individual column speed
    chars: string[];  // Pre-calculated char stream to reduce jitter (optional)
}

export const useMatrixRain = (
    canvasRef: React.RefObject<HTMLCanvasElement>, 
    config: MatrixConfig,
    width: number,
    height: number
) => {
    // We use a ref to access the latest config inside the animation loop without restarting it
    const configRef = useRef(config);
    useEffect(() => { configRef.current = config; }, [config]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Reset canvas size
        canvas.width = width;
        canvas.height = height;

        // Initialize Columns
        const fontSize = config.density;
        const colCount = Math.ceil(width / fontSize);
        const columns: Column[] = [];

        // Characters pool
        const charSet = "0123456789ABCDEFXYZアイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン"; 

        for (let i = 0; i < colCount; i++) {
            columns.push({
                x: i * fontSize,
                y: Math.random() * -height, // Start randomly above screen
                speed: 1 + Math.random() * 3, // Random speed factor (1x to 4x)
                chars: [] // Dynamic chars
            });
        }

        let animationId: number;

        const render = () => {
            const cfg = configRef.current;

            // 1. CLEAR canvas completely (Crucial for transparent background support)
            ctx.clearRect(0, 0, width, height);

            ctx.font = `bold ${cfg.density}px monospace`;
            ctx.textBaseline = 'top';

            // 2. Render each column
            columns.forEach(col => {
                // Determine drop speed
                const moveSpeed = col.speed * cfg.speed;

                // Draw the Trail
                // We draw from the head upwards
                for (let j = 0; j < cfg.trailLength; j++) {
                    const charY = col.y - (j * cfg.density);

                    // Optimization: Don't draw if way off screen
                    if (charY > height || charY < -cfg.density) continue;

                    // Calculate Opacity based on trail position
                    // Head (j=0) is brightest
                    const alpha = Math.max(0, (1 - j / cfg.trailLength) * cfg.textOpacity);

                    // Pick a character (Randomize occasionally for glitch effect)
                    const char = charSet[Math.floor(Math.random() * charSet.length)];

                    // Color Logic
                    if (j === 0) {
                        ctx.fillStyle = cfg.headColor; // Head is white/bright
                        // Add glow to head
                        ctx.shadowColor = cfg.headColor;
                        ctx.shadowBlur = 5;
                    } else {
                        ctx.fillStyle = cfg.textColor; // Body is theme color
                        ctx.shadowBlur = 0;
                    }

                    // Apply opacity using globalAlpha is expensive, use rgba string if possible or globalAlpha sparingly
                    // For performance with hex colors, globalAlpha is easiest
                    ctx.globalAlpha = alpha;
                    ctx.fillText(char, col.x, charY);
                }

                // 3. Update Position
                col.y += moveSpeed;

                // Loop
                if (col.y - (cfg.trailLength * cfg.density) > height) {
                    // Reset to top with random delay
                    col.y = Math.random() * -100;
                    col.speed = 1 + Math.random() * 3; // Re-roll speed
                }
            });

            // Reset Global Alpha
            ctx.globalAlpha = 1.0;
            animationId = requestAnimationFrame(render);
        };

        render();

        return () => {
            cancelAnimationFrame(animationId);
        };
    }, [width, height, config.density]); // Re-init if size or density changes
};

