export interface MatrixConfig {
    // Rain Physics
    speed: number;        // Global Speed Multiplier
    density: number;      // Font Size (Smaller = More dense columns)
    trailLength: number;  // How long the tail is

    // Volatility (New)
    volatility: number;   // 0.0 - 1.0 (How fast characters change in place)

    // Content (New)
    charSet: string;      // The pool of characters

    // Colors
    textColor: string;    // Main text color
    headColor: string;    // Leading character color (usually white)
    bgColor: string;      // The background overlay color

    // Opacity
    bgOpacity: number;    // 0.0 - 1.0 (Independent background dimming)
    textOpacity: number;  // 0.0 - 1.0 (Master text brightness)
}

const DEFAULT_CHARS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz" +
                      "αβγδεζηθικλμνξοπρστυφχψωΩΔΣΦΨ" + // Greek
                      "アイウエオカキクケコサシスセソタチツテトナニヌネノハヒフヘホマミムメモヤユヨラリルレロワヲン" + // Katakana
