                      "戰機龍魔神界虚無光影雷風火土水氷剣盾弓矢兵将王帝聖邪鬼神愛憎生死"; // Kanji

export const DEFAULT_MATRIX_CONFIG: MatrixConfig = {
    speed: 1.0,
    density: 16,
    trailLength: 20,
    volatility: 0.05,     // Low value = Characters stay stable longer
    charSet: DEFAULT_CHARS,
    textColor: '#06b6d4', // Cyan-500
    headColor: '#ffffff',
    bgColor: '#020617',   // Slate-950
    bgOpacity: 0.5,       // Semi-transparent default
    textOpacity: 1.0
};

import React, { useEffect, useRef } from 'react';
import { MatrixConfig } from './types';

interface Column {
    x: number;
    y: number;        // Current head position
    speed: number;    // Individual column speed
}

export const useMatrixRain = (
    canvasRef: React.RefObject<HTMLCanvasElement>, 
    config: MatrixConfig,
    width: number,
    height: number
) => {
    const configRef = useRef(config);
    useEffect(() => { configRef.current = config; }, [config]);

    // Track time for volatility logic
    const timeRef = useRef(0);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Reset canvas size
        canvas.width = width;
        canvas.height = height;

        // Initialize Columns
        const fontSize = config.density;
        const colCount = Math.ceil(width / fontSize);
        const columns: Column[] = [];

        for (let i = 0; i < colCount; i++) {
            columns.push({
                x: i * fontSize,
                y: Math.random() * -height, // Start randomly above screen
                speed: 1 + Math.random() * 3, // Random speed factor (1x to 4x)
            });
        }

        let animationId: number;

        // Pseudo-random character picker that is stable over time unless volatility triggers a change
        // This ensures text doesn't flicker violently every frame (60fps)
        const getStableChar = (colIdx: number, rowIdx: number, charSet: string, volatility: number, time: number) => {
            const len = charSet.length;
            if (len === 0) return "";

            // Volatility Step: 
            // If volatility is 0.1, the "seed" changes every 10 units of time.
            // If volatility is 1.0, it changes every unit of time.
            // We use Math.floor to create discrete time steps.
            const timeStep = volatility > 0 ? Math.floor(time * volatility * 0.1) : 0;

            // Simple hash function combining position and time
            // (col * large_prime + row + time_step * prime) % length
            const index = Math.abs((colIdx * 15485863 + rowIdx * 1231 + timeStep * 7919) % len);
            return charSet[index];
        };

        const render = () => {
            const cfg = configRef.current;
            timeRef.current++;

            // 1. CLEAR canvas completely
            ctx.clearRect(0, 0, width, height);

            ctx.font = `bold ${cfg.density}px monospace`;
            ctx.textBaseline = 'top';

            // 2. Render each column
            columns.forEach((col, i) => {
                // Determine drop speed
                const moveSpeed = col.speed * cfg.speed;

                // Draw the Trail
                for (let j = 0; j < cfg.trailLength; j++) {
                    const charY = col.y - (j * cfg.density);

                    // Optimization: Don't draw if way off screen
                    if (charY > height || charY < -cfg.density) continue;

                    // Calculate Opacity
                    const alpha = Math.max(0, (1 - j / cfg.trailLength) * cfg.textOpacity);

                    // Logic to pick character
                    // We calculate the virtual "Row Index" of this character in the grid
                    const rowIdx = Math.floor(charY / cfg.density);

                    // Use the stable picker
                    const char = getStableChar(i, rowIdx, cfg.charSet, cfg.volatility, timeRef.current);

                    // Color Logic
                    if (j === 0) {
                        ctx.fillStyle = cfg.headColor; 
                        ctx.shadowColor = cfg.headColor;
                        ctx.shadowBlur = 5;
                    } else {
                        ctx.fillStyle = cfg.textColor; 
                        ctx.shadowBlur = 0;
                    }

                    ctx.globalAlpha = alpha;
                    ctx.fillText(char, col.x, charY);
                }

                // 3. Update Position
                col.y += moveSpeed;

                // Loop
                if (col.y - (cfg.trailLength * cfg.density) > height) {
                    // Reset to top with random delay
                    col.y = Math.random() * -200; // Start slightly higher to stagger
                    col.speed = 1 + Math.random() * 3; // Re-roll speed
                }
            });

            ctx.globalAlpha = 1.0;
            animationId = requestAnimationFrame(render);
        };

        render();

        return () => {
            cancelAnimationFrame(animationId);
        };
    }, [width, height, config.density]); // Re-init if size or density changes
};

