export type LayoutPreset = 'CENTER' | 'BOTTOM_CENTER' | 'BOTTOM_LEFT' | 'BOTTOM_RIGHT';
export type StreamDirection = 'DOWN' | 'UP' | 'LEFT' | 'RIGHT';

export interface MatrixConfig {
    // Physics
    direction: StreamDirection;
    speed: number;        // Global Speed Multiplier
    fontSize: number;     // Size of the characters (px)
    spacing: number;      // Extra space between columns/rows (px)
    trailLength: number;  // Length of the fade trail

    // Logic
    volatility: number;   // 0.0 - 1.0 (Glitchiness)

    // Content
    charSet: string;

    // Visuals
    textColor: string;    // Body color
    headColor: string;    // Leading char color
    bgColor: string;      // Background overlay color

    // Opacity
    bgOpacity: number;    
    textOpacity: number;  
}

import React, { useEffect, useRef } from 'react';
import { MatrixConfig, StreamDirection } from './types';

interface Stream {
    primary: number;   // The fixed coordinate (X for vertical, Y for horizontal)
    secondary: number; // The moving coordinate (Y for vertical, X for horizontal)
    speed: number;     // Movement speed
    offset: number;    // Stagger offset
}

export const useMatrixRain = (
    canvasRef: React.RefObject<HTMLCanvasElement>, 
    config: MatrixConfig,
    width: number,
    height: number
) => {
    const configRef = useRef(config);
    useEffect(() => { configRef.current = config; }, [config]);

    const timeRef = useRef(0);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        canvas.width = width;
        canvas.height = height;

        const { direction, fontSize, spacing } = configRef.current;
        const isVertical = direction === 'DOWN' || direction === 'UP';

        // Determine stream count based on orientation
        const totalSize = fontSize + spacing;
        const streamCount = Math.ceil(isVertical ? width / totalSize : height / totalSize);

        const streams: Stream[] = [];

        // Initialize Streams
        for (let i = 0; i < streamCount; i++) {
            const primaryPos = i * totalSize;
            // Start at random secondary position outside bounds for smoother entry
            const limit = isVertical ? height : width;
            const startPos = Math.random() * limit; 

            streams.push({
                primary: primaryPos,
                secondary: startPos,
                speed: 1 + Math.random() * 3, // 1x to 4x multiplier
                offset: Math.random() * 1000 // For character randomness seed
            });
        }

        let animationId: number;

        // Stable Random Character Picker
        const getStableChar = (streamIdx: number, cellIdx: number, charSet: string, volatility: number, time: number) => {
            const len = charSet.length;
            if (len === 0) return "";
            const timeStep = volatility > 0 ? Math.floor(time * volatility * 0.1) : 0;
            const index = Math.abs((streamIdx * 15485863 + cellIdx * 1231 + timeStep * 7919) % len);
            return charSet[index];
        };

        const render = () => {
            const cfg = configRef.current;
            timeRef.current++;

            // 1. Clear Frame
            ctx.clearRect(0, 0, width, height);

            ctx.font = `bold ${cfg.fontSize}px monospace`;
            ctx.textBaseline = 'top';

            // 2. Setup Direction Vectors
            // moveVec: How the head moves per frame
            // trailVec: Direction from head to tail (opposite of flow)
            let moveDelta = 0;
            let trailDx = 0; 
            let trailDy = 0;

            switch(cfg.direction) {
                case 'DOWN':  moveDelta = 1;  trailDx = 0; trailDy = -1; break;
                case 'UP':    moveDelta = -1; trailDx = 0; trailDy = 1;  break;
                case 'RIGHT': moveDelta = 1;  trailDx = -1; trailDy = 0; break;
                case 'LEFT':  moveDelta = -1; trailDx = 1;  trailDy = 0; break;
            }

            const isVert = cfg.direction === 'DOWN' || cfg.direction === 'UP';
            const boundLimit = isVert ? height : width;

            // 3. Render Streams
            streams.forEach((stream, i) => {
                // Move Head
                stream.secondary += stream.speed * cfg.speed * moveDelta;

                // Loop Logic
                // If moved past positive bound (DOWN/RIGHT)
                if (moveDelta > 0 && stream.secondary > boundLimit + (cfg.trailLength * cfg.fontSize)) {
                    stream.secondary = -cfg.fontSize * 5;
                    stream.speed = 1 + Math.random() * 3;
                }
                // If moved past negative bound (UP/LEFT)
                else if (moveDelta < 0 && stream.secondary < -(cfg.trailLength * cfg.fontSize)) {
                    stream.secondary = boundLimit + cfg.fontSize * 5;
                    stream.speed = 1 + Math.random() * 3;
                }

                // Draw Trail
                for (let j = 0; j < cfg.trailLength; j++) {
                    // Calculate Character Position
                    // Start at head (secondary), move back by j steps in trail direction
                    const cellSize = cfg.fontSize;

                    let x = 0, y = 0;
                    if (isVert) {
                        x = stream.primary;
                        y = stream.secondary + (j * cellSize * trailDy);
                    } else {
                        x = stream.secondary + (j * cellSize * trailDx);
                        y = stream.primary;
                    }

                    // Cull off-screen
                    if (x < -cellSize || x > width || y < -cellSize || y > height) continue;

                    // Opacity Fade
                    const alpha = Math.max(0, (1 - j / cfg.trailLength) * cfg.textOpacity);

                    // Character Selection (Grid based on pixel pos for stability)
                    // Virtual Row/Col index
                    const virtualIdx = Math.floor((isVert ? y : x) / cellSize);
                    const char = getStableChar(i, virtualIdx, cfg.charSet, cfg.volatility, timeRef.current);

                    // Render
                    if (j === 0) {
                        // Head
                        ctx.fillStyle = cfg.headColor;
                        ctx.shadowColor = cfg.headColor;
                        ctx.shadowBlur = 8;
                    } else {
                        // Body
                        ctx.fillStyle = cfg.textColor;
                        ctx.shadowBlur = 0;
                    }

                    ctx.globalAlpha = alpha;
                    ctx.fillText(char, x, y);
                }
            });

            ctx.globalAlpha = 1.0;
            ctx.shadowBlur = 0;
            animationId = requestAnimationFrame(render);
        };

        render();

        return () => {
            cancelAnimationFrame(animationId);
        };
    }, [width, height, config.direction, config.fontSize, config.spacing]); 
};

import React from 'react';
