                    } else {
                        ctx.fillStyle = cfg.textColor;
                        ctx.shadowBlur = 0;
                    }

                    ctx.globalAlpha = alpha;
                    ctx.fillText(char, x, y);
                }
            }

            ctx.globalAlpha = 1.0;
            ctx.shadowBlur = 0;
            animationId = requestAnimationFrame(render);
        };

        render();

        return () => {
            cancelAnimationFrame(animationId);
        };
    }, [width, height, config.direction, config.fontSize, config.spacing, config.depthVariance, config.streamGap, config.enabled]); 
};

import React, { useRef, useState, useEffect } from 'react';
import { MatrixConfig, LayoutPreset } from './showcase/types';
import { DEFAULT_MATRIX_CONFIG } from './showcase/defaults';
import { useMatrixRain } from './showcase/useMatrixRain';
import { ShowcaseSettings } from './showcase/ShowcaseSettings';

interface ShowcaseOverlayProps {
    onEnter: () => void;
    timeScale: number;
    setTimeScale: (v: number) => void;
}

export const ShowcaseOverlay: React.FC<ShowcaseOverlayProps> = ({ onEnter, timeScale, setTimeScale }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [config, setConfig] = useState<MatrixConfig>(DEFAULT_MATRIX_CONFIG);
    const [layout, setLayout] = useState<LayoutPreset>('BOTTOM_CENTER');
    const [showSettings, setShowSettings] = useState(false);

    // Track window size for canvas init
    const [viewport, setViewport] = useState({ w: window.innerWidth, h: window.innerHeight });

    useEffect(() => {
        const handleResize = () => setViewport({ w: window.innerWidth, h: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Hook: Handles the Matrix Rain rendering on the transparent canvas
    useMatrixRain(canvasRef, config, viewport.w, viewport.h);

    // Helper: Determine UI Layout classes
    const getLayoutClasses = () => {
        switch (layout) {
            case 'CENTER': 
                return 'inset-0 flex-col justify-center items-center text-center p-12';
            case 'BOTTOM_CENTER': 
                // Wide Rectangle (Max 2/3 Width, Max 1/5 Height)
                return 'bottom-8 left-1/2 -translate-x-1/2 w-full md:w-2/3 max-h-[20vh] flex-row justify-between items-center px-8 py-6';
            case 'BOTTOM_LEFT': 
                return 'bottom-0 left-0 w-[400px] flex-col justify-end items-start p-8';
            case 'BOTTOM_RIGHT': 
                return 'bottom-0 right-0 w-[400px] flex-col justify-end items-end p-8 text-right';
            default: 
                return 'inset-0 justify-center items-center';
        }
    };
    const isCompact = layout !== 'CENTER';
    const isWideBar = layout === 'BOTTOM_CENTER';

    // Helper: Convert Hex to RGB for Background opacity application
    const getRgbaBg = (hex: string, alpha: number) => {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        if (!result) return `rgba(0,0,0,${alpha})`;
        const r = parseInt(result[1], 16);
        const g = parseInt(result[2], 16);
        const b = parseInt(result[3], 16);
        return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    };

    return (
        <div className="absolute inset-0 z-50 overflow-hidden pointer-events-none">

            {/* LAYER 1: Background Color Overlay (Separate from Canvas) */}
            <div 
                className="absolute inset-0 transition-colors duration-300"
                style={{ backgroundColor: getRgbaBg(config.bgColor, config.enabled ? config.bgOpacity : 0) }}
            ></div>

            {/* LAYER 2: Matrix Rain Canvas (Transparent BG) */}
            <canvas 
                ref={canvasRef} 
                className="absolute inset-0 block w-full h-full pointer-events-none mix-blend-screen"
            />

            {/* LAYER 3: CRT Scanline / Vignette Effects */}
            {config.enabled && config.bgOpacity > 0.1 && (
                <>
                    <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiAvPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSIxIiBmaWxsPSJyZ2JhKDI1NSwgMjU1LDI1NSwgMC4wNSkiIC8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.4)_90%)] pointer-events-none"></div>
                </>
            )}

            {/* LAYER 4: UI Content (Title & Buttons) */}
            <div className={`absolute z-[55] flex animate-fade-in pointer-events-none ${getLayoutClasses()}`}>
                <div className={`relative pointer-events-auto transition-all duration-500 w-full h-full flex ${isWideBar ? 'flex-row items-center justify-between' : 'flex-col'} ${isCompact ? 'bg-slate-950/80 border border-slate-700 backdrop-blur-md rounded shadow-2xl p-6' : ''}`}>

                    {/* Content Wrapper for Wide Mode */}
                    <div className={`flex flex-col ${isWideBar ? 'items-start text-left' : 'items-center text-center'} flex-1`}>
                        {/* Compact Header */}
                        {isCompact && (
                            <div className={`flex w-full mb-1 opacity-50 text-cyan-500 font-mono text-[10px] tracking-widest ${isWideBar ? 'justify-start gap-4' : 'justify-between border-b border-cyan-900 pb-1'}`}>
                                <span>// SYSTEM_READY</span>
                                <span>V4.0.3</span>
                            </div>
                        )}

                        {/* Main Title */}
                        <h1 className={`${isCompact ? (isWideBar ? 'text-5xl' : 'text-4xl') : 'text-7xl md:text-9xl'} font-black text-transparent bg-clip-text bg-gradient-to-b from-white via-cyan-200 to-cyan-500 mb-1 font-mono tracking-tighter drop-shadow-[0_0_15px_rgba(6,182,212,0.5)]`}>
                            TACTICAL.OS
                        </h1>

                        {/* Subtitle */}
                        <div className={`flex items-center gap-4 text-cyan-400 font-mono ${isCompact ? 'text-xs' : 'text-sm md:text-base justify-center mb-10'} tracking-[0.3em] uppercase`}>
                            {!isCompact && <span className="w-2 h-2 bg-cyan-500 rounded-full animate-pulse"></span>}
                            <span>Neural Battle Simulation</span>
                            {!isCompact && <span className="w-2 h-2 bg-cyan-500 rounded-full animate-pulse"></span>}
                        </div>
                    </div>

                    {/* Start Button */}
                    <div className={`${isCompact ? (isWideBar ? 'ml-8 shrink-0' : 'mt-4 w-full') : ''}`}>
                        <button 
                            onClick={onEnter}
                            className={`group relative inline-flex items-center justify-center ${isCompact ? (isWideBar ? 'px-12 py-4 text-lg' : 'w-full py-3 text-sm') : 'px-16 py-5 text-xl'} overflow-hidden font-bold text-white transition-all duration-300 bg-cyan-950/30 border border-cyan-500/50 hover:border-cyan-400 hover:bg-cyan-900/40 hover:shadow-[0_0_20px_rgba(6,182,212,0.4)]`}
                        >
                            <span className="relative tracking-[0.2em] flex items-center gap-3 group-hover:gap-5 transition-all">
                                INITIALIZE
                                <svg className="w-4 h-4 fill-current" viewBox="0 0 24 24"><path d="M10 6L8.59 7.41 13.17 12l-4.58 4.59L10 18l6-6z"/></svg>
                            </span>
                        </button>
                    </div>
                </div>
            </div>

            {/* LAYER 5: Controls (Top Left) */}
            <button 
                onClick={() => setShowSettings(!showSettings)}
                className="absolute top-4 left-4 z-[60] pointer-events-auto p-2 bg-slate-900/80 border border-slate-700 text-slate-400 hover:text-cyan-400 hover:border-cyan-500 rounded transition-all shadow-lg"
                title="特效設定"
            >
                <svg className="w-6 h-6 animate-spin-slow" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            </button>

            <ShowcaseSettings 
                show={showSettings} 
                onClose={() => setShowSettings(false)}
                config={config} 
                setConfig={setConfig} 
                timeScale={timeScale}
                setTimeScale={setTimeScale}
                layout={layout}
                setLayout={setLayout}
            />
        </div>
    );
};

import { Agent } from "../../../game";
import { AssetManager } from "../../../assets";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 
        let bodyColor = isSilhouette ? 'transparent' : '#78350f'; 
        let glowColor = isSilhouette ? silhouetteColor : '#ef4444'; 
        let secondary = isSilhouette ? silhouetteColor : '#1c1917'; 

        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 3 : 0;
        let jitterX = 0; let jitterY = 0; let energyGather = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            if (progress < 0.6) {
                energyGather = progress;
                jitterX = (Math.random() - 0.5) * 3 * progress;
                jitterY = (Math.random() - 0.5) * 3 * progress;
            } else {
                const recoil = (progress - 0.6) / 0.4;
                jitterX = -5 * recoil; 
            }
        }

        ctx.save();
        ctx.translate(jitterX, floatY + jitterY);

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent';
        } else {
            ctx.fillStyle = bodyColor;
            ctx.strokeStyle = '#450a0a'; // Dark Outline
            ctx.lineWidth = 1.5;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
                ctx.ellipse(0, -10, 18, 28, 0, 0, Math.PI*2);
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
                ctx.moveTo(-10, -30); ctx.lineTo(10, -30);
                ctx.lineTo(14, 15); ctx.lineTo(0, 20); ctx.lineTo(-14, 15);
        } else {
                ctx.ellipse(0, -10, 12, 25, 0, 0, Math.PI*2);
        }

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.stroke();
        }

        // Floating Orbs (Mage/Support)
        if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && agent.hp > 0) {
            const orbGlow = AssetManager.getGlowSprite(glowColor);
            for(let i=0; i<3; i++) {
                const angle = t * 2 + (i * Math.PI * 2 / 3);
                const ox = Math.cos(angle) * (agent.role === Role.MAGE ? 20 : 15) * (1 - energyGather * 0.8);
                const oy = Math.sin(angle) * 5;
                ctx.save(); ctx.translate(ox, oy - 20);
                if(!isSilhouette) { 
                    ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.6;
                    ctx.drawImage(orbGlow, -10, -15, 20, 20);
                    ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1.0;
                    ctx.fillStyle = glowColor;
                    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.fill();
                } else {
                    ctx.strokeStyle = glowColor;
                    ctx.beginPath(); ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); ctx.stroke();
                }
                ctx.restore();
            }
        }

        if (!isSilhouette) {
            ctx.fillStyle = secondary;
            ctx.beginPath(); ctx.ellipse(0, -10, 6, 15, 0, 0, Math.PI*2); ctx.fill();
            const coreGlow = AssetManager.getGlowSprite(glowColor);
            ctx.save(); ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.5 + Math.sin(t*10)*0.2 + energyGather * 0.5;
            ctx.drawImage(coreGlow, -10, -25, 20, 20); ctx.restore();
            ctx.fillStyle = glowColor;
            ctx.beginPath(); ctx.arc(0, -15, 4, 0, Math.PI*2); ctx.fill();
        }

        // Head
        ctx.save();
        const headBob = (agent.hp > 0) ? Math.sin(t*3.5)*2 : 0;
        ctx.translate(0, (agent.role === Role.TANK ? -45 : -40) + headBob); 

        if (isSilhouette) {
            ctx.fillStyle = 'transparent'; ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = '#f5f5f4';
            ctx.strokeStyle = '#450a0a';
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            ctx.moveTo(-12, -10); ctx.lineTo(12, -10); ctx.lineTo(0, 12);
        } else {
            ctx.moveTo(-6, -8); ctx.lineTo(6, -8); ctx.lineTo(0, 8);
        }

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.stroke();
            ctx.fillStyle = glowColor;
            ctx.fillRect(-3, -4, 2, 2); ctx.fillRect(1, -4, 2, 2);
        }
        ctx.restore();

        // Weapon (Floating)
        ctx.save();
        ctx.translate(15, -15);
        if (agent.role === Role.WARRIOR || agent.role === Role.TANK) {
            const bladeAngle = (agent.hp > 0) ? Math.sin(t) * 0.2 + (agent.animState === AnimState.ATTACK ? -1 : 0) : 0;
            ctx.rotate(bladeAngle);
            if(!isSilhouette) {
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, -10, -20, 30, 30); ctx.restore();
            } else {
                ctx.strokeStyle = silhouetteColor;
            }

            if (agent.role === Role.TANK) {
                ctx.lineWidth = 3;
                if (!isSilhouette) ctx.strokeStyle = glowColor;
                ctx.beginPath(); ctx.arc(0, 0, 20, Math.PI/2, 3*Math.PI/2); ctx.stroke();
            } else {
                ctx.beginPath();
                ctx.moveTo(0, 10); ctx.lineTo(5, -30); ctx.lineTo(-2, -25);
                if (isSilhouette) ctx.stroke(); 
                else { 
                    ctx.fillStyle = glowColor; 
                    ctx.fill(); 
                    // Add outline for consistency
                    ctx.strokeStyle = '#450a0a';
                    ctx.lineWidth = 1;
                    ctx.stroke();
                }
            }
        } else if (agent.role === Role.RANGER) {
            ctx.translate(5, 0);
            ctx.rotate(agent.animState === AnimState.ATTACK ? -0.5 : 0);
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.stroke();
            } else {
                ctx.fillStyle = secondary;
                ctx.strokeStyle = '#450a0a';
                ctx.beginPath(); ctx.moveTo(-5, -5); ctx.lineTo(15, 0); ctx.lineTo(-5, 5); ctx.fill(); ctx.stroke();
                const wepGlow = AssetManager.getGlowSprite(glowColor);
                ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.4;
                ctx.drawImage(wepGlow, 0, -10, 20, 20); ctx.restore();
                ctx.fillStyle = glowColor; ctx.beginPath(); ctx.arc(10, 0, 3, 0, Math.PI*2); ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }
};

import { Agent } from "../../../game";
import { AssetManager } from "../../../assets";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#3b82f6'; 
        let grad: any = silhouetteColor;
        let accent = silhouetteColor;

        if (!isSilhouette) {
            grad = ctx.createLinearGradient(-20, -40, 20, 40);
            grad.addColorStop(0, '#eff6ff'); 
            grad.addColorStop(0.5, '#93c5fd'); 
            grad.addColorStop(1, '#2563eb');   
            accent = '#3b82f6'; 
        }

        let breathe = (agent.hp > 0) ? Math.sin(t * 3) * 1 : 0;
        let thrustX = 0;
        let armRot = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            if (progress < 0.3) {
                thrustX = -5 * (progress / 0.3);
                armRot = -0.5 * (progress / 0.3);
            } else if (progress < 0.5) {
                thrustX = 15;
                armRot = 1.0;
            } else {
                thrustX = 15 * (1 - (progress - 0.5)/0.5);
                armRot = 1.0 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, breathe);

        // 1. Back Arm (Weapon)
        ctx.save();
        ctx.translate(10, -10);
        ctx.rotate(armRot);
        drawImperialWeapon(ctx, agent.role, accent, isSilhouette);
        ctx.restore();

        // 2. Body Shape
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent'; 
        } else {
            ctx.fillStyle = grad;
            ctx.strokeStyle = '#1e3a8a'; 
            ctx.lineWidth = 1.5;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            ctx.moveTo(-18, -30); ctx.lineTo(18, -30);  
            ctx.lineTo(12, 15); ctx.lineTo(-12, 15);   
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.moveTo(-10, -25); ctx.lineTo(10, -25);  
            ctx.lineTo(16, 25); ctx.lineTo(-16, 25);
        } else if (agent.role === Role.RANGER) {
            ctx.moveTo(-8, -25); ctx.lineTo(8, -25);  
            ctx.lineTo(6, 15); ctx.lineTo(-6, 15);
        } else {
            ctx.moveTo(-12, -25); ctx.lineTo(12, -25);  
            ctx.lineTo(8, 15); ctx.lineTo(-8, 15);   
        }
        ctx.closePath();

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.fillStyle = '#172554';
            ctx.stroke();
            // Rivets
            if (agent.role === Role.TANK) {
                [[-12,-25], [12,-25], [-8, 10], [8, 10]].forEach(([rx, ry]) => {
                    ctx.beginPath(); ctx.arc(rx, ry, 1, 0, Math.PI*2); ctx.fill();
                });
            }
        }

        // 3. Head
        ctx.save();
        ctx.translate(0, (agent.role === Role.TANK ? -35 : -32) + breathe * 0.5);
        if (isSilhouette) {
            ctx.fillStyle = 'transparent';
            ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = grad;
        }

        ctx.beginPath();
        if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            ctx.moveTo(-10, 5); ctx.lineTo(-8, -15); ctx.lineTo(8, -15); ctx.lineTo(10, 5);
        } else if (agent.role === Role.TANK) {
            ctx.rect(-10, -14, 20, 16);
        } else {
            ctx.rect(-8, -12, 16, 14);
        }

        if (isSilhouette) ctx.stroke();
        else {
            ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#fef08a'; ctx.fillRect(-6, -8, 12, 2);
        }
        ctx.restore();

        // 4. Front Arm / Shield
        ctx.save();
        ctx.translate(-12, -8);
        if (agent.role === Role.TANK) {
            ctx.rotate(armRot * 0.2);
            ctx.translate(-5, 5);

            if (isSilhouette) {
                ctx.fillStyle = 'transparent';
                ctx.strokeStyle = silhouetteColor;
            } else {
                ctx.fillStyle = '#2563eb'; ctx.strokeStyle = '#fcd34d'; 
            }
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.moveTo(-10, -20); ctx.lineTo(10, -20);
            ctx.lineTo(10, 10); ctx.lineTo(0, 25); ctx.lineTo(-10, 10);
            ctx.closePath();

            if (isSilhouette) ctx.stroke();
            else { ctx.fill(); ctx.stroke(); }

        } else if (agent.role === Role.RANGER) {
            ctx.rotate(armRot);
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.strokeRect(-2, -2, 4, 15);
            } else {
                ctx.fillStyle = '#334155'; ctx.fillRect(-2, -2, 4, 15);
            }
        } else {
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); 
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor; ctx.stroke();
            } else {
                ctx.fillStyle = grad; ctx.fill();
            }
        }
        ctx.restore();

        ctx.restore(); 
    }
};

function drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, accent: string, isSilhouette: boolean) {
    if (isSilhouette) {
        ctx.strokeStyle = '#3b82f6';
        ctx.lineWidth = 2;
    }

    if (role === Role.WARRIOR || role === Role.TANK) {
        ctx.beginPath();
        ctx.moveTo(-2, 0); ctx.lineTo(2, 0);
        ctx.lineTo(2, -40); ctx.lineTo(0, -45); ctx.lineTo(-2, -40);
        if (isSilhouette) ctx.stroke();
        else {
            ctx.fillStyle = '#e2e8f0'; ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#f59e0b'; ctx.fillRect(-6, 0, 12, 3);
        }
    } else if (role === Role.RANGER) {
        ctx.rotate(-Math.PI/2);
        if (isSilhouette) ctx.strokeRect(0, -3, 30, 4);
        else {
            ctx.fillStyle = '#475569'; ctx.fillRect(0, -3, 30, 4);
            ctx.fillStyle = '#78350f'; ctx.fillRect(-10, -2, 10, 6);
        }
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        if (isSilhouette) ctx.strokeRect(-2, -40, 4, 50);
        else {
            ctx.fillStyle = '#475569'; ctx.fillRect(-2, -40, 4, 50);
            const glow = AssetManager.getGlowSprite(accent);
            ctx.save(); ctx.globalCompositeOperation = 'lighter';
            ctx.drawImage(glow, -16, -55, 32, 32); ctx.restore();
            ctx.fillStyle = accent; ctx.fillRect(-6, -45, 12, 12);
        }
    }
}

