            } else if (progress < 0.5) {
                thrustX = 15;
                armRot = 1.0;
            } else {
                thrustX = 15 * (1 - (progress - 0.5)/0.5);
                armRot = 1.0 * (1 - (progress - 0.5)/0.5);
            }
        }

        ctx.save();
        ctx.translate(thrustX, breathe);

        // 1. Back Arm (Weapon)
        // Draw weapon BEHIND body for standard view
        ctx.save();
        ctx.translate(10, -10);
        ctx.rotate(armRot);
        drawImperialWeapon(ctx, agent.role, accent, isSilhouette);
        ctx.restore();

        // 2. Body Shape
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent'; 
        } else {
            ctx.fillStyle = grad;
            ctx.strokeStyle = '#1e3a8a'; 
            ctx.lineWidth = 1.5;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            // Tank: Bulky Heavy Armor
            ctx.moveTo(-18, -32); ctx.lineTo(18, -32);  
            ctx.lineTo(14, 15); ctx.lineTo(-14, 15);   
        } else if (agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
            // Robes: Flared bottom
            ctx.moveTo(-10, -28); ctx.lineTo(10, -28);  
            ctx.lineTo(18, 25); ctx.lineTo(-18, 25);
        } else if (agent.role === Role.RANGER) {
            // Light Armor: Slim
            ctx.moveTo(-8, -25); ctx.lineTo(8, -25);  
            ctx.lineTo(6, 15); ctx.lineTo(-6, 15);
        } else {
            // Warrior: Standard Plate
            ctx.moveTo(-12, -28); ctx.lineTo(12, -28);  
            ctx.lineTo(8, 15); ctx.lineTo(-8, 15);   
        }
        ctx.closePath();

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.fillStyle = '#172554';
            ctx.stroke();

            // Details
            if (agent.role === Role.TANK) {
                // Heavy rivets
                [[-12,-25], [12,-25], [-10, 5], [10, 5]].forEach(([rx, ry]) => {
                    ctx.beginPath(); ctx.arc(rx, ry, 2, 0, Math.PI*2); ctx.fill();
                });
            } else if (agent.role === Role.WARRIOR) {
                // Chest plate line
                ctx.beginPath(); ctx.moveTo(-8, -10); ctx.lineTo(8, -10); ctx.stroke();
            }
        }

        // 3. Head
        ctx.save();
        ctx.translate(0, (agent.role === Role.TANK ? -38 : -34) + breathe * 0.5);

        if (isSilhouette) {
            ctx.fillStyle = 'transparent';
            ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = grad;
        }

        ctx.beginPath();
        if (agent.role === Role.MAGE) {
            // Hood / Hat
            ctx.moveTo(-10, 5); ctx.lineTo(0, -20); ctx.lineTo(10, 5);
        } else if (agent.role === Role.SUPPORT) {
            // Rounder Hood
            ctx.arc(0, -5, 10, Math.PI, 0); 
            ctx.lineTo(10, 5); ctx.lineTo(-10, 5);
        } else if (agent.role === Role.TANK) {
            // Great Helm (Boxy)
            ctx.rect(-11, -15, 22, 18);
        } else {
            // Standard Helm
            ctx.rect(-8, -12, 16, 14);
        }

        if (isSilhouette) ctx.stroke();
        else {
            ctx.fill(); ctx.stroke();
            // Visor / Face
            ctx.fillStyle = '#fef08a'; 
            if(agent.role === Role.MAGE || agent.role === Role.SUPPORT) {
                ctx.fillStyle = '#1e3a8a'; // Dark face in hood
                ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
            } else {
                ctx.fillRect(-6, -8, 12, 3);
            }
        }
        ctx.restore();

        // 4. Front Arm / Shield
        ctx.save();
        ctx.translate(-12, -8);

        if (agent.role === Role.TANK) {
            // --- TOWER SHIELD ---
            ctx.rotate(armRot * 0.2);
            ctx.translate(-6, 8);

            if (isSilhouette) {
                ctx.fillStyle = 'transparent';
                ctx.strokeStyle = silhouetteColor;
            } else {
                ctx.fillStyle = '#1e40af'; // Darker blue shield
                ctx.strokeStyle = '#fcd34d'; // Gold trim
            }
            ctx.lineWidth = 2;

            ctx.beginPath();
            // Kite Shield Shape
            ctx.moveTo(-12, -22); ctx.lineTo(12, -22);
            ctx.lineTo(12, 5); ctx.lineTo(0, 25); ctx.lineTo(-12, 5);
            ctx.closePath();

            if (isSilhouette) ctx.stroke();
            else { 
                ctx.fill(); ctx.stroke(); 
                // Shield Emblem
                ctx.fillStyle = '#fcd34d';
                ctx.beginPath(); ctx.arc(0, -5, 4, 0, Math.PI*2); ctx.fill();
            }

        } else if (agent.role === Role.RANGER) {
            // --- CROSSBOW STOCK ARM ---
            ctx.rotate(armRot);
            ctx.translate(5, 5); // Shift forward to hold gun
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor;
                ctx.strokeRect(-2, -2, 12, 6);
            } else {
                ctx.fillStyle = '#334155'; 
                ctx.fillRect(-2, -2, 12, 6); // Forearm holding stock
            }
        } else {
            // --- STANDARD HAND / BUCKLER ---
            ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); 
            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor; ctx.stroke();
            } else {
                ctx.fillStyle = grad; ctx.fill();
                // Warrior gets a small buckler
                if(agent.role === Role.WARRIOR) {
                    ctx.strokeStyle = '#fcd34d';
                    ctx.lineWidth = 2;
                    ctx.stroke();
                }
            }
        }
        ctx.restore();

        ctx.restore(); 
    }
};

function drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, accent: string, isSilhouette: boolean) {
    if (isSilhouette) {
        ctx.strokeStyle = '#3b82f6';
        ctx.lineWidth = 2;
    }

    if (role === Role.WARRIOR) {
        // --- SWORD ---
        ctx.beginPath();
        ctx.moveTo(-2, 0); ctx.lineTo(2, 0);
        ctx.lineTo(2, -45); ctx.lineTo(0, -50); ctx.lineTo(-2, -45);
        if (isSilhouette) ctx.stroke();
        else {
            ctx.fillStyle = '#e2e8f0'; ctx.fill(); ctx.stroke();
            ctx.fillStyle = '#f59e0b'; ctx.fillRect(-6, 0, 12, 3); // Crossguard
        }
    } else if (role === Role.TANK) {
        // --- MACE ---
        ctx.beginPath();
        ctx.moveTo(-3, 0); ctx.lineTo(3, 0); // Handle Base
        ctx.lineTo(3, -35); ctx.lineTo(-3, -35); // Shaft
        if (isSilhouette) ctx.stroke();
        else {
            ctx.fillStyle = '#475569'; ctx.fill(); ctx.stroke();
            // Mace Head
            ctx.fillStyle = '#cbd5e1'; 
            ctx.fillRect(-8, -45, 16, 12);
            ctx.strokeRect(-8, -45, 16, 12);
        }
    } else if (role === Role.RANGER) {
        // --- CROSSBOW / RIFLE ---
        ctx.rotate(-Math.PI/2);
        if (isSilhouette) ctx.strokeRect(0, -3, 35, 6);
        else {
            ctx.fillStyle = '#475569'; ctx.fillRect(0, -3, 35, 6); // Barrel
            ctx.fillStyle = '#78350f'; ctx.fillRect(-8, -2, 10, 8); // Stock
        }
    } else if (role === Role.MAGE) {
        // --- GEM STAFF ---
        if (isSilhouette) {
            ctx.strokeRect(-2, -40, 4, 50);
            ctx.strokeRect(-6, -50, 12, 12);
        } else {
            ctx.fillStyle = '#475569'; ctx.fillRect(-2, -40, 4, 50);
            const glow = AssetManager.getGlowSprite(accent);
            ctx.save(); ctx.globalCompositeOperation = 'lighter';
            ctx.drawImage(glow, -16, -55, 32, 32); ctx.restore();
            // Gem
            ctx.fillStyle = accent; 
            ctx.beginPath(); ctx.moveTo(0, -55); ctx.lineTo(5, -45); ctx.lineTo(0, -35); ctx.lineTo(-5, -45); ctx.fill();
        }
    } else if (role === Role.SUPPORT) {
        // --- CLERIC STAFF ---
        if (isSilhouette) {
            ctx.strokeRect(-2, -40, 4, 50);
            ctx.beginPath(); ctx.arc(0, -45, 8, 0, Math.PI*2); ctx.stroke();
        } else {
            ctx.fillStyle = '#e2e8f0'; ctx.fillRect(-2, -40, 4, 50); // White staff
            // Halo / Ring
            ctx.strokeStyle = '#fcd34d'; ctx.lineWidth = 2;
            ctx.beginPath(); ctx.arc(0, -45, 8, 0, Math.PI*2); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(0, -53); ctx.lineTo(0, -37); ctx.stroke();
            ctx.beginPath(); ctx.moveTo(-8, -45); ctx.lineTo(8, -45); ctx.stroke();
        }
    }
}

import { Agent } from "../../../game";
import { AssetManager } from "../../../assets";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 
        let bodyColor = isSilhouette ? 'transparent' : '#78350f'; 
        let glowColor = isSilhouette ? silhouetteColor : '#ef4444'; 
        let secondary = isSilhouette ? silhouetteColor : '#1c1917'; 

        // Animation Vars
        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 3 : 0;
        let jitterX = 0; let jitterY = 0; let energyGather = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const progress = getCastProgress(agent);
            if (progress < 0.6) {
                energyGather = progress;
                jitterX = (Math.random() - 0.5) * 3 * progress;
                jitterY = (Math.random() - 0.5) * 3 * progress;
            } else {
                const recoil = (progress - 0.6) / 0.4;
                jitterX = -5 * recoil; 
            }
        }

        ctx.save();
        ctx.translate(jitterX, floatY + jitterY);

        // --- 1. BODY SHAPE ---
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.fillStyle = 'transparent';
        } else {
            ctx.fillStyle = bodyColor;
            ctx.strokeStyle = '#450a0a'; // Dark Outline
            ctx.lineWidth = 1.5;
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
                // Tank: Large, Heavy Oval
                ctx.ellipse(0, -10, 22, 30, 0, 0, Math.PI*2);
        } else if (agent.role === Role.MAGE) {
                // Mage: Inverted Sharp Triangle (Floating)
                ctx.moveTo(-12, -35); ctx.lineTo(12, -35);
                ctx.lineTo(0, 15); ctx.lineTo(-12, -35);
        } else if (agent.role === Role.SUPPORT) {
                // Support: Diamond / Rhombus (Floating)
                ctx.moveTo(0, -40); ctx.lineTo(14, -10);
                ctx.lineTo(0, 20); ctx.lineTo(-14, -10); ctx.lineTo(0, -40);
        } else if (agent.role === Role.RANGER) {
                // Ranger: Slim, Tapered
                ctx.ellipse(0, -10, 10, 22, 0, 0, Math.PI*2);
        } else {
                // Warrior: Standard Spiked Oval
                ctx.ellipse(0, -10, 14, 26, 0, 0, Math.PI*2);
        }

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.stroke();
        }

        // --- 2. FLOATING ORBS (Core Feature) ---
        // Only for Mage/Support active visuals
        if ((agent.role === Role.MAGE || agent.role === Role.SUPPORT) && agent.hp > 0) {
            const orbGlow = AssetManager.getGlowSprite(glowColor);
            const count = agent.role === Role.MAGE ? 3 : 2;

            for(let i=0; i<count; i++) {
                const speed = agent.role === Role.MAGE ? 2 : 1.5;
                const angle = t * speed + (i * Math.PI * 2 / count);
                const ox = Math.cos(angle) * 20 * (1 - energyGather * 0.8);
                const oy = Math.sin(angle) * 8 - 20; // Flattened orbit

                ctx.save(); ctx.translate(ox, oy);
                if(!isSilhouette) { 
                    ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = 0.6;
                    ctx.drawImage(orbGlow, -10, -10, 20, 20);
                    ctx.globalCompositeOperation = 'source-over'; ctx.globalAlpha = 1.0;
                    ctx.fillStyle = glowColor;

                    ctx.beginPath();
                    if (agent.role === Role.MAGE) {
                        // Mage: Shards
                        ctx.moveTo(0, -5); ctx.lineTo(3, 0); ctx.lineTo(0, 5); ctx.lineTo(-3, 0); 
                    } else {
                        // Support: Spheres
                        ctx.arc(0, 0, 3, 0, Math.PI*2);
                    }
                    ctx.fill();
                } else {
                    ctx.strokeStyle = glowColor;
                    ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.stroke();
                }
                ctx.restore();
            }
        }

        // Core Body Detail (Glow)
        if (!isSilhouette) {
            ctx.fillStyle = secondary;

            // Draw core shape
            if (agent.role === Role.TANK) {
                // Tank Core: Blocky
                ctx.fillRect(-8, -20, 16, 20);
            } else {
                ctx.beginPath(); ctx.ellipse(0, -10, 6, 15, 0, 0, Math.PI*2); ctx.fill();
            }

            const coreGlow = AssetManager.getGlowSprite(glowColor);
            ctx.save(); ctx.globalCompositeOperation = 'lighter';
            ctx.globalAlpha = 0.5 + Math.sin(t*10)*0.2 + energyGather * 0.5;
            ctx.drawImage(coreGlow, -10, -25, 20, 20); ctx.restore();

            ctx.fillStyle = glowColor;
            ctx.beginPath(); ctx.arc(0, -15, 4, 0, Math.PI*2); ctx.fill();
        }

        // --- 3. HEAD ---
        ctx.save();
        const headBob = (agent.hp > 0) ? Math.sin(t*3.5)*2 : 0;
        ctx.translate(0, (agent.role === Role.TANK ? -45 : -40) + headBob); 

        if (isSilhouette) {
            ctx.fillStyle = 'transparent'; ctx.strokeStyle = silhouetteColor;
        } else {
            ctx.fillStyle = '#f5f5f4'; // Bone color
            ctx.strokeStyle = '#450a0a';
        }

        ctx.beginPath();
        if (agent.role === Role.TANK) {
            // Tank: Bull/Demon Horns
            ctx.moveTo(-15, -8); ctx.lineTo(-8, 0); ctx.lineTo(8, 0); ctx.lineTo(15, -8); // Horns
            ctx.lineTo(10, 12); ctx.lineTo(-10, 12); // Jaw
        } else if (agent.role === Role.WARRIOR) {
            // Warrior: Spiked Mask
            ctx.moveTo(-8, -8); ctx.lineTo(8, -8); ctx.lineTo(0, 10);
            ctx.moveTo(-8, -8); ctx.lineTo(-10, -15); // Spike L
            ctx.moveTo(8, -8); ctx.lineTo(10, -15); // Spike R
        } else {
            // Standard: Simple Skull mask
            ctx.moveTo(-6, -8); ctx.lineTo(6, -8); ctx.lineTo(0, 8);
        }

        if (isSilhouette) {
            ctx.stroke();
        } else {
            ctx.fill();
            ctx.stroke();
            // Red Eyes
            ctx.fillStyle = glowColor;
            ctx.fillRect(-4, -4, 3, 3); ctx.fillRect(1, -4, 3, 3);
        }
        ctx.restore();

        // --- 4. WEAPON (Floating) ---
        ctx.save();

        // Positioning Logic
        if (agent.role === Role.RANGER) {
            ctx.translate(10, -5);
        } else {
            ctx.translate(20, -15);
        }

        if (agent.role === Role.TANK) {
            // --- TANK: GIANT CRESCENT BLADE/SHIELD ---
            const angle = (agent.hp > 0) ? Math.sin(t) * 0.1 : 0;
            ctx.rotate(angle);

            ctx.lineWidth = 4;
            if (!isSilhouette) ctx.strokeStyle = '#7f1d1d'; // Dark Red Metal
            else ctx.strokeStyle = silhouetteColor;

            // Outer Blade
            ctx.beginPath(); 
            ctx.arc(0, 0, 24, Math.PI/2, 3*Math.PI/2); 
            ctx.stroke();

            if (!isSilhouette) {
                // Inner Glow
                ctx.lineWidth = 2;
                ctx.strokeStyle = glowColor;
                ctx.beginPath(); ctx.arc(0, 0, 18, Math.PI/2, 3*Math.PI/2); ctx.stroke();
            }

        } else if (agent.role === Role.WARRIOR) {
            // --- WARRIOR: JAGGED CLEAVER ---
            const angle = (agent.hp > 0) ? Math.sin(t) * 0.2 + (agent.animState === AnimState.ATTACK ? -1 : 0) : 0;
            ctx.rotate(angle);

            ctx.beginPath();
            // Serrated Blade
            ctx.moveTo(0, 10); 
            ctx.lineTo(8, -20); // Top tip
            ctx.lineTo(4, -15); // Tooth 1
            ctx.lineTo(4, -10); // Tooth 2
            ctx.lineTo(-4, -5); // Base
            ctx.closePath();

            if (isSilhouette) {
                ctx.strokeStyle = silhouetteColor; ctx.stroke();
            } else {
                ctx.fillStyle = '#b91c1c'; ctx.fill(); 
                ctx.strokeStyle = '#450a0a'; ctx.stroke();
                // Edge Glow
                ctx.strokeStyle = glowColor; ctx.beginPath(); ctx.moveTo(0, 10); ctx.lineTo(8, -20); ctx.stroke();
            }

        } else if (agent.role === Role.RANGER) {
            // --- RANGER: FLOATING BONE BOW ---
            const angle = agent.animState === AnimState.ATTACK ? -0.5 : 0;
            ctx.rotate(angle);

            // Upper Limb
            ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(10, -10, 0, -20);
            if (isSilhouette) { ctx.strokeStyle = silhouetteColor; ctx.stroke(); }
            else { ctx.strokeStyle = '#f5f5f4'; ctx.lineWidth=3; ctx.stroke(); }

            // Lower Limb
            ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(10, 10, 0, 20);
            if (isSilhouette) { ctx.strokeStyle = silhouetteColor; ctx.stroke(); }
            else { ctx.strokeStyle = '#f5f5f4'; ctx.lineWidth=3; ctx.stroke(); }

            // String (Energy)
            if (!isSilhouette) {
                ctx.strokeStyle = glowColor; ctx.lineWidth = 1;
                ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(0, 20); ctx.stroke();
            }
        }

        ctx.restore();
        ctx.restore(); 
    }
};

import { Agent, GameEngine } from "../game";
import { MovementType } from "../../types";
import { HexUtils } from "../utils";

// Physics Constants
const PHYSICS_STIFFNESS_ALIVE = 150;
const PHYSICS_STIFFNESS_DEAD = 0;
const PHYSICS_DAMPING_ALIVE = 25; 
const PHYSICS_DAMPING_DEAD = 1.0; 
const GRAVITY = 2000; 

export class PhysicsEngine {

    public update(a: Agent, dt: number, engine: GameEngine) {
        const isDead = a.hp <= 0;
        const stiffness = isDead ? PHYSICS_STIFFNESS_DEAD : PHYSICS_STIFFNESS_ALIVE; 

        // If airborne (z > 0), reduce drag to allow projectile motion
        const isAirborne = a.physics.z > 0;
        const damping = (isDead && isAirborne) ? 0.5 : (isDead ? PHYSICS_DAMPING_DEAD : PHYSICS_DAMPING_ALIVE);

        // 1. Spring Forces (Return to 0,0 relative local space)
        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        // 2. Acceleration (Force - Damping)
        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        // 3. Integrate Velocity
        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        // 4. Vertical Dynamics (Gravity vs Flight)
        if (a.movementType === MovementType.FLYING && !isDead) {
            // Flying Unit Logic
            if (a.stunTimer > 0 || a.visualStatus === 'FROZEN' || a.visualStatus === 'POLYMORPH') {
                // CRASH STATE: Apply Gravity immediately
                a.physics.vz -= GRAVITY * dt;
            } else {
                // HOVER STATE: Bob around a target altitude
                // Adjusted: Lowered from 90 to 55 to be closer to action but still visually flying
                const hoverHeight = 55; 
                const hoverFreq = 2.5; // Slightly slower bob
                // Reduced amplitude from 10 to 5 for stability
                const targetZ = hoverHeight + Math.sin(engine.battleTime * hoverFreq) * 5;

                // Soft spring to maintain height
                const dz = targetZ - a.physics.z;
                a.physics.vz += dz * 5 * dt;
                a.physics.vz *= 0.92; // Increased drag (was 0.95) to stop oscillation at lower height
            }
        } else {
            // Ground Unit Logic
            if (isDead || isAirborne) {
                a.physics.vz -= GRAVITY * dt;
            }
        }

        // 5. Integrate Position
        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // 6. Ground Collision (Bounce)
        if (a.physics.z < 0) {
            a.physics.z = 0;
            // Elastic collision with ground loss
            if (Math.abs(a.physics.vz) > 100) {
                a.physics.vz = -a.physics.vz * 0.5; // Bounce back
                a.physics.vx *= 0.6; // Ground friction
                a.physics.vy *= 0.6;
                a.physics.vAngle *= 0.5;
            } else {
                a.physics.vz = 0;
            }
        }

        // 7. World Position Drift (Slide effect for dead units or knockback correction)
        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px;
            const dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            // Increased snap threshold to stop jitter
            if (distSq > 0.5) {
                const driftSpeed = 12.0 * dt;
                a.px += dx * driftSpeed;
                a.py += dy * driftSpeed;
                if (distSq < 2) {
                    a.px = targetPos.x;
                    a.py = targetPos.y;
                }
            } else {
                a.px = targetPos.x;
                a.py = targetPos.y;
            }
        } else if (isDead) {
            // Apply physics velocity to world position (Flying through air)
            a.px += a.physics.vx * dt * 0.1; 
            a.py += a.physics.vy * dt * 0.1;
        }
    }
}

const spawnShowcaseUnits = useCallback(() => {
    const engine = engineRef.current;

    // 1. Get truly valid spawn locations (Not blocked by obstacles)
    let validHexes = (Array.from(engine.mapKeys) as string[])
        .map(k => {
            const [q, r] = k.split(',').map(Number);
            return {q, r};
        })
        .filter(h => !engine.map.isBlocked(h.q, h.r, engine)); // Important: Filter out obstacles

    // 2. Shuffle
    for (let i = validHexes.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
    }

    // 3. Determine Balanced Team Size
    // Randomize between 4 to 6 units, constrained by map size
    const desiredTeamSize = 4 + Math.floor(Math.random() * 3); 
    const maxPossibleSize = Math.floor(validHexes.length / 2);
    const teamSize = Math.min(desiredTeamSize, maxPossibleSize);

    let spawnIndex = 0;
    const spawn = (team: Team) => {
        if (spawnIndex < validHexes.length) {
            const h = validHexes[spawnIndex++];
            const hp = 500 + Math.floor(Math.random() * 400); 
            engine.addAgent(team, h.q, h.r, hp);
        }
    };

    for(let i=0; i<teamSize; i++) spawn(Team.BLUE);
    for(let i=0; i<teamSize; i++) spawn(Team.RED);

    engine.play();
    setIsPlaying(true);
}, []);

