import { ShowcaseOverlay } from './components/ui/ShowcaseOverlay';
import { MapSettingsModal } from './components/ui/MapSettingsModal';
import { ToolType, Role, Team, Skill } from './types';

const App: React.FC = () => {
    const engineRef = useRef(new GameEngine());
    // Force update for UI components that rely on engine state outside of canvas loop
    const [tick, setTick] = useState(0); 

    const [isPlaying, setIsPlaying] = useState(false);
    const [timeScale, setTimeScale] = useState(1.0);
    const [winner, setWinner] = useState<Team | null>(null);

    const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
    const [selectedObstacle, setSelectedObstacle] = useState<string>('WALL');
    const [hpInput, setHpInput] = useState<number>(1000);
    const [spawnMode, setSpawnMode] = useState<'RANDOM' | 'DRAFT'>('RANDOM');
    const [draftRole, setDraftRole] = useState<Role>(Role.WARRIOR);

    const [selectedAgent, setSelectedAgent] = useState<Agent | null>(null);
    const [hoveredSkill, setHoveredSkill] = useState<Skill | null>(null);

    const [showMapSettings, setShowMapSettings] = useState(false);
    const [showMobileInspector, setShowMobileInspector] = useState(false);
    const [isShowcaseMode, setIsShowcaseMode] = useState(false);

    // Map Config
    const [mapW, setMapW] = useState(engineRef.current.mapConfig.w);
    const [mapH, setMapH] = useState(engineRef.current.mapConfig.h);

    const [transitionPhase, setTransitionPhase] = useState<'IDLE' | 'IN' | 'OUT'>('IDLE');

    // Sync engine config
    useEffect(() => {
        engineRef.current.timeScale = timeScale;
    }, [timeScale]);

    const handleUpdateMap = () => {
        setTransitionPhase('OUT');
        setTimeout(() => {
            const engine = engineRef.current;
            engine.mapConfig.w = mapW;
            engine.mapConfig.h = mapH;
            engine.rebuildMap();
            setTransitionPhase('IN');
            setTimeout(() => setTransitionPhase('IDLE'), 1000);
            setTick(t => t + 1);
        }, 1000);
        setShowMapSettings(false);
    };

    const handleClearMap = () => {
        engineRef.current.clear(true);
        setWinner(null);
        setIsPlaying(false);
        setSelectedAgent(null);
        setTick(t => t + 1);
        setShowMapSettings(false);
    };

    const togglePlay = () => {
        if (isPlaying) {
            engineRef.current.stop();
            setIsPlaying(false);
        } else {
            if (winner) return;
            engineRef.current.play();
            setIsPlaying(true);
        }
    };

    const handleRestart = () => {
        engineRef.current.restart();
        setWinner(null);
        setIsPlaying(true);
        setTick(t => t + 1);
    };

    const spawnShowcaseUnits = useCallback(() => {
        const engine = engineRef.current;

        // 1. Get truly valid spawn locations (Not blocked by obstacles)
        let validHexes = (Array.from(engine.mapKeys) as string[])
            .map(k => {
                const [q, r] = k.split(',').map(Number);
                return {q, r};
            })
            .filter(h => !engine.map.isBlocked(h.q, h.r, engine)); // Important: Filter out obstacles

        // 2. Shuffle
        for (let i = validHexes.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [validHexes[i], validHexes[j]] = [validHexes[j], validHexes[i]];
        }

        // 3. Determine Balanced Team Size
        // Randomize between 4 to 6 units, constrained by map size
        const desiredTeamSize = 4 + Math.floor(Math.random() * 3); 
        const maxPossibleSize = Math.floor(validHexes.length / 2);
        const teamSize = Math.min(desiredTeamSize, maxPossibleSize);

        let spawnIndex = 0;
        const spawn = (team: Team) => {
            if (spawnIndex < validHexes.length) {
                const h = validHexes[spawnIndex++];
                const hp = 500 + Math.floor(Math.random() * 400); 
                engine.addAgent(team, h.q, h.r, hp);
            }
        };

        for(let i=0; i<teamSize; i++) spawn(Team.BLUE);
        for(let i=0; i<teamSize; i++) spawn(Team.RED);

        engine.play();
        setIsPlaying(true);
    }, []);

    const handleEnterShowcase = () => {
        setTransitionPhase('OUT');
        setIsShowcaseMode(true);

        setTimeout(() => {
            const engine = engineRef.current;
            engine.clear(false); // Clear and randomize scene

            // Re-sync map dimensions to state if randomized
            setMapW(engine.mapConfig.w);
            setMapH(engine.mapConfig.h);

            setWinner(null);
            spawnShowcaseUnits();

            setTransitionPhase('IN');
            setTimeout(() => setTransitionPhase('IDLE'), 1000);
        }, 1000);
    };

    return (
        <div className="flex h-screen w-screen overflow-hidden bg-slate-950 text-slate-200 font-sans selection:bg-cyan-500/30">
            {isShowcaseMode && (
                <ShowcaseOverlay 
                    onEnter={() => {
                        setIsShowcaseMode(false);
                        handleClearMap();
                    }}
                    timeScale={timeScale}
                    setTimeScale={setTimeScale}
                />
            )}

            <div className="flex-1 flex flex-col relative">
                {/* HUD & Canvas */}
                <div className="flex-1 relative overflow-hidden">
                    <PlaybackHUD 
                        hidden={isShowcaseMode}
                        isPlaying={isPlaying}
                        winner={winner}
                        timeScale={timeScale}
                        onTogglePlay={togglePlay}
                        onRestart={handleRestart}
                        onSetTimeScale={setTimeScale}
                        onShowcase={handleEnterShowcase}
                    />

                    <GameCanvas 
                        engine={engineRef.current}
                        tool={tool}
                        selectedObstacle={selectedObstacle}
                        hpInput={hpInput}
                        selectedAgent={selectedAgent}
                        hoveredSkill={hoveredSkill}
                        isShowcaseMode={isShowcaseMode}
                        spawnMode={spawnMode}
                        draftRole={draftRole}
                        onSelect={setSelectedAgent}
                        onWin={setWinner}
                        winner={winner}
                        rematch={handleRestart}
                        transitionPhase={transitionPhase}
                    />

                    {showMapSettings && (
                        <MapSettingsModal 
                            width={mapW} height={mapH}
                            onChangeW={setMapW} onChangeH={setMapH}
                            onRebuild={handleUpdateMap}
                            onClear={handleClearMap}
                            onClose={() => setShowMapSettings(false)}
                        />
                    )}
                </div>

                {/* Bottom Dock */}
                <ControlDock 
                    hidden={isShowcaseMode}
                    tool={tool} setTool={setTool}
                    spawnMode={spawnMode} setSpawnMode={setSpawnMode}
                    draftRole={draftRole} setDraftRole={setDraftRole}
                    selectedObstacle={selectedObstacle} setSelectedObstacle={setSelectedObstacle}
                    hpInput={hpInput} setHpInput={setHpInput}
                    mapW={mapW} setMapW={setMapW}
                    mapH={mapH} setMapH={setMapH}
                    unitCount={engineRef.current.agents.length}
                    onUpdateMap={handleUpdateMap}
                    onClearMap={handleClearMap}
                    showMapSettings={showMapSettings} setShowMapSettings={setShowMapSettings}
                    showMobileInspector={showMobileInspector} setShowMobileInspector={setShowMobileInspector}
                    hasSelectedAgent={!!selectedAgent}
                />
            </div>

            {/* Desktop Inspector */}
            <div className={`w-96 hidden md:flex flex-col border-l border-slate-800 bg-slate-900 transition-all ${isShowcaseMode ? 'mr-[-24rem]' : ''}`}>
                <InspectorPanel 
                    agent={selectedAgent} 
                    engine={engineRef.current} 
                    logs={engineRef.current.logs}
                    db={engineRef.current.skillDB}
                    onHoverSkill={setHoveredSkill}
                />
            </div>

            {/* Mobile Inspector Overlay */}
            {showMobileInspector && selectedAgent && (
                <div className="md:hidden absolute inset-0 z-40 bg-slate-900 flex flex-col animate-slide-up">
                    <div className="flex justify-between items-center p-4 border-b border-slate-800">
                        <h3 className="font-bold text-slate-300">單位詳情</h3>
                        <button onClick={() => setShowMobileInspector(false)} className="w-8 h-8 flex items-center justify-center bg-slate-800 rounded text-slate-400">✕</button>
                    </div>
                    <div className="flex-1 overflow-hidden">
                        <InspectorPanel 
                            agent={selectedAgent} 
                            engine={engineRef.current} 
                            logs={engineRef.current.logs}
                            db={engineRef.current.skillDB}
                        />
                    </div>
                </div>
            )}
        </div>
    );
};

export default App;

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils } from "../utils";
import { Hex, Skill, Projectile } from "../../types";

// Renderers
import { TerrainRenderer } from "../renderers/grid/TerrainRenderer";
import { GridOverlays } from "../renderers/grid/GridOverlays";

export interface RenderableItem {
    y: number;
    z: number;
    draw: (ctx: CanvasRenderingContext2D) => void;
}

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

export class GridSystem {
    // Optimization: Cache tiles to avoid re-parsing keys and re-calculating positions every frame
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuseable buffers to reduce GC pressure
    // Updated: Include 'visual' in the value
    private _dangerZones = new Map<string, {color: string, progress: number, visual: string}>();
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    // Passthrough
    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtScreenPoint(mx: number, my: number, camera: {x: number, y: number, zoom: number}, engine: GameEngine): Hex | null {
        this.ensureCache(engine);

        // Convert screen mouse to world coordinates (unzoomed)
        const wx = mx / camera.zoom + camera.x;
        const wy = my / camera.zoom + camera.y;

        const candidates: CachedTile[] = [];
        const limit = HEX_SIZE * 2; 

        for (const tile of this._tileCache) {
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - (tile.py - tile.h));
            if (dist < limit) { 
                candidates.push(tile);
            }
        }

        // Sort by visual depth (Front to Back)
        candidates.sort((a, b) => b.py - a.py);

        for (const cand of candidates) {
            const testHex = HexUtils.fromPx(wx, wy + cand.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === cand.q && rounded.r === cand.r) {
                return { q: cand.q, r: cand.r };
            }
        }

        return null;
    }

    /**
     * Identifies agents that are visually blocked by taller terrain in front of them.
     */
    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);

            // In Diamond Isometric, "Front" means Higher Y on screen.
            // Blocks with higher Y and higher Z can occlude units with lower Y.
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            let isBlocked = false;

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);

                    // Check if neighbor is physically "in front" (Screen Y is larger)
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         // If the blocking tile is strictly taller
                         if (nHeight > uHeight) {
                             isBlocked = true;
                             break;
                         }
                    }
                }
            }

            if (isBlocked) {
                occluded.push(a);
            }
        });

        return occluded;
    }

    collectRenderables(
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        flashes: any[],
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ): RenderableItem[] {
        this.ensureCache(engine);

        const list: RenderableItem[] = [];
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Clear and Reuse Buffers
        this._dangerZones.clear();
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        engine.agents.forEach(a => {
            if (a.hp > 0 && a.castingSkillIdx !== -1) {
                const s = a.skills[a.castingSkillIdx];
                if (s && s.type === 'AOE') {
                    let centerHex: Hex | null = null;
                    if (a.targetHex) centerHex = a.targetHex;
                    else if (a.target) centerHex = {q: a.target.q, r: a.target.r};
                    else centerHex = {q: a.q, r: a.r};

                    if (centerHex) {
                        const progress = 1 - (a.castTimer / s.cast);
                        // Using raw HexUtils range which creates arrays, acceptable for small radii
                        HexUtils.range(centerHex, s.aoeRadius || 1).forEach(h => {
                            this._dangerZones.set(`${h.q},${h.r}`, {
                                color: s.color, 
                                progress: progress,
                                visual: s.visual || 'BOLT' // Pass visual type
                            });
                        });
                    }
                }
            }

            if(a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') {
                    this._unitVisualStatus.set(key, a.visualStatus);
                }
            }
        });

        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            // --- TRANSITION LOGIC ---
            let visualY = py;

            if (transitionPhase !== 'IDLE') {
                const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                const d = dist / maxDist; 

                if (transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (transitionT > trigger) {
                        const fallT = Math.min(1, (transitionT - trigger) * 2.5);
                        const easedFall = fallT * fallT * fallT;
                        visualY += easedFall * 1000;
                    }
                } else if (transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                }
            }

            if (visualY > py + 800) continue;

            const flash = flashes.find(f => f.q === q && f.r === r);
            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                // HEIGHT AWARE RANGE CHECK
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const tileH = h;
                const bonus = Math.max(0, Math.floor((agentH - tileH) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;

                if (HexUtils.dist({q, r}, highlightAgent) <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;

            const k = `${q},${r}`;
            const dangerInfo = this._dangerZones.get(k);
            const hasUnit = this._unitPresence.has(k);
            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;
            const PROJ_LIGHT_RADIUS = 40; 
            const PROJ_LIGHT_RADIUS_SQ = PROJ_LIGHT_RADIUS * PROJ_LIGHT_RADIUS;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / PROJ_LIGHT_RADIUS);
                }
            }

            list.push({
                y: visualY, 
                z: 0,        
                draw: (ctx) => {
                    // 1. Draw Physical Block
                    TerrainRenderer.drawBlockGeometry(ctx, px, visualY, HEX_SIZE, h, theme);

                    // 2. Draw Texture Detail
                    TerrainRenderer.drawTerrainDetail(ctx, px, visualY - h, q, r, scene.textureType, theme.detail);

                    // 3. Draw Overlays (Status, Range, Danger, Lighting)
                    GridOverlays.drawOverlays(
                        ctx, px, visualY - h, HEX_SIZE,
                        specialStatus, dangerInfo,
                        lightColor, Math.min(1, lightIntensity),
                        flash, isRange, rangeColor, isHover, hasUnit,
                        q, r, globalTime
                    );
                }
            });
        }

        return list;
    }
}

import { TerrainRenderer } from "./TerrainRenderer";

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Note: y here should be the "visual top" y (y - topY)
        size: number,
        specialStatus: string | undefined,
        dangerInfo: {color: string, progress: number, visual: string} | undefined,
        lightColor: string | null,
        lightIntensity: number,
        flash: any,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number
    ) {
        // Helper to trace the hex shape at current position
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        // 1. SPECIAL STATUS FLOOR EFFECT (Frozen/Polymorph)
        if (specialStatus) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // 2. AOE TELEGRAPH (Danger Zone) - NOW DIFFERENTIATED
        if (dangerInfo) {
            const { color, progress, visual } = dangerInfo;
            const opacity = 0.2 + progress * 0.5;

            trace(); 
            ctx.save();

            // --- A. SMASH / EARTH (Physical Cracks) ---
            if (visual === 'SMASH') {
                ctx.fillStyle = '#000';
                ctx.globalAlpha = opacity * 0.4;
                ctx.fill(); // Darken base

                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.globalAlpha = progress; 
                ctx.stroke(); // Border

                // Cracks emanating from center
                // Seed random based on coordinates to keep cracks stable
                const seed = Math.abs(q * 123 + r * 456);

                if (progress > 0.1) {
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.beginPath();
                    // Generate 3 random cracks
                    for(let i=0; i<3; i++) {
                        const angle = (seed + i * 2) % (Math.PI * 2);
                        const len = size * progress * 0.8;

                        // Jagged line
                        let cx = x; let cy = y;
                        ctx.moveTo(cx, cy);
                        for(let s=0; s<3; s++) {
                            cx += Math.cos(angle + (s%2==0?0.5:-0.5)) * (len/3);
                            cy += Math.sin(angle + (s%2==0?0.5:-0.5)) * (len/3);
                            ctx.lineTo(cx, cy);
                        }
                    }
                    ctx.strokeStyle = color;
                    ctx.lineWidth = 1 + progress * 2;
                    ctx.stroke();
                }

            // --- B. FIREBALL / BOMB (Pulsing Core) ---
            } else if (visual === 'FIREBALL' || visual === 'BOMB') {
                const pulse = 1 + Math.sin(globalTime * 15) * 0.1;

                // Gradient Fill
                const grad = ctx.createRadialGradient(x, y, 0, x, y, size * 0.8);
                grad.addColorStop(0, color);
                grad.addColorStop(progress, 'transparent'); // Expands

                ctx.fillStyle = grad;
                ctx.globalAlpha = opacity * 0.8;
                ctx.globalCompositeOperation = 'lighter';
                ctx.fill();

                // Warning Border
                ctx.strokeStyle = color;
                ctx.lineWidth = 2 * pulse;
                ctx.globalAlpha = 1.0;
                ctx.stroke();

            // --- C. ARROW / RANGER (Focusing Reticle) ---
            } else if (visual === 'ARROW') {
                // Background tint
                ctx.fillStyle = color;
                ctx.globalAlpha = 0.1;
                ctx.fill();

                // Shrinking Circle (Focus)
                const shrink = (1 - progress); // 1.0 -> 0.0
                const radius = size * (0.2 + shrink * 0.8);

                ctx.globalAlpha = 0.8 + progress * 0.2;
                ctx.globalCompositeOperation = 'source-over';
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;

                // Crosshair
                ctx.beginPath();
                ctx.moveTo(x - 5, y); ctx.lineTo(x + 5, y);
                ctx.moveTo(x, y - 5); ctx.lineTo(x, y + 5);
                ctx.stroke();

                // Ring
                ctx.beginPath();
                ctx.arc(x, y, radius, 0, Math.PI * 2);
                ctx.stroke();

            // --- D. DEFAULT / MAGIC (Rising Particles) ---
            } else {
                ctx.fillStyle = color;
                ctx.globalAlpha = opacity;
                ctx.globalCompositeOperation = 'lighter'; 
                ctx.fill(); 

                // Glowing Border
                ctx.strokeStyle = color;
                ctx.lineWidth = 1 + progress * 2;
                ctx.globalAlpha = 0.8;
                ctx.stroke();

                // Rising Runes/Particles
                if (progress > 0.2) {
                    const particleCount = 2 + Math.floor(progress * 3);
                    for(let i=0; i<particleCount; i++) {
                        const pSeed = (Math.abs(q * 100 + r * 10) + i * 123.45);
                        const speed = 20 + (pSeed % 20);
                        const t = (globalTime * speed * 0.05 + pSeed) % 1; 
                        const pAlpha = 1 - t;

                        const pX = x + Math.sin(t * 10 + pSeed) * (size * 0.5);
                        const pY = y - (t * 40); 

                        ctx.globalAlpha = pAlpha * opacity; 
                        const pSize = 1 + (pSeed % 2);

                        ctx.beginPath();
                        ctx.arc(pX, pY, pSize, 0, Math.PI*2);
                        ctx.fill();
                    }
                }
            }

            ctx.restore();
        }

        // 3. Dynamic Lighting (Projectile Pass)
        if (lightColor && lightIntensity > 0) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // 4. Interactive Highlights (Hover/Range/Flash)
        if (flash || isRange || isHover || hasUnit) {
            ctx.save();
            trace(); 

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2; 
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.8; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.15)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 3; 
                ctx.stroke(); 
            }

            if (flash) {
                ctx.globalCompositeOperation = 'lighter';
                ctx.fillStyle = flash.color;
                ctx.globalAlpha = 0.6;
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            if (hasUnit && !isHover && !dangerInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.3)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { TerrainRenderer } from "./TerrainRenderer";

export const AOERenderer = {
    draw(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        visual: string,
        progress: number,
        globalTime: number,
        q: number, r: number
    ) {
        // Helper trace function
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        ctx.save();

        // COMMON: No heavy fill, just light tint and strong borders
        const opacity = 0.5 + progress * 0.5;

        // --- A. SMASH / EARTH (Cracks) ---
        if (visual === 'SMASH') {
            // Only draw borders and cracks, no background tint
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = opacity;
            trace();
            ctx.stroke();

            // Cracks
            const seed = Math.abs(q * 123 + r * 456);
            if (progress > 0.1) {
                ctx.globalCompositeOperation = 'source-over';
                ctx.beginPath();
                for(let i=0; i<3; i++) {
                    const angle = (seed + i * 2) % (Math.PI * 2);
                    const len = size * 0.8;
                    let cx = x; let cy = y;
                    ctx.moveTo(cx, cy);
                    // Jagged line
                    for(let s=0; s<3; s++) {
                        cx += Math.cos(angle + (s%2==0?0.5:-0.5)) * (len/3);
                        cy += Math.sin(angle + (s%2==0?0.5:-0.5)) * (len/3);
                        ctx.lineTo(cx, cy);
                    }
                }
                ctx.strokeStyle = color;
                ctx.lineWidth = 1 + progress;
                ctx.stroke();
            }

        // --- B. FIREBALL / BOMB (Pulse Ring) ---
        } else if (visual === 'FIREBALL' || visual === 'BOMB') {
            const pulse = 1 + Math.sin(globalTime * 20) * 0.1;

            // Outer Ring Glow (Halo) instead of tile fill
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            ctx.strokeStyle = color;
            ctx.lineWidth = 3 * pulse;
            ctx.globalAlpha = 1.0;

            trace();
            ctx.stroke();

            // Inner heat core (Small dot)
            ctx.fillStyle = color;
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); 
            ctx.arc(x, y, size * 0.2 * pulse, 0, Math.PI*2); 
            ctx.fill();

        // --- C. ARROW / RANGER (Target Lock) ---
        } else if (visual === 'ARROW') {
            // Reticle corners only
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.8;

            const s = size * 0.6;
            ctx.beginPath();
            // Top Left
            ctx.moveTo(x - s, y - s/2); ctx.lineTo(x - s, y - s); ctx.lineTo(x - s/2, y - s);
            // Top Right
            ctx.moveTo(x + s/2, y - s); ctx.lineTo(x + s, y - s); ctx.lineTo(x + s, y - s/2);
            // Bottom Right
            ctx.moveTo(x + s, y + s/2); ctx.lineTo(x + s, y + s); ctx.lineTo(x + s/2, y + s);
            // Bottom Left
            ctx.moveTo(x - s/2, y + s); ctx.lineTo(x - s, y + s); ctx.lineTo(x - s, y + s/2);
            ctx.stroke();

            // Center Dot
            ctx.fillStyle = color;
            ctx.beginPath(); ctx.arc(x, y, 2, 0, Math.PI*2); ctx.fill();

        // --- D. DEFAULT / MAGIC (Runes) ---
        } else {
            // Magic Border
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 0.8;
            ctx.shadowColor = color;
            ctx.shadowBlur = 5;
            trace();
            ctx.stroke();

            // Floating Particles
            if (progress > 0.2) {
                const particleCount = 1 + Math.floor(Math.random() * 2);
                for(let i=0; i<particleCount; i++) {
                    const pSeed = (Math.abs(q * 100 + r * 10) + i * 123.45 + globalTime);
                    const pX = x + Math.sin(pSeed) * (size * 0.4);
                    const pY = y + Math.cos(pSeed) * (size * 0.4);

                    ctx.globalAlpha = 0.6 + Math.sin(globalTime * 10 + i) * 0.4;
                    ctx.fillStyle = color;
                    ctx.beginPath();
                    ctx.arc(pX, pY, 1.5, 0, Math.PI*2);
                    ctx.fill();
                }
            }
        }

        ctx.restore();
    }
};

import { TerrainRenderer } from "./TerrainRenderer";
import { AOERenderer } from "./AOERenderer";

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Note: y here should be the "visual top" y (y - topY)
        size: number,
        specialStatus: string | undefined,
        dangerInfo: {color: string, progress: number, visual: string} | undefined,
        lightColor: string | null,
        lightIntensity: number,
        flash: any,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number
    ) {
        // Helper to trace the hex shape at current position
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        // 1. SPECIAL STATUS FLOOR EFFECT (Frozen/Polymorph)
        if (specialStatus) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // 2. AOE TELEGRAPH (Danger Zone) - Delegated
        if (dangerInfo) {
            AOERenderer.draw(
                ctx, x, y, size, 
                dangerInfo.color, dangerInfo.visual, dangerInfo.progress, 
                globalTime, q, r
            );
        }

        // 3. Dynamic Lighting (Projectile Pass)
        if (lightColor && lightIntensity > 0) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // 4. Interactive Highlights (Hover/Range/Flash)
        if (flash || isRange || isHover || hasUnit) {
            ctx.save();
            trace(); 

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.1; // Fainter fill
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.6; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.1)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2; 
                ctx.stroke(); 
            }

            if (flash) {
                ctx.globalCompositeOperation = 'lighter';
                ctx.fillStyle = flash.color;
                ctx.globalAlpha = 0.4;
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            // Only draw unit base ring if not hovering and no danger zone (cleaner look)
            if (hasUnit && !isHover && !dangerInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.15)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils } from "../utils";
import { Hex, Skill, Projectile } from "../../types";

// Renderers
import { TerrainRenderer } from "../renderers/grid/TerrainRenderer";
import { GridOverlays } from "../renderers/grid/GridOverlays";

export interface RenderableItem {
    y: number;
    z: number;
    draw: (ctx: CanvasRenderingContext2D) => void;
}

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

export class GridSystem {
    // Optimization: Cache tiles to avoid re-parsing keys and re-calculating positions every frame
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuseable buffers to reduce GC pressure
    private _dangerZones = new Map<string, {color: string, progress: number, visual: string}>();
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    // Passthrough
    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtScreenPoint(mx: number, my: number, camera: {x: number, y: number, zoom: number}, engine: GameEngine): Hex | null {
        this.ensureCache(engine);

        // Convert screen mouse to world coordinates (unzoomed)
        const wx = mx / camera.zoom + camera.x;
        const wy = my / camera.zoom + camera.y;

        const candidates: CachedTile[] = [];
        const limit = HEX_SIZE * 2; 

        for (const tile of this._tileCache) {
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - (tile.py - tile.h));
            if (dist < limit) { 
                candidates.push(tile);
            }
        }

        // Sort by visual depth (Front to Back)
        candidates.sort((a, b) => b.py - a.py);

        for (const cand of candidates) {
            const testHex = HexUtils.fromPx(wx, wy + cand.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === cand.q && rounded.r === cand.r) {
                return { q: cand.q, r: cand.r };
            }
        }

        return null;
    }

    /**
     * Identifies agents that are visually blocked by taller terrain in front of them.
     */
    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);

            // In Diamond Isometric, "Front" means Higher Y on screen.
            // Blocks with higher Y and higher Z can occlude units with lower Y.
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            let isBlocked = false;

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);

                    // Check if neighbor is physically "in front" (Screen Y is larger)
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         // If the blocking tile is strictly taller
                         if (nHeight > uHeight) {
                             isBlocked = true;
                             break;
                         }
                    }
                }
            }

            if (isBlocked) {
                occluded.push(a);
            }
        });

        return occluded;
    }

    collectRenderables(
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        flashes: any[],
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ): RenderableItem[] {
        this.ensureCache(engine);

        const list: RenderableItem[] = [];
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Clear and Reuse Buffers
        this._dangerZones.clear();
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        engine.agents.forEach(a => {
            // STRICT CHECK: If silenced, stunned, banished, or dead, IMMEDIATELY stop drawing warnings.
            if (a.hp <= 0 || a.stunTimer > 0 || a.silenceTimer > 0 || a.banished) return;

            if (a.castingSkillIdx !== -1) {
                const s = a.skills[a.castingSkillIdx];
                if (s && s.type === 'AOE') {
                    let centerHex: Hex | null = null;
                    if (a.targetHex) centerHex = a.targetHex;
                    else if (a.target) centerHex = {q: a.target.q, r: a.target.r};
                    else centerHex = {q: a.q, r: a.r};

                    if (centerHex) {
                        const progress = 1 - (a.castTimer / s.cast);
                        // DYNAMIC EXPANSION:
                        // Calculate current radius based on progress (expanding wave)
                        // Minimum 0.5 to show center immediately
                        const currentRadius = Math.max(0.5, (s.aoeRadius || 1) * progress);

                        // We scan valid map tiles instead of blindly generating range to handle distance checks properly
                        // Optimization: Just get range of Max Radius, then filter by Current Radius
                        const potentialHexes = HexUtils.range(centerHex, s.aoeRadius || 1);

                        potentialHexes.forEach(h => {
                            if (HexUtils.dist(centerHex!, h) <= currentRadius) {
                                this._dangerZones.set(`${h.q},${h.r}`, {
                                    color: s.color, 
                                    progress: progress,
                                    visual: s.visual || 'BOLT'
                                });
                            }
                        });
                    }
                }
            }

            if(a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') {
                    this._unitVisualStatus.set(key, a.visualStatus);
                }
            }
        });

        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            // --- TRANSITION LOGIC ---
            let visualY = py;

            if (transitionPhase !== 'IDLE') {
                const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                const d = dist / maxDist; 

                if (transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (transitionT > trigger) {
                        const fallT = Math.min(1, (transitionT - trigger) * 2.5);
                        const easedFall = fallT * fallT * fallT;
                        visualY += easedFall * 1000;
                    }
                } else if (transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                }
            }

            if (visualY > py + 800) continue;

            const flash = flashes.find(f => f.q === q && f.r === r);
            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                // HEIGHT AWARE RANGE CHECK
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const tileH = h;
                const bonus = Math.max(0, Math.floor((agentH - tileH) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;

                if (HexUtils.dist({q, r}, highlightAgent) <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;

            const k = `${q},${r}`;
            const dangerInfo = this._dangerZones.get(k);
            const hasUnit = this._unitPresence.has(k);
            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;
            const PROJ_LIGHT_RADIUS = 40; 
            const PROJ_LIGHT_RADIUS_SQ = PROJ_LIGHT_RADIUS * PROJ_LIGHT_RADIUS;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / PROJ_LIGHT_RADIUS);
                }
            }

            list.push({
                y: visualY, 
                z: 0,        
                draw: (ctx) => {
                    // 1. Draw Physical Block
                    TerrainRenderer.drawBlockGeometry(ctx, px, visualY, HEX_SIZE, h, theme);

                    // 2. Draw Texture Detail
                    TerrainRenderer.drawTerrainDetail(ctx, px, visualY - h, q, r, scene.textureType, theme.detail);

                    // 3. Draw Overlays (Status, Range, Danger, Lighting)
                    GridOverlays.drawOverlays(
                        ctx, px, visualY - h, HEX_SIZE,
                        specialStatus, dangerInfo,
                        lightColor, Math.min(1, lightIntensity),
                        flash, isRange, rangeColor, isHover, hasUnit,
                        q, r, globalTime
                    );
                }
            });
        }

        return list;
    }
}

import { GameEngine } from "../../game";
import { HexUtils, Vector, MapConfig } from "../../utils";
import { AssetManager } from "../../assets";
import { RenderableItem } from "../grid";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { Particle } from "../vfx/state"; // Changed import to state

const UNIT_CHEST_HEIGHT = 40;

export class VFXRenderer {

    // --- Helper to calculate vertical offset during map transition ---
    private getTransitionOffset(x: number, y: number, mapConfig: MapConfig, t: number, phase: 'IN' | 'OUT' | 'IDLE'): number {
        if (phase === 'IDLE') return 0;
        const centerQ = Math.floor(mapConfig.w / 2);
        const centerR = Math.floor(mapConfig.h / 2);
        const hex = HexUtils.fromPx(x, y, mapConfig);
        const maxDist = Math.max(mapConfig.w, mapConfig.h) / 2;
        const dist = Math.sqrt((hex.q - centerQ)**2 + (hex.r - centerR)**2);
        const d = dist / maxDist;

        if (phase === 'OUT') {
            const trigger = d * 0.3;
            if (t > trigger) {
                const fallT = Math.min(1, (t - trigger) * 2.5);
                return fallT * fallT * fallT * 1000;
            }
        } else if (phase === 'IN') {
            const trigger = d * 0.3;
            const riseT = Math.max(0, Math.min(1, (t - trigger) * 2.5));
            const easedRise = 1 - Math.pow(1 - riseT, 3);
            return (1 - easedRise) * 1000;
        }
        return 0;
    }

    // --- Rendering Collections ---

    public collectRenderables(
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        // 1. Decals (Ground Level) - Access via state
        vfx.state.decals.forEach(d => {
            const offsetY = this.getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            list.push({
                y: drawY, z: 0,
                draw: (ctx) => {
                    const img = AssetManager.getBlastZone(d.color);
                    ctx.save();
                    ctx.translate(d.x, drawY);
                    ctx.scale(d.scale, d.scale);
                    ctx.globalAlpha = Math.min(1, d.life);
                    ctx.drawImage(img, -64, -32, 128, 64);
                    ctx.restore();
                }
            });
        });

        // 2. Projectiles (Projectiles are stored in Engine, not VFX state, so this remains same)
        engine.projectiles.forEach(p => {
             const offsetP = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             const getVisualPos = (lx: number, ly: number) => {
                 const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: lx, y: ly});
                 const t = Math.min(1, Math.max(0, currentDist / totalDist));
                 const currentTerrainHeight = hStart + (hEnd - hStart) * t;

                 let arcOffset = 0;
                 // Apply Arc to ARROW, FIREBALL, and BOMB
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'FIREBALL' || p.skill.visual === 'BOMB') {
                     const apex = Math.min(150, totalDist * 0.3);
                     arcOffset = Math.sin(t * Math.PI) * apex; 
                 }

                 const off = this.getTransitionOffset(lx, ly, mapConfig, transitionT, transitionPhase);
                 return {
                     x: lx,
                     y: ly - currentTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     shadowY: ly - currentTerrainHeight + off
                 };
             };

             const headVis = getVisualPos(p.x, p.y);

             // Calculate Pitch Rotation (Visual Angle)
             // Use current direction to target to allow for homing curves
             const lookAheadDist = 5;
             const currentDir = Vector.sub(p.targetPos, {x: p.x, y: p.y});
             const distRemaining = Vector.mag(currentDir);

             // SAFE FALLBACK: If extremely close, keep moving towards target (or use last known good dir)
             // to prevent NaN when normalization fails on 0-length vector
             let dir;
             if (distRemaining > 0.1) {
                 dir = Vector.normalize(currentDir);
             } else {
                 // Fallback to overall trajectory logic to prevent snap
                 const totalTrajectory = Vector.sub(p.targetPos, {x: p.startX, y: p.startY});
                 const totalMag = Vector.mag(totalTrajectory);
                 dir = totalMag > 0.1 ? Vector.normalize(totalTrajectory) : {x: 1, y: 0};
             }

             const nextLx = p.x + dir.x * lookAheadDist;
             const nextLy = p.y + dir.y * lookAheadDist;
             const nextVis = getVisualPos(nextLx, nextLy);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);

             // Extra rotation for bombs (spin)
             const spin = p.skill.visual === 'BOMB' ? (Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y}) * 0.1) : 0;

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail (Before Head) ---
                    if (p.trail.length > 1) {
                        const trailVis = p.trail.map(t => getVisualPos(t.x, t.y));
                        // Add current head position to close the gap
                        trailVis.push(headVis);

                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            // ARROW: Thin, faint motion blur line
                            ctx.beginPath();
                            ctx.moveTo(trailVis[0].x, trailVis[0].y);
                            for (let i = 1; i < trailVis.length; i++) {
                                ctx.lineTo(trailVis[i].x, trailVis[i].y);
                            }
                            ctx.strokeStyle = `rgba(255, 255, 255, 0.2)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            // MAGIC / BOLT / FIREBALL: Tapered glowing ribbon
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            // Iterate segments to vary width/opacity
                            for (let i = 0; i < trailVis.length - 1; i++) {
                                const pt = trailVis[i];
                                const next = trailVis[i+1];

                                // Ratio 0 (tail) -> 1 (head)
                                const ratio = i / (trailVis.length - 1); 

                                ctx.beginPath();
                                ctx.moveTo(pt.x, pt.y);
                                ctx.lineTo(next.x, next.y);

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio;

                                // Color handling
                                ctx.strokeStyle = p.skill.color;
                                ctx.globalAlpha = ratio * 0.5; // Fade out tail

                                ctx.stroke();
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.shadowY);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.ellipse(0, 0, 10, 5, 0, 0, Math.PI*2); ctx.fill();
                    ctx.restore();

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') {
                        ctx.rotate(spin);
                    } else {
                        ctx.rotate(angle);
                    }

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);

                    // Visual Fallback for Missing Assets
                    if (img && img.width > 0) {
                        ctx.drawImage(img, -48, -32, 96, 64);
                    } else {
                        ctx.fillStyle = '#ff00ff';
                        ctx.fillRect(-5, -5, 10, 10);
                    }

                    ctx.restore();
                 }
             });
        });

        return list;
    }

    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        // Iterate over vfx.state.particles
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            const offset = this.getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            // Z acts as Y-offset in 2D draw call (up is negative)
            const drawY = p.y + offset - p.z;

            if (p.type === 'PILLAR' || p.type === 'SHOCKWAVE' || p.type === 'DOMAIN') {
                ctx.save();
                ctx.translate(p.x, drawY - 20); // Ground effects
                if (p.type === 'PILLAR') this.drawPillar(ctx, p, progress);
                else if (p.type === 'SHOCKWAVE') this.drawShockwave(ctx, p, progress);
                else if (p.type === 'DOMAIN') this.drawDomain(ctx, p, progress);
                ctx.restore();
                return;
            }

            ctx.save();
            ctx.translate(p.x, drawY);

            if (p.type === 'BEAM') {
                if (p.targetX !== undefined && p.targetY !== undefined) {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 5;
                    ctx.lineCap = 'round';
                    ctx.globalCompositeOperation = 'lighter';
                    ctx.beginPath();
                    ctx.moveTo(0, 0);
                    ctx.lineTo(p.targetX - p.x, p.targetY - p.y); 
                    ctx.stroke();
                }
            } else if (p.type === 'RING') {
                ctx.scale(1, 0.55); 
                const r = progress * 40;
                ctx.strokeStyle = p.color;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 1 - progress;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
            } else if (p.type === 'SPARK') {
                const r = p.size;
                const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
                grad.addColorStop(0, '#fff'); 
                grad.addColorStop(0.3, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.globalAlpha = 1 - Math.pow(progress, 3); 
                ctx.globalCompositeOperation = 'lighter'; 
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();
            } else if (p.type === 'DEBRIS' || p.type === 'SHARD') {
                // Drawing Shards as jagged polygons
                ctx.fillStyle = p.color;
                ctx.rotate(p.rotation);

                // Draw a rough triangle/quad shape
                ctx.beginPath();
                const s = p.size;
                if (p.type === 'SHARD') {
                    // Jagged Shard
                    ctx.moveTo(-s, -s/2);
                    ctx.lineTo(0, -s);
                    ctx.lineTo(s, -s/2);
                    ctx.lineTo(0, s);
                } else {
                    // Box debris
                    ctx.rect(-s/2, -s/2, s, s);
                }
                ctx.fill();

                // Add highlight edge
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        });
    }

    private drawPillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.globalCompositeOperation = 'lighter';

        const lifeRatio = p.life / p.maxLife;
        // Pulse width at start, then thin out
        const pulse = 1 + Math.sin(progress * 20) * 0.2;
        const baseWidth = 50 * (lifeRatio < 0.2 ? lifeRatio * 5 : 1) * pulse;
        const height = 1200; // Taller to go off screen
        const alpha = Math.sin(lifeRatio * Math.PI) * 0.8; 

        ctx.save();
        ctx.scale(1, 0.55); 

        // Ground Blast Ring
        const ringSize = baseWidth * 1.8;
        const ringGrad = ctx.createRadialGradient(0, 0, ringSize * 0.3, 0, 0, ringSize);
        ringGrad.addColorStop(0, 'rgba(255,255,255,0.8)');
        ringGrad.addColorStop(0.4, p.color);
        ringGrad.addColorStop(1, 'rgba(0,0,0,0)');

        ctx.fillStyle = ringGrad;
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.arc(0, 0, ringSize, 0, Math.PI*2); ctx.fill();
        ctx.restore();

        // Core Beam (Solid White Center)
        const coreWidth = baseWidth * 0.3;
        const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
        coreGrad.addColorStop(0, '#ffffff');
        coreGrad.addColorStop(0.2, '#ffffff');
        coreGrad.addColorStop(1, 'transparent');

        ctx.fillStyle = coreGrad;
        ctx.globalAlpha = alpha;
        ctx.fillRect(-coreWidth/2, -height, coreWidth, height);

        // Outer Glow Beam (Color)
        const glowGrad = ctx.createLinearGradient(0, 0, 0, -height);
        glowGrad.addColorStop(0, p.color);
        glowGrad.addColorStop(0.6, 'transparent');

        ctx.fillStyle = glowGrad;
        ctx.globalAlpha = alpha * 0.6;
        ctx.fillRect(-baseWidth * 0.8, -height, baseWidth * 1.6, height);
    }

    private drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        ctx.scale(1, 0.55); 
        ctx.globalCompositeOperation = 'lighter';

        // Main Outer Ring
        const r = progress * 250; 
        const width = 20 * (1 - progress);

        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;
        ctx.globalAlpha = (1 - progress) * 0.9;
        ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        // Inner Fast Ring (Echo)
        if (progress > 0.1) {
            const r2 = (progress - 0.1) * 300;
            const w2 = 10 * (1 - progress);
            ctx.lineWidth = w2;
            ctx.globalAlpha = (1 - progress) * 0.5;
            ctx.beginPath(); ctx.arc(0, 0, r2, 0, Math.PI * 2); ctx.stroke();
        }
    }

    private drawDomain(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         ctx.scale(1, 0.55); // Isometric squash
         const time = performance.now() / 1000;

         // 1. Dynamic Radius Pulse
         const baseRadius = 250;
         const pulse = 1 + Math.sin(time * 5) * 0.02;
         const r = baseRadius * pulse;

         ctx.globalCompositeOperation = 'lighter'; // Additive blending for energy feel

         // 2. Base Energy Field (Gradient instead of flat color)
         const grad = ctx.createRadialGradient(0, 0, r * 0.2, 0, 0, r);
         grad.addColorStop(0, 'transparent'); // Clear center to see units
         grad.addColorStop(0.7, p.color + '33'); // Faint color (approx 0.2 alpha)
         grad.addColorStop(0.95, p.color); // Hard edge
         grad.addColorStop(1, 'transparent');

         ctx.fillStyle = grad;
         ctx.globalAlpha = 0.6 * (1 - progress); // Fade out over lifetime
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // 3. Rotating Rune Rings (The "Turbulence")
         ctx.globalAlpha = 0.8 * (1 - progress);
         ctx.strokeStyle = p.color;

         // Ring 1: Slow Clockwise
         ctx.save();
         ctx.rotate(time * 0.5);
         ctx.lineWidth = 3;
         ctx.setLineDash([40, 60]); // Dashed "Rune" look
         ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI * 2); ctx.stroke();
         ctx.restore();

         // Ring 2: Fast Counter-Clockwise
         ctx.save();
         ctx.rotate(-time * 1.2);
         ctx.lineWidth = 2;
         ctx.setLineDash([20, 30]);
         ctx.beginPath(); ctx.arc(0, 0, r * 0.6, 0, Math.PI * 2); ctx.stroke();
         ctx.restore();

         // 4. Vertical Energy Spikes (Simulated 3D wall)
         // Draw small vertical lines along the rim
         ctx.globalAlpha = 0.4 * (1 - progress);
         const spikeCount = 12;
         for(let i=0; i<spikeCount; i++) {
             const angle = (i / spikeCount) * Math.PI * 2 + time;
             const sx = Math.cos(angle) * r;
             const sy = Math.sin(angle) * r;
             // Un-squash Y for vertical height
             // Since context is scaled (1, 0.55), drawing Y-100 means visual height ~55
             ctx.beginPath();
             ctx.moveTo(sx, sy);
             ctx.lineTo(sx, sy - 80); // Beam height
             ctx.lineWidth = 4;

             // Fade out tip
             const beamGrad = ctx.createLinearGradient(sx, sy, sx, sy - 80);
             beamGrad.addColorStop(0, p.color);
             beamGrad.addColorStop(1, 'transparent');
             ctx.strokeStyle = beamGrad;
             ctx.stroke();
         }
    }
}

import { Skill, Team, Role, MovementType, AnimState, Hex } from "../../types";
import { HexUtils, MapConfig } from "../utils";
import { UNIT_DB } from "../../data/units";
import { BTNode } from "../behaviorTree";

export type SpecialVisualStatus = 'NONE' | 'FROZEN' | 'POLYMORPH' | 'STASIS';

export class Agent {
    public id: string;
    public team: Team;
    public role: Role;
    public q: number;
    public r: number;
    public px: number;
    public py: number;

    // Stats
    public hp: number = 100;
    public maxHp: number = 100;
    public mp: number = 0;
    public maxMp: number = 100;
    public moveSpeed: number = 1.0; 
    public moveSpeedMult: number = 1.0; 
    public jump: number = 1; // Vertical mobility tier
    public weight: number = 1; // Knockback resistance
    public movementType: MovementType = MovementType.GROUND;

    // Skills
    public skillIds: (string | null)[] = [null, null, null];
    public skills: (Skill | null)[] = [];
    public castingSkillIdx: number = -1;
    public castTimer: number = 0;
    public castingAnimationTimer: number = 0; 
    public curCDs: number[] = [0, 0, 0];

    // State / AI
    public isMoving: boolean = false;
    public path: Hex[] = []; 
    public trajectory: Hex[] = []; 
    public moveProgress: number = 0;
    public facing: number = 1; 
    public target: Agent | null = null;
    public targetHex: Hex | null = null; 
    public btStatus: string = "待機";
    public bt: BTNode | null = null;

    // Status Effects
    public stunTimer: number = 0;
    public banishTimer: number = 0;
    public silenceTimer: number = 0;
    public banished: boolean = false;
    public dotTimer: number = 0;
    public dotDmg: number = 0;
    public hotTimer: number = 0;
    public hotVal: number = 0;

    // Visual State
    public visualStatus: SpecialVisualStatus = 'NONE';
    public spawnTimer: number = 0;

    // Visual Persistence for Interruptions
    public interruptedVisual: {
        skill: Skill;
        center: Hex;
        radius: number;
        progress: number;
        visual: string;
        color: string;
        timer: number;    // Current fade time
        maxTimer: number; // Total fade duration
    } | null = null;

    // Lifecycle
    public deadLogged: boolean = false;
    public fullyDead: boolean = false;
    public animState: AnimState = AnimState.IDLE;
    public animTimer: number = 0; 
    public hitFlashTimer: number = 0;

    // Physics
    public physics = { 
        x: 0, y: 0, z: 0,          
        vx: 0, vy: 0, vz: 0,       
        angle: 0, vAngle: 0   
    };

    public initialState: { q: number, r: number, maxHp: number, skillIds: (string|null)[], role: Role };

    constructor(team: Team, q: number, r: number, config: MapConfig) {
        this.id = Math.random().toString(36).substr(2, 5).toUpperCase();
        this.team = team;
        this.role = Role.WARRIOR; 
        this.q = q;
        this.r = r;

        const p = HexUtils.toPx(q, r, config);
        this.px = p.x;
        this.py = p.y;
        this.facing = team === Team.BLUE ? 1 : -1;

        this.initialState = { q, r, maxHp: 100, skillIds: [], role: Role.WARRIOR };
    }

    setAnim(state: AnimState) {
        if (this.animState !== state && this.animState !== AnimState.DEAD) {
            this.animState = state;
            this.animTimer = 0;
        }
    }

    saveState() {
        this.initialState = {
            q: this.q,
            r: this.r,
            maxHp: this.maxHp,
            skillIds: [...this.skillIds],
            role: this.role
        };
    }

    reset(config: MapConfig) {
        this.q = this.initialState.q;
        this.r = this.initialState.r;
        const p = HexUtils.toPx(this.q, this.r, config);
        this.px = p.x;
        this.py = p.y;

        this.maxHp = this.initialState.maxHp;
        this.hp = this.maxHp;
        this.mp = 0;

        this.skillIds = [...this.initialState.skillIds];
        this.role = this.initialState.role;

        const stats = UNIT_DB[this.role];
        if (stats) {
            this.moveSpeed = stats.moveSpeed;
            this.maxMp = stats.maxMp;
            this.jump = stats.jump;
            this.weight = stats.weight;
            this.movementType = stats.movementType;
        }

        this.castingSkillIdx = -1;
        this.castTimer = 0;
        this.castingAnimationTimer = 0;
        this.curCDs = [0, 0, 0];

        this.isMoving = false;
        this.moveSpeedMult = 1.0; 
        this.path = [];
        this.moveProgress = 0;

        this.stunTimer = 0;
        this.banishTimer = 0;
        this.silenceTimer = 0;
        this.banished = false;
        this.dotTimer = 0;
        this.hotTimer = 0;
        this.visualStatus = 'NONE';
        this.interruptedVisual = null;

        this.hitFlashTimer = 0;
        this.deadLogged = false;
        this.fullyDead = false;
        this.animState = AnimState.IDLE;
        this.spawnTimer = 0.5; 

        this.target = null;
        this.targetHex = null;
        this.physics = { x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, angle: 0, vAngle: 0 };
    }
}

import { Agent, GameEngine } from "../game";
import { AnimState } from "../../types";

export class StatusSystem {

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 1. Cooldowns
        agent.curCDs = agent.curCDs.map(c => Math.max(0, c - dt));

        // 2. Control Timers
        if (agent.stunTimer > 0) agent.stunTimer -= dt;
        if (agent.silenceTimer > 0) agent.silenceTimer -= dt;

        // 3. Banish Logic
        if (agent.banishTimer > 0) {
            agent.banishTimer -= dt;
            if (agent.banishTimer <= 0) {
                agent.banished = false;
                engine.log(agent, '放逐結束', null, '返回');
            }
        }

        // 4. Spawn Animation Timer
        if (agent.spawnTimer > 0) {
            agent.spawnTimer -= dt;
        }

        // 5. Interrupted Visual Decay
        if (agent.interruptedVisual) {
            agent.interruptedVisual.timer -= dt;
            if (agent.interruptedVisual.timer <= 0) {
                agent.interruptedVisual = null;
            }
        }

        // 6. Visual State Reset
        if (agent.visualStatus === 'FROZEN' && agent.stunTimer <= 0) agent.visualStatus = 'NONE';
        if (agent.visualStatus === 'POLYMORPH' && !agent.banished) agent.visualStatus = 'NONE';
        if (agent.visualStatus === 'STASIS' && !agent.banished) agent.visualStatus = 'NONE';

        // 7. DoT (Damage over Time)
        if (agent.dotTimer > 0) {
            agent.dotTimer -= dt;
            agent.hp -= agent.dotDmg * dt;
            // Visual feedback throttling (random chance per tick to avoid spamming events)
            if (Math.random() < 0.05) { 
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.round(agent.dotDmg), 
                    color: '#10b981' 
                });
                agent.hitFlashTimer = 0.1;
            }
        }

        // 8. HoT (Heal over Time)
        if (agent.hotTimer > 0) {
            agent.hotTimer -= dt;
            agent.hp = Math.min(agent.maxHp, agent.hp + agent.hotVal * dt);
            if (Math.random() < 0.05) {
                engine.events.push({ 
                    type: 'HEAL', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: Math.round(agent.hotVal), 
                    color: '#86efac' 
                });
            }
        }

        // 9. Animation State Reset
        // If not stunned, not banished, not moving, and not casting -> Return to Idle
        if (agent.stunTimer <= 0 && agent.banishTimer <= 0 && !agent.isMoving && agent.castingSkillIdx === -1) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, GameEventType, AnimState } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { BLOCK_HEIGHT } from "../../../constants";

const HIT_IMPULSE_MAX = 20;
const HIT_IMPULSE_MIN = 5;

export class SkillResolutionSystem {

    public updateCasting(a: Agent, dt: number, engine: GameEngine) {
        // Interrupt Checks (Stun / Silence / Banish / Death)
        if (a.stunTimer > 0 || a.banished || a.silenceTimer > 0 || a.hp <= 0) {
            const skillIdx = a.castingSkillIdx;

            // If actively casting, create a visual snapshot of the "Broken" spell
            if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
                const s = a.skills[skillIdx]!;
                const skillName = s.name;
                engine.log(a, 'CC', '中斷', skillName, '詠唱被打斷');

                // --- CREATE BROKEN SNAPSHOT ---
                let centerHex = { q: a.q, r: a.r };
                if (s.type === 'AOE') {
                    if (a.targetHex) centerHex = a.targetHex;
                    else if (a.target) centerHex = {q: a.target.q, r: a.target.r};
                }

                a.interruptedVisual = {
                    skill: s,
                    center: centerHex,
                    radius: s.aoeRadius || 1,
                    visual: s.visual || 'BOLT',
                    color: s.color,
                    progress: 1 - (a.castTimer / s.cast),
                    timer: 0.5, // 0.5s fade out
                    maxTimer: 0.5
                };
            }

            a.castingSkillIdx = -1;
            a.castTimer = 0;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.IDLE); 
            return;
        }

        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        // Cast Completion
        if (a.castTimer <= 0) {
            const s = a.skills[a.castingSkillIdx]!;

            // Mana Cost & Gain
            a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
            a.curCDs[a.castingSkillIdx] = s.cd;

            // Execution Branch: Projectile vs Instant
            if (s.projectileSpeed && s.projectileSpeed > 0) {
                 engine.combat.spawnProjectile(a, s, engine);
            } else {
                this.executeInstantSkill(a, s, engine);
            }

            // Reset State
            a.castingSkillIdx = -1;
            a.castingAnimationTimer = 0;
            a.setAnim(AnimState.COMBAT_IDLE);
        }
    }

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        const radius = skill.aoeRadius || 1;
        let targets: Agent[] = [];
        let centerHex: { q: number, r: number } | null = null;

        // 1. Identify Targets
        if (skill.type === 'AOE') {
            if (source.targetHex) {
                centerHex = source.targetHex;
            } else if (source.target) {
                centerHex = { q: source.target.q, r: source.target.r };
            } else {
                centerHex = { q: source.q, r: source.r };
            }

            if (centerHex) {
                targets = engine.agents.filter(e => 
                    e.team !== source.team && 
                    e.hp > 0 && !e.banished &&
                    HexUtils.dist(centerHex!, e) <= radius
                );
            }
        } else {
            // Single Target - Verify Height-Aware Range
            if (source.target && !source.target.banished && source.target.hp > 0) {
                const effectiveRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                const actualDist = HexUtils.dist(source, source.target);

                if (actualDist <= effectiveRange) {
                    targets = [source.target];
                }
            }
        }

        const origin = {x: source.px, y: source.py};

        // 2. VISUAL ENFORCEMENT: Beam/Tracer for Ranged Instant Attacks
        // If range > 1, we MUST draw a line. If range == 1, it's melee (SMASH/SLASH) handles itself via hit effect.
        targets.forEach(t => {
            const dist = HexUtils.dist(source, t);
            if (dist > 1) {
                engine.events.push({
                    type: 'VISUAL_BEAM',
                    pos: { x: t.px, y: t.py }, // Beam End Point
                    sourceId: source.id,
                    targetId: t.id,
                    skill: skill,
                    color: skill.color
                });
            }
            this.resolveHit(source, t, skill, origin, engine);
        });

        // 3. Melee / Self / Miss Visuals
        if (targets.length === 0 && skill.type === 'AOE' && centerHex) {
             // Missed/Ground Hit logic if needed, but CAST_FINISH handles the ground circle/smash visual
        }

        engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        let rawDmg = skill.power;

        // Execute Logic
        const isExecute1 = skill.effectType === 'EXECUTE';
        const isExecute2 = skill.effectType2 === 'EXECUTE';
        if ((isExecute1 || isExecute2) && target.hp < target.maxHp * 0.3) {
            const multiplier = (isExecute1 ? skill.effectVal : skill.effectVal2) || 1.5;
            rawDmg = Math.floor(rawDmg * multiplier);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });
        }

        let evtType: GameEventType = 'DAMAGE';
        let val = 0;
        const oldHp = Math.ceil(target.hp);

        if (rawDmg > 0) {
            target.hp -= rawDmg;
            val = -rawDmg;
            evtType = 'DAMAGE';
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Physics Impulse
            const originX = origin ? origin.x : source.px;
            const originY = origin ? origin.y : source.py;
            let dx = target.px - originX;
            let dy = target.py - originY;
            const len = Math.sqrt(dx * dx + dy * dy);
            if (len > 0) {
                dx /= len; dy /= len;
                const impactForce = Math.min(HIT_IMPULSE_MAX, Math.max(HIT_IMPULSE_MIN, rawDmg * 0.3));
                target.physics.vx += dx * impactForce;
                target.physics.vy += dy * impactForce;
                target.physics.vAngle += (Math.random() - 0.5) * impactForce * 0.05;
            }

            // Vamp Logic
            const isVamp1 = skill.effectType === 'VAMP';
            const isVamp2 = skill.effectType2 === 'VAMP';
            if ((isVamp1 || isVamp2) && source.hp > 0) {
                const vampPct = (isVamp1 ? skill.effectVal : skill.effectVal2) || 0.5;
                const healAmt = Math.floor(rawDmg * vampPct);
                if (healAmt > 0) {
                    source.hp = Math.min(source.maxHp, source.hp + healAmt);
                    engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: healAmt, color: '#86efac' });
                }
            }

        } else if (rawDmg < 0) {
            const heal = -rawDmg;
            target.hp = Math.min(target.maxHp, target.hp + heal);
            val = heal;
            evtType = 'HEAL';
        }

        const newHp = Math.ceil(target.hp);

        // Mana Burn
        const isBurn1 = skill.effectType === 'MANA_BURN';
        const isBurn2 = skill.effectType2 === 'MANA_BURN';
        if (isBurn1 || isBurn2) {
            const burnAmt = (isBurn1 ? skill.effectVal : skill.effectVal2) || 30;
            target.mp = Math.max(0, target.mp - burnAmt);
            source.mp = Math.min(source.maxMp, source.mp + burnAmt);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${burnAmt} MP`, color: "#3b82f6" });
        }

        // Mana Restore
        const isRestore1 = skill.effectType === 'MANA_RESTORE';
        const isRestore2 = skill.effectType2 === 'MANA_RESTORE';
        if (isRestore1 || isRestore2) {
             const amt = (isRestore1 ? skill.effectVal : skill.effectVal2) || 30;
             target.mp = Math.min(target.maxMp, target.mp + amt);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${amt} MP`, color: "#60a5fa" });
        }

        // EMIT EVENT
        engine.events.push({
            type: evtType,
            pos: { x: target.px, y: target.py },
            value: val,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        this.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        this.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        // RICH LOG: Hit
        engine.log(
            source, 
            rawDmg < 0 ? 'HEAL' : 'HIT', 
            skill.name, 
            target.id, 
            `${rawDmg > 0 ? '造成傷害' : '回復生命'} ${Math.abs(rawDmg)} (HP: ${oldHp} -> ${newHp})`
        );

        // RICH LOG: Kill
        if (oldHp > 0 && newHp <= 0) {
            engine.log(source, 'DEATH', '擊殺', target.id, `${target.id} 已陣亡`);
        }
    }

    public applyCC(source: Agent, target: Agent, skill: Skill, type: string | undefined, dur: number | undefined, force: number | undefined, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        if (!type) return;
        const duration = dur || 0;
        const power = force || 0;

        if (type === 'STUN') {
            target.stunTimer = Math.max(target.stunTimer, duration);
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "暈眩", color: "#facc15" });

            const isIce = skill.color.toLowerCase().includes('blue') || 
                          skill.color.includes('#60a5fa') || 
                          skill.color.includes('#e0f2fe') || 
                          skill.name.includes("冰") || 
                          skill.name.includes("凍") || 
                          skill.name.includes("雪");

            if (isIce) {
                target.visualStatus = 'FROZEN';
            }
        } else if (type === 'SILENCE') {
            target.silenceTimer = Math.max(target.silenceTimer, duration);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "沉默", color: "#94a3b8" });
        } else if (type === 'BANISH') {
            target.banishTimer = Math.max(target.banishTimer, duration);
            target.banished = true;
            target.isMoving = false;
            target.setAnim(AnimState.STUN);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "放逐", color: "#c084fc" });

            if (skill.name.includes("變形") || skill.name.includes("羊") || skill.name.includes("動物")) {
                target.visualStatus = 'POLYMORPH'; 
            } else {
                target.visualStatus = 'STASIS'; 
            }
        } else if (type === 'KNOCKBACK' || type === 'PULL') {
            const rawForce = Math.max(1, power);
            const resistance = target.weight || 1; 
            const tilesToPush = Math.max(0, rawForce - resistance);

            if (tilesToPush === 0) {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "抵抗", color: "#94a3b8" });
                return;
            }

            const originPx = origin ? origin : {x: source.px, y: source.py};
            const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));
            const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1);

            let currentH = {q: target.q, r: target.r};
            let currentHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
            let finalH = currentH;

            for(let k=0; k<tilesToPush; k++) {
                const neighbors = HexUtils.neighbors(currentH);
                let bestN = null;
                let bestDot = -99;

                for(const n of neighbors) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                    const nDir = Vector.normalize(Vector.sub(nPx, cPx));
                    const dot = nDir.x * vector.x + nDir.y * vector.y;

                    if (dot > bestDot) {
                        bestDot = dot;
                        bestN = n;
                    }
                }

                if (bestN) {
                    if (!engine.isValid(bestN.q, bestN.r)) break; 
                    if (engine.hasObstacle(bestN.q, bestN.r)) break; 

                    const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);
                    if (nextHeight > currentHeight + BLOCK_HEIGHT) break; 
                    if (nextHeight < currentHeight - BLOCK_HEIGHT * 2) break; 

                    currentH = bestN;
                    currentHeight = nextHeight;
                    finalH = bestN;
                } else {
                    break;
                }
            }

            if (finalH.q !== target.q || finalH.r !== target.r) {
                engine.updateAgentPosition(target, finalH.q, finalH.r);
                target.isMoving = false; 
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: type === 'PULL' ? "牽引" : "擊退", color: "#fff" });
                target.setAnim(AnimState.HIT);
                target.physics.vz += 200;
            }
        } else if (type === 'DOT') {
            target.dotDmg = power || 5;
            target.dotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "中毒", color: "#10b981" });
        } else if (type === 'HOT') {
            target.hotVal = power || 5;
            target.hotTimer = duration || 3;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "再生", color: "#86efac" });
        }
    }
}

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils } from "../utils";
import { Hex, Skill, Projectile } from "../../types";

// Renderers
import { TerrainRenderer } from "../renderers/grid/TerrainRenderer";
import { GridOverlays } from "../renderers/grid/GridOverlays";

export interface RenderableItem {
    y: number;
    z: number;
    draw: (ctx: CanvasRenderingContext2D) => void;
}

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
}

export class GridSystem {
    // Optimization: Cache tiles to avoid re-parsing keys and re-calculating positions every frame
    private _tileCache: CachedTile[] = [];
    private _lastMapVersion: number = -1;

    // Optimization: Reuseable buffers to reduce GC pressure
    // Updated: Include 'state' in the value ('ACTIVE' | 'BROKEN')
    private _dangerZones = new Map<string, {color: string, progress: number, visual: string, state: 'ACTIVE' | 'BROKEN', fadeRatio: number}>();
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    // Passthrough
    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileCache.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileCache = [];
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            this._tileCache.push({ q, r, px: pos.x, py: pos.y, h });
        });
    }

    getHexAtScreenPoint(mx: number, my: number, camera: {x: number, y: number, zoom: number}, engine: GameEngine): Hex | null {
        this.ensureCache(engine);

        // Convert screen mouse to world coordinates (unzoomed)
        const wx = mx / camera.zoom + camera.x;
        const wy = my / camera.zoom + camera.y;

        const candidates: CachedTile[] = [];
        const limit = HEX_SIZE * 2; 

        for (const tile of this._tileCache) {
            const dist = Math.abs(wx - tile.px) + Math.abs(wy - (tile.py - tile.h));
            if (dist < limit) { 
                candidates.push(tile);
            }
        }

        // Sort by visual depth (Front to Back)
        candidates.sort((a, b) => b.py - a.py);

        for (const cand of candidates) {
            const testHex = HexUtils.fromPx(wx, wy + cand.h, engine.mapConfig);
            const rounded = HexUtils.round(testHex.q, testHex.r);
            if (rounded.q === cand.q && rounded.r === cand.r) {
                return { q: cand.q, r: cand.r };
            }
        }

        return null;
    }

    /**
     * Identifies agents that are visually blocked by taller terrain in front of them.
     */
    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);

            // In Diamond Isometric, "Front" means Higher Y on screen.
            // Blocks with higher Y and higher Z can occlude units with lower Y.
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            let isBlocked = false;

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);

                    // Check if neighbor is physically "in front" (Screen Y is larger)
                    if (nPx.y > uPx.y) {
                         const nHeight = engine.map.getTerrainHeight(n.q, n.r);
                         // If the blocking tile is strictly taller
                         if (nHeight > uHeight) {
                             isBlocked = true;
                             break;
                         }
                    }
                }
            }

            if (isBlocked) {
                occluded.push(a);
            }
        });

        return occluded;
    }

    collectRenderables(
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        flashes: any[],
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ): RenderableItem[] {
        this.ensureCache(engine);

        const list: RenderableItem[] = [];
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Clear and Reuse Buffers
        this._dangerZones.clear();
        this._unitPresence.clear();
        this._unitVisualStatus.clear();

        engine.agents.forEach(a => {
            // 1. ACTIVE CASTS (Only if not suppressed)
            if (a.hp > 0 && a.stunTimer <= 0 && a.silenceTimer <= 0 && !a.banished && a.castingSkillIdx !== -1) {
                const s = a.skills[a.castingSkillIdx];
                if (s && s.type === 'AOE') {
                    let centerHex: Hex | null = null;
                    if (a.targetHex) centerHex = a.targetHex;
                    else if (a.target) centerHex = {q: a.target.q, r: a.target.r};
                    else centerHex = {q: a.q, r: a.r};

                    if (centerHex) {
                        const progress = 1 - (a.castTimer / s.cast);
                        // DYNAMIC EXPANSION:
                        const currentRadius = Math.max(0.5, (s.aoeRadius || 1) * progress);
                        const potentialHexes = HexUtils.range(centerHex, s.aoeRadius || 1);

                        potentialHexes.forEach(h => {
                            if (HexUtils.dist(centerHex!, h) <= currentRadius) {
                                this._dangerZones.set(`${h.q},${h.r}`, {
                                    color: s.color, 
                                    progress: progress,
                                    visual: s.visual || 'BOLT',
                                    state: 'ACTIVE',
                                    fadeRatio: 1.0
                                });
                            }
                        });
                    }
                }
            }

            // 2. INTERRUPTED VISUALS (Fading out)
            if (a.interruptedVisual) {
                const iv = a.interruptedVisual;
                const fadeRatio = iv.timer / iv.maxTimer;
                const potentialHexes = HexUtils.range(iv.center, iv.radius);
                const currentRadius = Math.max(0.5, iv.radius * iv.progress);

                potentialHexes.forEach(h => {
                    if (HexUtils.dist(iv.center, h) <= currentRadius) {
                        // Key might overwrite active cast if same tile, but broken usually implies interrupt anyway
                        this._dangerZones.set(`${h.q},${h.r}`, {
                            color: iv.color,
                            progress: iv.progress,
                            visual: iv.visual,
                            state: 'BROKEN',
                            fadeRatio: fadeRatio
                        });
                    }
                });
            }

            if(a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') {
                    this._unitVisualStatus.set(key, a.visualStatus);
                }
            }
        });

        const centerQ = Math.floor(engine.mapConfig.w / 2);
        const centerR = Math.floor(engine.mapConfig.h / 2);
        const maxDist = Math.max(engine.mapConfig.w, engine.mapConfig.h) / 2;

        for (const tile of this._tileCache) {
            const { q, r, px, py, h } = tile;

            // --- TRANSITION LOGIC ---
            let visualY = py;
            if (transitionPhase !== 'IDLE') {
                const dist = Math.sqrt((q - centerQ)**2 + (r - centerR)**2);
                const d = dist / maxDist; 

                if (transitionPhase === 'OUT') {
                    const trigger = d * 0.3;
                    if (transitionT > trigger) {
                        const fallT = Math.min(1, (transitionT - trigger) * 2.5);
                        const easedFall = fallT * fallT * fallT;
                        visualY += easedFall * 1000;
                    }
                } else if (transitionPhase === 'IN') {
                    const trigger = d * 0.3;
                    const riseT = Math.max(0, Math.min(1, (transitionT - trigger) * 2.5));
                    const easedRise = 1 - Math.pow(1 - riseT, 3);
                    visualY += (1 - easedRise) * 1000;
                }
            }

            if (visualY > py + 800) continue;

            const flash = flashes.find(f => f.q === q && f.r === r);
            let isRange = false;
            let rangeColor = '';

            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const tileH = h;
                const bonus = Math.max(0, Math.floor((agentH - tileH) / BLOCK_HEIGHT));
                const effRange = hoveredSkill.range + bonus;

                if (HexUtils.dist({q, r}, highlightAgent) <= effRange) {
                    isRange = true; 
                    rangeColor = hoveredSkill.color;
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;

            const k = `${q},${r}`;
            const dangerInfo = this._dangerZones.get(k);
            const hasUnit = this._unitPresence.has(k);
            const specialStatus = this._unitVisualStatus.get(k);

            let lightColor = null;
            let lightIntensity = 0;
            const PROJ_LIGHT_RADIUS = 40; 
            const PROJ_LIGHT_RADIUS_SQ = PROJ_LIGHT_RADIUS * PROJ_LIGHT_RADIUS;

            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / PROJ_LIGHT_RADIUS);
                }
            }

            list.push({
                y: visualY, 
                z: 0,        
                draw: (ctx) => {
                    // 1. Draw Physical Block
                    TerrainRenderer.drawBlockGeometry(ctx, px, visualY, HEX_SIZE, h, theme);

                    // 2. Draw Texture Detail
                    TerrainRenderer.drawTerrainDetail(ctx, px, visualY - h, q, r, scene.textureType, theme.detail);

                    // 3. Draw Overlays (Status, Range, Danger, Lighting)
                    GridOverlays.drawOverlays(
                        ctx, px, visualY - h, HEX_SIZE,
                        specialStatus, dangerInfo,
                        lightColor, Math.min(1, lightIntensity),
                        flash, isRange, rangeColor, isHover, hasUnit,
                        q, r, globalTime
                    );
                }
            });
        }

        return list;
    }
}

import { TerrainRenderer } from "./TerrainRenderer";

export const AOERenderer = {
    draw(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        visual: string,
        progress: number,
        globalTime: number,
        q: number, r: number,
        state: 'ACTIVE' | 'BROKEN' = 'ACTIVE',
        fadeRatio: number = 1.0
    ) {
        // Helper trace function
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        ctx.save();

        // COMMON: No heavy fill, just light tint and strong borders
        const baseOpacity = 0.5 + progress * 0.5;
        // If broken, fade out based on timer
        const opacity = state === 'BROKEN' ? baseOpacity * fadeRatio : baseOpacity;

        // --- BROKEN STATE MODIFIERS ---
        if (state === 'BROKEN') {
            ctx.globalAlpha = opacity;
            ctx.setLineDash([5, 10]); // Dashed line implies "broken"
            // Jitter for instability
            const jitterX = (Math.random() - 0.5) * 4;
            const jitterY = (Math.random() - 0.5) * 4;
            ctx.translate(jitterX, jitterY);

            // Expand slightly as it dissipates
            const expand = 1.0 + (1 - fadeRatio) * 0.2;
            ctx.scale(expand, expand);
        } else {
            ctx.globalAlpha = 1.0;
        }

        // --- A. SMASH / EARTH (Cracks) ---
        if (visual === 'SMASH') {
            // Only draw borders and cracks, no background tint
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = opacity;
            trace();
            ctx.stroke();

            // Cracks
            const seed = Math.abs(q * 123 + r * 456);
            if (progress > 0.1) {
                ctx.globalCompositeOperation = 'source-over';
                ctx.beginPath();
                for(let i=0; i<3; i++) {
                    const angle = (seed + i * 2) % (Math.PI * 2);
                    const len = size * 0.8;
                    let cx = x; let cy = y;
                    ctx.moveTo(cx, cy);
                    // Jagged line
                    for(let s=0; s<3; s++) {
                        cx += Math.cos(angle + (s%2==0?0.5:-0.5)) * (len/3);
                        cy += Math.sin(angle + (s%2==0?0.5:-0.5)) * (len/3);
                        ctx.lineTo(cx, cy);
                    }
                }
                ctx.strokeStyle = color;
                ctx.lineWidth = 1 + progress;
                ctx.stroke();
            }

        // --- B. FIREBALL / BOMB (Pulse Ring) ---
        } else if (visual === 'FIREBALL' || visual === 'BOMB') {
            const pulse = 1 + Math.sin(globalTime * 20) * 0.1;

            // Outer Ring Glow (Halo) instead of tile fill
            ctx.shadowColor = color;
            ctx.shadowBlur = state === 'BROKEN' ? 0 : 10;
            ctx.strokeStyle = color;
            ctx.lineWidth = 3 * pulse;
            ctx.globalAlpha = opacity; // Use computed opacity

            trace();
            ctx.stroke();

            // Inner heat core (Small dot) - Only if active
            if (state === 'ACTIVE') {
                ctx.fillStyle = color;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath(); 
                ctx.arc(x, y, size * 0.2 * pulse, 0, Math.PI*2); 
                ctx.fill();
            }

        // --- C. ARROW / RANGER (Target Lock) ---
        } else if (visual === 'ARROW') {
            // Reticle corners only
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = opacity * 0.8;

            const s = size * 0.6;
            ctx.beginPath();
            // Top Left
            ctx.moveTo(x - s, y - s/2); ctx.lineTo(x - s, y - s); ctx.lineTo(x - s/2, y - s);
            // Top Right
            ctx.moveTo(x + s/2, y - s); ctx.lineTo(x + s, y - s); ctx.lineTo(x + s, y - s/2);
            // Bottom Right
            ctx.moveTo(x + s, y + s/2); ctx.lineTo(x + s, y + s); ctx.lineTo(x + s/2, y + s);
            // Bottom Left
            ctx.moveTo(x - s/2, y + s); ctx.lineTo(x - s, y + s); ctx.lineTo(x - s, y + s/2);
            ctx.stroke();

            // Center Dot
            if (state === 'ACTIVE') {
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(x, y, 2, 0, Math.PI*2); ctx.fill();
            }

        // --- D. DEFAULT / MAGIC (Runes) ---
        } else {
            // Magic Border
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = opacity * 0.8;
            ctx.shadowColor = state === 'BROKEN' ? 'transparent' : color;
            ctx.shadowBlur = 5;
            trace();
            ctx.stroke();

            // Floating Particles
            if (progress > 0.2 && state === 'ACTIVE') {
                const particleCount = 1 + Math.floor(Math.random() * 2);
                for(let i=0; i<particleCount; i++) {
                    const pSeed = (Math.abs(q * 100 + r * 10) + i * 123.45 + globalTime);
                    const pX = x + Math.sin(pSeed) * (size * 0.4);
                    const pY = y + Math.cos(pSeed) * (size * 0.4);

                    ctx.globalAlpha = 0.6 + Math.sin(globalTime * 10 + i) * 0.4;
                    ctx.fillStyle = color;
                    ctx.beginPath();
                    ctx.arc(pX, pY, 1.5, 0, Math.PI*2);
                    ctx.fill();
                }
            }
        }

        ctx.restore();
    }
};

import { TerrainRenderer } from "./TerrainRenderer";
import { AOERenderer } from "./AOERenderer";

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Note: y here should be the "visual top" y (y - topY)
        size: number,
        specialStatus: string | undefined,
        dangerInfo: {color: string, progress: number, visual: string, state: 'ACTIVE' | 'BROKEN', fadeRatio: number} | undefined,
        lightColor: string | null,
        lightIntensity: number,
        flash: any,
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,
        q: number, r: number,
        globalTime: number
    ) {
        // Helper to trace the hex shape at current position
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        // 1. SPECIAL STATUS FLOOR EFFECT (Frozen/Polymorph)
        if (specialStatus) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'overlay';
            if (specialStatus === 'FROZEN') {
                ctx.fillStyle = '#bae6fd'; 
                ctx.globalAlpha = 0.6;
            } else if (specialStatus === 'POLYMORPH') {
                ctx.fillStyle = '#d8b4fe'; 
                ctx.globalAlpha = 0.5;
            } else if (specialStatus === 'STASIS') {
                ctx.fillStyle = '#fde047';
                ctx.globalAlpha = 0.5;
            }
            ctx.fill(); 
            ctx.restore();
        }

        // 2. AOE TELEGRAPH (Danger Zone) - Delegated
        if (dangerInfo) {
            AOERenderer.draw(
                ctx, x, y, size, 
                dangerInfo.color, dangerInfo.visual, dangerInfo.progress, 
                globalTime, q, r,
                dangerInfo.state, 
                dangerInfo.fadeRatio
            );
        }

        // 3. Dynamic Lighting (Projectile Pass)
        if (lightColor && lightIntensity > 0) {
            trace(); 
            ctx.save();
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.globalAlpha = lightIntensity * 0.8; 
            ctx.fillStyle = lightColor;
            ctx.fill();
            ctx.restore();
        }

        // 4. Interactive Highlights (Hover/Range/Flash)
        if (flash || isRange || isHover || hasUnit) {
            ctx.save();
            trace(); 

            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.1; // Fainter fill
                ctx.fill();
                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.6; 
                ctx.stroke();
            }

            if (isHover) { 
                ctx.fillStyle = 'rgba(255,255,255,0.1)'; 
                ctx.globalAlpha = 1.0;
                ctx.fill(); 
                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2; 
                ctx.stroke(); 
            }

            if (flash) {
                ctx.globalCompositeOperation = 'lighter';
                ctx.fillStyle = flash.color;
                ctx.globalAlpha = 0.4;
                ctx.fill();
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            // Only draw unit base ring if not hovering and no danger zone (cleaner look)
            if (hasUnit && !isHover && !dangerInfo) {
                ctx.strokeStyle = 'rgba(255,255,255,0.15)';
                ctx.lineWidth = 1;
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { TerrainRenderer } from "./TerrainRenderer";

export const AOERenderer = {
    draw(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        visual: string,
        progress: number,
        globalTime: number,
        q: number, r: number,
        state: 'ACTIVE' | 'BROKEN' = 'ACTIVE',
        fadeRatio: number = 1.0
    ) {
        // Helper trace function
        const trace = () => TerrainRenderer.traceTopFace(ctx, x, y);

        ctx.save();

        // COMMON: No heavy fill, just light tint and strong borders
        const baseOpacity = 0.5 + progress * 0.5;
        // If broken, fade out based on timer
        const opacity = state === 'BROKEN' ? baseOpacity * fadeRatio : baseOpacity;

        // --- BROKEN STATE MODIFIERS ---
        if (state === 'BROKEN') {
            ctx.globalAlpha = opacity;
            ctx.setLineDash([5, 5]); // Dashed line implies "broken"

            // Jitter for instability
            const jitterX = (Math.random() - 0.5) * 5;
            const jitterY = (Math.random() - 0.5) * 5;

            // Expand slightly as it dissipates
            const expand = 1.0 + (1 - fadeRatio) * 0.3;

            // CRITICAL FIX: Scale around the center of the tile (x, y)
            // Otherwise it scales from canvas (0,0) and flies off screen
            ctx.translate(x + jitterX, y + jitterY);
            ctx.scale(expand, expand);
            ctx.translate(-x, -y);

            // Optional: Shift color towards grey/white to indicate loss of magic
            ctx.shadowColor = 'transparent';
        } else {
            ctx.globalAlpha = 1.0;
        }

        // --- A. SMASH / EARTH (Cracks) ---
        if (visual === 'SMASH') {
            // Only draw borders and cracks, no background tint
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = opacity;
            trace();
            ctx.stroke();

            // Cracks
            const seed = Math.abs(q * 123 + r * 456);
            if (progress > 0.1) {
                ctx.globalCompositeOperation = 'source-over';
                ctx.beginPath();
                for(let i=0; i<3; i++) {
                    const angle = (seed + i * 2) % (Math.PI * 2);
                    const len = size * 0.8;
                    let cx = x; let cy = y;
                    ctx.moveTo(cx, cy);
                    // Jagged line
                    for(let s=0; s<3; s++) {
                        cx += Math.cos(angle + (s%2==0?0.5:-0.5)) * (len/3);
                        cy += Math.sin(angle + (s%2==0?0.5:-0.5)) * (len/3);
                        ctx.lineTo(cx, cy);
                    }
                }
                ctx.strokeStyle = color;
                ctx.lineWidth = 1 + progress;
                ctx.stroke();
            }

        // --- B. FIREBALL / BOMB (Pulse Ring) ---
        } else if (visual === 'FIREBALL' || visual === 'BOMB') {
            const pulse = 1 + Math.sin(globalTime * 20) * 0.1;

            // Outer Ring Glow (Halo) instead of tile fill
            ctx.shadowColor = color;
            ctx.shadowBlur = state === 'BROKEN' ? 0 : 10;
            ctx.strokeStyle = color;
            ctx.lineWidth = 3 * pulse;
            ctx.globalAlpha = opacity; // Use computed opacity

            trace();
            ctx.stroke();

            // Inner heat core (Small dot) - Only if active
            if (state === 'ACTIVE') {
                ctx.fillStyle = color;
                ctx.globalCompositeOperation = 'lighter';
                ctx.beginPath(); 
                ctx.arc(x, y, size * 0.2 * pulse, 0, Math.PI*2); 
                ctx.fill();
            }

        // --- C. ARROW / RANGER (Target Lock) ---
        } else if (visual === 'ARROW') {
            // Reticle corners only
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = opacity * 0.8;

            const s = size * 0.6;
            ctx.beginPath();
            // Top Left
            ctx.moveTo(x - s, y - s/2); ctx.lineTo(x - s, y - s); ctx.lineTo(x - s/2, y - s);
            // Top Right
            ctx.moveTo(x + s/2, y - s); ctx.lineTo(x + s, y - s); ctx.lineTo(x + s, y - s/2);
            // Bottom Right
            ctx.moveTo(x + s, y + s/2); ctx.lineTo(x + s, y + s); ctx.lineTo(x + s/2, y + s);
            // Bottom Left
            ctx.moveTo(x - s/2, y + s); ctx.lineTo(x - s, y + s); ctx.lineTo(x - s, y + s/2);
            ctx.stroke();

            // Center Dot
            if (state === 'ACTIVE') {
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(x, y, 2, 0, Math.PI*2); ctx.fill();
            }

        // --- D. DEFAULT / MAGIC (Runes) ---
        } else {
            // Magic Border
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = opacity * 0.8;
            ctx.shadowColor = state === 'BROKEN' ? 'transparent' : color;
            ctx.shadowBlur = 5;
            trace();
            ctx.stroke();

            // Floating Particles
            if (progress > 0.2 && state === 'ACTIVE') {
                const particleCount = 1 + Math.floor(Math.random() * 2);
                for(let i=0; i<particleCount; i++) {
                    const pSeed = (Math.abs(q * 100 + r * 10) + i * 123.45 + globalTime);
                    const pX = x + Math.sin(pSeed) * (size * 0.4);
                    const pY = y + Math.cos(pSeed) * (size * 0.4);

                    ctx.globalAlpha = 0.6 + Math.sin(globalTime * 10 + i) * 0.4;
                    ctx.fillStyle = color;
                    ctx.beginPath();
                    ctx.arc(pX, pY, 1.5, 0, Math.PI*2);
                    ctx.fill();
                }
            }
        }

        ctx.restore();
    }
};

